window.CGDD_DATA = {"flow":"%% CGDD-Game2 script flow\n%% Generated by CGDD/Export Trace Docs. Do not edit by hand.\nflowchart TD\n  AmbientAudio(\"<b>AmbientAudio</b><br/>Background sound: drone, ventilation, the danger layer that rises when you are seen, sudden silence on a warning\")\n  ArchiveDirector(\"<b>ArchiveDirector</b><br/>Chapter 5 The Archive (Thursday): a buzz gives you away -› SILENT MODE (the little bell, M); the noise meter (footsteps, Ctrl = quiet); the oldest book's stamp (SEARCH = 0467); search words you READ; the old books awaiting repair - turning the pages is louder than walking\")\n  AudioSynth(\"<b>AudioSynth</b><br/>Every sound in the game, generated in code (hum, drones, chimes, footsteps, voices, the climax chord)\")\n  DangerFX(\"<b>DangerFX</b><br/>Red vignette and colour fringing that grow while you are being seen\")\n  EndScreen(\"<b>EndScreen</b><br/>Page after each chapter: CAUGHT (retry), chapter complete (continue), or one of the two endings\")\n  Fluorescent(\"<b>Fluorescent</b><br/>Ceiling fluorescent light with buzz; neglected ones flicker\")\n  Footsteps(\"<b>Footsteps</b><br/>3D footsteps (and the warden's keys) so you can hear where a watcher is\")\n  GameFlow(\"<b>GameFlow</b><br/>Scene flow: Title -› Chapter 1-6 (Monday to Friday) -› End page (win: next chapter, caught: retry); saves progress and the player name\")\n  GameSpeed(\"<b>GameSpeed</b><br/>2x story speed (Tab, or the title page): dialogue, messages, typing, loading bars and scripted waits run twice as fast - walking and watchers don't\")\n  HumSource(\"<b>HumSource</b><br/>The girl who hums: 3D off-key anthem you find by listening (fades in only when close)\")\n  Interactable(\"<b>Interactable</b><br/>Anything the player can use with E (desk cubby, panel, phone, shoulder tap, seats, doors)\")\n  Level01Director(\"<b>Level01Director</b><br/>Chapter 1 The Lesson: walked to your seat, roll call, find the phone in the desk, codes from the lecture, tap the student with the chalk triangle\")\n  Level02Director(\"<b>Level02Director</b><br/>Chapter 2 Lunch: sweeping camera + Lunch Monitor, follow the humming, forward the message within reach, sneak to the STAFF door and down the stairs\")\n  Level03Director(\"<b>Level03Director</b><br/>Chapter 3 Lights Out: listen for the warden, hold Space to pretend to sleep, Contacts code from his room call, flash the screen at the window 3 times\")\n  Level04Director(\"<b>Level04Director</b><br/>Chapter 6 Inspection Day (Friday, the fifth day): get the phone back, the 1979 photo (Voss was Seat 31), desk inspection, final choice: hide it (THE SEAT) or send it to everyone (LIGHTS)\")\n  LevelDirectorBase(\"<b>LevelDirectorBase</b><br/>Shared chapter rules: one subtitle at a time, danger meter, 3 hidden warnings, objective panel, prompts, chapter cards\")\n  Loc(\"<b>Loc</b><br/>Language setting (English / 中文): inline pairs L(en, zh) for story text, and a table T(en) for data text (lecture lines, posters, photo captions)\")\n  LocTable(\"<b>LocTable</b><br/>Chinese text for everything that is stored as English data: scene posters, contacts, photos, lessons, labels\")\n  PatrolAI(\"<b>PatrolAI</b><br/>A walking watcher on a NavMesh (Lunch Monitor, night warden): roams, follows scripted routes, scans while waiting\")\n  PhoneController(\"<b>PhoneController</b><br/>The hidden phone: hold to raise, passcodes, app loading, Photos, Messages, Contacts, forward/reply tasks, notifications, danger shake\")\n  PhotoTarget(\"<b>PhotoTarget</b><br/>Something worth photographing with the phone's Camera app (Chapter 4 Picture Day)\")\n  PictureDayDirector(\"<b>PictureDayDirector</b><br/>Chapter 4 Picture Day (Wednesday): a gym full of students milling about; every so often a CLASS PHOTO countdown - get to your spot, phone down, hold still, smile. Between photos: CAMERA (1045), photograph 3 things without being reported\")\n  Pigeon(\"<b>Pigeon</b><br/>A courtyard pigeon outside the classroom windows: pecks, looks around, hops a little. Not monitored. ...Yet.\")\n  PlayerRig(\"<b>PlayerRig</b><br/>The player body: walk, pulled to the seat, seated look, inspect the desk cubby, lie down in bed\")\n  PosterEgg(\"<b>PosterEgg</b><br/>A poster that changes when you come close and look at it: a too-perfect smile, a glitch, an inedible lunch, a mirror (you, in uniform), a red X, or Voss\")\n  Readable(\"<b>Readable</b><br/>A poster / sign / label the player can read by walking up and looking at it: a thought, a Search keyword, or the poster answering back\")\n  TVStatic(\"<b>TVStatic</b><br/>A screen showing nothing but snow ('LIVE' with nobody on it) - flickering grey emission\")\n  TeacherAI(\"<b>TeacherAI</b><br/>The teacher on a NavMesh: lectures, writes on the board (back turned = safe), wanders, calls on you, comes to take the phone\")\n  TeacherVision(\"<b>TeacherVision</b><br/>Can a watcher see a point: range + view cone + line of sight (classmates, pillars and desks are cover)\")\n  TitleScreen(\"<b>TitleScreen</b><br/>Title page: New Game (asks your name) / Continue / Chapters / Quit\")\n  UIFactory(\"<b>UIFactory</b><br/>Builds every on-screen panel, text, button and world-space poster canvas in code (no prefabs), with the right font for English or Chinese\")\n\n  AmbientAudio --> AudioSynth\n  ArchiveDirector --> LevelDirectorBase\n  ArchiveDirector --> PatrolAI\n  ArchiveDirector --> TeacherVision\n  ArchiveDirector --> PhoneController\n  ArchiveDirector --> Readable\n  ArchiveDirector --> Interactable\n  ArchiveDirector --> AudioSynth\n  ArchiveDirector --> Pigeon\n  EndScreen --> GameFlow\n  EndScreen --> AmbientAudio\n  EndScreen --> AudioSynth\n  Fluorescent --> AudioSynth\n  Footsteps --> AudioSynth\n  HumSource --> AudioSynth\n  Level01Director --> LevelDirectorBase\n  Level01Director --> TeacherAI\n  Level01Director --> TeacherVision\n  Level01Director --> PhoneController\n  Level01Director --> PlayerRig\n  Level01Director --> Interactable\n  Level02Director --> LevelDirectorBase\n  Level02Director --> PatrolAI\n  Level02Director --> TeacherVision\n  Level02Director --> HumSource\n  Level02Director --> PhoneController\n  Level02Director --> PlayerRig\n  Level02Director --> Interactable\n  Level03Director --> LevelDirectorBase\n  Level03Director --> PatrolAI\n  Level03Director --> TeacherVision\n  Level03Director --> Footsteps\n  Level03Director --> PhoneController\n  Level03Director --> PlayerRig\n  Level04Director --> LevelDirectorBase\n  Level04Director --> TeacherAI\n  Level04Director --> TeacherVision\n  Level04Director --> PhoneController\n  Level04Director --> PlayerRig\n  Level04Director --> Interactable\n  Level04Director --> GameFlow\n  LevelDirectorBase --> PlayerRig\n  LevelDirectorBase --> PhoneController\n  LevelDirectorBase --> DangerFX\n  LevelDirectorBase --> AmbientAudio\n  LevelDirectorBase --> AudioSynth\n  LevelDirectorBase --> Interactable\n  LevelDirectorBase --> GameFlow\n  LevelDirectorBase --> GameSpeed\n  LevelDirectorBase --> Readable\n  LevelDirectorBase --> PosterEgg\n  PatrolAI --> TeacherVision\n  PhoneController --> AudioSynth\n  PictureDayDirector --> LevelDirectorBase\n  PictureDayDirector --> PatrolAI\n  PictureDayDirector --> TeacherVision\n  PictureDayDirector --> PhoneController\n  PictureDayDirector --> PhotoTarget\n  PictureDayDirector --> Readable\n  Pigeon --> AudioSynth\n  PosterEgg --> AudioSynth\n  PosterEgg --> UIFactory\n  PosterEgg --> GameSpeed\n  PosterEgg --> Loc\n  Readable --> Loc\n  TeacherAI --> TeacherVision\n  TitleScreen --> GameFlow\n  TitleScreen --> AmbientAudio\n\n  classDef manager fill:#f0a202,stroke:#1a140e,color:#1a140e,stroke-width:2.5px\n  classDef actor fill:#fff8ea,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef world fill:#9cba6a,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  classDef ui fill:#efe6cf,stroke:#c4841a,color:#1a140e,stroke-width:2px\n  classDef other fill:#efe6cf,stroke:#1a140e,color:#1a140e,stroke-width:2px\n  class PhoneController manager\n  class PlayerRig,UIFactory actor\n  class LevelDirectorBase world\n  class AmbientAudio,ArchiveDirector,AudioSynth,DangerFX,EndScreen,Fluorescent,Footsteps,GameFlow,GameSpeed,HumSource,Interactable,Level01Director,Level02Director,Level03Director,Level04Director,Loc,LocTable,PatrolAI,PhotoTarget,PictureDayDirector,Pigeon,PosterEgg,Readable,TVStatic,TeacherAI,TeacherVision,TitleScreen other\n","tunables":"# Tunables\n\nGenerated from `@tune` headers by the menu `CGDD/Export Trace Docs`. Hand edits are overwritten on the next export.\n\n| Script | Field | Type | Range | Default | Note |\n| --- | --- | --- | --- | --- | --- |\n| AmbientAudio | droneVolume | float | 0-0.5 | 0.16 | background drone level |\n| AmbientAudio | ventVolume | float | 0-0.5 | 0.09 | ventilation hum level |\n| ArchiveDirector | walkDoubling | float | 0.5-6 | 2 | walking without a break doubles the noise rate every this many seconds |\n| ArchiveDirector | walkMaxFactor | float | 1-10 | 5 | cap on that build-up |\n| ArchiveDirector | pigeonNear | float | 1-5 | 2.6 | closer than this to the window when she comes to shoo the pigeons = a warning (m) |\n| ArchiveDirector | noiseWalk | float | 0-0.3 | 0.08 | meter per second while walking |\n| ArchiveDirector | noiseSneak | float | 0-0.1 | 0.012 | meter per second while walking quietly (Ctrl / C) |\n| ArchiveDirector | noiseRun | float | 0.1-1 | 0.45 | meter per second while running (Shift) |\n| ArchiveDirector | noiseDecay | float | 0.05-0.5 | 0.12 | meter drain per second while standing still |\n| ArchiveDirector | flipNoise | float | 0.02-0.4 | 0.16 | meter per page turned (slow) |\n| ArchiveDirector | silentFailChance | float | 0-1 | 0.3 | chance the silent switch quietly fails each time the phone comes out |\n| ArchiveDirector | fastFlipFactor | float | 1-5 | 2.6 | a page turned within fastFlipSeconds of the last one is this much louder |\n| Fluorescent | buzzVolume | float | 0-0.3 | 0.07 | fluorescent buzz loudness |\n| Footsteps | stepLength | float | 0.3-1.2 | 0.7 | metres per step sound |\n| Footsteps | volume | float | 0-1 | 0.55 | footstep loudness |\n| Footsteps | maxDistance | float | 5-30 | 18 | how far footsteps carry (m) |\n| Footsteps | keysEverySteps | int | 0-10 | 0 | key jingle every N steps (0 = never) |\n| HumSource | volume | float | 0-1 | 0.8 | humming loudness |\n| HumSource | maxDistance | float | 2-15 | 6.5 | from how far you can start to hear her (m) |\n| Level01Director | answerSeconds | float | 4-20 | 10 | time to answer when the teacher calls on you |\n| Level01Director | firstCallAtBootSecond | float | 0-5 | 3 | the first question comes this many seconds into the phone start-up |\n| Level02Director | reachDistance | float | 2-8 | 4 | how close you must be to the girl for the message to send |\n| Level03Director | lightNoticeSeconds | float | 0.5-4 | 1.6 | seconds his flashlight needs on the phone screen |\n| Level03Director | awakeNoticeSeconds | float | 1-6 | 3.2 | seconds he needs to see you sitting up during a bed check |\n| Level04Director | answerSeconds | float | 4-20 | 10 | time to answer his questions |\n| Level04Director | inspectionFallbackSeconds | float | 60-300 | 100 | the inspection starts anyway this long after you take the phone |\n| Level04Director | choiceSeconds | float | 5-30 | 14 | time to decide when he is one desk away |\n| LevelDirectorBase | chances | int | 1-5 | 3 | warnings before the phone is taken (never shown as a number) |\n| LevelDirectorBase | noticeSeconds | float | 0.5-6 | 2.5 | seconds a watcher must see the phone before a warning |\n| LevelDirectorBase | dangerDecayPerSecond | float | 0.1-1 | 0.35 | how fast danger drains once nobody is looking |\n| LevelDirectorBase | graceAfterWarning | float | 0-6 | 3 | seconds of safety right after a warning |\n| LevelDirectorBase | typeCharsPerSecond | float | 20-120 | 55 | subtitle typewriter speed |\n| PatrolAI | scanAngle | float | 0-90 | 55 | how far he looks left/right while standing |\n| PatrolAI | scanSpeed | float | 0.1-2 | 0.6 | how fast he looks around |\n| PhoneController | bootSeconds | float | 1-10 | 5 | start-up time (lowering the phone resets it) |\n| PhoneController | raiseSeconds | float | 0.1-1 | 0.25 | time to raise the phone |\n| PhoneController | readCharsPerSecond | float | 5-60 | 22 | message reading speed (only while the phone is up) |\n| PhoneController | glowIntensity | float | 0-4 | 1.6 | how much the screen lights your face (and gives you away at night) |\n| PictureDayDirector | freeSeconds | float | 20-90 | 42 | free time between two class photos |\n| PictureDayDirector | callSeconds | float | 5-40 | 10 | countdown to get to your spot |\n| PictureDayDirector | shutterHearing | float | 1-8 | 2.2 | how close a prefect must be to hear the shutter (m) - 2.2 = right next to you |\n| PictureDayDirector | flashRange | float | 4-20 | 15 | how far a flash is seen (any direction, line of sight) |\n| Pigeon | hopRadius | float | 0-1.5 | 0.6 | how far it hops from where it started (m) |\n| Pigeon | cooVolume | float | 0-1 | 0.2 | coo loudness (about as present as a footstep) |\n| PlayerRig | walkSpeed | float | 1-5 | 2.8 | walking speed (m/s) |\n| PlayerRig | sneakSpeed | float | 0.5-2 | 1.2 | quiet walking speed (hold Ctrl / C) |\n| PlayerRig | sensitivity | float | 1-10 | 5 | mouse look speed |\n| PlayerRig | pullSpeed | float | 0.5-3 | 1.3 | speed when the class watches you walk to your seat |\n| PosterEgg | readFirst | float | 0-5 | — | seconds of looking before it starts to change (0 = from the text length) |\n| PosterEgg | changeSeconds | float | 0-5 | — | seconds the change takes (0 = by kind) |\n| TeacherAI | lectureWeight | float | 0-1 | 0.35 | chance he lectures facing the class |\n| TeacherAI | boardWeight | float | 0-1 | 0.3 | chance he turns to the board (safe window) |\n| TeacherVision | viewAngle | float | 30-180 | 90 | width of the view cone (degrees) |\n| TeacherVision | viewRange | float | 3-20 | 12 | how far he can see (m) |\n\n","challenge":"# How the challenge changes\n\nLook first at whether win and loss change, then at whether the player's verb changes. If neither changes, it is the same game, just tighter or looser.\n\n| Change | Win/loss changed | Verb changed | Data | Script.field |\n| --- | --- | --- | --- | --- |\n| Start: Ch.1 classroom, one teacher who watches and asks questions | — (baseline: win = contact the student in front; loss = 3 warnings, phone taken) | — (watch, peek, act, hide) | noticeSeconds=2.5, chances=3 | LevelDirectorBase.noticeSeconds, LevelDirectorBase.chances |\n| Teacher questions about the lecture | No (a wrong answer costs a warning) | Adds *listen* (or look out of the window: the oak is there) | answerSeconds=10 | Level01Director.answerSeconds |\n| Ch.2 cafeteria: a sweeping camera + a roaming Lunch Monitor | Win changes (deliver the message, reach the STAFF door) | Adds *walk & position*: where you stand decides who sees you | reachDistance=4, viewAngle=90 | Level02Director.reachDistance, TeacherVision.viewAngle |\n| Ch.2 the girl you find by sound | No | Adds *listen to locate* | maxDistance=6.5 | HumSource.maxDistance |\n| Ch.3 dark dorm, the warden is mostly heard, not seen | Win changes (flash the window 3 times) | Adds *pretend to sleep* (hold Space) | lightNoticeSeconds=1.6, awakeNoticeSeconds=3.2 | Level03Director.lightNoticeSeconds, Level03Director.awakeNoticeSeconds |\n| Less frequent warden visits | No | No (looser pressure) | wait 24–38 s between visits | Level03Director (WardenLoop) |\n| Posters you can read (walk up and look at one) | No | Adds *read*: every poster, sign and label gives a thought, a clue, a Search word, or changes when read | readSeconds=0.6 | LevelDirectorBase.readSeconds, Readable.range |\n| New Ch.4 Picture Day (gym): prefects who report, the photographer, CAMERA app | Win changes (photograph 3 things, send them, stand in the final class photo) | Adds *photograph*: aim, the shutter can be heard, the flash can be seen | shutterHearing=2.2, flashRange=15 | PictureDayDirector.shutterHearing, PictureDayDirector.flashRange |\n| Ch.4 class-photo rhythm: free time, then a countdown to a yellow X that moves every time | No (a missed / moving / unsmiling / phone-in-photo shot = a warning) | Adds *be in place on time* + *smile* (hold Space) + *find your new spot* | freeSeconds=42, firstFreeSeconds=55, callSeconds=10 | PictureDayDirector.freeSeconds, PictureDayDirector.callSeconds |\n| Ch.4 prefects must be close to notice | No | No (looser) | shutterHearing=2.2, prefect view 6 m / 90° | PictureDayDirector.shutterHearing, TeacherVision.viewRange |\n| New Ch.5 The Archive (library): the librarian's noise meter, SEARCH app | Win changes (find and read Records, vol. 31) | Adds *move quietly* and *search with words you have read* | noiseWalk=0.08, noiseRun=0.45, noiseDecay=0.12 | ArchiveDirector.noiseWalk, ArchiveDirector.noiseRun, ArchiveDirector.noiseDecay |\n| Ch.5 silent mode that fails at random, quiet steps, turning old pages, a second librarian | No | Adds *silence the phone* (M, and check the bell every time), *sneak* (Ctrl/C), *read slowly* (A/D pages; fast = loud) | silentFailChance=0.3, noiseSneak=0.012, flipNoise=0.16, fastFlipFactor=2.6 | ArchiveDirector.silentFailChance, ArchiveDirector.noiseSneak, ArchiveDirector.flipNoise, ArchiveDirector.fastFlipFactor |\n| Ch.5 walking noise builds up exponentially | No | No (tighter: stop often) | doubles every 2 s, up to 5x | ArchiveDirector.walkDoubling, ArchiveDirector.walkMaxFactor |\n| Ch.5 pigeons on the window ledge get noisy; the librarian comes to shoo them | No (standing near the window when she comes = a warning) | Adds *keep away from the windows* when the flock gets loud | every 40–60 s, pigeonNear=2.6 | ArchiveDirector.pigeonEvery, ArchiveDirector.pigeonNear |\n| Ch.5 research must be complete: SEARCH all 8 words (progress n / 8 in the objective) | Win changes (record read AND all 8 words searched) | Adds *gather every word before the ending* | 8 words | ArchiveDirector.AllWords |\n| Inspection Day moves to Ch.6 (Friday, \"day five\") | No (same two endings) | No | — | Level04Director |\n| Ch.6 desk inspection + final choice | Win splits into two endings (hide it / send it to everyone) | Adds *decide* | choiceSeconds=14, inspectionFallbackSeconds=100 | Level04Director.choiceSeconds, Level04Director.inspectionFallbackSeconds |\n| 2x story speed (Tab / title button) | No | No (player-chosen pacing of dialogue and waits; watchers' timers you play against stay real-time, except the Ch.3 warden) | Factor 2 | GameSpeed.Factor |\n","devlog":"# DEVLOG\n\nOnly append. Do not edit old sections. Two samples stay so students can see the format.\n\nOnly changes to the game itself are logged: the verb, win and loss, pressure, and what the player can feel.\nSite language, diagram styling, and click-to-read-script do not go into an Interaction or a Stage Reflection.\n\nEach gameplay change should add a section `## Interaction NNN — title` (the Agent can append this when it changes the game).\nAdd `## Stage Reflection NNN — title` only when you ask for one: Keep / Change / Cut, and which AI suggestions you accepted or rejected. That reflection stays on the game.\n\n## Interaction 000 — EXAMPLE (sample, do not delete)\n\n- Date: —\n- Who asked: teacher (sample)\n- Request: Tighten one tunable and see if it is still the same game.\n- What changed: Sample only. The current code was not changed. A real change would touch only one `@tune` field.\n- Result: The player's verb did not change. Win and loss did not change. Pressure changed, not the skeleton.\n\n## Stage Reflection 000 — EXAMPLE (sample, do not delete)\n\n### Keep\n- A core verb you can say in one sentence, and a clear win/loss.\n\n### Change\n- To make it harder, turn an existing `@tune` first. Do not add a new system yet.\n\n### Cut\n- No shop, no deep inventory, no optimization that is off-lesson.\n\n### AI\n- Accept: tune feel with existing fields; avoid opening new scripts.\n- Reject: GraphView, object pools, long hand-written scene YAML. This class is about script relationships and tunable numbers.\n\n## Interaction 001 — White box: school blockout kit\n\n- Date: 2026-09-28\n- Who asked: Ariel & Nina\n- Request: Build a white-box school from modular prefabs (classroom, corridor, cafeteria) using player metrics from The Level Design Book.\n- What changed: Blockout kit (walls, doors, windows, desks, figures, a security camera, a patrolling teacher) and the Blockout_School scene. The player sits in the back corner seat by the window.\n- Result: The core verb was set: watch the teacher, then use the phone when he can't see you. Classmates and pillars act as cover. There was no win or loss yet.\n\n## Interaction 002 — Chapter 1 \"The Lesson\": you can win, you can lose\n\n- Date: 2026-10-12\n- Who asked: Ariel & Nina (assignment: \"You can win, you can lose\")\n- Request: Make one level with a clear win and loss, Inside-style (no HUD hearts).\n- What changed: The player is pulled to their seat, then finds a phone behind a loose panel in the desk. The passcodes come from the lecture (founding year 1952; lights-out 21:00 = 2100). The teacher walks on a NavMesh and asks questions about what he already said. A Photos clue leads to the student in front: tap their shoulder to win. If he sees the phone, the phone shakes and turns red. Three warnings means he takes the phone and you lose.\n- Result: Win (contact made) and loss (phone taken) now exist. The verbs are watch, peek, act and hide. The danger meter (`LevelDirectorBase.noticeSeconds`) controls the pressure.\n\n## Interaction 003 — Playtest feedback round (Chapter 1)\n\n- Date: mid-October 2026\n- Who asked: Ariel & Nina (playtest notes)\n- Request: The hearts read as too gamey, subtitles overlapped, the entrance felt stiff, and it was unclear where to look.\n- What changed: Removed the hearts; the three chances are now only spoken by the teacher. Only one subtitle shows at a time (teacher at the top, thoughts at the bottom-left). The player types their name and the teacher reads it in a roll call. The rules are told through thoughts during the roll call. The phone is lower and bigger. Being noticed shows as the phone shaking and turning red.\n- Result: Win/loss unchanged. The verb is unchanged, but the player now learns the rules before the pressure starts.\n\n## Interaction 004 — Four chapters, a story and an art pass\n\n- Date: 2026-10-19\n- Who asked: Ariel & Nina (cultural aesthetic: anti-utopian + dark humour)\n- Request: Apply the Clearview Academy style and grow the game to about 20 minutes, with a beginning, an ending, chapters and win/loss.\n- What changed: Ch.2 Lunch (security camera + Lunch Monitor; find the girl who hums by sound; reach the STAFF door). Ch.3 Lights Out (a night warden you track by footsteps and keys; hold Space to pretend to sleep; flash the window three times). Ch.4 Inspection Day (the 1979 photo shows Instructor Voss sat in the same seat; the final choice is to hide it or send it to everyone, giving two endings). Added a title page with Continue and Chapters, an end page after every chapter, and retry-from-chapter. Added procedural textures, fluorescent lights, posters, cameras with blinking LEDs, PA announcements and generated sound.\n- Result: Each chapter keeps the same verb but adds a new watcher: a camera, a roaming monitor, a guard you can only hear. The loss is the same each time (three warnings). The win changes per chapter, and the final win is a choice between two endings.\n\n## Interaction 005 — Guidance: an objective panel and the hum by distance\n\n- Date: 2026-10-19\n- Who asked: Ariel & Nina (stuck at \"find the girl by the window\" in Ch.2)\n- Request: Players did not know where to go or what to do next.\n- What changed: An always-on OBJECTIVE panel (top-left) states the next step and where to go. In Ch.2, the humming now fades in only within 6.5 m (`HumSource.maxDistance`). Hints play when you get close, you can press E on her, and a signal line shows while the phone is up (within `Level02Director.reachDistance`). F8 skips a chapter for playtests.\n- Result: Same game, but guided. Getting stuck no longer replaces the tension.\n\n## Interaction 006 — Stairs you walk down; random bed checks; a shorter finale\n\n- Date: 2026-10-19\n- Who asked: Ariel & Nina\n- Request: The stairs behind the STAFF door felt fake. The warden was predictable. Chapter 4 had dead time.\n- What changed: Ch.2 ends with the player walking down a real stairwell (painted \"WE KEEP THINGS FROM EACH OTHER\", chalk \"SEAT 31\" years) to a door with voices behind it. Ch.3 bed checks are picked from six events, and the same one never comes twice in a row. Ch.4 inspects only four desks, and the ending LIGHTS finally shows the room at the bottom of the stairs, where Voss closes the door from the outside.\n- Result: Win/loss unchanged. The story now pays off the stairs from Ch.2 in the last scene.\n\n## Interaction 007 — Pacing and feedback polish\n\n- Date: 2026-10-20\n- Who asked: Ariel & Nina\n- Request: Too many warden visits in Ch.3. The PA box looked like a phone notification. There was no notification for new messages.\n- What changed: The warden now waits 24–38 s between visits and fewer visits come into the room. PA lines use the normal dark subtitle style. The phone shows a real new-message notification at the bottom while it is down.\n- Result: There is more room to act in Ch.3. Same verbs and same win/loss.\n\n## Interaction 008 — The climax sounds like a climax\n\n- Date: 2026-10-23\n- Who asked: Ariel & Nina\n- Request: When every phone lights up (ending LIGHTS), the sound should feel big. The crack on the phone screen went outside the glass.\n- What changed: The room goes quiet and a chord swells. Each phone rings its own rising note as it lights, faster and faster, then a large open chord blooms. The phone screen now clips its contents.\n- Result: The emotional peak of the game is louder than any warning. Gameplay is unchanged.\n\n## Interaction 009 — The climax: freedom, but lonely\n\n- Date: 2026-10-23\n- Who asked: Ariel & Nina\n- Request: The climax sound felt too positive. It should feel liberating but desolate, a little solemn but not heroic.\n- What changed: The rising chord is now A minor (add9). The phones ring up a minor pentatonic scale, softer and slower. The final chord has open fifths and ninths with no third (neither happy nor sad), swells in instead of hitting, and fades into wind. One distant bell is answered a step lower.\n- Result: Gameplay is unchanged. The ending now reads as release with a cost, which fits Voss closing the door from the outside.\n\n## Interaction 010 — Apps unlock in chapter order, \"???\" hints, Chinese version\n\n- Date: 2026-10-24\n- Who asked: Ariel & Nina\n- Request: Each chapter should unlock one phone app, so the apps should be listed in unlock order. A passcode hint should read \"???\" until the player reaches the chapter that unlocks it. Add a Chinese version that can be switched at the start.\n- What changed: The home screen now lists the apps in unlock order (1 Photos, 2 Messages, 3 Contacts, 4 Camera, 5 Search), each with its number. A hint shows \"Hint: ???\" until the current chapter is the app's chapter or later. Camera and Search have codes ready for the coming chapters. The title page has a Language button (English / 中文, saved). Every story line, phone text, poster, lesson question and end page has a Chinese version and uses a Chinese system font.\n- Result: Win/loss and player verbs are unchanged. Later apps no longer give their answers away early. Chinese players can now play and read the posters.\n\n## Interaction 011 — No more flickering faces on the characters\n\n- Date: 2026-10-24\n- Who asked: Ariel & Nina\n- Request: Two faces of a character model should not lie exactly on top of each other, because that flickers (z-fighting).\n- What changed: After a student or adult is dressed, the scene builder checks every pair of box parts. If two faces lie in the same plane and face the same way (for example the hair top and the back hair, or a part flush with the body block), the smaller part grows by 3 mm on that axis. Scene version 15.\n- Result: Gameplay is unchanged. Characters no longer flicker when the camera moves.\n\n## Interaction 012 — Collar redesign, Chinese names, faster roll call\n\n- Date: 2026-10-25\n- Who asked: Ariel & Nina\n- Request: The collar still overlapped the clothes and flickered. Character names should be Chinese in the Chinese version. Roll call in Ch.1 should be tighter.\n- What changed: The collar is now a skin neck, a collar band that sits 5 mm inside the torso, and two tilted collar points. The anti-flicker check now also counts the white-box body. Roll-call names and VOSS have Chinese names. Each name + \"Here\" takes about 3.5 s instead of 6.5 s, and the gaps between lines are shorter.\n- Result: Gameplay is unchanged. Ch.1 gets to the lesson faster.\n\n## Interaction 013 — Two new chapters, readable posters, the Third Wave homage\n\n- Date: 2026-10-25\n- Who asked: Ariel & Nina\n- Request: Add chapters so every phone app gets used, one app per chapter. Every text in the game should mean something (a clue or an easter egg), and posters should respond when the player reads them. Base the background on a real event in education as an homage.\n- What changed: The game now runs Monday to Friday over six chapters, after the Third Wave experiment (Palo Alto, April 1967). New Ch.4 Picture Day (Camera, 1045): photograph the report board, the empty LIVE screen and the 1967 photo while prefects report you, the shutter can be heard and the flash can be seen; then stand in the class photo. New Ch.5 The Archive (Search, 0467): the librarian's noise meter; Search only knows words you have read; 1967 → DAY FIVE → drawer 31 tells what happened in 1967. Inspection Day is now Ch.6. Every poster in every chapter can be read (walk up and look); it gives a thought, a clue, a Search word, or changes as you read it.\n- Result: Two new wins and new verbs (photograph, move quietly, search with words you read, read the walls). The loss is still three warnings. The two endings are unchanged.\n\n## Interaction 014 — Picture Day as a rhythm, silent mode and old books, the 1952 homage\n\n- Date: 2026-10-25\n- Who asked: Ariel & Nina\n- Request: Ch.4 scenery flickered (overlapping surfaces), and everyone sat still while only the player moved. Make the class walk about, call a class photo every so often (get to your place, smile), and allow the phone only in the gaps. The flash should switch back on every time the phone comes out. In Ch.5, a message should give you away first, then you learn about silent mode; then footsteps; the target book should sit with the old books awaiting repair, which students may not touch; turning its pages should be noisy, and noisier when fast. Also give the roll-call names a historical meaning.\n- What changed: An anti-flicker pass now runs over every chapter, so no two boxes share a face. Ch.4: fifteen students roam the gym. Every 40–55 s a 20 s countdown starts and everyone walks to the risers. The player must be on the \"31\" spot, phone down, standing still and holding SPACE to smile, or it is a report (a warning); the photographer always finds a reason to retake. The camera flash resets to ON on every raise. Ch.5: the first message buzzes and the librarian comes (a warning). Only then is the phone's little bell explained: silent mode, M. Then the noise meter: walk, Ctrl/C to walk quietly, Shift to run. Records vol. 31 sits among the old books awaiting repair: open it and turn the pages with A/D; each page rustles louder than a step, and fast turns are much louder; being seen there is a warning. The roll call is now Irving Adler, Harry Keyishian, Ellwood Cubberley and Bert (Feinberg Law 1952 / Keyishian 1967 / Cubberley / \"Duck and Cover\" 1952). Searching \"1952\" finds the court-ruling record.\n- Result: Ch.4 adds *be where you're told, on time* and *smile*. Ch.5 adds *silence the phone*, *sneak* and *read slowly*. Loss is still three warnings.\n\n## Interaction 015 — Clearer girls and boys, a moving X, faster countdown, Chinese text pass\n\n- Date: 2026-10-26\n- Who asked: Ariel & Nina\n- Request: Make girl and boy models clearer; girls should not look like they have a beard. In Ch.4 the X on the floor should move between photos, and the class-photo countdown should be faster (the gaps between photos stay the same). Fix Chinese grammar, and keep Chinese text inside its boxes (wrap).\n- What changed: The mouth was a dark bar under the nose, which read as a moustache. Girls now have rose lips, blush and lashes; boys have a thin skin-toned mouth. Girls' side hair hangs behind the ears instead of along the jaw. Standing students (Ch.4) are now schoolgirls (long hair or ponytail, bow, skirt, white socks) or schoolboys (school tie, grey trousers). Ch.4: the yellow X (with a small flag) moves to a random place on the risers before every photo, and the objective says where it is. The countdown is 12 s (was 20), and the students walk faster during it. Chinese: names unified (三角, 午餐监督员, 304 寝室), awkward lines rewritten, and the old \"drawer 31\" reference corrected to vol. 31. Subtitle and thought boxes grow with their text; phone texts shrink to fit.\n- Result: Ch.4 gets tighter: you have to find a new spot each time, in less time. Win/loss unchanged.\n\n## Interaction 016 — No \"moustache\" on the girls, prefects need to be close\n\n- Date: 2026-10-26\n- Who asked: Ariel & Nina\n- Request: Girls still had something above the lips that looked like a moustache. In Ch.4 a photo almost always set off a prefect warning; a prefect should have to stand close.\n- What changed: Girls' nose is now small, skin-coloured and casts no shadow (its shadow above the lip read as a moustache). A prefect now hears the shutter only within 2.2 m (was 4.5 m), and prefects see 6 m in a 90° cone (was 8 m, 100°).\n- Result: Ch.4 is easier. Photograph when no armband is right next to you. Win/loss unchanged.\n\n## Interaction 017 — Real eyes, the final photo spot, an unreliable silent switch\n\n- Date: 2026-10-26\n- Who asked: Ariel & Nina\n- Request: The final class photo should use the spot the text names (back row, by the window). No dark rectangle on girls' faces. The spot should be only an X, no flag. In Ch.5 page turns should fill the meter more, a second librarian should patrol, and silent mode should fail at random, without the player knowing when.\n- What changed: The white-box eye band, a dark bar that sat low on the standing figures and read as a moustache, is gone. Every figure now has two eyes with a glint; girls also get lashes, blush, rose lips and a small nose. Ch.4: the first and the final photo always use back row, window end, and the flag is removed. Ch.5: a page turn now adds 0.16 to the meter (was 0.09), and ×2.6 if fast. An assistant librarian walks the aisles all the time. Each time the phone comes out, silent mode has a 30% chance of quietly switching off; only the grey bell shows it. The school's alerts arrive every 28–45 s and buzz if it has failed.\n- Result: Ch.5 is harder (check the bell every time, two watchers). Ch.4 ending matches the text. Win/loss unchanged.\n\n## Interaction 018 — Dazed students\n\n- Date: 2026-10-26\n- Who asked: Ariel & Nina\n- Request: Remove the eye highlights, make the black eyes bigger and taller than they are wide, and make the students look more dazed.\n- What changed: Eyes are now plain black, tall narrow rectangles (no glint). Students, seated and the standing schoolchildren, have eyes set wider apart, raised short brows and a tiny mouth. Adults keep normal faces.\n- Result: Look only. Gameplay is unchanged.\n\n## Interaction 019 — 2x story speed, faster roll call, full library research, a courtyard for the lesson\n\n- Date: 2026-11-02\n- Who asked: Ariel & Nina\n- Request: Make the roll call much faster. Add a 2x speed for all dialogue, messages and waiting (for example the lights-out waits). Get the player into the lights-out chapter's first step sooner. Check that no wall posters overlap. Everything the dialogue or text mentions (pigeons, the left-handed moustache) must be in the world, or the text goes. In the library, every word must be searched before the chapter ends, with progress in the objective.\n- What changed: Tab (or the title-screen button \"Story speed\") switches 1x / 2x and is remembered. 2x speeds up line timing, the typewriter, message reading and typing, scripted waits, lesson pacing, PA timers, the warden's rest between visits (Ch.3), and the Ch.4 free time after your photos are sent. Timers you play against (answer timer, photo countdown, noise) stay real-time. Roll call: each name is now 1.0 s and each \"Here\" 0.8 s, with gaps of 0.1–0.15 s. Ch.3 opens with one instruction line (hold SPACE when he comes in), and the first message comes after about 3 s. Ch.5: all 8 search words must be searched; the objective shows \"SEARCHED n / 8\" with a checklist, and unknown words show as ???. The classroom now has the Founding Charter (four rules), the founder's portrait with a pencil moustache whose curls are drawn left-handed, and the wall bell. Outside the west windows there is a courtyard with the founder's oak and pigeons on the ledges, the grass and a branch. All of these can be read by looking at them. Ch.6 adds \"SINCE 1953\" to the banner and a \"LAST YEAR: 412 ITEMS FOUND\" poster. Each desk Voss inspects now shows what he names: pencils, a horse drawing, nothing, a 'help' note. He takes away what he confiscates. Unused verdicts (gum, eraser) were removed. Posters checked: no overlaps. The two classroom hits from the checker were posters in different chapters, and the corridor sign is on a closed door. ScenesVersion is now 24.\n- Result: Same win and loss conditions in every chapter except Ch.5, which now ends only after all 8 words are searched and the record has been read. 2x is optional.\n\n## Interaction 020 — Fix: Chinese font atlas overflow on chapter load\n\n- Date: 2026-11-02\n- Who asked: Ariel & Nina\n- Request: Starting a chapter showed \"Failed to update dynamic font (PingFang SC) texture; all the needed characters do not fit onto a single texture (max size 4096)\".\n- What changed: Wall posters use world-space canvases laid out at 1000 units per metre. They rendered their letters at 3x that size, so a banner title became a glyph of several hundred pixels. With the larger Chinese text added (Charter, posters), the shared Chinese font texture filled up. Posters now render text at 0.5 texture px per unit (500 px per metre). This is set at runtime in `TypewriterFont`, so existing scenes are fixed without a rebuild, and new ones get it from `UIFactory.MakeWorldCanvas`.\n- Result: Look only (poster text slightly softer up close). Gameplay unchanged.\n\n## Interaction 021 — Posters that change, pigeons with a job, Voss's beard, a basement that turns its head\n\n- Date: 2026-11-02\n- Who asked: Ariel & Nina\n- Request: Posters should have an easter egg when you walk up to them: smile posters show an uncanny smile, glitch-related ones glitch, lunch posters show an inedible lunch, uniform or photo posters slowly become a mirror (with a neutral player model), red-X posters become a red X, and Voss posters become Voss. Give Voss a full beard as the only one in the school. Ch.3 should get to the phone faster. In Ch.1, the desk search should open right after the player answers roll call. The Ch.4 photo countdown goes from 10 s to 7 s. The pigeons should carry through the game and matter later: in the library the librarian goes to the window to shoo them, warns you if you are close, with set-up beforehand and soft coo sounds. The library walking noise should climb exponentially. Ch.6 sending the message should move faster afterwards, while Voss's verdicts get longer pauses. Boys' side fringe should connect to the top hair. In the basement, everyone slowly turns to look at Voss and turns back after he closes the door, and the phone stays usable with everyone chatting on it.\n- What changed: New `PosterEgg` (built per poster name by `AddEggs`):\n  - Smile: Poster_Smile, Poster_WholeFace. A symmetric toothy smile with blank eyes that follow you.\n  - Glitch: Sign_Devices, Sign_LiveAddress, Banner_DaysSinceIncident, Sign_NotHere. Colour ghosts, jitter, scrambled letters and a soft glitch sound.\n  - Lunch: Poster_Menu, Poster_Privilege. A grey tray, grey food, a hair in the soup and a fly.\n  - Mirror: Poster_Uniform, Poster_CitizenCard, Photo_1967. A render-texture mirror of the player.\n  - Red X: Poster_CardsReady. The text turns red, then a red X is drawn.\n  - Voss: Poster_InspectedDesk, Display_Yearbook1980. His bearded portrait, with eyes that follow you.\n\n  Other changes:\n  - Player model: a neutral body (straight bob, uniform, trousers) on layer 30. Only mirrors render it; the player's camera skips it.\n  - Voss: a full beard on him in the classroom and in the basement doorway.\n  - Hair: boys' fringe now overlaps the top hair, so there is no gap.\n  - Ch.1: the desk cubby unlocks right after \"Here\".\n  - Ch.3: the opening authority line is merged, the girl walks off without being waited for, the first bed check is shorter, and message gaps are shorter.\n  - Ch.4: callSeconds is 7.\n  - Pigeons: synthesized coo and wing-flap sounds, soft (3D, max 9 m), on ledges in the courtyard, gym and library.\n  - Ch.2: a new PA line, \"Do not feed the pigeons. Pigeons are loud. Loud things are noticed.\"\n  - Ch.5 pigeons: Triangle warns \"stay off the windows\". Every 40–60 s the flock gets noisy and the librarian walks to the window to shoo them. Within 2.6 m of the window spot during her 4 s there = a warning.\n  - Ch.5 noise: walking without a break doubles the noise rate every 2 s, up to 5x. Quiet steps don't count.\n  - Ch.6: each verdict now shows 4.2 s plus a 3.6 s silence. Lines after the send are about 35% shorter.\n  - Basement: head parts are re-parented to a neck pivot so heads turn one after another towards the door and back. The phone stays usable and a group chat arrives.\n\n  ScenesVersion is now 25.\n- Result: Ch.5 is harder (exponential noise, pigeon events). Ch.4's photo call is tighter. The other changes are atmosphere and pacing. Win/loss conditions are unchanged.\n\n## Interaction 022 — Staring pigeon, faster lesson, landscapes outside every window\n\n- Date: 2026-11-02\n- Who asked: Ariel & Nina\n- Request: The pigeon must actually stare when the text says it does. The Ch.1 lecture and the chalk-triangle exchange were still too slow at 1x. The librarian should not walk onto her desk. The smile poster should have no teeth, only big eyes, a big mouth and dimples. Fix the overlapping door signs in Ch.2 and check every sign in the game. Posters should change more slowly, after the player has read them. At 2x speed the Ch.3 warden should walk faster too. The windows should show trees and buildings, not an empty plane.\n- What changed:\n  - Pigeon: one ledge pigeon (`starer`) turns and stares at you within 12 m.\n  - Ch.1: lecture lines now last 2.4–5 s depending on length (was 7.5 s, plus a 4.4 s pause). The pause between lines is 1.1 s plus 0.25 s. The shoulder-tap scene is about half as long.\n  - Library: the desk, returns cart, shelves and crates are Not Walkable in the NavMesh, and the librarian's desk spot moved to z 1.5.\n  - Smile egg: no teeth. Big eyes, a thick arc mouth, dimples and blush.\n  - Ch.2: \"IN SESSION\" now hangs on the back door itself, clear of the CLASSROOM 1 plaque. All scene signs were rechecked and there are no other overlaps.\n  - Poster eggs: a poster only starts to change after you have looked at it for a reading time (2.5–7 s by text length), then changes over 5–7 s.\n  - Ch.3: at 2x the warden's walking speed and pauses scale too (`PatrolAI.timeScale`).\n  - New `Backdrop` in every scene: lawn, a school wall 16 m out, about 46 trees 4.5–14 m out, and about 12 buildings 24–36 m out (lit windows at night). Nothing is placed inside the playable rectangle, and nothing has colliders.\n  - ScenesVersion is now 26.\n- Result: Pacing and look only. Win/loss unchanged.\n\n- Follow-up (same day): poster eggs a little faster - reading time 1.5-4.5 s (was 2.5-7), change 3 s (mirror / Voss 4.5 s, glitch 0.8 s).\n- Follow-up: poster eggs now start counting only while the crosshair is ON the poster (from up to 3-5 m), then keep changing while you look its way. Reading time 0.8-2.2 s, change 1.8 s (mirror / Voss 2.5 s, glitch 0.5 s).\n- Follow-up: trigger back to the original (within 2-3.6 m and within 38 degrees of the view centre; not crosshair-only). The faster timings stay (reading 0.8-2.2 s, change 1.8 s / 2.5 s / 0.5 s).\n- Follow-up: poster eggs faster again at 1x - reading 0.4-1.2 s, change 1 s (mirror / Voss 1.4 s, glitch 0.3 s); 2x story speed doubles both. More glitch posters, mostly the ones that insist on a date: Poster_Catalogue (1967), Poster_BannedBooks (1981), Poster_Founding (1952), Sign_LightsOut (21:00), Banner_PictureDay (10:45), Poster_Counting, Sign_Repair. The table now lives in PosterEgg.Table and is also applied at runtime (PosterEgg.InstallAll), so no rebuild is needed.\n- Follow-up: Ch.4 class-photo countdown back to 10 s (callSeconds). ScenesVersion 27.\n","scripts":{"AmbientAudio":{"path":"Assets/Game/Scripts/AmbientAudio.cs","role":"Background sound: drone, ventilation, the danger layer that rises when you are seen, sudden silence on a warning","source":"// @role Background sound: drone, ventilation, the danger layer that rises when you are seen, sudden silence on a warning\n// @calls AudioSynth\n// @tune droneVolume:float:0-0.5:background drone level\n// @tune ventVolume:float:0-0.5:ventilation hum level\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The level's background sound: a slow drone + ventilation hum, a dissonant layer that rises with danger,\n    /// and \"sudden silence\" (Duck) when a rule is broken. Also plays 2D one-shots (chimes, stingers, ticks).\n    /// Created at runtime by the level director.\n    /// </summary>\n    public class AmbientAudio : MonoBehaviour\n    {\n        public float droneVolume = 0.16f;\n        public float ventVolume = 0.09f;\n        public float extraVolume = 0f;\n        [Range(0f, 1f)] public float dangerLevel;\n\n        AudioSource drone, vent, danger, extra, sfx, voice;\n        float duck = 1f, duckHold;\n\n        public static AmbientAudio Create(Transform parent)\n        {\n            GameObject g = new GameObject(\"AmbientAudio\");\n            g.transform.SetParent(parent, false);\n            return g.AddComponent<AmbientAudio>();\n        }\n\n        AudioSource Loop(AudioClip clip)\n        {\n            AudioSource s = gameObject.AddComponent<AudioSource>();\n            s.clip = clip;\n            s.loop = true;\n            s.spatialBlend = 0f;\n            s.playOnAwake = false;\n            s.volume = 0f;\n            if (clip != null) { s.time = Random.Range(0f, clip.length * 0.9f); s.Play(); }\n            return s;\n        }\n\n        void Awake()\n        {\n            drone = Loop(AudioSynth.Drone());\n            vent = Loop(AudioSynth.Ventilation());\n            danger = Loop(AudioSynth.DangerLayer());\n            extra = gameObject.AddComponent<AudioSource>();\n            extra.loop = true;\n            extra.playOnAwake = false;\n            sfx = gameObject.AddComponent<AudioSource>();\n            sfx.playOnAwake = false;\n            voice = gameObject.AddComponent<AudioSource>();\n            voice.playOnAwake = false;\n        }\n\n        /// <summary>An extra 2D loop for the level (e.g. sleeping students breathing).</summary>\n        public void SetExtraLoop(AudioClip clip, float volume)\n        {\n            extra.clip = clip;\n            extraVolume = volume;\n            if (clip != null) extra.Play(); else extra.Stop();\n        }\n\n        /// <summary>Everything goes silent for a moment.</summary>\n        public void Duck(float seconds) { duckHold = Mathf.Max(duckHold, seconds); }\n\n        public void Play(AudioClip clip, float volume, float pitch = 1f)\n        {\n            if (clip == null) return;\n            if (Mathf.Abs(pitch - 1f) < 0.001f) { sfx.PlayOneShot(clip, volume); return; }\n            voice.pitch = pitch;\n            voice.PlayOneShot(clip, volume);\n        }\n\n        void Update()\n        {\n            if (duckHold > 0f) duckHold -= Time.unscaledDeltaTime;\n            duck = Mathf.MoveTowards(duck, duckHold > 0f ? 0f : 1f, Time.unscaledDeltaTime * (duckHold > 0f ? 6f : 0.6f));\n            drone.volume = droneVolume * duck;\n            vent.volume = ventVolume * duck;\n            danger.volume = Mathf.Clamp01(dangerLevel) * 0.32f * duck;\n            extra.volume = extraVolume * duck;\n            AudioListener.volume = Mathf.Lerp(0.35f, 1f, duck);   // the whole room goes quiet, not only the music\n        }\n\n        void OnDestroy() { AudioListener.volume = 1f; }\n    }\n}\n"},"ArchiveDirector":{"path":"Assets/Game/Scripts/ArchiveDirector.cs","role":"Chapter 5 The Archive (Thursday): a buzz gives you away -> SILENT MODE (the little bell, M); the noise meter (footsteps, Ctrl = quiet); the oldest book's stamp (SEARCH = 0467); search words you READ; the old books awaiting repair - turning the pages is louder than walking","source":"// @role Chapter 5 The Archive (Thursday): a buzz gives you away -> SILENT MODE (the little bell, M); the noise meter (footsteps, Ctrl = quiet); the oldest book's stamp (SEARCH = 0467); search words you READ; the old books awaiting repair - turning the pages is louder than walking\n// @calls LevelDirectorBase, PatrolAI, TeacherVision, PhoneController, Readable, Interactable, AudioSynth, Pigeon\n// @tune walkDoubling:float:0.5-6:walking without a break doubles the noise rate every this many seconds\n// @tune walkMaxFactor:float:1-10:cap on that build-up\n// @tune pigeonNear:float:1-5:closer than this to the window when she comes to shoo the pigeons = a warning (m)\n// @tune noiseWalk:float:0-0.3:meter per second while walking\n// @tune noiseSneak:float:0-0.1:meter per second while walking quietly (Ctrl / C)\n// @tune noiseRun:float:0.1-1:meter per second while running (Shift)\n// @tune noiseDecay:float:0.05-0.5:meter drain per second while standing still\n// @tune flipNoise:float:0.02-0.4:meter per page turned (slow)\n// @tune silentFailChance:float:0-1:chance the silent switch quietly fails each time the phone comes out\n// @tune fastFlipFactor:float:1-5:a page turned within fastFlipSeconds of the last one is this much louder\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 5 \"The Archive\" (the library in the Cubberley Wing, Thursday after school - \"day four\").\n    ///  1. The first message BUZZES out loud. The librarian comes looking: a warning. Only now does anyone mention the\n    ///     little bell in the corner of the phone screen: SILENT MODE (phone up, M).\n    ///     The old switch is unreliable: each time the phone comes out it may switch itself off (only the bell shows it),\n    ///     and the school's alerts arrive every half minute or so.\n    ///  2. Then the NOISE METER (top right): walking fills it, running (Shift) fills it fast, walking quietly\n    ///     (Ctrl / C, half speed) barely; standing still drains it; closer to her = louder. Full = \"Shhh.\" = a warning.\n    ///     A message arriving while the phone is NOT silent = a loud spike.\n    ///  3. SEARCH, code = the stamp in the oldest book on the returns cart: RECEIVED APR 1967 -> 0467.\n    ///     Search only knows words you have READ: 1967 -> DAY FIVE -> \"Records, vol. 31\", shelved with the OLD BOOKS\n    ///     AWAITING REPAIR (north-east, behind the rope). Students may not touch them.\n    ///  4. Open it and turn the pages (A / D). Every page RUSTLES - louder than footsteps, and much louder if you turn\n    ///     them fast. Being seen there, or with the book, = a warning (and you're sent out). Read to the last page. WIN.\n    /// </summary>\n    public class ArchiveDirector : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public PatrolAI librarian;\n        public TeacherVision librarianVision;\n        [Tooltip(\"A second librarian who walks the aisles the whole time.\")]\n        public PatrolAI assistant;\n        public TeacherVision assistantVision;\n        public Transform deskSpot;\n        public Interactable returnsCart;\n        public Interactable oldBook;\n\n        [Header(\"Zones\")]\n        [Tooltip(\"The old books awaiting repair, behind the rope (x min, z min, x max, z max). Students may not be seen here.\")]\n        public Vector4 restrictedZone = new Vector4(9.8f, 9.7f, 14f, 12f);\n        public Vector3 restrictedReturn = new Vector3(8f, 0f, 8.6f);\n\n        [Header(\"Noise meter\")]\n        public float noiseWalk = 0.08f;\n        public float noiseSneak = 0.012f;\n        public float noiseRun = 0.45f;\n        public float noiseDecay = 0.12f;\n        public float nearLibrarian = 6f;\n        public float buzzNoise = 0.6f;\n\n        [Header(\"Turning pages\")]\n        public float flipNoise = 0.16f;\n        public float fastFlipSeconds = 0.7f;\n        public float fastFlipFactor = 2.6f;\n        [Header(\"Pigeons (west window ledges)\")]\n        [Tooltip(\"Inside the windows: where the librarian stands to shoo the pigeons.\")]\n        public Transform pigeonSpot;\n        [Tooltip(\"Seconds between the flock getting noisy.\")]\n        public Vector2 pigeonEvery = new Vector2(40f, 60f);\n        [Tooltip(\"Closer than this to the window when she comes = a warning.\")]\n        public float pigeonNear = 2.6f;\n        [Tooltip(\"Walking without a break: the noise rate doubles every this many seconds (capped).\")]\n        public float walkDoubling = 2f;\n        public float walkMaxFactor = 5f;\n        [Header(\"Silent mode (unreliable)\")]\n        [Range(0f, 1f)] public float silentFailChance = 0.3f;\n        public Vector2 alertEvery = new Vector2(28f, 45f);\n\n        bool firstBuzz, silentOn, meterOn, stampRead, unlocked, foundRecord, finished, toldRaise, toldSearchWords, toldSneak, toldFlip, toldMeter;\n        bool bookOpen, toldSilentFail, bookRead, toldResearch;\n        /// <summary>Every word that can be found in the library. The chapter ends only when ALL have been searched.</summary>\n        static readonly string[] AllWords = { \"CLEARVIEW\", \"1952\", \"1967\", \"DAY FIVE\", \"STRENGTH\", \"THE WAVE\", \"VOSS\", \"RED X\" };\n        readonly System.Collections.Generic.HashSet<string> searched = new System.Collections.Generic.HashSet<string>();\n        bool AllSearched { get { return searched.Count >= AllWords.Length; } }\n\n        /// <summary>\"Searched 3 / 8: [x] CLEARVIEW  [x] 1967  [ ] ??? ...\" - unknown words stay ??? until you've read them.</summary>\n        string Progress()\n        {\n            string o = L(\"SEARCHED \", \"已搜索 \") + searched.Count + \" / \" + AllWords.Length + \"\\n\";\n            int col = 0;\n            foreach (string w in AllWords)\n            {\n                bool known = phone.searchWords.Contains(w);\n                o += (searched.Contains(w) ? \"[x] \" : \"[  ] \") + (known ? Loc.T(w) : \"???\");\n                o += (++col % 2 == 0) ? \"\\n\" : \"    \";\n            }\n            return o.TrimEnd();\n        }\n        int page;\n        float lastFlip = -9f, pageDwell;\n        float noise, noiseGrace, zoneSeen, zoneGrace, routeTimer = 18f, speed, walkStreak, pigeonTimer = 30f;\n        bool pigeonBusy, toldPigeons;\n        Vector3 lastPos;\n        Image meterFill;\n        Text meterLabel;\n        GameObject meterRoot, bookRoot;\n        Text bookText, bookPage, bookHelp;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"LIBRARIAN\";\n            authorityPitch = 1.15f;\n            phone.hasPhone = true;\n            phone.allowRaise = false;\n            phone.phoneClock = \"15:31\";\n            phone.showOldPhoto = false;\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.appUnlocked[PhoneController.AppMessages] = true;\n            phone.appUnlocked[PhoneController.AppContacts] = true;\n            phone.appUnlocked[PhoneController.AppCamera] = true;\n            phone.silentAvailable = false;\n            phone.silent = false;\n            phone.lockNotification = L(\"No new messages.\", \"没有新信息。\");\n            phone.AddHistory(\"Triangle\", L(\"got them. look at the board again: 20 reports. 3 reporters.\", \"收到了。再看看那块板：20 份举报。3 个举报员。\"), false);\n            phone.AddHistory(\"Hums When Scared\", L(\"my card has no X. I checked twice.\", \"我的卡上没有 X。我检查了两遍。\"), false);\n            phone.onMessageArrived = OnMessage;\n            phone.onSilentChanged = OnSilent;\n            phone.searchWords.Clear();\n            phone.AddSearchWord(\"CLEARVIEW\");\n            phone.AddSearchWord(\"1952\");\n            phone.searchFunc = SearchResult;\n            phone.onSearched = OnSearched;\n            if (returnsCart != null) { returnsCart.prompt = \"Read the stamp in the oldest book\"; returnsCart.onUse = ReadStamp; }\n            if (oldBook != null) { oldBook.prompt = \"Open the old book (Records, vol. 31)\"; oldBook.onUse = OpenBook; }\n            BuildMeter();\n            BuildBook();\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (librarian != null) librarian.Begin();\n            if (assistant != null) assistant.Begin();\n            lastPos = rig.transform.position;\n            rig.Lock();\n            StartCoroutine(Opening());\n        }\n\n        IEnumerator Opening()\n        {\n            yield return ChapterCard(\"CHAPTER 5\", \"THE ARCHIVE\", \"THURSDAY  -  15:30\");\n            Authority(L(\"Shoes quiet. Voices off. I hear everything in here.\", \"鞋子放轻。声音关掉。这里的一切我都听得见。\"), 4.5f);\n            rig.AllowWalk();\n            Thought(L(\"Thursday, after school. The library is in the Cubberley Wing -\\nthe name on the trophy case. \", \"星期四，放学后。图书馆在库伯利楼——\\n就是奖杯柜上那个名字。\") + Rule(L(\"Same month as that photo.\", \"和那张照片同一个月。\")), 7f);\n            yield return WaitIdle();\n            yield return Wait(2.5f);\n            // the first message: it buzzes. Out loud. In a library.\n            phone.Receive(\"Triangle\", L(\"you're in? good. put your phone on silent first - she hears everything.\", \"进去了？很好。先把手机调成静音——她什么都听得见。\"));\n        }\n\n        // ------------------------------------------------------------------ the buzz, silent mode\n        void OnMessage()\n        {\n            if (phone.silent) return;\n            ambient.Play(AudioSynth.Vibrate(), 0.95f);\n            if (!firstBuzz) { firstBuzz = true; StartCoroutine(FirstBuzz()); return; }\n            if (!meterOn) return;\n            noise = Mathf.Clamp01(noise + buzzNoise);\n            if (phone.silentJustFailed && !toldSilentFail)\n            {\n                toldSilentFail = true;\n                Thought(L(\"It BUZZED. I put it on silent... didn't I?\\nThe little bell is grey again. \", \"它震了！我明明调成静音了……不是吗？\\n小铃铛又变回灰色了。\") + Rule(L(\"The switch is broken - check the bell EVERY time I take it out.\", \"开关坏了——每次拿出手机都要看一眼小铃铛。\")), 8f, true);\n            }\n            else Thought(L(\"It buzzed again. \", \"又震了。\") + Rule(L(\"Silent mode: phone up, M. Check the bell.\", \"静音模式：拿起手机，按 M。看一眼小铃铛。\")), 4.5f, true);\n            phone.silentJustFailed = false;\n        }\n\n        /// <summary>The school's own alerts arrive now and then. If the switch has failed, they buzz.</summary>\n        IEnumerator Alerts()\n        {\n            string[] en =\n            {\n                \"reminder: silence is for everyone.\",\n                \"your library visit is being enjoyed.\",\n                \"a book you have not borrowed is overdue.\",\n                \"please do not read alone.\",\n                \"thank you for being quiet. we can tell.\",\n            };\n            string[] zh =\n            {\n                \"提醒：安静是为了每一个人。\",\n                \"您的图书馆之行正在被享受。\",\n                \"一本您没有借过的书已逾期。\",\n                \"请不要独自阅读。\",\n                \"感谢您保持安静。我们听得出来。\",\n            };\n            int i = 0;\n            while (!ended && !finished)\n            {\n                float t = Random.Range(alertEvery.x, alertEvery.y);\n                while (t > 0f && !ended && !finished) { t -= Time.deltaTime; yield return null; }\n                if (ended || finished) yield break;\n                phone.Receive(\"CLEARVIEW ALERTS\", L(en[i % en.Length], zh[i % zh.Length]));\n                i++;\n            }\n        }\n\n        IEnumerator FirstBuzz()\n        {\n            Authority(L(\"...Whose phone was that?\", \"……那是谁的手机？\"), 3f, true);\n            Thought(L(\"It buzzed. Out loud. \", \"它震了。很响。\") + Rule(L(\"Phone DOWN. Don't move.\", \"放下手机。别动。\")), 4f);\n            if (librarian != null)\n            {\n                Vector3 to = rig.transform.position - librarian.transform.position; to.y = 0f;\n                Vector3 stop = rig.transform.position - to.normalized * Mathf.Min(2.4f, to.magnitude);\n                librarian.Approach(stop, rig.transform);\n                float t = 0f;\n                yield return Wait(0.4f);\n                while (!librarian.HasArrived && t < 8f) { t += Time.deltaTime; yield return null; }\n            }\n            yield return Wait(1.2f);\n            Strike(L(\"In MY library. Silence is for everyone.\", \"在我的图书馆里。安静是为了每一个人。\"));\n            yield return WaitIdle();\n            Authority(L(\"I'll be listening.\", \"我会一直听着。\"), 3f);\n            if (librarian != null && deskSpot != null) librarian.RunRoute(new[] { deskSpot.position }, new[] { 0.2f }, new[] { 0f }, null);\n            routeTimer = 25f;\n            yield return WaitIdle();\n            phone.silentAvailable = true;\n            Thought(L(\"Silent... this phone has a \", \"静音……这部手机有\") + Rule(L(\"little bell\", \"一个小铃铛\")) + L(\" in the corner of the screen. I never needed it before.\\n\", \"，就在屏幕角落。以前从来没用过。\\n\") + Rule(L(\"Phone up, press M.\", \"拿起手机，按 M。\")), 8f);\n        }\n\n        void OnSilent(bool on)\n        {\n            if (!on || silentOn) return;\n            silentOn = true;\n            meterOn = true;\n            meterRoot.SetActive(true);\n            ambient.Play(AudioSynth.Confirm(), 0.25f, 1.4f);\n            phone.silentFailChance = silentFailChance;\n            StartCoroutine(Alerts());\n            Thought(L(\"Silent. ...Now my feet. She hears footsteps too.\\n\", \"静音了。……现在是脚步。她也听得见脚步声。\\n\") + Rule(L(\"HOLD CTRL (or C) to walk quietly.\", \"按住 Ctrl（或 C）轻轻走。\")), 7f, true);\n            StartCoroutine(TriangleAfterSilent());\n        }\n\n        IEnumerator TriangleAfterSilent()\n        {\n            yield return Wait(4f);\n            phone.Receive(\"Triangle\", L(\"better. search opens with the stamp in the oldest book. month and year.\", \"好多了。“搜索”的密码是最旧那本书里的印章。月份加年份。\"));\n            phone.Receive(\"Triangle\", L(\"the oldest book is never on a shelf. it's on the returns cart. nobody ever returns it.\", \"最旧的书从来不在书架上。它在还书车上。从来没人还它。\"));\n            phone.Receive(\"Triangle\", L(\"and stay off the windows. the pigeons get loud, she comes to shoo them, and whoever's standing there gets the blame.\", \"还有，别待在窗边。鸽子一吵，她就会过去赶，站在那儿的人会一起挨骂。\"));\n            phone.Receive(\"Triangle\", L(\"then search what happened in '67.\", \"然后搜一搜 67 年发生了什么。\"));\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            if (finished) return;\n            Vector3 p = rig.transform.position;\n            Vector3 dp = p - lastPos; dp.y = 0f;\n            speed = dp.magnitude / Mathf.Max(0.0001f, Time.deltaTime);\n            lastPos = p;\n\n            PlayerRig.Mode m = rig.CurrentMode;\n            phone.allowRaise = phone.hasPhone && m == PlayerRig.Mode.Walk && !bookOpen;\n            rig.freezeMovement = phone.IsExposed || bookOpen;\n            if (phone.IsExposed && !toldRaise && silentOn)\n            {\n                toldRaise = true;\n                Thought(L(\"While I look at the phone, \", \"看手机的时候，\") + Rule(L(\"I stand still\", \"我站着不动\")) + L(\". Shelves are tall here. Good.\", \"。这里的书架很高。很好。\"), 6f);\n            }\n            if (!unlocked && phone.IsUnlocked(PhoneController.AppSearch))\n            {\n                unlocked = true;\n                Thought(L(\"0467. It opened: the school's catalogue. \", \"0467。打开了：学校的图书目录。\") + Rule(L(\"Search 1967.\", \"搜索 1967。\")), 5f);\n            }\n            if (!toldSearchWords && phone.Screen == PhoneController.PhoneScreen.Search && phone.IsUp)\n            {\n                toldSearchWords = true;\n                Thought(L(\"It only searches words I've \", \"它只能搜我\") + Rule(L(\"read\", \"读到过\")) + L(\" somewhere.\\nPosters, labels, the yearbook... \", \"的词。\\n海报、标签、年鉴……\") + Rule(L(\"Walk up to them and look.\", \"走过去看。\")), 7f, true);\n            }\n            if (bookOpen) UpdateBook();\n            UpdateNoise();\n            UpdateObjective();\n            UpdateDanger();\n            UpdateRestricted();\n            UpdateLibrarianRounds();\n            UpdatePigeons();\n            SetPrompt(m == PlayerRig.Mode.Walk && !bookOpen ? RaycastInteract() : null);\n        }\n\n        void UpdateObjective()\n        {\n            if (finished) return;\n            if (bookRead && !AllSearched) { SetObjective(L(\"Finish the research: SEARCH every word in the library.\\nUnknown words (???): read more posters, labels, the yearbook.\\n\", \"完成调查：把图书馆里每一个词都搜一遍。\\n未知的词（???）：去读更多海报、标签、年鉴。\\n\") + Progress()); return; }\n            if (bookOpen) { SetObjective(L(\"Turn the pages: A / D. SLOWLY - every page rustles.\\nRead to the last page. Q: close the book.\\nIf she comes round the shelf: close it.\", \"翻页：A / D。慢慢翻——每一页都会沙沙响。\\n读到最后一页。Q：合上书。\\n她要是绕过书架过来了：合上它。\")); return; }\n            if (foundRecord) { SetObjective(L(\"Records, vol. 31: the OLD BOOKS AWAITING REPAIR\\n(NORTH-EAST corner, behind the rope). Go when nobody looks. Open it (E).\\n\", \"记录，第 31 卷：在“待修旧书”里\\n（东北角，绳子后面）。趁没人看时过去。打开它（E）。\\n\") + Progress()); return; }\n            if (unlocked)\n            {\n                SetObjective(L(\"SEARCH every word you can find - start with 1967.\\nSearch only knows words you have READ: walk up to posters and labels.\\n\", \"把能找到的词都搜一遍——先搜 1967。\\n搜索只认识你读到过的词：走近海报和标签去读。\\n\") + Progress());\n                return;\n            }\n            if (stampRead) { SetObjective(L(\"Unlock SEARCH.\\nCode = the stamp: APR 1967 -> month + year (4 digits).\", \"解锁“搜索”。\\n密码 = 印章：1967 年 4 月 → 月份 + 年份（四位数）。\")); return; }\n            if (silentOn) { SetObjective(L(\"Find the OLDEST book: on the RETURNS CART (west wall, by the door).\\nRead the stamp (E). Walk quietly: HOLD CTRL / C. Watch the meter.\", \"找到最旧的那本书：在还书车上（西墙，门边）。\\n读印章（E）。轻轻走：按住 Ctrl / C。注意噪音表。\")); return; }\n            if (phone.silentAvailable) { SetObjective(L(\"Put the phone on SILENT.\\nHOLD RIGHT MOUSE (behind a shelf), then press M. The little bell turns red.\", \"把手机调成静音。\\n按住鼠标右键（躲到书架后面），再按 M。小铃铛会变红。\")); return; }\n            SetObjective(L(\"Don't move. Phone down.\", \"别动。放下手机。\"));\n        }\n\n        void ReadStamp()\n        {\n            if (stampRead) { Thought(L(\"RECEIVED: APR 1967. The stamp hasn't changed.\", \"收到：1967 年 4 月。印章还是那个印章。\"), 3.5f, true); return; }\n            stampRead = true;\n            phone.AddSearchWord(\"1967\");\n            ambient.Play(AudioSynth.Rustle(), 0.3f);\n            noise = Mathf.Clamp01(noise + flipNoise);\n            Thought(L(\"The oldest book in the library. Inside the cover, a stamp:\\n\", \"图书馆里最旧的书。封面内侧有一个印章：\\n\") + Rule(L(\"RECEIVED: APR 1967\", \"收到：1967 年 4 月\")) + L(\" - Clearview Library, Cubberley Wing.\", \" - 明鉴图书馆，库伯利楼。\"), 7f, true);\n            Thought(L(\"April = 04. 1967 = 67. \", \"四月 = 04。1967 = 67。\") + Rule(L(\"0467.\", \"0467。\")) + L(\"\\n(Search word noted: 1967)\", \"\\n（记下搜索词：1967）\"), 6f);\n        }\n\n        // ------------------------------------------------------------------ search\n        string SearchResult(string w)\n        {\n            switch (w)\n            {\n                case \"1967\":\n                    return L(\"1 record found.\\n\\n'DAY FIVE'  -  April 1967\\nStatus: RESTRICTED\\n\\n(Ask a librarian.)\\n(Do not ask a librarian.)\",\n                             \"找到 1 条记录。\\n\\n“第五天”  -  1967 年 4 月\\n状态：限制查阅\\n\\n（请咨询图书管理员。）\\n（不要咨询图书管理员。）\");\n                case \"DAY FIVE\":\n                    return L(\"RECORDS, VOL. 31  (copied by hand)\\n\\nShelved with: OLD BOOKS AWAITING REPAIR\\nnorth-east corner, behind the rope.\\nDO NOT HANDLE.\\n\\nLast opened: 1980, by H. VOSS.\",\n                             \"记录，第 31 卷（手抄本）\\n\\n存放于：待修旧书\\n东北角，绳子后面。\\n请勿触碰。\\n\\n上次翻阅：1980 年，H. 沃斯。\");\n                case \"STRENGTH\":\n                    return L(\"School motto, adopted April 1967:\\n\\nStrength through discipline.\\nStrength through community.\\nStrength through action.\\n\\n(There was a fourth line. It has been removed.)\",\n                             \"校训，1967 年 4 月采用：\\n\\n纪律带来力量。\\n集体带来力量。\\n行动带来力量。\\n\\n（原本还有第四句。已被删除。）\");\n                case \"THE WAVE\":\n                    return L(\"THE WAVE (1981)\\nA teacher turns his class into a movement in five days - to show them how easily it happens.\\n\\nCopies owned: 0\\nStatus: never purchased\",\n                             \"《浪潮》（1981）\\n一位老师在五天里把他的班级变成一场运动——为了让他们看清这种事有多容易发生。\\n\\n馆藏：0 册\\n状态：从未购入\");\n                case \"VOSS\":\n                    return L(\"VOSS, H.\\nSeat 31, class of 1980.\\nReporter of the Year, 1980.\\nReturned one (1) device to the school.\\n\\nNow: Instructor.\",\n                             \"沃斯，H.\\n31 号座，1980 届。\\n1980 年度最佳举报员。\\n向学校交还设备一（1）台。\\n\\n现任：督导。\");\n                case \"CLEARVIEW\":\n                    return L(\"4,812 results.\\n\\nThey all say: what is seen, is safe.\", \"4,812 条结果。\\n\\n它们都在说：被看见的，就是安全的。\");\n                case \"1952\":\n                    return L(\"1 record (damaged).\\n\\n'March 1952. A court has ruled that a school may watch its teachers.\\nThe Founder is delighted. Clearview opens\\nthat same spring.'\\n\\n(The rest of the page has been reorganised.)\",\n                             \"1 条记录（已损毁）。\\n\\n“1952 年 3 月。法院裁定：学校可以监视它的老师。\\n创办人非常满意。明鉴学院\\n于同年春天开学。”\\n\\n（本页其余部分已被重新整理。）\");\n                case \"RED X\":\n                    return L(\"RED X: see REPORTER.\\nREPORTER: see RED X.\", \"红色 X：参见“举报员”。\\n举报员：参见“红色 X”。\");\n            }\n            return null;\n        }\n\n        void OnSearched(string w)\n        {\n            searched.Add(w);\n            if (bookRead && AllSearched && !finished) { StartCoroutine(Finish()); return; }\n            if (w == \"1967\" && phone.AddSearchWord(\"DAY FIVE\"))\n                Thought(L(\"A record called \", \"一条叫\") + Rule(L(\"DAY FIVE\", \"“第五天”\")) + L(\". Restricted.\\n(Search word noted: DAY FIVE)\", \"的记录。限制查阅。\\n（记下搜索词：第五天）\"), 6f, true);\n            if (w == \"DAY FIVE\" && !foundRecord)\n            {\n                foundRecord = true;\n                Thought(L(\"Volume 31. \", \"第 31 卷。\") + Rule(L(\"Of course it's 31.\", \"当然是 31。\")) + L(\"\\nWith the old books waiting for repair. The ones we're not allowed to touch.\", \"\\n和那些等着修的旧书放在一起。我们不许碰的那些。\"), 7f, true);\n                phone.Receive(\"Triangle\", L(\"the repair shelf? go between her rounds. and turn the pages SLOWLY. old paper is loud.\", \"待修书架？趁她巡视的间隙去。翻页要慢。旧纸很响。\"));\n            }\n        }\n\n        // ------------------------------------------------------------------ the old book\n        string[] Pages()\n        {\n            return new[]\n            {\n                L(\"CLEARVIEW LIBRARY\\nRECORDS, VOL. 31\\n\\n(water damaged -\\nawaiting repair -\\ndo not handle)\", \"明鉴图书馆\\n记录，第 31 卷\\n\\n（水渍受损——\\n等待修复——\\n请勿触碰）\"),\n                L(\"Lost and found, 1966:\\n1 umbrella. 3 gloves (left).\\n1 diary - burned, unread,\\nfor the owner's safety.\", \"失物招领，1966 年：\\n雨伞 1 把。手套 3 只（左手）。\\n日记 1 本——为了失主的安全，\\n未读即焚。\"),\n                L(\"Visitors, April 1967:\\n'Two observers from the\\nCubberley Wing committee.\\nThey took notes. Many notes.'\", \"访客记录，1967 年 4 月：\\n“库伯利楼委员会的\\n两位观察员。\\n他们做了笔记。很多笔记。”\"),\n                L(\"[ this page has been\\ntorn out ]\", \"［ 这一页\\n被撕掉了 ］\"),\n                L(\"DAY FIVE\\n(copied by hand from a newspaper, April 1967)\\n\\nA high school in California. A history teacher wants to show his class how it happens - how people go along.\", \"第五天\\n（1967 年 4 月，从报纸上手抄）\\n\\n加州的一所高中。一位历史老师想让他的学生看清它是怎么发生的——人们是怎么跟着走的。\"),\n                L(\"Day one: discipline.\\nDay two: community.\\nDay three: action - member cards, a salute, and three students assigned to report the others.\\n\\nBy the end of it, about twenty were reporting.\", \"第一天：纪律。\\n第二天：集体。\\n第三天：行动——会员卡、一种敬礼，还有三个被指派去举报别人的学生。\\n\\n到最后，大约有二十个人在举报。\"),\n                L(\"Day five: a rally. They are told a leader will speak to them on the screen.\\n\\nThe screen shows nothing.\\n\\nIt was a lesson. And then it ended.\", \"第五天：一场集会。他们被告知，屏幕上会有一位领袖对他们讲话。\\n\\n屏幕上什么都没有。\\n\\n那是一堂课。然后，它结束了。\"),\n                L(\"(in pencil, under the typing)\\n\\n\\\"Clearview opened its Cubberley Wing that same month.\\nThey kept the lesson.\\nThey threw away the ending.\\\"\", \"（打字稿下面，用铅笔写着）\\n\\n“明鉴学院在同一个月启用了库伯利楼。\\n他们留下了那堂课。\\n扔掉了结局。”\"),\n                L(\"(a newer hand)\\n\\n\\\"I read this in 1980.\\nI gave the phone back anyway.\\n\\n- H.V.\\\"\", \"（另一种更新的字迹）\\n\\n“我在 1980 年读过这个。\\n我还是把手机交了回去。\\n\\n——H.V.”\"),\n            };\n        }\n\n        void OpenBook()\n        {\n            if (!foundRecord) { Thought(L(\"OLD BOOKS - AWAITING REPAIR. Spines falling apart.\\nI don't even know which one I'd want.\", \"待修旧书。书脊都散了。\\n我都不知道自己要找哪一本。\"), 4.5f, true); return; }\n            if (bookOpen || finished) return;\n            bookOpen = true;\n            page = 0;\n            pageDwell = 0f;\n            bookRoot.SetActive(true);\n            ShowPage();\n            ambient.Play(AudioSynth.Creak(), 0.25f, 1.7f);\n            noise = Mathf.Clamp01(noise + flipNoise * Near());\n            if (!toldFlip)\n            {\n                toldFlip = true;\n                Thought(Rule(L(\"Every page rustles.\", \"每一页都会沙沙响。\")) + L(\" Louder than footsteps.\\nOne page at a time. Slowly.\", \"比脚步声还响。\\n一页一页来。慢慢翻。\"), 6f, true);\n            }\n        }\n\n        void CloseBook()\n        {\n            bookOpen = false;\n            bookRoot.SetActive(false);\n        }\n\n        void UpdateBook()\n        {\n            string[] pages = Pages();\n            if (GameInput.BackDown()) { CloseBook(); return; }\n            int dir = GameInput.RightKeyDown() ? 1 : (GameInput.LeftKeyDown() ? -1 : 0);\n            if (dir != 0)\n            {\n                int np = Mathf.Clamp(page + dir, 0, pages.Length - 1);\n                if (np != page)\n                {\n                    bool fast = Time.time - lastFlip < fastFlipSeconds;\n                    lastFlip = Time.time;\n                    page = np;\n                    pageDwell = 0f;\n                    ShowPage();\n                    ambient.Play(AudioSynth.Rustle(), fast ? 0.75f : 0.45f, Random.Range(0.9f, 1.1f));\n                    noise = Mathf.Clamp01(noise + flipNoise * (fast ? fastFlipFactor : 1f) * Near());\n                    noiseGrace = 0f;\n                    if (fast && DialogueIdle) Thought(L(\"Too fast - the paper crackles.\", \"太快了——纸页哗哗作响。\"), 2.5f);\n                }\n            }\n            pageDwell += Time.deltaTime;\n            if (page == pages.Length - 1 && pageDwell > 2.5f && !finished && !bookRead)\n            {\n                bookRead = true;\n                if (AllSearched) StartCoroutine(Finish());\n                else if (!toldResearch)\n                {\n                    toldResearch = true;\n                    CloseBook();\n                    Thought(L(\"That's the record. But I only know half of what this place hides.\\n\", \"这就是那份记录。可这地方藏着的东西，我只知道一半。\\n\") + Rule(L(\"Search every word in the library\", \"把图书馆里每一个词都搜一遍\")) + L(\" - then I'll know what I'm walking into tomorrow.\", \"——明天我才知道自己要面对什么。\"), 8f, true);\n                }\n            }\n        }\n\n        void ShowPage()\n        {\n            string[] pages = Pages();\n            bookText.text = pages[page];\n            UIFactory.FitFont(bookText, pages[page], 16);\n            bookPage.text = (page + 1) + \" / \" + pages.Length;\n            bookHelp.text = L(\"A / D: turn the page (slowly)     Q: close\", \"A / D：翻页（慢慢来）     Q：合上\");\n        }\n\n        IEnumerator Finish()\n        {\n            finished = true;\n            yield return Wait(0.5f);\n            CloseBook();\n            rig.Lock();\n            phone.allowRaise = false;\n            SetPrompt(null);\n            SetObjective(\"\");\n            meterRoot.SetActive(false);\n            ambient.Duck(12f);\n            Thought(L(\"Five days. Meant to end with the truth.\\nClearview kept the first four.\", \"五天。本该以真相结束。\\n明鉴学院留下了前四天。\"), 6f, true);\n            yield return WaitIdle();\n            phone.Receive(\"Triangle\", L(\"now you know. the screen is always empty. there's no leader. there's just the school.\", \"现在你知道了。屏幕永远是空的。没有领袖。只有这所学校。\"));\n            phone.Receive(\"Triangle\", L(\"tomorrow is friday. day five. inspection. he'll check every desk.\", \"明天是星期五。第五天。检查日。他会查每一张课桌。\"));\n            Thought(L(\"Tomorrow is the fifth day.\", \"明天就是第五天。\"), 4f);\n            yield return WaitIdle();\n            yield return FinishLevel(\"record\", 2.2f);\n        }\n\n        void BuildBook()\n        {\n            Canvas c = UIFactory.MakeCanvas(\"OldBook\", 39);\n            c.transform.SetParent(transform, false);\n            RectTransform box = UIFactory.Centered(\"Book\", c.transform, -260f, 40f, 760f, 520f);\n            UIFactory.AddImage(box, new Color(0.25f, 0.17f, 0.1f, 0.96f));\n            RectTransform paper = UIFactory.Rect(\"Paper\", box, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-30f, -30f));\n            UIFactory.AddImage(paper, new Color(0.86f, 0.8f, 0.66f));\n            UIFactory.AddImage(UIFactory.Rect(\"Stain\", paper, new Vector2(0.62f, 0.05f), new Vector2(0.98f, 0.4f), new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero), new Color(0.6f, 0.5f, 0.32f, 0.25f));\n            bookText = UIFactory.AddText(UIFactory.Rect(\"Text\", paper, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), new Vector2(0f, 14f), new Vector2(-70f, -110f)), \"\", 27, new Color(0.18f, 0.13f, 0.09f), TextAnchor.MiddleCenter);\n            bookPage = UIFactory.AddText(UIFactory.Rect(\"Page\", paper, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 46f), new Vector2(0f, 26f)), \"\", 18, new Color(0.35f, 0.27f, 0.18f), TextAnchor.MiddleCenter);\n            bookHelp = UIFactory.AddText(UIFactory.Rect(\"Help\", paper, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 14f), new Vector2(0f, 26f)), \"\", 17, new Color(0.45f, 0.3f, 0.2f), TextAnchor.MiddleCenter);\n            bookRoot = box.gameObject;\n            bookRoot.SetActive(false);\n        }\n\n        // ------------------------------------------------------------------ noise meter\n        void BuildMeter()\n        {\n            Canvas c = UIFactory.MakeCanvas(\"NoiseMeter\", 41);\n            c.transform.SetParent(transform, false);\n            RectTransform box = UIFactory.Rect(\"Meter\", c.transform, new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(-28f, -170f), new Vector2(300f, 70f));\n            UIFactory.AddImage(box, new Color(0.05f, 0.055f, 0.06f, 0.9f));\n            meterLabel = UIFactory.AddText(UIFactory.TopLeft(\"Label\", box, 16f, 8f, 270f, 22f), L(\"QUIET, PLEASE\", \"请保持安静\"), 16, new Color(1f, 0.8f, 0.45f), TextAnchor.UpperLeft);\n            meterLabel.fontStyle = FontStyle.Bold;\n            RectTransform bar = UIFactory.TopLeft(\"Bar\", box, 16f, 38f, 268f, 16f);\n            UIFactory.AddImage(bar, new Color(1f, 1f, 1f, 0.12f));\n            meterFill = UIFactory.AddImage(UIFactory.Rect(\"Fill\", bar, Vector2.zero, new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero), new Color(0.6f, 0.85f, 0.6f));\n            meterRoot = box.gameObject;\n            meterRoot.SetActive(false);\n        }\n\n        float Near()\n        {\n            float d = 999f;\n            if (librarian != null) d = Vector3.Distance(librarian.transform.position, rig.transform.position);\n            if (assistant != null) d = Mathf.Min(d, Vector3.Distance(assistant.transform.position, rig.transform.position));\n            return 1f + Mathf.Clamp01((nearLibrarian - d) / nearLibrarian) * 1.5f;\n        }\n\n        bool Sees(Vector3 p)\n        {\n            if (librarianVision != null && librarian != null && librarian.Running && librarianVision.CanSee(p, rig.transform)) return true;\n            if (assistantVision != null && assistant != null && assistant.Running && assistantVision.CanSee(p, rig.transform)) return true;\n            return false;\n        }\n\n        void UpdateNoise()\n        {\n            if (!meterOn) return;\n            if (noiseGrace > 0f) noiseGrace -= Time.deltaTime;\n            bool moving = speed > 0.3f;\n            // the longer you walk without stopping, the faster the meter climbs (exponential); quiet steps don't count\n            if (moving && !GameInput.SneakHeld()) walkStreak += Time.deltaTime;\n            else walkStreak = Mathf.Max(0f, walkStreak - Time.deltaTime * 3f);\n            float rate;\n            if (!moving) rate = -noiseDecay;\n            else if (GameInput.SneakHeld()) rate = noiseSneak;\n            else if (speed > 3.4f) rate = noiseRun;\n            else rate = noiseWalk;\n            if (rate > 0f) rate *= Near() * Mathf.Min(walkMaxFactor, Mathf.Pow(2f, walkStreak / Mathf.Max(0.2f, walkDoubling)));\n            if (noiseGrace > 0f && rate > 0f) rate = 0f;\n            if (bookOpen && rate < 0f) rate *= 0.6f;   // holding an old book open isn't quite silence\n            noise = Mathf.Clamp01(noise + rate * Time.deltaTime);\n            meterFill.rectTransform.anchorMax = new Vector2(noise, 1f);\n            meterFill.color = Color.Lerp(new Color(0.6f, 0.85f, 0.6f), new Color(0.95f, 0.25f, 0.18f), noise);\n            meterLabel.text = noise > 0.75f ? L(\"QUIET, PLEASE  -  SHHH...\", \"请保持安静  -  嘘……\") : L(\"QUIET, PLEASE\", \"请保持安静\");\n            if (moving && !GameInput.SneakHeld() && !toldSneak && noise > 0.25f)\n            {\n                toldSneak = true;\n                Thought(Rule(L(\"The meter\", \"噪音表\")) + L(\" (top right) fills when I walk. \", \"（右上角）一走路就涨。\") + Rule(L(\"HOLD CTRL / C\", \"按住 Ctrl / C\")) + L(\" = quiet steps.\\nStanding still lets it drain. Running is the worst.\", \" = 轻步走。\\n站着不动它就会降。跑步最糟。\"), 7f, true);\n            }\n            if (!toldMeter && noise > 0.6f)\n            {\n                toldMeter = true;\n                Thought(L(\"Closer to her = louder. \", \"离她越近 = 越响。\") + Rule(L(\"Stand still for a moment.\", \"先站着别动一会儿。\")), 5f, true);\n            }\n            if (noise >= 1f)\n            {\n                noise = 0.35f;\n                noiseGrace = 3f;\n                Strike(bookOpen ? L(\"Who is turning pages back there? ...SHHH.\", \"谁在后面翻书？……嘘！\") : L(\"SHHH. ...Libraries are for silence. Silence is for everyone.\", \"嘘。……图书馆是用来安静的。安静是为了每一个人。\"));\n            }\n        }\n\n        // ------------------------------------------------------------------ watchers\n        void UpdateDanger()\n        {\n            bool seen = false;\n            if (phone.IsExposed) seen = Sees(phoneExposurePoint.position);\n            if (AccumulateDanger(seen ? 1f / Mathf.Max(0.05f, noticeSeconds) : 0f))\n                Strike(L(\"A device. In my library. Devices are not books.\", \"一台设备。在我的图书馆里。设备不是书。\"));\n        }\n\n        void UpdateRestricted()\n        {\n            if (zoneGrace > 0f) zoneGrace -= Time.deltaTime;\n            bool inside = In(rig.transform.position, restrictedZone);\n            bool seen = inside && zoneGrace <= 0f && Sees(rig.eye.position);\n            zoneSeen = seen ? zoneSeen + Time.deltaTime * (bookOpen ? 2f : 1f) : Mathf.Max(0f, zoneSeen - Time.deltaTime);\n            if (zoneSeen > 0.6f)\n            {\n                zoneSeen = 0f;\n                zoneGrace = 2.5f;\n                bool withBook = bookOpen;\n                CloseBook();\n                Strike(withBook ? L(\"Students do NOT touch the old books. They are waiting for repair.\", \"学生不许碰旧书。它们在等着修。\") : L(\"That corner is for books awaiting repair. Not for students.\", \"那个角落是给待修的书的。不是给学生的。\"));\n                if (!ended) rig.Teleport(restrictedReturn, 180f);\n            }\n        }\n\n        /// <summary>She sits at the desk, then walks a round of the aisles, then comes back. Her rounds pass the rope.</summary>\n        void UpdateLibrarianRounds()\n        {\n            if (librarian == null || deskSpot == null || !librarian.RouteDone || !firstBuzz || !silentOn) return;\n            routeTimer -= Time.deltaTime;\n            if (routeTimer > 0f) return;\n            routeTimer = Random.Range(22f, 30f);\n            bool east = Random.value < 0.5f;\n            Vector3[] pts = east\n                ? new[] { new Vector3(9.4f, 0f, 3.2f), new Vector3(9.4f, 0f, 9.2f), new Vector3(11.8f, 0f, 9.2f), new Vector3(7f, 0f, 8.4f), deskSpot.position }\n                : new[] { new Vector3(4.6f, 0f, 3.2f), new Vector3(4.6f, 0f, 9.2f), new Vector3(7f, 0f, 9.4f), new Vector3(9.4f, 0f, 9.2f), deskSpot.position };\n            float[] waits = { 1.5f, 2.5f, 3f, 1.5f, 0.2f };\n            float[] yaws = { float.NaN, 90f, 0f, float.NaN, 0f };\n            librarian.RunRoute(pts, waits, yaws, null);\n        }\n\n        // ------------------------------------------------------------------ the pigeons: noisy, and she hates them\n        void UpdatePigeons()\n        {\n            if (pigeonBusy || !silentOn || librarian == null || pigeonSpot == null || deskSpot == null || ended || finished || Pigeon.All.Count == 0) return;\n            pigeonTimer -= Time.deltaTime;\n            if (pigeonTimer <= 0f) StartCoroutine(PigeonEvent());\n        }\n\n        static float Flat(Vector3 v) { v.y = 0f; return v.magnitude; }\n\n        IEnumerator PigeonEvent()\n        {\n            pigeonBusy = true;\n            foreach (Pigeon pg in Pigeon.All) pg.Agitate(16f);\n            yield return Wait(2f);   // the flapping first\n            if (ended || finished) { pigeonBusy = false; yield break; }\n            Authority(L(\"...Those birds. Again.\", \"……又是那些鸟。\"), 2.5f);\n            if (!toldPigeons)\n            {\n                toldPigeons = true;\n                Thought(L(\"The pigeons on the window ledge. \", \"窗台上的鸽子。\") + Rule(L(\"She's coming to the windows - stay away from them.\", \"她要过来窗边了——离窗户远点。\")), 5f);\n            }\n            bool done = false;\n            librarian.RunRoute(new[] { pigeonSpot.position, deskSpot.position }, new[] { 4.5f, 0.2f }, new[] { pigeonSpot.eulerAngles.y, 0f }, () => done = true);\n            float t = 0f;\n            while (!ended && t < 14f && Flat(librarian.transform.position - pigeonSpot.position) > 0.6f) { t += Time.deltaTime; yield return null; }\n            if (!ended)\n            {\n                ambient.Play(AudioSynth.Click(), 0.45f, 0.55f);   // she raps on the glass\n                Authority(L(\"Shoo. SHOO. ...Filthy, noisy things.\", \"去。去！……又脏又吵的东西。\"), 3f, true);\n                foreach (Pigeon pg in Pigeon.All) pg.Calm();\n                float stay = 0f;\n                while (!ended && stay < 4f)\n                {\n                    stay += Time.deltaTime;\n                    if (Flat(rig.transform.position - pigeonSpot.position) < pigeonNear)\n                    {\n                        Strike(L(\"And you. Away from the window. Nobody stands about with the birds.\", \"还有你。离窗户远点。谁也不许跟那些鸟待在一起。\"));\n                        break;\n                    }\n                    yield return null;\n                }\n            }\n            t = 0f;\n            while (!done && !ended && t < 15f) { t += Time.deltaTime; yield return null; }\n            routeTimer = Random.Range(10f, 18f);\n            pigeonTimer = Random.Range(pigeonEvery.x, pigeonEvery.y);\n            pigeonBusy = false;\n        }\n\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        protected override IEnumerator OnCaught()\n        {\n            phone.allowRaise = false;\n            CloseBook();\n            rig.Lock();\n            meterRoot.SetActive(false);\n            Authority(L(\"That's three. The device is overdue. I'll take it.\", \"第三次了。这台设备逾期了。我收走了。\"), 4f, true);\n            if (librarian != null)\n            {\n                Vector3 to = rig.transform.position - librarian.transform.position; to.y = 0f;\n                librarian.Approach(rig.transform.position - to.normalized * 0.9f, rig.transform);\n                float t = 0f;\n                yield return Wait(0.4f);\n                while (!librarian.HasArrived && t < 7f) { t += Time.deltaTime; yield return null; }\n            }\n            Authority(L(\"Returned. ...Shhh.\", \"已归还。……嘘。\"), 3.5f);\n            yield return WaitIdle();\n            yield return Caught(\"shhh\");\n        }\n\n        protected override void OnRead(Readable r)\n        {\n            base.OnRead(r);\n            if (r.keyword == \"STRENGTH\" || r.keyword == \"THE WAVE\" || r.keyword == \"VOSS\" || r.keyword == \"RED X\") ambient.Play(AudioSynth.Ping(), 0.25f, 1.2f);\n        }\n    }\n}\n"},"AudioSynth":{"path":"Assets/Game/Scripts/AudioSynth.cs","role":"Every sound in the game, generated in code (hum, drones, chimes, footsteps, voices, the climax chord)","source":"// @role Every sound in the game, generated in code (hum, drones, chimes, footsteps, voices, the climax chord)\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Every sound in the game is made here, in code - no audio files needed.\n    /// Loops are built with a whole number of cycles (or a cross-fade), so they repeat without a click.\n    /// Audio identity (from our style sheet): fluorescent buzzing, ventilation hum, footsteps in quiet halls,\n    /// sparse repetitive drones, polite chimes, sudden silence when a rule is broken.\n    /// </summary>\n    public static class AudioSynth\n    {\n        const int SR = 22050;\n        static readonly Dictionary<string, AudioClip> cache = new Dictionary<string, AudioClip>();\n        static System.Random rng = new System.Random(1952);\n\n        static AudioClip Make(string name, float[] data)\n        {\n            AudioClip c = AudioClip.Create(name, data.Length, 1, SR, false);\n            c.SetData(data, 0);\n            cache[name] = c;\n            return c;\n        }\n\n        static bool Cached(string name, out AudioClip c) { return cache.TryGetValue(name, out c) && c != null; }\n        static float Noise() { return (float)(rng.NextDouble() * 2.0 - 1.0); }\n        static float TwoPi { get { return Mathf.PI * 2f; } }\n\n        /// <summary>Joins the end of a longer buffer onto its start, so it loops seamlessly.</summary>\n        static float[] CrossfadeLoop(float[] raw, int length, int fade)\n        {\n            float[] o = new float[length];\n            for (int i = 0; i < length; i++) o[i] = raw[i];\n            for (int i = 0; i < fade; i++)\n            {\n                float a = i / (float)fade;\n                o[i] = raw[i] * a + raw[length + i] * (1f - a);\n            }\n            return o;\n        }\n\n        static void Normalize(float[] d, float peak)\n        {\n            float m = 0.0001f;\n            for (int i = 0; i < d.Length; i++) m = Mathf.Max(m, Mathf.Abs(d[i]));\n            float k = peak / m;\n            for (int i = 0; i < d.Length; i++) d[i] *= k;\n        }\n\n        // ------------------------------------------------------------------ loops\n        /// <summary>Fluorescent tube: 120 Hz mains hum with harmonics and a faint crackle. 2 s loop.</summary>\n        public static AudioClip FluorescentHum()\n        {\n            AudioClip c; if (Cached(\"hum\", out c)) return c;\n            int n = SR * 2;\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float s = Mathf.Sin(TwoPi * 120f * t) * 0.5f + Mathf.Sin(TwoPi * 240f * t) * 0.3f + Mathf.Sin(TwoPi * 360f * t) * 0.12f\n                        + Mathf.Sin(TwoPi * 1080f * t) * 0.04f;\n                d[i] = s + Noise() * 0.035f;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"hum\", d);\n        }\n\n        /// <summary>Ventilation: soft low-passed noise. 4 s loop.</summary>\n        public static AudioClip Ventilation()\n        {\n            AudioClip c; if (Cached(\"vent\", out c)) return c;\n            int n = SR * 4, f = SR / 4;\n            float[] raw = new float[n + f];\n            float lp = 0f, lp2 = 0f;\n            for (int i = 0; i < raw.Length; i++)\n            {\n                lp += (Noise() - lp) * 0.06f;\n                lp2 += (lp - lp2) * 0.08f;\n                raw[i] = lp2;\n            }\n            float[] d = CrossfadeLoop(raw, n, f);\n            Normalize(d, 0.6f);\n            return Make(\"vent\", d);\n        }\n\n        /// <summary>Sparse institutional drone (A1 + E2 + a slightly sour A2), slow swell. 8 s loop.</summary>\n        public static AudioClip Drone()\n        {\n            AudioClip c; if (Cached(\"drone\", out c)) return c;\n            int n = SR * 8;\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float swell = 0.65f + 0.35f * Mathf.Sin(TwoPi * t / 8f);\n                float s = Mathf.Sin(TwoPi * 55f * t) * 0.55f\n                        + Mathf.Sin(TwoPi * 82.5f * t) * 0.3f * (0.5f + 0.5f * Mathf.Sin(TwoPi * t / 4f))\n                        + Mathf.Sin(TwoPi * 110.375f * t) * 0.18f\n                        + Mathf.Sin(TwoPi * 164.875f * t) * 0.07f;\n                d[i] = s * swell;\n            }\n            Normalize(d, 0.55f);\n            return Make(\"drone\", d);\n        }\n\n        /// <summary>Dissonant beating layer that fades in with danger. 4 s loop.</summary>\n        public static AudioClip DangerLayer()\n        {\n            AudioClip c; if (Cached(\"danger\", out c)) return c;\n            int n = SR * 4;\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float trem = 0.6f + 0.4f * Mathf.Sin(TwoPi * 6f * t);\n                d[i] = (Mathf.Sin(TwoPi * 233.25f * t) + Mathf.Sin(TwoPi * 246.75f * t) * 0.9f + Mathf.Sin(TwoPi * 58.25f * t) * 0.7f) * trem;\n            }\n            Normalize(d, 0.55f);\n            return Make(\"danger\", d);\n        }\n\n        /// <summary>Someone humming an off-key anthem. 7.5 s loop.</summary>\n        public static AudioClip HumMelody()\n        {\n            AudioClip c; if (Cached(\"melody\", out c)) return c;\n            float[] notes = { 261.6f, 329.6f, 392f, 329.6f, 349.2f, 293.7f, 261.6f, 0f, 293.7f, 311f, 0f };\n            float noteLen = 0.68f;\n            int n = (int)(SR * noteLen * notes.Length);\n            float[] d = new float[n];\n            float phase = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                int k = Mathf.Min(notes.Length - 1, (int)(t / noteLen));\n                float local = t - k * noteLen;\n                float f = notes[k];\n                if (f <= 0f) { d[i] = 0f; continue; }\n                f *= (k % 3 == 1) ? 0.985f : 1f;                                   // a little flat, sometimes\n                f *= 1f + 0.012f * Mathf.Sin(TwoPi * 5.2f * t);                    // vibrato\n                phase += TwoPi * f / SR;\n                float env = Mathf.Clamp01(local / 0.08f) * Mathf.Clamp01((noteLen - local) / 0.12f);\n                d[i] = (Mathf.Sin(phase) + 0.35f * Mathf.Sin(phase * 2f) + 0.1f * Mathf.Sin(phase * 3f)) * env;\n            }\n            Normalize(d, 0.6f);\n            return Make(\"melody\", d);\n        }\n\n        /// <summary>Slow breathing of sleeping students. 4 s loop.</summary>\n        public static AudioClip Breathing()\n        {\n            AudioClip c; if (Cached(\"breath\", out c)) return c;\n            int n = SR * 4;\n            float[] d = new float[n];\n            float lp = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                lp += (Noise() - lp) * 0.12f;\n                float env = Mathf.Pow(Mathf.Sin(Mathf.PI * t / 4f), 2f);\n                d[i] = lp * env;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"breath\", d);\n        }\n\n        // ------------------------------------------------------------------ one-shots\n        /// <summary>Two-tone PA chime (\"ding-dong\").</summary>\n        public static AudioClip Chime()\n        {\n            AudioClip c; if (Cached(\"chime\", out c)) return c;\n            int n = (int)(SR * 1.8f);\n            float[] d = new float[n];\n            Bell(d, 659.25f, 0f, 1.2f);\n            Bell(d, 523.25f, 0.55f, 1.25f);\n            Normalize(d, 0.6f);\n            return Make(\"chime\", d);\n        }\n\n        /// <summary>Bright confirmation chime (message sent, door open...).</summary>\n        public static AudioClip Confirm()\n        {\n            AudioClip c; if (Cached(\"confirm\", out c)) return c;\n            int n = (int)(SR * 0.9f);\n            float[] d = new float[n];\n            Bell(d, 1046.5f, 0f, 0.6f);\n            Bell(d, 1568f, 0.12f, 0.7f);\n            Normalize(d, 0.45f);\n            return Make(\"confirm\", d);\n        }\n\n        static void Bell(float[] d, float f, float start, float len)\n        {\n            int s0 = (int)(start * SR), s1 = Mathf.Min(d.Length, s0 + (int)(len * SR));\n            for (int i = s0; i < s1; i++)\n            {\n                float t = (i - s0) / (float)SR;\n                float env = Mathf.Exp(-3.2f * t) * Mathf.Clamp01(t / 0.004f);\n                d[i] += (Mathf.Sin(TwoPi * f * t) + 0.35f * Mathf.Sin(TwoPi * f * 2.76f * t) * Mathf.Exp(-6f * t) + 0.2f * Mathf.Sin(TwoPi * f * 2f * t)) * env;\n            }\n        }\n\n        static AudioClip[] steps;\n        /// <summary>Three variations of a footstep on hard floor.</summary>\n        public static AudioClip[] Steps()\n        {\n            if (steps != null && steps[0] != null) return steps;\n            steps = new AudioClip[3];\n            for (int v = 0; v < 3; v++)\n            {\n                int n = (int)(SR * 0.16f);\n                float[] d = new float[n];\n                float lp = 0f, cut = 0.18f + v * 0.05f;\n                for (int i = 0; i < n; i++)\n                {\n                    float t = i / (float)SR;\n                    lp += (Noise() - lp) * cut;\n                    d[i] = lp * Mathf.Exp(-t * 38f) * 1.4f + Mathf.Sin(TwoPi * (68f + v * 9f) * t) * Mathf.Exp(-t * 28f) * 0.8f;\n                }\n                Normalize(d, 0.8f);\n                steps[v] = Make(\"step\" + v, d);\n            }\n            return steps;\n        }\n\n        /// <summary>A ring of keys.</summary>\n        public static AudioClip Keys()\n        {\n            AudioClip c; if (Cached(\"keys\", out c)) return c;\n            int n = (int)(SR * 0.5f);\n            float[] d = new float[n];\n            float[] onsets = { 0f, 0.07f, 0.16f, 0.21f };\n            for (int o = 0; o < onsets.Length; o++)\n            {\n                float f1 = 2600f + o * 530f, f2 = 4100f + o * 370f;\n                int s0 = (int)(onsets[o] * SR);\n                for (int i = s0; i < n; i++)\n                {\n                    float t = (i - s0) / (float)SR;\n                    float env = Mathf.Exp(-t * 22f);\n                    d[i] += (Mathf.Sin(TwoPi * f1 * t) + 0.6f * Mathf.Sin(TwoPi * f2 * t) + Noise() * 0.3f) * env;\n                }\n            }\n            Normalize(d, 0.45f);\n            return Make(\"keys\", d);\n        }\n\n        /// <summary>A creaking door.</summary>\n        /// <summary>A page turned in an old book: a dry, papery rustle (band-passed noise, two quick swells).</summary>\n        public static AudioClip Rustle()\n        {\n            AudioClip c; if (Cached(\"rustle\", out c)) return c;\n            int n = (int)(SR * 0.32f);\n            float[] d = new float[n];\n            float lp = 0f, hp = 0f, prev = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float x = Noise();\n                lp += (x - lp) * 0.35f;          // low-pass\n                hp = lp - prev; prev = lp;        // then high-pass = papery band\n                float env = Mathf.Exp(-Mathf.Pow((t - 0.06f) / 0.04f, 2f)) + 0.7f * Mathf.Exp(-Mathf.Pow((t - 0.19f) / 0.06f, 2f));\n                d[i] = hp * env * (0.7f + 0.3f * Noise());\n            }\n            Normalize(d, 0.55f);\n            return Make(\"rustle\", d);\n        }\n\n        public static AudioClip Creak()\n        {\n            AudioClip c; if (Cached(\"creak\", out c)) return c;\n            int n = (int)(SR * 1.0f);\n            float[] d = new float[n];\n            float phase = 0f, lp = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float f = 170f + 130f * t + 25f * Mathf.Sin(TwoPi * 7f * t) + Noise() * 20f;\n                phase += f / SR;\n                float saw = (phase % 1f) * 2f - 1f;\n                lp += (saw - lp) * 0.25f;\n                d[i] = lp * Mathf.Sin(Mathf.PI * t) * (0.6f + 0.4f * Mathf.Sin(TwoPi * 13f * t));\n            }\n            Normalize(d, 0.5f);\n            return Make(\"creak\", d);\n        }\n\n        /// <summary>A pigeon's soft \"hoo-HOOoo\" (low, breathy - about as present as a footstep, never startling).</summary>\n        public static AudioClip Coo()\n        {\n            AudioClip c; if (Cached(\"coo\", out c)) return c;\n            int n = (int)(SR * 1.15f);\n            float[] d = new float[n];\n            float phase = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                // two notes: a short low one, then a longer one that rises and falls\n                float env, f;\n                if (t < 0.28f) { env = Mathf.Sin(Mathf.PI * t / 0.28f); f = 300f; }\n                else if (t < 0.38f) { env = 0f; f = 300f; }\n                else { float u = (t - 0.38f) / 0.77f; env = Mathf.Sin(Mathf.PI * u) * (1f - 0.3f * u); f = 310f + 70f * Mathf.Sin(Mathf.PI * u); }\n                f += 9f * Mathf.Sin(TwoPi * 23f * t);   // the throaty warble\n                phase += f / SR;\n                float tone = Mathf.Sin(TwoPi * phase) + 0.25f * Mathf.Sin(TwoPi * phase * 2f);\n                d[i] = (tone * 0.85f + Noise() * 0.12f) * env * env;\n            }\n            Normalize(d, 0.45f);\n            return Make(\"coo\", d);\n        }\n\n        /// <summary>A few wing beats (soft noise bursts).</summary>\n        public static AudioClip Flap()\n        {\n            AudioClip c; if (Cached(\"flap\", out c)) return c;\n            int n = (int)(SR * 0.7f);\n            float[] d = new float[n];\n            float lp = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float beat = Mathf.Repeat(t, 0.11f) / 0.11f;\n                float env = Mathf.Exp(-beat * 6f) * (1f - t / 0.7f);\n                lp += (Noise() - lp) * 0.35f;\n                d[i] = lp * env;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"flap\", d);\n        }\n\n        /// <summary>Low hit used when a warning is given.</summary>\n        public static AudioClip Stinger()\n        {\n            AudioClip c; if (Cached(\"stinger\", out c)) return c;\n            int n = (int)(SR * 1.2f);\n            float[] d = new float[n];\n            float phase = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float f = 70f * Mathf.Exp(-t * 1.5f) + 32f;\n                phase += TwoPi * f / SR;\n                d[i] = Mathf.Sin(phase) * Mathf.Exp(-t * 2.2f) * 1.2f\n                     + Noise() * Mathf.Exp(-t * 18f) * 0.5f\n                     + (Mathf.Sin(TwoPi * 466f * t) + Mathf.Sin(TwoPi * 493f * t)) * 0.12f * Mathf.Exp(-t * 3f);\n            }\n            Normalize(d, 0.8f);\n            return Make(\"stinger\", d);\n        }\n\n        /// <summary>Phone vibrating in a drawer.</summary>\n        public static AudioClip Vibrate()\n        {\n            AudioClip c; if (Cached(\"vibrate\", out c)) return c;\n            int n = (int)(SR * 0.35f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float env = Mathf.Sin(Mathf.PI * t / 0.35f);\n                d[i] = Mathf.Sign(Mathf.Sin(TwoPi * 160f * t)) * 0.3f * env;\n            }\n            return Make(\"vibrate\", d);\n        }\n\n        /// <summary>Typewriter tick.</summary>\n        public static AudioClip Tick()\n        {\n            AudioClip c; if (Cached(\"tick\", out c)) return c;\n            int n = (int)(SR * 0.025f);\n            float[] d = new float[n];\n            float prev = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float x = Noise();\n                d[i] = (x - prev) * Mathf.Exp(-t * 260f);\n                prev = x;\n            }\n            Normalize(d, 0.5f);\n            return Make(\"tick\", d);\n        }\n\n        /// <summary>A short \"voice\" syllable. Pitch it per speaker (Animal-Crossing style mumble).</summary>\n        public static AudioClip Blip()\n        {\n            AudioClip c; if (Cached(\"blip\", out c)) return c;\n            int n = (int)(SR * 0.085f);\n            float[] d = new float[n];\n            float f0 = 150f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float s = 0f;\n                for (int h = 1; h <= 12; h++)\n                {\n                    float fh = f0 * h;\n                    float w = Mathf.Exp(-Mathf.Pow((fh - 700f) / 260f, 2f)) + 0.6f * Mathf.Exp(-Mathf.Pow((fh - 1200f) / 300f, 2f)) + 0.25f / h;\n                    s += Mathf.Sin(TwoPi * fh * t) * w;\n                }\n                d[i] = s * Mathf.Sin(Mathf.PI * t / 0.085f);\n            }\n            Normalize(d, 0.5f);\n            return Make(\"blip\", d);\n        }\n\n        /// <summary>\n        /// Many people talking at a normal volume behind a door (muffled). 6 s seamless loop.\n        /// The one sound in the game that is not polite, not monitored, not quiet.\n        /// </summary>\n        public static AudioClip Murmur()\n        {\n            AudioClip c; if (Cached(\"murmur\", out c)) return c;\n            int n = SR * 6, fade = SR / 2;\n            float[] raw = new float[n + fade];\n            System.Random r = new System.Random(304);\n            for (int v = 0; v < 7; v++)\n            {\n                float f0 = 105f + (float)r.NextDouble() * 170f;\n                float pan = 0.6f + (float)r.NextDouble() * 0.6f;\n                int i = (int)(r.NextDouble() * SR * 0.5);\n                while (i < raw.Length)\n                {\n                    // one syllable, then a short gap (or a longer pause between phrases)\n                    int len = (int)(SR * (0.09 + r.NextDouble() * 0.16));\n                    float fa = 450f + (float)r.NextDouble() * 500f, fb = 1000f + (float)r.NextDouble() * 900f;\n                    float bend = 1f + ((float)r.NextDouble() - 0.5f) * 0.25f;\n                    for (int k = 0; k < len && i + k < raw.Length; k++)\n                    {\n                        float t = k / (float)SR;\n                        float env = Mathf.Sin(Mathf.PI * k / len);\n                        float f = f0 * Mathf.Lerp(1f, bend, k / (float)len);\n                        float sum = 0f;\n                        for (int h = 1; h <= 8; h++)\n                        {\n                            float fh = f * h;\n                            float w = Mathf.Exp(-Mathf.Pow((fh - fa) / 220f, 2f)) + 0.5f * Mathf.Exp(-Mathf.Pow((fh - fb) / 280f, 2f)) + 0.15f / h;\n                            sum += Mathf.Sin(TwoPi * fh * t) * w;\n                        }\n                        raw[i + k] += sum * env * 0.12f * pan;\n                    }\n                    i += len + (int)(SR * (r.NextDouble() < 0.18 ? 0.35 + r.NextDouble() * 0.6 : 0.03 + r.NextDouble() * 0.08));\n                }\n            }\n            // muffled: through a door\n            float y = 0f;\n            for (int i = 0; i < raw.Length; i++) { y += (raw[i] - y) * 0.18f; raw[i] = y + Noise() * 0.004f; }\n            float[] d = CrossfadeLoop(raw, n, fade);\n            Normalize(d, 0.5f);\n            return Make(\"murmur\", d);\n        }\n\n        // ------------------------------------------------------------------ the climax (every phone lights up)\n        static float Bellish(float f, float t)\n        {\n            // a clear bell: a few inharmonic partials with their own decays\n            return Mathf.Sin(TwoPi * f * t) * Mathf.Exp(-t * 2.2f)\n                 + 0.45f * Mathf.Sin(TwoPi * f * 2.76f * t) * Mathf.Exp(-t * 4.5f)\n                 + 0.22f * Mathf.Sin(TwoPi * f * 5.4f * t) * Mathf.Exp(-t * 8f)\n                 + 0.3f * Mathf.Sin(TwoPi * f * 2f * t) * Mathf.Exp(-t * 3f);\n        }\n\n        /// <summary>One phone waking up: a soft bright bell (play at different pitches, one per phone).</summary>\n        public static AudioClip Ping()\n        {\n            AudioClip c; if (Cached(\"ping\", out c)) return c;\n            int n = (int)(SR * 1.6f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float atk = Mathf.Clamp01(t / 0.004f);\n                d[i] = Bellish(660f, t) * atk;\n            }\n            Normalize(d, 0.6f);\n            return Make(\"ping\", d);\n        }\n\n        /// <summary>A rising swell under the lights coming on: a wide minor chord slowly opening up, with a cold shimmer on top.</summary>\n        public static AudioClip Swell()\n        {\n            AudioClip c; if (Cached(\"swell\", out c)) return c;\n            float len = 6f;\n            int n = (int)(SR * len);\n            float[] d = new float[n];\n            float[] chord = { 55f, 110f, 164.81f, 220f, 261.63f, 329.63f, 493.88f };   // A minor add9: open, a little sad\n            float lp = 0f;\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float k = t / len;\n                float env = k * k * (3f - 2f * k);               // smooth rise\n                float s = 0f;\n                for (int j = 0; j < chord.Length; j++)\n                {\n                    float f = chord[j] * (1f + 0.002f * Mathf.Sin(t * (0.7f + j * 0.13f)));   // slow chorus\n                    float voice = Mathf.Sin(TwoPi * f * t) + 0.35f * Mathf.Sin(TwoPi * f * 2f * t) * k + 0.15f * Mathf.Sin(TwoPi * f * 3f * t) * k * k;\n                    float enter = Mathf.Clamp01((k - j * 0.06f) * 3f);   // low notes first, then higher ones join\n                    s += voice * enter / chord.Length;\n                }\n                // airy shimmer that opens up (filtered noise)\n                lp += (Noise() - lp) * (0.02f + 0.25f * k);\n                s += lp * 0.25f * k * k;\n                s *= 1f + 0.08f * Mathf.Sin(TwoPi * 5.5f * t) * k;     // tremolo as it grows\n                d[i] = s * env;\n            }\n            Normalize(d, 0.7f);\n            return Make(\"swell\", d);\n        }\n\n        /// <summary>\n        /// The moment everyone is lit: freedom, but lonely. Open fifths and ninths with no third (neither happy nor sad),\n        /// a slow swell instead of a hit, one distant bell answered a step lower, and wind in the long tail.\n        /// </summary>\n        public static AudioClip Bloom()\n        {\n            AudioClip c; if (Cached(\"bloom\", out c)) return c;\n            float lpw = 0f;\n            float len = 9f;\n            int n = (int)(SR * len);\n            float[] d = new float[n];\n            float[] chord = { 55f, 82.41f, 110f, 164.81f, 246.94f, 329.63f, 493.88f, 659.26f };\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                float atk = Mathf.Clamp01(t / 0.9f);\n                atk = atk * atk * (3f - 2f * atk);\n                float s = 0f;\n                for (int j = 0; j < chord.Length; j++)\n                {\n                    float f = chord[j];\n                    float decay = Mathf.Exp(-t * (0.18f + j * 0.04f));\n                    float beat = 1f + 0.003f * Mathf.Sin(t * (0.5f + j * 0.21f));     // slightly unsteady, like a room tone\n                    s += (Mathf.Sin(TwoPi * f * beat * t) + 0.25f * Mathf.Sin(TwoPi * f * 2.003f * t)) * decay * (j < 2 ? 1.3f : 1f);\n                }\n                s /= chord.Length;\n                // one far bell (E5)... answered a step lower (D5), quieter: the question nobody answers\n                if (t > 0.6f) s += 0.32f * Bellish(659.26f, t - 0.6f);\n                if (t > 2.4f) s += 0.2f * Bellish(587.33f, t - 2.4f);\n                lpw += (Noise() - lpw) * 0.015f;                     // wind in the tail\n                s += lpw * 0.5f * Mathf.Clamp01((t - 1.5f) / 3f) * Mathf.Exp(-Mathf.Max(0f, t - 6f) * 0.6f);\n                d[i] = s * atk;\n            }\n            Normalize(d, 0.85f);\n            return Make(\"bloom\", d);\n        }\n\n        /// <summary>Screen flash click.</summary>\n        public static AudioClip Click()\n        {\n            AudioClip c; if (Cached(\"click\", out c)) return c;\n            int n = (int)(SR * 0.06f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                d[i] = (Mathf.Sin(TwoPi * 2200f * t) * 0.6f + Noise() * 0.4f) * Mathf.Exp(-t * 90f);\n            }\n            Normalize(d, 0.4f);\n            return Make(\"click\", d);\n        }\n\n        /// <summary>Glitchy PA - the system stuttering.</summary>\n        public static AudioClip Glitch()\n        {\n            AudioClip c; if (Cached(\"glitch\", out c)) return c;\n            int n = (int)(SR * 0.8f);\n            float[] d = new float[n];\n            for (int i = 0; i < n; i++)\n            {\n                float t = i / (float)SR;\n                bool on = ((int)(t * 23f)) % 3 != 0;\n                d[i] = on ? (Mathf.Sign(Mathf.Sin(TwoPi * (300f + 900f * Mathf.Repeat(t * 7f, 1f)) * t)) * 0.4f + Noise() * 0.3f) * (1f - t / 0.8f) : 0f;\n            }\n            Normalize(d, 0.45f);\n            return Make(\"glitch\", d);\n        }\n    }\n}\n"},"DangerFX":{"path":"Assets/Game/Scripts/DangerFX.cs","role":"Red vignette and colour fringing that grow while you are being seen","source":"// @role Red vignette and colour fringing that grow while you are being seen\nusing UnityEngine;\nusing UnityEngine.Rendering;\nusing UnityEngine.Rendering.Universal;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Screen-side danger feedback (URP post-processing, built at runtime):\n    /// a deep-red vignette + chromatic aberration that grow while you are being seen,\n    /// and a hard red flash when a warning is given. Also darkens the screen while lying down.\n    /// </summary>\n    public class DangerFX : MonoBehaviour\n    {\n        [Range(0f, 1f)] public float level;\n        Volume vol;\n        Vignette vig;\n        ChromaticAberration ca;\n        float flash;\n\n        public static DangerFX Create(Transform parent)\n        {\n            GameObject g = new GameObject(\"DangerFX\");\n            g.transform.SetParent(parent, false);\n            return g.AddComponent<DangerFX>();\n        }\n\n        void Awake()\n        {\n            vol = gameObject.AddComponent<Volume>();\n            vol.isGlobal = true;\n            vol.priority = 100f;\n            VolumeProfile p = ScriptableObject.CreateInstance<VolumeProfile>();\n            vig = p.Add<Vignette>(false);\n            vig.color.Override(new Color(0.55f, 0f, 0.02f));\n            vig.intensity.Override(0.52f);\n            vig.smoothness.Override(0.8f);\n            ca = p.Add<ChromaticAberration>(false);\n            ca.intensity.Override(0.75f);\n            vol.sharedProfile = p;\n            vol.weight = 0f;\n        }\n\n        public void Flash() { flash = 1f; }\n\n        void Update()\n        {\n            if (flash > 0f) flash -= Time.unscaledDeltaTime * 1.1f;\n            vol.weight = Mathf.Clamp01(level * level * 0.9f + Mathf.Max(0f, flash));\n        }\n    }\n}\n"},"EndScreen":{"path":"Assets/Game/Scripts/EndScreen.cs","role":"Page after each chapter: CAUGHT (retry), chapter complete (continue), or one of the two endings","source":"// @role Page after each chapter: CAUGHT (retry), chapter complete (continue), or one of the two endings\n// @calls GameFlow, AmbientAudio, AudioSynth\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The page between chapters (builds its own UI). Reads GameFlow.lastResult / lastLevel / endingChoice.\n    ///  - Caught      -> what happened in that chapter. [Retry chapter] [Title]\n    ///  - Chapter won -> a short \"what you did\". [Continue] [Title]\n    ///  - Last chapter-> ENDING (The Seat / Lights) + epilogue + credits. [Play Again] [Title]\n    /// </summary>\n    public class EndScreen : MonoBehaviour\n    {\n        static readonly Color Paper = new Color(0.93f, 0.90f, 0.82f);\n        static readonly Color Red = new Color(0.86f, 0.18f, 0.14f);\n        static readonly Color Warm = new Color(1f, 0.85f, 0.55f);\n\n        static readonly string[] WinHead = { \"SOMEONE ANSWERED\", \"THE STAIRS GO DOWN\", \"SOMEONE FLASHED BACK\", \"SAY \\\"CLEARVIEW!\\\"\", \"THE LESSON NEVER ENDED\" };\n        static readonly string[] WinBody =\n        {\n            \"The one in front of you is one of them.\\nAfter the bell: the stairwell.\",\n            \"A message, passed hand to hand.\\nThe door marked STAFF was never locked.\\nIt was only watched.\",\n            \"Three lights across the yard.\\nOther dorms. Other rooms. Other phones.\\nYou are not the first. You are not the only.\",\n            \"Twenty reports. Three reporters.\\nA live screen with nobody on it.\\nAnd a photo from April 1967.\",\n            \"Five days in 1967, meant to end with the truth.\\nClearview kept the first four days.\\nTomorrow is the fifth.\",\n        };\n        static readonly string[] CaughtHead = { \"CAUGHT\", \"CONFISCATED\", \"LIGHTS OUT\", \"DEVELOPED\", \"SHHH\", \"INSPECTED\" };\n        static readonly string[] CaughtBody =\n        {\n            \"Three warnings.\\nThe phone is his now.\",\n            \"The Lunch Monitor files a report.\\nThe stairs stay closed. Lunch continues.\",\n            \"He took it with the flashlight still on your face.\\nSweet dreams.\",\n            \"Report number twenty-one.\\nYour citizen card comes back with a red X.\\nNow you report, too.\",\n            \"The librarian stamps your hand: RETURNED.\\nThe book goes back on the repair shelf.\",\n            \"One item found.\\n\\\"You'll thank me. Just like I was.\\\"\",\n        };\n\n        Text head, body, small;\n        AmbientAudio audioOut;\n\n        void Start()\n        {\n            Time.timeScale = 1f;\n            Cursor.lockState = CursorLockMode.None;\n            Cursor.visible = true;\n            UIFactory.EnsureEventSystem();\n            audioOut = AmbientAudio.Create(transform);\n            audioOut.droneVolume = 0.08f;\n            audioOut.ventVolume = 0.03f;\n\n            int lvl = Mathf.Max(0, GameFlow.LevelIndex(GameFlow.lastLevel));\n            bool won = GameFlow.lastResult == LessonResult.Win;\n            bool final = won && GameFlow.IsLastLevel(GameFlow.lastLevel);\n\n            Canvas canvas = UIFactory.MakeCanvas(\"EndCanvas\", 10);\n            Transform root = canvas.transform;\n            UIFactory.AddImage(UIFactory.Stretch(\"BG\", root), final && GameFlow.endingChoice == 2 ? new Color(0.06f, 0.08f, 0.1f) : new Color(0.05f, 0.05f, 0.055f));\n            Color accent = won ? Warm : Red;\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", root, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 10f)), accent);\n            Text label = UIFactory.AddText(UIFactory.Centered(\"Label\", root, 0f, 330f, 1600f, 40f), \"\", 24, new Color(0.6f, 0.6f, 0.6f), TextAnchor.MiddleCenter);\n            head = UIFactory.AddText(UIFactory.Centered(\"Headline\", root, 0f, 230f, 1700f, 140f), \"\", 96, accent, TextAnchor.MiddleCenter);\n            head.fontStyle = FontStyle.Bold;\n            body = UIFactory.AddText(UIFactory.Centered(\"Body\", root, 0f, 30f, 1500f, 260f), \"\", 32, Paper, TextAnchor.MiddleCenter);\n            small = UIFactory.AddText(UIFactory.Centered(\"Small\", root, 0f, -150f, 1500f, 110f), \"\", 22, new Color(0.62f, 0.62f, 0.64f), TextAnchor.MiddleCenter);\n            UIFactory.AddText(UIFactory.Rect(\"Footer\", root, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 30f), new Vector2(1600f, 34f)),\n                Loc.L(\"CLEARVIEW ACADEMY  -  WHAT IS SEEN, IS SAFE.\", \"明鉴学院  -  被看见的，就是安全的。\"), 18, new Color(0.7f, 0.22f, 0.2f), TextAnchor.MiddleCenter);\n\n            string h, b, s = \"\";\n            Button primary;\n            if (final)\n            {\n                bool lights = GameFlow.endingChoice == 2;\n                label.text = Loc.L(\"ENDING \", \"结局 \") + (lights ? \"2 / 2\" : \"1 / 2\");\n                h = lights ? Loc.L(\"LIGHTS\", \"灯火\") : Loc.L(\"THE SEAT\", \"座位\");\n                b = lights\n                    ? Loc.L(\"Every hidden screen in the room lit up at once.\\nThat afternoon, the room at the bottom of the stairs was full.\\nHe closed the door. From the outside.\", \"教室里每一块藏起来的屏幕同时亮了。\\n那天下午，楼梯底下的房间坐满了人。\\n他关上了门。从外面。\")\n                    : Loc.L(\"The phone stays behind the panel.\\nNext year, someone new sits in seat thirty-one.\\nThey will find it. They always do.\", \"手机留在挡板后面。\\n明年，会有新的人坐进三十一号座位。\\n他们会找到它的。一直都是这样。\");\n                s = (lights ? Loc.L(\"The PA said nothing happened today. For once, it was lying.\", \"广播说今天什么都没发生。这一次，它在撒谎。\") : Loc.L(\"What is seen, is safe. What is hidden, is passed on.\", \"被看见的，就是安全的。被藏起来的，会传下去。\"))\n                    + Loc.L(\"\\n\\nCOVER  -  a game by Ariel & Nina  -  CGDD 2026\", \"\\n\\nCOVER  -  Ariel & Nina 作品  -  CGDD 2026\");\n                primary = UIFactory.MakeButton(\"PrimaryButton\", root, Loc.L(\"Play Again\", \"再玩一次\"), -220f, -300f, 380f, 90f);\n                primary.onClick.AddListener(GameFlow.StartNewGame);\n                audioOut.Play(lights ? AudioSynth.Confirm() : AudioSynth.Chime(), 0.4f);\n            }\n            else if (won)\n            {\n                label.text = Loc.L(\"CHAPTER \", \"第 \") + (lvl + 1) + Loc.L(\"  COMPLETE\", \" 章  完成\");\n                h = Loc.T(WinHead[Mathf.Clamp(lvl, 0, WinHead.Length - 1)]);\n                b = Loc.T(WinBody[Mathf.Clamp(lvl, 0, WinBody.Length - 1)]);\n                if (lvl + 1 < GameFlow.LevelTitles.Length) s = Loc.L(\"NEXT:  CHAPTER \", \"下一章：\") + Loc.T(GameFlow.LevelTitles[lvl + 1]);\n                primary = UIFactory.MakeButton(\"PrimaryButton\", root, Loc.L(\"Continue\", \"继续\"), -220f, -300f, 380f, 90f);\n                primary.onClick.AddListener(GameFlow.NextLevel);\n                audioOut.Play(AudioSynth.Confirm(), 0.35f);\n            }\n            else\n            {\n                label.text = Loc.L(\"CHAPTER \", \"第 \") + (lvl + 1) + Loc.L(\"  -  GAME OVER\", \" 章  -  游戏结束\");\n                h = Loc.T(CaughtHead[Mathf.Clamp(lvl, 0, CaughtHead.Length - 1)]);\n                b = Loc.T(CaughtBody[Mathf.Clamp(lvl, 0, CaughtBody.Length - 1)]);\n                s = Loc.L(\"Try again from the start of this chapter.\", \"从本章开头重新开始。\");\n                primary = UIFactory.MakeButton(\"PrimaryButton\", root, Loc.L(\"Retry\", \"重试\"), -220f, -300f, 380f, 90f);\n                primary.onClick.AddListener(GameFlow.RetryLevel);\n                audioOut.Play(AudioSynth.Stinger(), 0.5f);\n            }\n            Button title = UIFactory.MakeButton(\"TitleButton\", root, Loc.L(\"Title\", \"标题画面\"), 220f, -300f, 380f, 90f);\n            title.onClick.AddListener(GameFlow.GoToTitle);\n            StartCoroutine(Type(h, b, s));\n        }\n\n        IEnumerator Type(string h, string b, string s)\n        {\n            yield return TypeInto(head, h, 18f);\n            yield return new WaitForSeconds(0.25f);\n            yield return TypeInto(body, b, 60f);\n            small.text = s;\n        }\n\n        IEnumerator TypeInto(Text t, string s, float cps)\n        {\n            for (int i = 1; i <= s.Length; i++)\n            {\n                t.text = s.Substring(0, i);\n                if (char.IsLetterOrDigit(s[i - 1]) && i % 2 == 0) audioOut.Play(AudioSynth.Tick(), 0.08f, Random.Range(0.9f, 1.1f));\n                if (GameInput.AnyKeyDown()) { t.text = s; yield break; }\n                yield return new WaitForSeconds(1f / cps);\n            }\n        }\n    }\n}\n"},"Fluorescent":{"path":"Assets/Game/Scripts/Fluorescent.cs","role":"Ceiling fluorescent light with buzz; neglected ones flicker","source":"// @role Ceiling fluorescent light with buzz; neglected ones flicker\n// @calls AudioSynth\n// @tune buzzVolume:float:0-0.3:fluorescent buzz loudness\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// A ceiling fluorescent fixture: light + glowing tube + 3D buzz.\n    /// \"Flicker\" fixtures (neglected areas) drop out at random, buzz louder and crackle.\n    /// </summary>\n    public class Fluorescent : MonoBehaviour\n    {\n        public Light lightSource;\n        public Renderer tube;\n        public bool flicker;\n        public Color emission = new Color(1.6f, 1.7f, 1.75f);\n        public float buzzVolume = 0.07f;\n        [Tooltip(\"0 = off. Lets a level dim or switch off the lights.\")]\n        [Range(0f, 1f)] public float master = 1f;\n\n        float baseIntensity, level = 1f, offUntil, nextEvent;\n        MaterialPropertyBlock mpb;\n        AudioSource buzz;\n\n        void Awake()\n        {\n            if (lightSource != null) baseIntensity = lightSource.intensity;\n            mpb = new MaterialPropertyBlock();\n            buzz = gameObject.AddComponent<AudioSource>();\n            buzz.clip = AudioSynth.FluorescentHum();\n            buzz.loop = true;\n            buzz.spatialBlend = 1f;\n            buzz.rolloffMode = AudioRolloffMode.Linear;\n            buzz.minDistance = 0.6f;\n            buzz.maxDistance = 7f;\n            buzz.dopplerLevel = 0f;\n            buzz.volume = buzzVolume;\n            buzz.pitch = Random.Range(0.97f, 1.03f);\n            buzz.playOnAwake = false;\n            buzz.time = Random.Range(0f, 1.9f);\n            buzz.Play();\n            nextEvent = Time.time + Random.Range(0.5f, 4f);\n        }\n\n        void Update()\n        {\n            float target = 1f;\n            if (flicker)\n            {\n                if (Time.time > nextEvent)\n                {\n                    // a burst of 1-4 quick drop-outs, then a pause\n                    offUntil = Time.time + Random.Range(0.04f, 0.18f);\n                    nextEvent = Time.time + (Random.value < 0.6f ? Random.Range(0.08f, 0.35f) : Random.Range(1.5f, 6f));\n                }\n                if (Time.time < offUntil) target = Random.value < 0.3f ? 0.25f : 0.02f;\n            }\n            level = target;\n            float k = level * master;\n            if (lightSource != null) lightSource.intensity = baseIntensity * k;\n            if (tube != null)\n            {\n                tube.GetPropertyBlock(mpb);\n                mpb.SetColor(\"_EmissionColor\", emission * k);\n                tube.SetPropertyBlock(mpb);\n            }\n            buzz.volume = buzzVolume * master * (flicker && level < 0.5f ? 2.2f : 1f);\n        }\n    }\n}\n"},"Footsteps":{"path":"Assets/Game/Scripts/Footsteps.cs","role":"3D footsteps (and the warden's keys) so you can hear where a watcher is","source":"// @role 3D footsteps (and the warden's keys) so you can hear where a watcher is\n// @calls AudioSynth\n// @tune stepLength:float:0.3-1.2:metres per step sound\n// @tune volume:float:0-1:footstep loudness\n// @tune maxDistance:float:5-30:how far footsteps carry (m)\n// @tune keysEverySteps:int:0-10:key jingle every N steps (0 = never)\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Footsteps (3D) for anyone who walks: you can hear where the teacher / monitor / warden is.\n    /// Optional key jingle every few steps (the night warden).\n    /// </summary>\n    public class Footsteps : MonoBehaviour\n    {\n        public float stepLength = 0.7f;\n        public float volume = 0.55f;\n        public float pitch = 1f;\n        public float minDistance = 1.5f;\n        public float maxDistance = 18f;\n        [Tooltip(\"0 = never. Otherwise a key jingle every N steps.\")]\n        public int keysEverySteps = 0;\n\n        AudioSource src;\n        AudioClip[] clips;\n        Vector3 last;\n        float acc;\n        int count;\n\n        void Awake()\n        {\n            src = gameObject.AddComponent<AudioSource>();\n            src.spatialBlend = 1f;\n            src.rolloffMode = AudioRolloffMode.Linear;\n            src.minDistance = minDistance;\n            src.maxDistance = maxDistance;\n            src.dopplerLevel = 0f;\n            src.playOnAwake = false;\n            clips = AudioSynth.Steps();\n            last = Flat(transform.position);\n        }\n\n        static Vector3 Flat(Vector3 v) { v.y = 0f; return v; }\n\n        void Update()\n        {\n            Vector3 p = Flat(transform.position);\n            float d = Vector3.Distance(p, last);\n            last = p;\n            if (d > 1f) return;   // teleported\n            acc += d;\n            if (acc < stepLength) return;\n            acc = 0f;\n            count++;\n            src.pitch = pitch * Random.Range(0.92f, 1.08f);\n            src.PlayOneShot(clips[Random.Range(0, clips.Length)], volume);\n            if (keysEverySteps > 0 && count % keysEverySteps == 0) src.PlayOneShot(AudioSynth.Keys(), volume * 0.6f);\n        }\n\n        /// <summary>Play a one-shot from this person's position (door creak, keys...).</summary>\n        public void PlayAt(AudioClip clip, float vol)\n        {\n            if (src != null && clip != null) src.PlayOneShot(clip, vol);\n        }\n    }\n}\n"},"GameFlow":{"path":"Assets/Game/Scripts/GameFlow.cs","role":"Scene flow: Title -> Chapter 1-6 (Monday to Friday) -> End page (win: next chapter, caught: retry); saves progress and the player name","source":"// @role Scene flow: Title -> Chapter 1-6 (Monday to Friday) -> End page (win: next chapter, caught: retry); saves progress and the player name\nusing UnityEngine;\nusing UnityEngine.SceneManagement;\n\nnamespace PhoneGame\n{\n    public enum LessonResult { None, Win, Caught, TimeUp }\n\n    /// <summary>\n    /// Scene-to-scene flow. Static, so it survives scene loads without a DontDestroyOnLoad object.\n    /// Title -> Chapter 1..6 -> End (after every chapter: win = Continue, caught = Retry this chapter).\n    /// The last chapter has two endings (endingChoice 1 = THE SEAT, 2 = LIGHTS).\n    /// Progress (highest chapter reached + the player's name) is saved in PlayerPrefs.\n    /// </summary>\n    public static class GameFlow\n    {\n        public const string TitleScene = \"Title\";\n        public const string EndScene = \"End\";\n        public static readonly string[] Levels = { \"Level01_Lesson\", \"Level02_Lunch\", \"Level03_LightsOut\", \"Level04_PictureDay\", \"Level05_Archive\", \"Level06_Inspector\" };\n        public static readonly string[] LevelTitles = { \"1   THE LESSON\", \"2   LUNCH\", \"3   LIGHTS OUT\", \"4   PICTURE DAY\", \"5   THE ARCHIVE\", \"6   INSPECTION DAY\" };\n\n        public static bool skipIntro;\n        /// <summary>Typed on the title page. The teacher uses it in the roll call and when he calls on you.</summary>\n        public static string playerName = \"Student\";\n        public static LessonResult lastResult = LessonResult.None;\n        public static string lastLevel = \"Level01_Lesson\";\n        public static string lastReason = \"\";\n        /// <summary>0 = not finished, 1 = \"The Seat\" (hid it), 2 = \"Lights\" (sent it to everyone).</summary>\n        public static int endingChoice;\n\n        const string KeyReached = \"cover_reached\";\n        const string KeyName = \"cover_name\";\n        static bool nameLoaded;\n\n        public static void LoadSavedName()\n        {\n            if (nameLoaded) return;\n            nameLoaded = true;\n            string n = PlayerPrefs.GetString(KeyName, \"\");\n            if (!string.IsNullOrEmpty(n)) playerName = n;\n        }\n\n        /// <summary>Highest chapter index (0-based) the player may start from.</summary>\n        public static int ReachedLevel\n        {\n            get { return Mathf.Clamp(PlayerPrefs.GetInt(KeyReached, 0), 0, Levels.Length - 1); }\n            set { PlayerPrefs.SetInt(KeyReached, Mathf.Clamp(value, 0, Levels.Length - 1)); PlayerPrefs.Save(); }\n        }\n\n        public static void SaveName(string n)\n        {\n            playerName = string.IsNullOrEmpty(n) ? \"Student\" : n;\n            nameLoaded = true;\n            PlayerPrefs.SetString(KeyName, playerName);\n            PlayerPrefs.Save();\n        }\n\n        public static int LevelIndex(string scene) { return System.Array.IndexOf(Levels, scene); }\n        public static bool IsLastLevel(string scene) { return LevelIndex(scene) == Levels.Length - 1; }\n\n        public static void StartNewGame()\n        {\n            ReachedLevel = 0;\n            LoadLevel(0);\n        }\n\n        public static void ContinueGame() { LoadLevel(ReachedLevel); }\n\n        public static void LoadLevel(int i)\n        {\n            LoadSavedName();\n            skipIntro = false;\n            endingChoice = 0;\n            Load(Levels[Mathf.Clamp(i, 0, Levels.Length - 1)]);\n        }\n\n        /// <summary>After a win: the next chapter.</summary>\n        public static void NextLevel()\n        {\n            int i = LevelIndex(lastLevel);\n            if (i < 0 || i >= Levels.Length - 1) { GoToTitle(); return; }\n            LoadLevel(i + 1);\n        }\n\n        /// <summary>Inside-style: back to the start of the SAME chapter.</summary>\n        public static void RetryLevel()\n        {\n            skipIntro = true;\n            endingChoice = 0;\n            Load(lastLevel);\n        }\n\n        public static void GoToTitle() { Load(TitleScene); }\n\n        public static void EndLevel(LessonResult result, string reason)\n        {\n            lastResult = result;\n            lastReason = reason;\n            lastLevel = SceneManager.GetActiveScene().name;\n            int i = LevelIndex(lastLevel);\n            if (result == LessonResult.Win && i >= 0 && i + 1 < Levels.Length && ReachedLevel < i + 1) ReachedLevel = i + 1;\n            Load(EndScene);\n        }\n\n        static void Load(string scene)\n        {\n            Time.timeScale = 1f;\n            AudioListener.volume = 1f;\n            SceneManager.LoadScene(scene);\n        }\n    }\n}\n"},"GameSpeed":{"path":"Assets/Game/Scripts/GameSpeed.cs","role":"2x story speed (Tab, or the title page): dialogue, messages, typing, loading bars and scripted waits run twice as fast - walking and watchers don't","source":"// @role 2x story speed (Tab, or the title page): dialogue, messages, typing, loading bars and scripted waits run twice as fast - walking and watchers don't\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Story speed. 2x makes everything you WAIT for faster: subtitles (typing + how long they stay), phone messages,\n    /// start-up / app loading, typing a reply, scripted pauses between story beats (e.g. after lights out).\n    /// It does NOT speed up walking, the watchers or the class-photo countdown (that would change the challenge).\n    /// Saved, so it stays on between chapters. Toggle with Tab in a chapter, or on the title page.\n    /// </summary>\n    public static class GameSpeed\n    {\n        const string Key = \"cover_speed2x\";\n        static int fast = -1;\n\n        public static bool Fast\n        {\n            get { if (fast < 0) fast = PlayerPrefs.GetInt(Key, 0); return fast == 1; }\n            set { fast = value ? 1 : 0; PlayerPrefs.SetInt(Key, fast); PlayerPrefs.Save(); }\n        }\n\n        public static float Factor { get { return Fast ? 2f : 1f; } }\n\n        /// <summary>Time.deltaTime at story speed.</summary>\n        public static float Dt { get { return Time.deltaTime * Factor; } }\n    }\n}\n"},"HumSource":{"path":"Assets/Game/Scripts/HumSource.cs","role":"The girl who hums: 3D off-key anthem you find by listening (fades in only when close)","source":"// @role The girl who hums: 3D off-key anthem you find by listening (fades in only when close)\n// @calls AudioSynth\n// @tune volume:float:0-1:humming loudness\n// @tune maxDistance:float:2-15:from how far you can start to hear her (m)\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>A student humming an off-key anthem - you find her by listening.</summary>\n    public class HumSource : MonoBehaviour\n    {\n        public float volume = 0.8f;\n        public float maxDistance = 6.5f;\n        AudioSource src;\n\n        void Awake()\n        {\n            src = gameObject.AddComponent<AudioSource>();\n            src.clip = AudioSynth.HumMelody();\n            src.loop = true;\n            src.spatialBlend = 1f;\n            src.rolloffMode = AudioRolloffMode.Linear;\n            src.minDistance = 0.8f;\n            src.maxDistance = maxDistance;\n            src.dopplerLevel = 0f;\n            src.volume = volume;\n            src.playOnAwake = false;\n            src.Play();\n        }\n\n        public bool Humming { get { return src != null && src.isPlaying; } }\n\n        public void StopHumming()\n        {\n            if (src != null) src.Stop();\n        }\n    }\n}\n"},"Interactable":{"path":"Assets/Game/Scripts/Interactable.cs","role":"Anything the player can use with E (desk cubby, panel, phone, shoulder tap, seats, doors)","source":"// @role Anything the player can use with E (desk cubby, panel, phone, shoulder tap, seats, doors)\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Something the player can use by looking at it (crosshair) and pressing E.\n    /// The level director sets prompt / active / onUse.\n    /// </summary>\n    public class Interactable : MonoBehaviour\n    {\n        public string prompt = \"Use\";\n        public bool active = true;\n        public System.Action onUse;\n    }\n}\n"},"Level01Director":{"path":"Assets/Game/Scripts/Level01Director.cs","role":"Chapter 1 The Lesson: walked to your seat, roll call, find the phone in the desk, codes from the lecture, tap the student with the chalk triangle","source":"// @role Chapter 1 The Lesson: walked to your seat, roll call, find the phone in the desk, codes from the lecture, tap the student with the chalk triangle\n// @calls LevelDirectorBase, TeacherAI, TeacherVision, PhoneController, PlayerRig, Interactable\n// @tune answerSeconds:float:4-20:time to answer when the teacher calls on you\n// @tune firstCallAtBootSecond:float:0-5:the first question comes this many seconds into the phone start-up\nusing System.Collections;\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 1 \"The Lesson\".\n    ///  1. Hallway: the teacher calls you in. Walking through the door you are pulled to your seat while the\n    ///     class turns to stare. No control during the walk.\n    ///  2. ROLL CALL: the teacher reads names (yours too - answer with 1). Between names, the player's\n    ///     thoughts quietly explain the rules (devices monitored, random questions, three warnings, the desk).\n    ///  3. Desk cubby -> books -> loose back panel -> the old phone.\n    ///  4. Codes come from numbers the teacher says: founding year 1952 (phone), lights-out 21:00 -> 2100 (Photos).\n    ///  5. A photo shows the sign of the student in front of you -> tap their shoulder -> WIN.\n    ///  Only ONE subtitle is on screen at a time: teacher (top) OR thought (bottom-left).\n    ///  Danger: while he can see the phone, the phone shakes and turns red. Full = a warning.\n    ///  Three warnings, never shown as UI - the teacher says so. Third: he takes the phone (LOSE).\n    /// </summary>\n    public class Level01Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public TeacherAI teacher;\n        public TeacherVision vision;\n        public Transform seatPoint;\n        public Interactable cubbyZone, books, loosePanel, hiddenPhone, frontStudent;\n        [Tooltip(\"The chair of the student in front - they turn around together with it.\")]\n        public Transform frontChair;\n        public Transform takePhoneStandPoint;\n        [Tooltip(\"The school bell at the very start.\")]\n        public AudioClip bellClip;\n\n        [Header(\"Classroom doors (x min, z min, x max, z max) - entering one pulls you to your seat\")]\n        public Vector4 backDoorZone = new Vector4(8.6f, 0f, 9.95f, 2.2f);\n        public Vector4 frontDoorZone = new Vector4(8.6f, 9.8f, 9.95f, 12f);\n        public float sideAisleX = 9.3f;\n        public float backAisleZ = 1.0f;\n\n        [Header(\"Questions\")]\n        public float answerSeconds = 10f;\n        public Vector2 callInterval = new Vector2(35f, 60f);\n        [Tooltip(\"The first question always comes this many seconds into the first phone start-up.\")]\n        public float firstCallAtBootSecond = 3f;\n\n        [Header(\"Roll call (the player's name goes after these)\")]\n        // Roll-call names are an homage: Irving Adler (the teacher fired under New York's Feinberg Law - Adler v. Board\n        // of Education, 1952), Harry Keyishian (whose case struck that law down in January 1967), Ellwood Cubberley\n        // (the school reformer the Cubberley Wing / Cubberley High School is named after) and Bert, the turtle from\n        // the 1952 school film \"Duck and Cover\".\n        public string[] namesBefore = { \"Irving Adler\", \"Harry Keyishian\", \"Ellwood Cubberley\" };\n        public string[] namesAfter = { \"Bert Turtle\" };\n\n        float nextCall = -1f;\n        bool seated, calling, rollCall, bootCallDone, cubbySearched, toldAboutDanger, staring;\n        LessonQuestion question;\n        float callTimer;\n        int linesSaid = -1;\n        readonly List<int> asked = new List<int>();\n        readonly List<Transform> classmates = new List<Transform>();\n        readonly List<Quaternion> classmateRest = new List<Quaternion>();\n        Coroutine lecture;\n\n        // ------------------------------------------------------------------ setup\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"TEACHER\";\n            authorityPitch = 0.8f;\n            if (phone != null) { phone.hasPhone = false; phone.allowRaise = false; phone.phoneClock = \"09:05\"; }\n            SetupDesk();\n            foreach (Transform t in FindObjectsByType<Transform>(FindObjectsInactive.Exclude, FindObjectsSortMode.None))\n            {\n                if (!t.name.StartsWith(\"Fig_Classmate_Seated\")) continue;\n                classmates.Add(t);\n                classmateRest.Add(t.rotation);\n            }\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (teacher != null) teacher.Begin();\n            StartCoroutine(Opening());\n        }\n\n        void SetupDesk()\n        {\n            if (cubbyZone != null)\n            {\n                cubbyZone.prompt = L(\"Search your desk\", \"翻找课桌\");\n                cubbyZone.active = false;   // unlocked after the roll call\n                cubbyZone.onUse = () => { rig.EnterInspect(); SetZone(false); cubbySearched = true; };\n            }\n            if (books != null) { books.prompt = L(\"Move the books aside\", \"把书挪到一边\"); books.onUse = () => StartCoroutine(MoveBooks()); }\n            if (loosePanel != null) { loosePanel.prompt = L(\"The back panel is loose - pull it out\", \"背板松了——把它拉出来\"); loosePanel.active = false; loosePanel.onUse = () => StartCoroutine(PullPanel()); }\n            if (hiddenPhone != null) { hiddenPhone.prompt = L(\"Take the phone\", \"拿起手机\"); hiddenPhone.active = false; hiddenPhone.onUse = TakePhone; }\n            if (frontStudent != null) { frontStudent.prompt = L(\"Tap their shoulder twice\", \"轻拍两下前桌的肩膀\"); frontStudent.active = false; frontStudent.onUse = () => StartCoroutine(StudentTurns()); }\n        }\n\n        void SetZone(bool on)\n        {\n            if (cubbyZone == null) return;\n            foreach (Collider c in cubbyZone.GetComponents<Collider>()) c.enabled = on;\n        }\n\n        protected override bool ReminderBlocked() { return calling || rollCall; }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelAlways() { UpdateStare(); }\n\n        protected override void LevelUpdate()\n        {\n            if (rig.CurrentMode == PlayerRig.Mode.Walk && EnteredClassroom(rig.transform.position)) BeginPull();\n\n            phone.allowRaise = rig.CurrentMode == PlayerRig.Mode.Seated && phone.hasPhone;\n            if (phone.hasPhone && phone.RaisedOnce && !toldAboutDanger)\n            {\n                toldAboutDanger = true;\n                Thought(L(\"If he can see it, \", \"只要他看得见，\") + Rule(L(\"the phone shakes and turns red\", \"手机就会抖动、变红\")) + L(\".\\nKeep it out of his sight.\", \"。\\n别让他看见。\"));\n            }\n\n            UpdateObjective();\n            UpdateInteraction();\n            UpdateDanger();\n            UpdateCalls();\n        }\n\n        void UpdateObjective()\n        {\n            if (rig.CurrentMode == PlayerRig.Mode.Walk) { SetObjective(L(\"Walk into the classroom.\\n(W + mouse)\", \"走进教室。\\n（W + 鼠标）\")); return; }\n            if (!seated) { SetObjective(\"\"); return; }\n            if (rollCall) { SetObjective(L(\"Roll call.\\nPress 1 when YOUR name is called.\", \"点名。\\n叫到你的名字时按 1。\")); return; }\n            if (!phone.hasPhone) { SetObjective(L(\"Search your desk.\\nLook down at the cubby and press E.\", \"翻找课桌。\\n低头看向桌肚，按 E。\")); return; }\n            if (!phone.IsUnlocked(PhoneController.AppPhotos)) { SetObjective(L(\"Sit up, HOLD RIGHT MOUSE.\\nPhone code = the year the school was founded. Then PHOTOS = lights out (24-hour clock).\", \"坐直，按住鼠标右键。\\n手机密码 = 学校建校的年份。相册密码 = 熄灯时间（24 小时制）。\")); return; }\n            if (!phone.ClueFound) { SetObjective(L(\"Look through PHOTOS (A / D).\\nOne of them shows a mark you can find in this room.\", \"翻看相册（A / D）。\\n其中一张照片上的记号，就在这间教室里。\")); return; }\n            SetObjective(L(\"Tap the shoulder of the student\\nwith the chalk triangle (E).\", \"轻拍椅背上有粉笔三角的\\n那位同学（E）。\"));\n        }\n\n        bool EnteredClassroom(Vector3 p) { return In(p, backDoorZone) || In(p, frontDoorZone); }\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        // ------------------------------------------------------------------ opening & walk in\n        IEnumerator Opening()\n        {\n            // quick start: he calls you in almost immediately; you can walk once he has spoken\n            rig.Lock();\n            caption.text = L(\"MONDAY.  FIRST PERIOD.\", \"星期一。第一节课。\");\n            if (bellClip != null) ambient.Play(bellClip, 0.85f);\n            StartCoroutine(Fade(1f, 0f, 1.2f));\n            yield return Wait(bellClip != null ? 2.6f : 0.5f);\n            Authority(L(\"(from inside the classroom)  ...The bell has rung. Whoever is standing at the door. In. Now.\", \"（教室里传来）……铃已经响了。站在门口的那个。进来。现在。\"), 4.5f, true, 0.3f);\n            yield return Wait(1.2f);\n            caption.text = \"\";\n            if (rig.CurrentMode == PlayerRig.Mode.Locked && !seated) rig.AllowWalk();\n            Thought(L(\"Late. Everyone is going to stare.\\nW + mouse: walk into the classroom\", \"迟到了。所有人都会盯着我看。\\nW + 鼠标：走进教室\"), 30f, false, 0.3f);\n        }\n\n        void BeginPull()\n        {\n            Vector3 p = rig.transform.position;\n            Vector3 s = seatPoint.position;\n            Vector3[] path =\n            {\n                new Vector3(sideAisleX, p.y, Mathf.Clamp(p.z, backAisleZ, 11f)),\n                new Vector3(sideAisleX, p.y, backAisleZ),\n                new Vector3(s.x + 0.8f, p.y, backAisleZ),\n                new Vector3(s.x, p.y, backAisleZ + 0.15f),\n                s,\n            };\n            rig.pullLookYaw = seatPoint.eulerAngles.y;\n            rig.PullToSeat(path, s, seatPoint.eulerAngles.y, OnSeated);\n            staring = true;\n            if (teacher != null) teacher.CallOn(rig.transform);\n            // short gaps here - these lines play while you are being walked to your seat\n            Authority(L(\"You're late, \" + Name + \".\", Name + \"，你迟到了。\"), 2.8f, true, 0.3f);\n            Authority(L(\"Everyone has been waiting for you.\", \"所有人都在等你。\"), 3f, false, 0.3f);\n            Authority(L(\"Sit.\", \"坐下。\"), 2f, false, 0.5f);\n        }\n\n        void OnSeated()\n        {\n            seated = true;\n            StartCoroutine(RollCall());\n        }\n\n        // ------------------------------------------------------------------ roll call (rules told through thoughts)\n        IEnumerator RollCall()\n        {\n            rollCall = true;\n            yield return WaitIdle();\n            staring = false;\n\n            Authority(L(\"Roll call. Answer when you hear your name.\", \"点名。听到名字就答到。\"), 2.2f, false, 0.15f);\n            yield return RollName(namesBefore.Length > 0 ? namesBefore[0] : null);\n            Thought(Rule(L(\"Every device in this school is monitored.\", \"这所学校的每台设备都被监控着。\")) + L(\"\\nIf he sees a phone, he takes it.\", \"\\n只要他看见手机，就会收走。\"), 4f, false, 0.15f);\n            yield return RollName(namesBefore.Length > 1 ? namesBefore[1] : null);\n            Thought(L(\"He calls on people at random.\\n\", \"他会随机点人回答问题。\\n\") + Rule(L(\"Listen to him\", \"认真听他讲\")) + L(\" - he only asks about what he has said.\", \"——他只问他讲过的内容。\"), 4f, false, 0.15f);\n            yield return RollName(namesBefore.Length > 2 ? namesBefore[2] : null);\n            Thought(L(\"The older kids say he gives \", \"学长学姐说他会给\") + Rule(L(\"three warnings\", \"三次警告\")) + L(\".\\nAfter the third, he takes whatever you're hiding.\", \"。\\n第三次之后，你藏的东西就归他了。\"), 4.5f, false, 0.15f);\n            yield return WaitIdle();\n\n            // the player's own name\n            bool answered = false;\n            for (int attempt = 0; attempt < 2 && !answered && !ended; attempt++)\n            {\n                Authority(attempt == 0 ? Name + L(\".\", \"。\") : L(Name + \". I said your name.\", Name + \"。我叫你的名字了。\"), 99f, true);\n                ShowQuestion(L(\"Your name was called.\\n\\n1    \\\"Here.\\\"\", \"叫到你的名字了。\\n\\n1    \\\"到。\\\"\"));\n                float t = 0f;\n                while (t < answerSeconds && !answered)\n                {\n                    t += Time.deltaTime;\n                    questionTimer.rectTransform.anchorMax = new Vector2(1f - t / answerSeconds, 1f);\n                    questionStatus.text = phone.IsExposed ? L(\"Put the phone down first!\", \"先把手机放下！\") : L(\"Press 1\", \"按 1\");\n                    if (!phone.IsExposed && GameInput.DigitDown() == 1) answered = true;\n                    yield return null;\n                }\n                questionBox.SetActive(false);\n                ClearLine();\n            }\n            if (answered) { StudentSay(Name, L(\"Here.\", \"到。\"), 1f, false, 0.15f); Authority(L(\"...Late, and slow. Noted.\", \"……迟到，还反应慢。记下了。\"), 2.2f, false, 0.2f); }\n            else Authority(L(\"...Present, I suppose. Barely.\", \"……算你在吧。勉强。\"), 2.2f, false, 0.2f);\n            // the desk can be searched right away (the rest of the roll call goes on around you)\n            rollCall = false;\n            if (cubbyZone != null) cubbyZone.active = true;\n            StartCoroutine(Reminder(L(\"(Something about this desk feels off... look down at the cubby.)\", \"（这张课桌有点不对劲……低头看看桌肚。）\"), () => cubbySearched, 30f));\n\n            Thought(L(\"And this seat... they say whoever sits here\\n\", \"还有这个座位……据说坐在这里的人\\n\") + Rule(L(\"finds something in the desk\", \"都会在课桌里找到点什么\")) + L(\".\", \"。\"), 4.5f, false, 0.15f);\n            foreach (string n in namesAfter) yield return RollName(n);\n            Authority(L(\"Good. Today: the Founding Charter. Listen carefully. I will be asking questions.\", \"很好。今天讲《建校章程》。认真听，我会提问。\"), 3.8f, false, 0.3f);\n            yield return WaitIdle();\n\n            if (teacher != null) teacher.EndCall();\n            lecture = StartCoroutine(Lecture());\n        }\n\n        IEnumerator RollName(string n)\n        {\n            if (string.IsNullOrEmpty(n)) yield break;\n            string shown = Loc.T(n);\n            Authority(shown + L(\".\", \"。\"), 1f, false, 0.1f);\n            StudentSay(shown, L(\"Here.\", \"到。\"), 0.8f, false, 0.15f);\n            yield return null;\n        }\n\n        // ------------------------------------------------------------------ the classmates stare while you walk in\n        void UpdateStare()\n        {\n            for (int i = 0; i < classmates.Count; i++)\n            {\n                Transform t = classmates[i];\n                if (t == null) continue;\n                if (frontStudent != null && t == frontStudent.transform && ended && strikes < chances) continue;  // turning to you (win)\n                if (staring)\n                {\n                    Vector3 d = rig.transform.position - t.position; d.y = 0f;\n                    if (d.sqrMagnitude < 0.01f) continue;\n                    // a small twist only - a seated body can't spin round without going through the chair and desk\n                    Quaternion limited = Quaternion.RotateTowards(classmateRest[i], Quaternion.LookRotation(d), 32f);\n                    t.rotation = Quaternion.RotateTowards(t.rotation, limited, 60f * Time.deltaTime);\n                }\n                else t.rotation = Quaternion.RotateTowards(t.rotation, classmateRest[i], 40f * Time.deltaTime);\n            }\n        }\n\n        // ------------------------------------------------------------------ interaction\n        void UpdateInteraction()\n        {\n            string p = null;\n            PlayerRig.Mode m = rig.CurrentMode;\n            if (m == PlayerRig.Mode.Seated || m == PlayerRig.Mode.Inspect)\n            {\n                if (m == PlayerRig.Mode.Inspect && GameInput.SpaceDown()) { rig.BackToSeat(); SetZone(true); SetPrompt(null); return; }\n                p = RaycastInteract();\n                if (p == null && m == PlayerRig.Mode.Inspect) p = L(\"[Space]  Sit back up\", \"[空格]  坐直\");\n            }\n            SetPrompt(p);\n        }\n\n        IEnumerator MoveBooks()\n        {\n            // slid to the left side of the cubby - they stay where you can see them\n            books.active = false;\n            Transform t = books.transform;\n            Vector3 from = t.localPosition, to = from + new Vector3(-0.23f, 0f, 0f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.6f) { t.localPosition = Vector3.Lerp(from, to, k * k * (3f - 2f * k)); yield return null; }\n            t.localPosition = to;\n            if (loosePanel != null) loosePanel.active = true;\n        }\n\n        IEnumerator PullPanel()\n        {\n            // pulled towards you, then set aside to the right - still in view\n            loosePanel.active = false;\n            Transform t = loosePanel.transform;\n            foreach (Collider c in t.GetComponentsInChildren<Collider>()) c.enabled = false;\n            Vector3 a = t.localPosition, b = a + new Vector3(0f, 0f, -0.14f), c2 = b + new Vector3(0.16f, 0f, 0f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(a, b, k * k * (3f - 2f * k)); yield return null; }\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(b, c2, k * k * (3f - 2f * k)); yield return null; }\n            t.localPosition = c2;\n            if (hiddenPhone != null) hiddenPhone.active = true;\n            Thought(L(\"There's something hidden behind it.\", \"后面藏着东西。\"), 4f, true);\n        }\n\n        void TakePhone()\n        {\n            hiddenPhone.active = false;\n            hiddenPhone.gameObject.SetActive(false);\n            phone.hasPhone = true;\n            nextCall = Random.Range(callInterval.x, callInterval.y);\n            Thought(L(\"(An old phone. A sticky note on the back: \\\"it opens the year it all began.\\\")\", \"（一部旧手机。背面贴着一张便利贴：\\\"密码是一切开始的那一年。\\\"）\"), 8f, true);\n            StartCoroutine(Reminder(L(\"Sit up [Space], then \", \"先坐直 [空格]，再\") + Rule(L(\"HOLD RIGHT MOUSE\", \"按住鼠标右键\")) + L(\" to take out the phone.\", \"拿出手机。\"), () => phone.RaisedOnce || ended, 20f));\n        }\n\n        IEnumerator StudentTurns()\n        {\n            ended = true;\n            frontStudent.active = false;\n            phone.allowRaise = false;\n            rig.Lock();\n            if (lecture != null) StopCoroutine(lecture);\n            Thought(L(\"(You tap their shoulder. Twice.)\", \"（你拍了拍前桌的肩膀。两下。）\"), 1.8f, true);\n            yield return Wait(0.8f);\n            // they turn round to face you, chair and all (the chair spins with them, so nothing clips)\n            Transform s = frontStudent.transform;\n            Quaternion r0 = s.rotation;\n            Quaternion c0 = frontChair != null ? frontChair.rotation : Quaternion.identity;\n            for (float k = 0f; k <= 1f; k += GameSpeed.Dt / 0.8f)\n            {\n                float e = Mathf.Clamp01(k * k * (3f - 2f * k));\n                Quaternion turn = Quaternion.Euler(0f, -180f * e, 0f);   // both turn the same way (towards the window side)\n                s.rotation = r0 * turn;\n                if (frontChair != null) frontChair.rotation = c0 * turn;\n                yield return null;\n            }\n            s.rotation = r0 * Quaternion.Euler(0f, 180f, 0f);\n            if (frontChair != null) frontChair.rotation = c0 * Quaternion.Euler(0f, 180f, 0f);\n            yield return Wait(0.3f);\n            StudentSay(L(\"STUDENT (whispering)\", \"同学（小声）\"), L(\"...Took you long enough. Keep it hidden.\", \"……你可真慢。藏好它。\"), 2.8f, false, 0.15f);\n            StudentSay(L(\"STUDENT (whispering)\", \"同学（小声）\"), L(\"After the bell - the stairwell. I'll show you where we really go.\", \"下课后——楼梯间。我带你去我们真正去的地方。\"), 3.8f, false, 0.15f);\n            yield return Wait(0.3f);\n            yield return WaitIdle();\n            yield return FinishLevel(\"contact\", 1.2f);\n        }\n\n        // ------------------------------------------------------------------ danger (stealth)\n        void UpdateDanger()\n        {\n            bool seen = phone.IsExposed && teacher != null && teacher.Running && vision != null && vision.CanSee(phoneExposurePoint.position, rig.transform);\n            if (AccumulateDanger(seen ? 1f / Mathf.Max(0.05f, noticeSeconds) : 0f))\n                Strike(L(\"...What was that? Eyes up here, \" + Name + \".\", \"……那是什么？\" + Name + \"，看这边。\"));\n            if (phone.ClueFound && frontStudent != null && !frontStudent.active && !ended)\n            {\n                frontStudent.active = true;\n                Thought(L(\"A chalk triangle... \", \"粉笔三角……\") + Rule(L(\"the chair in front of me has one\", \"前桌的椅背上就有一个\")) + L(\".\", \"。\"), 7f);\n            }\n        }\n\n        protected override IEnumerator OnCaught()\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            phone.allowRaise = false;\n            rig.Lock();\n            if (lecture != null) StopCoroutine(lecture);\n            Authority(L(\"That's three, \" + Name + \". Give it to me.\", \"第三次了，\" + Name + \"。交出来。\"), 6f, true);\n            if (teacher != null && takePhoneStandPoint != null) teacher.Approach(takePhoneStandPoint.position, rig.transform);\n            staring = true;\n            float t = 0f;\n            yield return Wait(0.5f);\n            while (teacher != null && !teacher.HasArrived && t < 8f) { t += Time.deltaTime; yield return null; }\n            yield return WaitIdle();\n            Thought(L(\"(He takes the phone. Everyone saw.)\", \"（他拿走了手机。所有人都看见了。）\"), 4f, true);\n            yield return WaitIdle();\n            yield return Caught(\"taken\");\n        }\n\n        // ------------------------------------------------------------------ lecture & questions\n        IEnumerator Lecture()\n        {\n            int i = 0;\n            bool pa1 = false, pa2 = false;\n            while (!ended)\n            {\n                if (!calling && DialogueIdle && teacher != null && teacher.lines.Count > 0)\n                {\n                    int idx = i % teacher.lines.Count;\n                    if (idx > linesSaid) linesSaid = idx;\n                    string line = Loc.T(teacher.lines[idx].text);\n                    // as long as it takes to read, no longer\n                    Authority(line, Mathf.Clamp(1.4f + line.Length * (Loc.Chinese ? 0.1f : 0.042f), 2.4f, 5f), false, 0.25f);\n                    i++;\n                    yield return WaitIdle();\n                    // the school interrupts, politely (dark humour)\n                    if (i == 5 && !pa1) { pa1 = true; PA(L(\"This is a reminder that you are happy. Thank you.\", \"温馨提示：您很快乐。谢谢。\"), 3.2f, false, 0.25f); yield return WaitIdle(); }\n                    if (i == 10 && !pa2) { pa2 = true; PA(L(\"Reminder: the pigeons in the courtyard are not your friends.\", \"提醒：庭院里的鸽子不是您的朋友。\"), 3.4f, false, 0.25f); yield return WaitIdle(); }\n                    // a short pause between lines - this is where the player's thoughts get their turn\n                    float t = 0f;\n                    while (t < 1.1f && !ended) { if (DialogueIdle) t += GameSpeed.Dt; yield return null; }\n                }\n                yield return null;\n            }\n        }\n\n        void UpdateCalls()\n        {\n            if (!seated || rollCall || !phone.hasPhone || teacher == null) return;\n            if (!calling)\n            {\n                if (!bootCallDone && phone.BootSecondsElapsed >= firstCallAtBootSecond) { bootCallDone = true; StartCall(); return; }\n                if (nextCall > 0f) { nextCall -= GameSpeed.Dt; if (nextCall <= 0f) StartCall(); }\n                return;\n            }\n\n            callTimer -= Time.deltaTime;\n            questionTimer.rectTransform.anchorMax = new Vector2(Mathf.Clamp01(callTimer / answerSeconds), 1f);\n            bool canAnswer = rig.CurrentMode == PlayerRig.Mode.Seated && !phone.IsExposed;\n            if (phone.IsExposed) questionStatus.text = L(\"PUT THE PHONE DOWN to answer!  (release Right Mouse)\", \"先放下手机再回答！（松开鼠标右键）\");\n            else if (rig.CurrentMode != PlayerRig.Mode.Seated) questionStatus.text = L(\"SIT UP to answer!  [Space]\", \"坐直才能回答！[空格]\");\n            else questionStatus.text = L(\"Press 1, 2 or 3\", \"按 1、2 或 3\");\n\n            if (canAnswer)\n            {\n                int d = GameInput.DigitDown();\n                if (d >= 1 && d <= 3) { EndCall(d - 1 == question.correct, false); return; }\n            }\n            if (callTimer <= 0f) EndCall(false, true);\n        }\n\n        void StartCall()\n        {\n            question = PickQuestion();\n            if (question == null) { nextCall = 10f; return; }\n            calling = true;\n            callTimer = answerSeconds;\n            teacher.CallOn(rig.transform);\n            Authority(Name + L(\".  \", \"。\") + Loc.T(question.question), answerSeconds + 1f, true);\n            string q = Loc.T(question.question) + \"\\n\";\n            for (int i = 0; i < question.options.Length; i++) q += \"\\n\" + (i + 1) + \"    \" + Loc.T(question.options[i]);\n            ShowQuestion(q);\n        }\n\n        LessonQuestion PickQuestion()\n        {\n            List<int> pool = new List<int>();\n            for (int i = 0; i < teacher.questions.Count; i++)\n                if (teacher.questions[i].aboutLine <= linesSaid && !asked.Contains(i)) pool.Add(i);\n            if (pool.Count == 0)\n            {\n                asked.Clear();\n                for (int i = 0; i < teacher.questions.Count; i++) if (teacher.questions[i].aboutLine <= linesSaid) pool.Add(i);\n            }\n            if (pool.Count == 0) return null;\n            int pick = pool[Random.Range(0, pool.Count)];\n            foreach (int i in pool) if (teacher.questions[i].aboutLine >= 0 && Random.value < 0.7f) { pick = i; break; }\n            asked.Add(pick);\n            return teacher.questions[pick];\n        }\n\n        void EndCall(bool correct, bool timedOut)\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            teacher.EndCall();\n            nextCall = Random.Range(callInterval.x, callInterval.y);\n            if (correct) Authority(L(\"...Correct. Hm. Keep listening.\", \"……正确。哼。继续听。\"), 4f, true);\n            else if (timedOut) Strike(L(\"I asked you a question, \" + Name + \".\", Name + \"，我在问你问题。\"));\n            else Strike(L(\"Wrong. Are you even listening?\", \"错了。你到底有没有在听？\"));\n        }\n    }\n}\n"},"Level02Director":{"path":"Assets/Game/Scripts/Level02Director.cs","role":"Chapter 2 Lunch: sweeping camera + Lunch Monitor, follow the humming, forward the message within reach, sneak to the STAFF door and down the stairs","source":"// @role Chapter 2 Lunch: sweeping camera + Lunch Monitor, follow the humming, forward the message within reach, sneak to the STAFF door and down the stairs\n// @calls LevelDirectorBase, PatrolAI, TeacherVision, HumSource, PhoneController, PlayerRig, Interactable\n// @tune reachDistance:float:2-8:how close you must be to the girl for the message to send\nusing System.Collections;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 2 \"Lunch\" (the cafeteria).\n    ///  - New threat: a sweeping security camera + a roaming Lunch Monitor. Danger comes from WHERE you stand.\n    ///    Pillars block the camera; people and pillars block the Monitor. The hallway is the only unwatched place.\n    ///  - Phone: unlock again (1952), then Messages - its code is announced by the PA: lunch at 12:40 -> 1240.\n    ///  - Triangle's job: find the girl who hums when she's scared (listen for the humming), get close\n    ///    (this phone only reaches phones nearby) and forward \"the stairs are open tonight\".\n    ///  - Then slip behind the counters to the STAFF door while the camera looks at the windows. WIN.\n    ///  - Being seen with the phone, or seen behind the counters: a warning. Three: the phone is taken.\n    /// </summary>\n    public class Level02Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public PatrolAI monitor;\n        public TeacherVision monitorVision;\n        public TeacherVision[] cameras;\n        public Transform hummer;\n        public HumSource hum;\n        public Interactable staffDoor;\n        public Transform staffDoorLeaf;\n        [Tooltip(\"Bench seats you can sit on (position = seat, forward = facing the table).\")]\n        public Interactable[] seats;\n        [Header(\"The stairwell behind the STAFF door\")]\n        public Interactable bottomDoor;\n        public Transform bottomDoorHinge;\n        public Transform voicesPoint;\n        public Vector3 throughDoorPoint = new Vector3(17f, 0f, 12.65f);\n\n        [Header(\"Zones\")]\n        [Tooltip(\"Behind the counters (x min, z min, x max, z max). Being seen here = a warning.\")]\n        public Vector4 kitchenZone = new Vector4(16f, 10.88f, 29.95f, 11.95f);\n        public Vector3 kitchenReturnPoint = new Vector3(28.6f, 0f, 9.7f);\n        public float kitchenReturnYaw = 180f;\n        [Tooltip(\"Inside the dining hall (for the Monitor's first comment).\")]\n        public Vector4 diningZone = new Vector4(14.2f, 0.1f, 29.9f, 10.8f);\n        [Tooltip(\"This phone only reaches phones this close.\")]\n        public float reachDistance = 4f;\n\n        bool gotJob, taskGiven, delivered, enteredDining, toldKitchen, toldRaise, winning, heardHum, toldInReach, listened;\n        float taskTime;\n        bool throughDoor, saidPaint, saidChalk, saidVoices;\n        AudioSource voices;\n        Light hummerGlow;\n        float kitchenSeen, kitchenGrace, paTimer = 40f, monitorTalk;\n        Interactable sitting;\n\n        static readonly string[] ambientPA =\n        {\n            \"Reminder: smiling is part of your uniform.\",\n            \"Today's dessert has been cancelled for your safety. Enjoy your safety.\",\n            \"A student has been happy for fourteen consecutive days. Congratulations to everyone.\",\n            \"Please do not look out of the windows. The windows are for light.\",\n            \"Do not feed the pigeons. Pigeons are loud. Loud things are noticed.\",\n            \"Lunch ends in five minutes. Please finish being nourished.\",\n        };\n        int paIndex;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"LUNCH MONITOR\";\n            authorityPitch = 0.95f;\n            phone.hasPhone = true;\n            phone.allowRaise = false;\n            phone.phoneClock = \"12:41\";\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.lockNotification = L(\"No new messages.\", \"没有新信息。\");\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            if (staffDoor != null) { staffDoor.prompt = \"Slip through the STAFF door\"; staffDoor.onUse = UseDoor; }\n            if (bottomDoor != null) { bottomDoor.prompt = \"Push the door open\"; bottomDoor.onUse = PushBottomDoor; }\n            if (hummer != null)\n            {\n                Interactable it = hummer.GetComponent<Interactable>();\n                if (it == null) it = hummer.gameObject.AddComponent<Interactable>();\n                it.prompt = \"Listen to her\";\n                it.onUse = ListenToHer;\n                // her own phone, glowing under the table - this phone can only reach phones close by\n                GameObject g = new GameObject(\"HerPhoneGlow\");\n                g.transform.SetParent(hummer, false);\n                g.transform.localPosition = new Vector3(0f, 0.75f, 0.35f);\n                hummerGlow = g.AddComponent<Light>();\n                hummerGlow.type = LightType.Point;\n                hummerGlow.color = new Color(0.65f, 0.85f, 1f);\n                hummerGlow.range = 1.2f;\n                hummerGlow.intensity = 0f;\n            }\n            if (seats != null)\n                foreach (Interactable s in seats)\n                {\n                    if (s == null) continue;\n                    Interactable seat = s;\n                    seat.prompt = \"Sit down\";\n                    seat.onUse = () => SitOn(seat);\n                }\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (monitor != null) monitor.Begin();\n            rig.Lock();\n            StartCoroutine(Opening());\n        }\n\n        IEnumerator Opening()\n        {\n            yield return ChapterCard(\"CHAPTER 2\", \"LUNCH\", \"MONDAY  -  12:40\");\n            phone.Receive(\"Triangle\", L(\"check Messages. the code is when we eat.\", \"看信息。密码是我们吃饭的时间。\"));\n            PA(L(\"Good afternoon, Clearview. Lunch begins at twelve-forty. Twelve. Forty.\", \"下午好，明鉴学院。午餐将于十二点四十分开始。十二。四十。\"), 6.5f);\n            PA(L(\"Please chew each bite thirty-two times. Thank you for eating correctly.\", \"请将每一口咀嚼三十二次。感谢您正确地进食。\"), 6f);\n            yield return Wait(1.5f);\n            rig.AllowWalk();\n            SetObjective(L(\"Read Triangle's message.\\nStay in the HALLWAY (safe) and HOLD RIGHT MOUSE.\", \"读三角发来的信息。\\n待在走廊（安全）里，按住鼠标右键。\"));\n            Thought(L(\"Triangle said: after the bell, the stairwell.\\nBut the only stairs are \", \"三角说：下课后，楼梯间。\\n可唯一的楼梯在\") + Rule(L(\"behind the kitchen\", \"厨房后面\")) + L(\".\", \"。\"), 8f);\n            Thought(Rule(L(\"One camera. One Lunch Monitor.\", \"一台摄像头。一个午餐监督员。\")) + L(\"\\nThe hallway is the only place nobody watches.\", \"\\n只有走廊没人盯着。\"), 8f);\n            yield return WaitIdle();\n            StartCoroutine(Reminder(L(\"My phone buzzed. \", \"手机震了。\") + Rule(L(\"HOLD RIGHT MOUSE\", \"按住鼠标右键\")) + L(\" - here in the hallway, where it's safe.\", \"——就在走廊，这里安全。\"), () => phone.RaisedOnce || ended, 22f));\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            if (throughDoor)\n            {\n                // behind the STAFF door nobody is watching: no camera, no monitor, no phone needed\n                rig.freezeMovement = false;\n                phone.allowRaise = false;\n                UpdateStairs();\n                SetPrompt(rig.CurrentMode == PlayerRig.Mode.Walk ? RaycastInteract() : null);\n                return;\n            }\n            PlayerRig.Mode m = rig.CurrentMode;\n            phone.allowRaise = phone.hasPhone && (m == PlayerRig.Mode.Walk || m == PlayerRig.Mode.Seated);\n            rig.freezeMovement = phone.IsExposed;\n            if (phone.IsExposed && m == PlayerRig.Mode.Walk && !toldRaise)\n            {\n                toldRaise = true;\n                Thought(L(\"While I look at the phone, \", \"看手机的时候，\") + Rule(L(\"I stand still\", \"我站着不动\")) + L(\". Anyone looking can see it.\", \"。谁看过来都能看见。\"), 7f);\n            }\n\n            UpdateObjective();\n            UpdateHumHints();\n            UpdateInteraction();\n            UpdateStory();\n            UpdateDanger();\n            UpdateKitchen();\n            UpdateAmbientLines();\n        }\n\n        void UpdateInteraction()\n        {\n            string p = null;\n            if (rig.CurrentMode == PlayerRig.Mode.Seated)\n            {\n                if (GameInput.SpaceDown() && !phone.IsExposed) { StandUp(); SetPrompt(null); return; }\n                p = phone.IsExposed ? null : L(\"[Space]  Stand up\", \"[空格]  站起来\");\n            }\n            else if (rig.CurrentMode == PlayerRig.Mode.Walk) p = RaycastInteract();\n            if (phone.IsExposed && taskGiven && !delivered && phone.OpenApp == PhoneController.AppMessages && phone.UnreadCount == 0)\n                p = InReach() ? L(\"SIGNAL: STRONG  -  A / D pick \\\"Hums When Scared\\\", Left Mouse, then HOLD Left Mouse\", \"信号：强  -  A / D 选\\\"害怕时会哼歌\\\"，点鼠标左键，再按住左键发送\")\n                              : L(\"SIGNAL: NONE  -  lower the phone and walk closer to the humming girl\", \"信号：无  -  放下手机，走近那个哼歌的女孩\");\n            SetPrompt(p);\n        }\n\n        void SitOn(Interactable seat)\n        {\n            if (seat == null) return;\n            sitting = seat;\n            rig.SitAt(seat.transform.position, seat.transform.eulerAngles.y);\n            foreach (Interactable s in seats) if (s != null) s.active = false;\n        }\n\n        void StandUp()\n        {\n            if (sitting == null) return;\n            Vector3 back = sitting.transform.position - sitting.transform.forward * 0.62f;\n            rig.StandUpAt(back);\n            sitting = null;\n            foreach (Interactable s in seats) if (s != null) s.active = true;\n        }\n\n        // ------------------------------------------------------------------ story\n        void UpdateStory()\n        {\n            if (!gotJob && phone.IsUnlocked(PhoneController.AppMessages))\n            {\n                gotJob = true;\n                phone.Receive(\"Triangle\", L(\"you made it. don't look for me. they watch who I talk to.\", \"你做到了。别来找我。他们盯着我跟谁说话。\"));\n                phone.Receive(\"Triangle\", L(\"a job first. someone at the window tables hums when she's scared. listen for her.\", \"先办件事。窗边那桌有个女孩，害怕时会哼歌。听声音找她。\"));\n                phone.Receive(\"Triangle\", L(\"tell her: the stairs are open tonight. this phone only reaches phones close by.\", \"告诉她：今晚楼梯开着。这部手机只能发给附近的手机。\"));\n            }\n            if (gotJob && !taskGiven && phone.UnreadCount == 0)\n            {\n                taskGiven = true;\n                phone.StartTask(new PhoneTask\n                {\n                    forward = true,\n                    header = \"Forward to...\",\n                    options = new[] { \"Mom (not mine)\", \"Don't Reply\", \"Lent Me An Eraser\", \"Hums When Scared\", \"Bus 14\" },\n                    correct = 3,\n                    sendText = L(\"the stairs are open tonight.\", \"今晚楼梯开着。\"),\n                    check = i => InReach() ? null : L(\"No signal. Get closer to her.\", \"没有信号。再靠近她一点。\"),\n                    onDone = i => StartCoroutine(Delivered()),\n                    typeSeconds = 3f,\n                });\n                Thought(Rule(L(\"Find the one who hums\", \"找到那个哼歌的人\")) + L(\" - pink ribbon, window table, far right corner.\\nPut the phone DOWN to walk. Pillars block the camera.\", \"——粉色蝴蝶结，靠窗那桌，最右边的角落。\\n放下手机才能走。柱子能挡住摄像头。\"), 9f);\n            }\n            if (!enteredDining && In(rig.transform.position, diningZone))\n            {\n                enteredDining = true;\n                if (monitor != null && Vector3.Distance(monitor.transform.position, rig.transform.position) < 9f)\n                    Authority(L(\"Find a seat. Eat. Smile.\", \"找位子。吃饭。微笑。\"), 4f);\n            }\n        }\n\n        bool InReach()\n        {\n            if (hummer == null) return true;\n            Vector3 a = rig.transform.position, b = hummer.position;\n            a.y = 0f; b.y = 0f;\n            return Vector3.Distance(a, b) <= reachDistance;\n        }\n\n        /// <summary>The goal box top-left always says what to do next, and where.</summary>\n        void UpdateObjective()\n        {\n            if (winning) return;\n            if (delivered) { SetObjective(L(\"Go to the STAFF door (north wall, behind the counters).\\nEnter the lane at the FAR RIGHT end of the counters. Move when the corner camera faces the windows.\", \"去员工通道门（北墙，柜台后面）。\\n从柜台最右端进入后面的过道。等角落的摄像头转向窗户时再走。\")); return; }\n            if (taskGiven)\n            {\n                if (InReach()) SetObjective(L(\"You're close enough.\\nHOLD RIGHT MOUSE -> Messages -> send to \\\"Hums When Scared\\\".\", \"已经够近了。\\n按住右键 -> 信息 -> 发给“害怕时会哼歌”。\"));\n                else SetObjective(L(\"Find the girl who HUMS (pink ribbon).\\nShe sits alone at the window table in the FAR RIGHT corner. Follow the sound.\", \"找到那个哼歌的女孩（粉色蝴蝶结）。\\n她一个人坐在最右边角落的靠窗那桌。循着声音走。\"));\n                return;\n            }\n            if (gotJob) { SetObjective(L(\"Keep the phone up and read Triangle's messages.\", \"别放下手机，读完三角的信息。\")); return; }\n            if (phone.RaisedOnce) SetObjective(L(\"Unlock MESSAGES.\\nCode = when lunch begins (the PA said it: 12:40 -> 4 digits).\", \"解锁\\\"信息\\\"。\\n密码 = 午餐开始的时间（广播说过：12:40 → 四位数）。\"));\n        }\n\n        void UpdateHumHints()\n        {\n            if (hummer == null) return;\n            float d = Vector3.Distance(new Vector3(rig.transform.position.x, 0f, rig.transform.position.z), new Vector3(hummer.position.x, 0f, hummer.position.z));\n            if (hummerGlow != null) hummerGlow.intensity = taskGiven && !delivered ? 0.6f + 0.4f * Mathf.Sin(Time.time * 3f) : 0f;\n            // she rocks slightly while she hums\n            if (hum != null && hum.Humming) hummer.localRotation = Quaternion.Euler(0f, hummer.localEulerAngles.y, Mathf.Sin(Time.time * 2.2f) * 2.5f);\n            if (!taskGiven || delivered) return;\n            taskTime += Time.deltaTime;\n            if (!heardHum && d < 6f && DialogueIdle)\n            {\n                heardHum = true;\n                Thought(L(\"That humming... the school anthem, off-key.\\n\", \"那个哼歌声……是校歌，跑调了。\\n\") + Rule(L(\"It's coming from the window table.\", \"是从靠窗那桌传来的。\")) + L(\" Pink ribbon.\", \"粉色蝴蝶结。\"), 6f);\n            }\n            if (!toldInReach && InReach())\n            {\n                toldInReach = true;\n                ambient.Play(AudioSynth.Confirm(), 0.3f, 1.5f);\n                Thought(Rule(L(\"Close enough - signal!\", \"够近了——发信号！\")) + L(\"\\nHOLD RIGHT MOUSE and send it to \\\"Hums When Scared\\\".\", \"\\n按住右键，发给“害怕时会哼歌”。\"), 7f, true);\n            }\n            if (taskTime > 50f && !InReach() && DialogueIdle)\n            {\n                taskTime = 0f;\n                Thought(L(\"Listen. \", \"听。\") + Rule(L(\"The humming\", \"哼歌声\")) + L(\" - far right corner, by the south windows.\", \"——最右边的角落，南边窗户旁。\"), 6f);\n            }\n        }\n\n        void ListenToHer()\n        {\n            if (delivered) { Thought(L(\"She mouths: thank you.\", \"她用口型说：谢谢。\"), 3.5f, true); return; }\n            if (!taskGiven) { Thought(L(\"She's humming the school anthem. Off-key, eyes on her tray.\\nShe looks scared.\", \"她在哼校歌。跑调了，眼睛盯着餐盘。\\n她看起来很害怕。\"), 5f, true); return; }\n            listened = true;\n            Thought(L(\"It's her. I can't talk to her - \", \"就是她。我不能跟她说话——\") + Rule(L(\"they watch who talks\", \"他们盯着谁在说话\")) + L(\".\\nHOLD RIGHT MOUSE and send the message from here.\", \"。\\n按住鼠标右键，就在这里把信息发出去。\"), 7f, true);\n        }\n\n        IEnumerator Delivered()\n        {\n            delivered = true;\n            ambient.Play(AudioSynth.Confirm(), 0.4f);\n            yield return Wait(1.5f);\n            if (hum != null) hum.StopHumming();\n            phone.Receive(\"Hums When Scared\", L(\"...ok. ok. thank you.\", \"……好。好。谢谢你。\"));\n            phone.Receive(\"Hums When Scared\", L(\"tell Triangle I'll be there.\", \"告诉三角，我会去的。\"));\n            yield return Wait(5f);\n            phone.Receive(\"Triangle\", L(\"good. now the STAFF door behind the counters.\", \"很好。现在去柜台后面的员工通道门。\"));\n            phone.Receive(\"Triangle\", L(\"the corner camera looks at the windows every few seconds. that's your moment.\", \"角落的摄像头每隔几秒就会转向窗户。那就是你的机会。\"));\n            Thought(Rule(L(\"Behind the counters, to the STAFF door.\", \"绕到柜台后面，去员工通道门。\")) + L(\"\\nGo when the camera faces the windows.\", \"\\n等摄像头转向窗户再走。\"), 9f);\n        }\n\n        void UseDoor()\n        {\n            if (!delivered) { Thought(L(\"Not yet. Triangle said: the job first.\", \"还不行。三角说了：先办事。\"), 4f, true); return; }\n            if (!winning) StartCoroutine(ThroughStaffDoor());\n        }\n\n        /// <summary>The STAFF door opens; you step through, it shuts behind you, and the stairs are yours to walk down.</summary>\n        IEnumerator ThroughStaffDoor()\n        {\n            winning = true;\n            rig.Lock();\n            SetPrompt(null);\n            phone.allowRaise = false;\n            ambient.Play(AudioSynth.Creak(), 0.6f);\n            Quaternion r0 = staffDoorLeaf != null ? staffDoorLeaf.localRotation : Quaternion.identity;\n            Quaternion r1 = r0 * Quaternion.Euler(0f, -100f, 0f);\n            if (staffDoorLeaf != null)\n                for (float k = 0f; k < 1f; k += Time.deltaTime / 0.8f) { staffDoorLeaf.localRotation = Quaternion.Slerp(r0, r1, k); yield return null; }\n            yield return Fade(0f, 1f, 0.35f);\n            rig.Teleport(throughDoorPoint, 0f);\n            throughDoor = true;\n            danger = 0f;\n            if (staffDoorLeaf != null) staffDoorLeaf.localRotation = r0;   // it shuts behind you\n            ambient.Play(AudioSynth.Click(), 0.7f, 0.6f);\n            ambient.droneVolume *= 0.5f;\n            if (voicesPoint != null)\n            {\n                voices = voicesPoint.gameObject.AddComponent<AudioSource>();\n                voices.clip = AudioSynth.Murmur();\n                voices.loop = true;\n                voices.spatialBlend = 1f;\n                voices.rolloffMode = AudioRolloffMode.Linear;\n                voices.minDistance = 1.5f;\n                voices.maxDistance = 7f;\n                voices.volume = 0.55f;\n                voices.dopplerLevel = 0f;\n                voices.Play();\n            }\n            yield return Fade(1f, 0f, 0.6f);\n            rig.AllowWalk();\n            SetObjective(L(\"Go down the stairs.\\nAt the bottom: the door (E).\", \"走下楼梯。\\n最底下有一扇门（E）。\"));\n            Thought(L(\"The door clicks shut behind me. \", \"门在身后咔哒一声关上了。\") + Rule(L(\"No camera here.\", \"这里没有摄像头。\")) + L(\"\\nStairs. Going down.\", \"\\n楼梯。往下走。\"), 5f, true);\n        }\n\n        void UpdateStairs()\n        {\n            float z = rig.transform.position.z;\n            if (!saidPaint && z > 13.5f)\n            {\n                saidPaint = true;\n                Thought(L(\"Someone painted on the wall, a long time ago:\\n\", \"很久以前，有人在墙上刷了一行字：\\n\") + Rule(L(\"WE KEEP THINGS FROM EACH OTHER.\", \"我们彼此之间有秘密。\")), 5.5f);\n            }\n            if (!saidChalk && z > 14.6f)\n            {\n                saidChalk = true;\n                Thought(L(\"And in chalk: \", \"还有粉笔字：\") + Rule(L(\"SEAT 31\", \"31 号座位\")) + L(\". '79, '86, '94...\\nYear after year. ...And me?\", \"。'79、'86、'94……\\n一年又一年。……那我呢？\"), 5.5f);\n            }\n            if (!saidVoices && z > 16.1f)\n            {\n                saidVoices = true;\n                Thought(L(\"Voices. Behind that door.\\n\", \"门后有人声。\\n\") + Rule(L(\"Nobody is whispering.\", \"没有人在小声说话。\")), 5f, true);\n            }\n        }\n\n        void PushBottomDoor()\n        {\n            if (ended) return;\n            StartCoroutine(PushDoorRoutine());\n        }\n\n        IEnumerator PushDoorRoutine()\n        {\n            ended = true;\n            rig.Lock();\n            SetPrompt(null);\n            SetObjective(\"\");\n            ambient.Play(AudioSynth.Creak(), 0.7f, 0.9f);\n            if (bottomDoorHinge != null)\n            {\n                Quaternion a = bottomDoorHinge.rotation, b = a * Quaternion.Euler(0f, -55f, 0f);\n                for (float k = 0f; k < 1f; k += Time.deltaTime / 1.1f)\n                {\n                    bottomDoorHinge.rotation = Quaternion.Slerp(a, b, k * k * (3f - 2f * k));\n                    if (voices != null) voices.volume = Mathf.Lerp(0.55f, 1f, k);\n                    yield return null;\n                }\n            }\n            Thought(L(\"Warm light. A lot of people, talking out loud.\\nSomeone says my seat number - like a name.\", \"暖黄的灯光。很多人，在大声说话。\\n有人叫出我的座位号——像在叫一个名字。\"), 5f, true);\n            yield return Wait(3.5f);\n            yield return FinishLevel(\"stairs\", 2.2f);\n        }\n\n        // ------------------------------------------------------------------ watchers\n        bool AnyCameraSees(Vector3 p)\n        {\n            if (cameras == null) return false;\n            foreach (TeacherVision c in cameras) if (c != null && c.CanSee(p, rig.transform)) return true;\n            return false;\n        }\n\n        void UpdateDanger()\n        {\n            bool byMonitor = false, byCamera = false;\n            if (phone.IsExposed)\n            {\n                Vector3 p = phoneExposurePoint.position;\n                byMonitor = monitorVision != null && monitor != null && monitor.Running && monitorVision.CanSee(p, rig.transform);\n                byCamera = !byMonitor && AnyCameraSees(p);\n            }\n            if (AccumulateDanger(byMonitor || byCamera ? 1f / Mathf.Max(0.05f, noticeSeconds) : 0f))\n            {\n                if (byMonitor) Strike(L(\"...Was that a phone?\", \"……那是手机吗？\"));\n                else Strike(L(\"A device has been observed in the dining hall.\", \"食堂内发现一台电子设备。\"), true);\n            }\n        }\n\n        void UpdateKitchen()\n        {\n            if (kitchenGrace > 0f) kitchenGrace -= Time.deltaTime;\n            bool inside = In(rig.transform.position, kitchenZone);\n            if (inside && !toldKitchen)\n            {\n                toldKitchen = true;\n                Thought(L(\"Behind the counters. \", \"到柜台后面了。\") + Rule(L(\"Keep moving\", \"别停\")) + L(\" - before it turns back.\", \"——趁它还没转回来。\"), 5f, true);\n            }\n            bool seen = false;\n            if (inside && kitchenGrace <= 0f)\n            {\n                Vector3 head = rig.eye.position;\n                seen = AnyCameraSees(head) || (monitorVision != null && monitor != null && monitor.Running && monitorVision.CanSee(head, rig.transform));\n            }\n            kitchenSeen = seen ? kitchenSeen + Time.deltaTime : Mathf.Max(0f, kitchenSeen - Time.deltaTime);\n            if (kitchenSeen > 0.7f)\n            {\n                kitchenSeen = 0f;\n                kitchenGrace = 2.5f;\n                Strike(L(\"Students are reminded that the kitchen is not a destination.\", \"提醒各位同学：厨房不是目的地。\"), true);\n                if (!ended) rig.Teleport(kitchenReturnPoint, kitchenReturnYaw);\n            }\n        }\n\n        void UpdateAmbientLines()\n        {\n            paTimer -= GameSpeed.Dt;\n            if (paTimer <= 0f && DialogueIdle)\n            {\n                paTimer = Random.Range(55f, 75f);\n                PA(Loc.T(ambientPA[paIndex % ambientPA.Length]), 6.5f);\n                paIndex++;\n            }\n            if (monitorTalk > 0f) monitorTalk -= Time.deltaTime;\n            if (monitor != null && monitorTalk <= 0f && DialogueIdle && !phone.IsExposed)\n            {\n                if (Vector3.Distance(monitor.transform.position, rig.transform.position) < 2.2f && In(rig.transform.position, diningZone))\n                {\n                    monitorTalk = 30f;\n                    string[] lines = { \"Chew. Thirty-two times.\", \"Why aren't you eating?\", \"Eyes forward. Thank you.\" };\n                    Authority(Loc.T(lines[Random.Range(0, lines.Length)]), 4f);\n                }\n            }\n        }\n\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        protected override IEnumerator OnCaught()\n        {\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            Authority(L(\"Device. Now.\", \"设备。交出来。\"), 4f, true);\n            if (monitor != null)\n            {\n                Vector3 to = rig.transform.position - monitor.transform.position; to.y = 0f;\n                Vector3 stand = rig.transform.position - to.normalized * 0.9f;\n                monitor.Approach(stand, rig.transform);\n                float t = 0f;\n                yield return Wait(0.4f);\n                while (!monitor.HasArrived && t < 7f) { t += Time.deltaTime; yield return null; }\n            }\n            yield return WaitIdle();\n            PA(L(\"A device has been retired. Thank you for your cooperation.\", \"一台设备已被回收。感谢您的配合。\"), 5f);\n            yield return WaitIdle();\n            yield return Caught(\"confiscated\");\n        }\n    }\n}\n"},"Level03Director":{"path":"Assets/Game/Scripts/Level03Director.cs","role":"Chapter 3 Lights Out: listen for the warden, hold Space to pretend to sleep, Contacts code from his room call, flash the screen at the window 3 times","source":"// @role Chapter 3 Lights Out: listen for the warden, hold Space to pretend to sleep, Contacts code from his room call, flash the screen at the window 3 times\n// @calls LevelDirectorBase, PatrolAI, TeacherVision, Footsteps, PhoneController, PlayerRig\n// @tune lightNoticeSeconds:float:0.5-4:seconds his flashlight needs on the phone screen\n// @tune awakeNoticeSeconds:float:1-6:seconds he needs to see you sitting up during a bed check\nusing System.Collections;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 3 \"Lights Out\" (dormitory, Room 304, night).\n    ///  - Watch becomes LISTEN: it is almost dark. You hear the Warden's footsteps and keys in the hall.\n    ///  - HOLD [SPACE] = lie down and pretend to sleep. If he comes in and you are sitting up, he notices (slowly).\n    ///  - The phone screen is the brightest thing in the room: if his flashlight catches it, he notices fast.\n    ///  - Never Blinks (across the room) can't sleep. Reply to her. Contacts' code is the room number (0304),\n    ///    which he says every night. The oldest contact: \"Seat 31 - '79\".\n    ///  - Triangle: flash your screen at the window three times so the dorm across the yard knows. They answer. WIN.\n    /// </summary>\n    public class Level03Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public PatrolAI warden;\n        [Tooltip(\"A student sneaking back from the stairwell at the start (the girl who hums).\")]\n        public PatrolAI sneaker;\n        public TeacherVision wardenVision;\n        public Footsteps wardenSteps;\n        public Transform bedSeat;\n        public Transform windowTarget;\n        public Renderer[] acrossWindows;\n        public Light acrossSignal;\n        public Light neverBlinksGlow;\n\n        [Header(\"Warden route (corridor centre line x = 9)\")]\n        public Vector3 corridorSouth = new Vector3(9f, 0f, -1.2f);\n        public Vector3 corridorNorth = new Vector3(9f, 0f, 11.2f);\n        public Vector3 doorOutside = new Vector3(9f, 0f, 3f);\n        public Vector3 doorInside = new Vector3(6.9f, 0f, 3f);\n        public Vector3 aisleSouth = new Vector3(4f, 0f, 3f);\n        public Vector3 aisleMiddle = new Vector3(4f, 0f, 6.2f);\n        public Vector3 aisleNorth = new Vector3(4f, 0f, 8.8f);\n        public Vector3 bedsideStand = new Vector3(5.4f, 0f, 5.6f);\n        [Tooltip(\"Inside the dorm room (x min, z min, x max, z max).\")]\n        public Vector4 roomZone = new Vector4(0.1f, 0.1f, 7.95f, 9.95f);\n\n        [Header(\"Rules\")]\n        [Tooltip(\"Seconds until he notices the phone's light in his flashlight.\")]\n        public float lightNoticeSeconds = 1.6f;\n        [Tooltip(\"Seconds until he notices you are sitting up during a bed check.\")]\n        public float awakeNoticeSeconds = 3.2f;\n\n        bool firstCheckDone, replied, contactsAsked, firstContactTold, signalAsked, answered, wardenWasInside, toldComing;\n        int flashes;\n        string lastSeenReason = \"\";\n        float wardenWait;\n        Coroutine wardenLoop;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"WARDEN\";\n            authorityPitch = 0.68f;\n            phone.hasPhone = true;\n            phone.allowRaise = false;\n            phone.phoneClock = \"23:41\";\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.appUnlocked[PhoneController.AppMessages] = true;\n            phone.lockNotification = L(\"No new messages.\", \"没有新信息。\");\n            phone.AddHistory(\"Triangle\", L(\"the stairs are open tonight. you did good at lunch.\", \"今晚楼梯开着。午饭时你干得不错。\"), false);\n            phone.AddHistory(\"Hums When Scared\", L(\"thank you. I mean it.\", \"谢谢你。真心的。\"), false);\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            ambient.droneVolume = 0.11f;\n            ambient.ventVolume = 0.05f;\n            ambient.SetExtraLoop(AudioSynth.Breathing(), 0.07f);\n            if (neverBlinksGlow != null) neverBlinksGlow.enabled = false;\n            GameObject rl = new GameObject(\"RoomLight (warden switches it on)\");\n            rl.transform.position = new Vector3(4f, 2.8f, 5f);\n            roomLight = rl.AddComponent<Light>();\n            roomLight.type = LightType.Point;\n            roomLight.range = 10f;\n            roomLight.intensity = 0f;\n            roomLight.color = new Color(0.92f, 0.98f, 1f);\n            if (acrossSignal != null) acrossSignal.enabled = false;\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (bedSeat != null) rig.SitAt(bedSeat.position, bedSeat.eulerAngles.y);\n            if (warden != null) warden.Begin();\n            StartCoroutine(Script());\n        }\n\n        protected override string StrikeSuffix(int n, bool pa)\n        {\n            return n == 1 ? L(\"  That's once. Three times, and it's mine.\", \"  这是第一次。到第三次，它就归我了。\") : L(\"  Twice. Next time, it's mine.\", \"  第二次了。下次，它就归我了。\");\n        }\n\n        // ------------------------------------------------------------------ story\n        IEnumerator Script()\n        {\n            rig.Lock();\n            yield return ChapterCard(\"CHAPTER 3\", \"LIGHTS OUT\", \"MONDAY  -  23:40\");\n            rig.BackToSeat();\n            yield return SneakBack();\n            Authority(L(\"Room three-oh-four. Three. Zero. Four. Bed check every fifteen minutes. Sleep.\", \"三零四寝室。三。零。四。每十五分钟查一次房。睡觉。\"), 3.6f, false, 0.15f);\n            yield return WaitIdle();\n            if (warden != null) warden.RunRoute(new[] { corridorNorth }, new[] { 6f }, new[] { float.NaN }, null);\n            // straight to what matters: when he comes, lie down; when he's gone, the phone\n            Thought(Rule(L(\"When his footsteps come in: HOLD [SPACE]\", \"他的脚步声一进来：按住 [空格]\")) + L(\" - lie down, pretend to sleep.\\nThe phone only when he's gone: it's the brightest thing in the room.\", \"——躺下装睡。\\n等他走了才能用手机：它是房间里最亮的东西。\"), 6.5f, false, 0.2f);\n            yield return WaitIdle();\n\n            // the first bed check is scripted, so everyone learns to lie down\n            if (!toldComing) { toldComing = true; Thought(L(\"Footsteps. He's coming back. \", \"脚步声。他回来了。\") + Rule(L(\"[SPACE]\", \"[空格]\")), 4f, true); }\n            yield return RoomCheck(true);\n            firstCheckDone = true;\n            wardenLoop = StartCoroutine(WardenLoop());\n\n            yield return Wait(0.5f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", L(\"are you awake\", \"你醒着吗\"));\n            yield return Wait(0.8f);\n            phone.Receive(\"Never Blinks\", L(\"it's me. across from you. i can't sleep. i count his footsteps.\", \"是我，在你对面。我睡不着。我在数他的脚步声。\"));\n            Thought(L(\"A message. Across the room - Never Blinks.\\n\", \"一条信息。房间对面——从不眨眼。\\n\") + Rule(L(\"Only when he's gone.\", \"只能等他走了再用。\")), 6f);\n            while (phone.UnreadCount > 0 && !ended) yield return null;\n            phone.StartTask(new PhoneTask\n            {\n                header = \"Reply\",\n                toLabel = \"To: Never Blinks\",\n                options = new[] { L(\"I'm here.\", \"我在。\"), L(\"Go to sleep.\", \"快睡吧。\") },\n                onDone = i => { replied = true; StartCoroutine(AfterReply(i)); },\n                typeSeconds = 2.5f,\n            });\n            while (!replied && !ended) yield return null;\n            while (!phone.IsUnlocked(PhoneController.AppContacts) && !ended) yield return null;\n            while (!phone.FirstContactSeen && !ended) yield return null;\n            if (ended) yield break;\n            firstContactTold = true;\n            Thought(L(\"Seat 31. Nineteen seventy-nine.\\nSomeone had this phone almost \", \"31 号座位。一九七九年。\\n将近\") + Rule(L(\"fifty years ago\", \"五十年前\")) + L(\".\", \"，就有人拿着这部手机了。\"), 7f);\n            yield return Wait(1f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", L(\"see it? the oldest one. nobody knows who.\", \"看到了吗？最老的那个。没人知道是谁。\"));\n            yield return Wait(2.5f);\n            phone.Receive(\"Triangle\", L(\"one more thing tonight.\", \"今晚还有一件事。\"));\n            phone.Receive(\"Triangle\", L(\"the dorm across the yard watches our window at midnight. flash your screen at it three times.\", \"院子对面那栋宿舍，半夜会盯着我们的窗户。用屏幕朝它闪三下。\"));\n            while (phone.UnreadCount > 0 && !ended) yield return null;\n            signalAsked = true;\n            Thought(Rule(L(\"Phone up, face the window, [LEFT MOUSE] to flash.\", \"拿起手机，面向窗户，按[鼠标左键]闪一下。\")) + L(\"\\nThree times. Only when he's far away.\", \"\\n闪三次。只在他走远的时候。\"), 9f);\n        }\n\n        /// <summary>Opening: someone tiptoes back from the stairwell, stops at your door, and whispers.</summary>\n        IEnumerator SneakBack()\n        {\n            if (sneaker == null) yield break;\n            sneaker.Begin();\n            bool done = false;\n            sneaker.RunRoute(new[] { doorOutside }, new[] { 0f }, new[] { -90f }, () => done = true);\n            Thought(L(\"Footsteps. Light ones - not his.\", \"脚步声。很轻——不是他的。\"), 3.5f);\n            float t = 0f;\n            while (!done && t < 14f) { t += Time.deltaTime; yield return null; }\n            StudentSay(\"(whispering)\", L(\"...psst. Seat thirty-one. It's real - down there. The stairs.\", \"……嘘。三十一号。是真的——就在下面。楼梯那里。\"), 3f, false, 0.1f);\n            Thought(L(\"The girl who hums. Back from the stairs.\\nShe's smiling. \", \"是那个会哼歌的女孩。刚从楼梯那边回来。\\n她在笑。\") + Rule(L(\"People really go down there.\", \"真的有人会去那下面。\")), 3.5f, false, 0.15f);\n            // she walks off on her own; the night goes on without waiting for her\n            sneaker.RunRoute(new[] { corridorNorth }, new[] { 0f }, new[] { float.NaN }, () => sneaker.gameObject.SetActive(false));\n            yield return WaitIdle();\n            if (wardenSteps != null) wardenSteps.PlayAt(AudioSynth.Keys(), 0.8f);\n        }\n\n        IEnumerator AfterReply(int choice)\n        {\n            yield return Wait(1f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", choice == 0 ? L(\"...thanks. nobody says that here.\", \"……谢谢。这里没人会这么说。\") : L(\"...you sound like him.\", \"……你说话跟他一样。\"));\n            yield return Wait(1.2f);\n            phone.Receive(\"Never Blinks\", L(\"triangle says: the oldest name in Contacts. its code is this room. he says it every night.\", \"三角说：看通讯录里最老的名字。密码就是这间寝室。他每晚都会念一遍。\"));\n            contactsAsked = true;\n            while (phone.UnreadCount > 0 && !ended) yield return null;\n            Thought(L(\"This room... \", \"这间寝室……\") + Rule(L(\"Three. Zero. Four.\", \"三。零。四。\")) + L(\"\\nContacts.\", \"\\n通讯录。\"), 6f);\n        }\n\n        void NeverBlinksTypes()\n        {\n            if (neverBlinksGlow != null) StartCoroutine(Glow(neverBlinksGlow, 2.2f));\n        }\n\n        IEnumerator Glow(Light l, float seconds)\n        {\n            l.enabled = true;\n            yield return Wait(seconds);\n            l.enabled = false;\n        }\n\n        IEnumerator Answer()\n        {\n            answered = true;\n            yield return Wait(2.5f);\n            for (int i = 0; i < 3; i++)\n            {\n                SetAcross(true);\n                yield return Wait(0.35f);\n                SetAcross(false);\n                yield return Wait(0.45f);\n            }\n            Thought(L(\"Three lights across the yard.\\n\", \"院子对面亮了三下。\\n\") + Rule(L(\"Someone answered.\", \"有人回应了。\")), 5f, true);\n            yield return Wait(2f);\n            NeverBlinksTypes();\n            phone.Receive(\"Never Blinks\", L(\"they saw. goodnight :)\", \"他们看见了。晚安 :)\"));\n            yield return Wait(4.5f);\n            ended = true;\n            phone.allowRaise = false;\n            yield return Fade(0f, 1f, 2.5f);\n            ambient.Play(AudioSynth.Chime(), 0.4f);\n            caption.text = L(\"06:00\\n\\nGOOD MORNING, CLEARVIEW. YOU SLEPT WELL.\\nTHANK YOU FOR SLEEPING.\", \"06:00\\n\\n早上好，明鉴学院。您睡得很好。\\n感谢您的睡眠。\");\n            yield return Wait(4.5f);\n            GameFlow.EndLevel(LessonResult.Win, \"signal\");\n        }\n\n        void SetAcross(bool on)\n        {\n            if (acrossSignal != null) acrossSignal.enabled = on;\n            if (acrossWindows != null)\n            {\n                MaterialPropertyBlock mpb = new MaterialPropertyBlock();\n                foreach (Renderer r in acrossWindows)\n                {\n                    if (r == null) continue;\n                    r.GetPropertyBlock(mpb);\n                    mpb.SetColor(\"_EmissionColor\", on ? new Color(3f, 2.6f, 1.6f) : new Color(0.25f, 0.2f, 0.1f));\n                    r.SetPropertyBlock(mpb);\n                }\n            }\n        }\n\n        // ------------------------------------------------------------------ warden\n        IEnumerator RoomCheck(bool first = false)\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            warden.RunRoute(\n                new[] { doorOutside, doorInside, aisleSouth, aisleMiddle, aisleNorth, aisleMiddle, doorInside, doorOutside, corridorSouth },\n                first ? new[] { 0.8f, 0.2f, 0.5f, 1.8f, 1.1f, 0.3f, 0.2f, 0.3f, 0f } : new[] { 1.2f, 0.3f, 0.8f, 2.6f, 1.6f, 0.4f, 0.3f, 0.5f, 0f },\n                new[] { -90f, float.NaN, 0f, 90f, 0f, float.NaN, float.NaN, float.NaN, float.NaN },\n                () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        IEnumerator Peek()\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            Vector3 end = Random.value < 0.5f ? corridorNorth : corridorSouth;\n            warden.RunRoute(new[] { doorOutside, end }, new[] { 4f, 0f }, new[] { -90f, float.NaN }, () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        IEnumerator PassBy()\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            Vector3 end = warden.transform.position.z > 5f ? corridorSouth : corridorNorth;\n            warden.RunRoute(new[] { end }, new[] { 0f }, new[] { float.NaN }, () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        // ---- random bed-check events: every visit is a little different\n        static readonly Vector3[] sleeperSpots =\n        {\n            new Vector3(2.6f, 0f, 1.3f), new Vector3(2.6f, 0f, 7.6f), new Vector3(5.4f, 0f, 8.3f), new Vector3(5.4f, 0f, 0.9f), new Vector3(2.6f, 0f, 4.4f),\n        };\n        static readonly string[] enterLines =\n        {\n            \"Bed check.\", \"Three-oh-four. Count.\", \"...\", \"Nobody move.\", \"Eyes closed. All of them.\", \"I can hear you breathing. Good. Keep doing that.\",\n        };\n        static readonly string[] sleeperLines =\n        {\n            \"Still breathing. Good.\", \"Bed number two. Asleep. Correct.\", \"Who taught you to snore like that.\", \"...Sleep is mandatory.\",\n        };\n        static readonly string[] mumbles = { \"...don't take it...\", \"...mum?...\", \"...thirty-two times...\", \"...I'm smiling, I'm smiling...\" };\n        Light roomLight;\n        int lastEvent = -1;\n\n        IEnumerator Route(Vector3[] pts, float[] waits, float[] yaws)\n        {\n            if (warden == null) yield break;\n            bool done = false;\n            warden.RunRoute(pts, waits, yaws, () => done = true);\n            while (!done && !ended) yield return null;\n        }\n\n        IEnumerator GoTo(Vector3 p, float wait, float yaw)\n        {\n            yield return Route(new[] { p }, new[] { wait }, new[] { yaw });\n        }\n\n        void WardenSays(string line, float seconds = 3.5f)\n        {\n            if (!ended && DialogueIdle) Authority(line, seconds);\n        }\n\n        /// <summary>He stops at a sleeping student and shines the light on them. Sometimes they talk in their sleep first.</summary>\n        IEnumerator CheckSleeper()\n        {\n            Vector3 spot = sleeperSpots[Random.Range(0, sleeperSpots.Length)];\n            if (Random.value < 0.5f) StudentSay(\"SLEEPING STUDENT\", Loc.T(mumbles[Random.Range(0, mumbles.Length)]), 3.5f);\n            yield return Route(new[] { doorOutside, doorInside, new Vector3(4f, 0f, spot.z) }, new[] { 0.8f, 0.2f, 0.2f }, new[] { -90f, float.NaN, float.NaN });\n            yield return GoTo(spot, 3.2f, spot.x < 4f ? -90f : 90f);\n            WardenSays(Loc.T(sleeperLines[Random.Range(0, sleeperLines.Length)]));\n            yield return Route(new[] { doorInside, doorOutside, Random.value < 0.5f ? corridorSouth : corridorNorth }, new[] { 0.3f, 0.4f, 0f }, new[] { float.NaN, float.NaN, float.NaN });\n        }\n\n        /// <summary>He walks right up to your bed and just stands there.</summary>\n        IEnumerator StandOverYou()\n        {\n            yield return Route(new[] { doorOutside, doorInside }, new[] { 1.0f, 0.4f }, new[] { -90f, float.NaN });\n            yield return GoTo(bedsideStand, Random.Range(4f, 6.5f), 90f);\n            WardenSays(Random.value < 0.5f ? L(\"...I know when someone is pretending.\", \"……谁在装睡，我都知道。\") : \"...\", 3.5f);\n            yield return Route(new[] { doorInside, doorOutside, corridorSouth }, new[] { 0.3f, 0.3f, 0f }, new[] { float.NaN, float.NaN, float.NaN });\n        }\n\n        /// <summary>He fills the doorway and doesn't move. Keys. Silence. Then leaves.</summary>\n        IEnumerator DoorwaySilence()\n        {\n            yield return GoTo(doorOutside, 0.5f, -90f);\n            yield return GoTo(doorInside, Random.Range(6f, 9f), -90f);\n            if (wardenSteps != null) wardenSteps.PlayAt(AudioSynth.Keys(), 0.6f);\n            WardenSays(Random.value < 0.5f ? L(\"Sweet dreams, three-oh-four.\", \"做个好梦，三零四。\") : L(\"Good. Nobody is awake.\", \"很好。没有人醒着。\"), 3.5f);\n            yield return Route(new[] { doorOutside, Random.value < 0.5f ? corridorNorth : corridorSouth }, new[] { 0.3f, 0f }, new[] { float.NaN, float.NaN });\n        }\n\n        /// <summary>Footsteps come right to the door... stop... and go away again.</summary>\n        IEnumerator FakeOut()\n        {\n            yield return GoTo(doorOutside, Random.Range(1.2f, 2.5f), 0f);\n            yield return GoTo(Random.value < 0.5f ? corridorNorth : corridorSouth, 0f, float.NaN);\n        }\n\n        /// <summary>He counts heads out loud, bed by bed. Yours is somewhere in the count.</summary>\n        IEnumerator CountHeads()\n        {\n            yield return Route(new[] { doorOutside, doorInside, aisleSouth }, new[] { 0.6f, 0.2f, 0.4f }, new[] { -90f, float.NaN, 0f });\n            string[] n = { \"One.\", \"Two.\", \"Three.\", \"Four.\", \"Five.\", \"...Six.\" };\n            Vector3[] stops = { new Vector3(4f, 0f, 1.3f), new Vector3(4f, 0f, 0.9f), new Vector3(4f, 0f, 4.4f), new Vector3(4.6f, 0f, 4.4f), new Vector3(4f, 0f, 7.6f), new Vector3(4f, 0f, 8.3f) };\n            float[] yaws = { -90f, 90f, -90f, 90f, -90f, 90f };\n            for (int i = 0; i < stops.Length && !ended; i++)\n            {\n                yield return GoTo(stops[i], i == 3 ? 2.2f : 0.9f, yaws[i]);\n                Authority(Loc.T(n[i]), 1.6f, true, 0.1f);\n            }\n            yield return Route(new[] { aisleMiddle, doorInside, doorOutside, corridorSouth }, new[] { 0.2f, 0.2f, 0.3f, 0f }, new[] { float.NaN, float.NaN, float.NaN, float.NaN });\n        }\n\n        /// <summary>He flicks the room light on. Everyone is lit. Then off again.</summary>\n        IEnumerator LightsOn()\n        {\n            yield return GoTo(doorOutside, 0.4f, -90f);\n            yield return GoTo(doorInside, 0.1f, -90f);\n            ambient.Play(AudioSynth.Click(), 0.8f, 0.7f);\n            if (roomLight != null) roomLight.intensity = 2.2f;\n            Authority(L(\"Lights.\", \"开灯。\"), 2f, true);\n            float t = 0f;\n            while (t < Random.Range(2.5f, 4f) && !ended) { t += Time.deltaTime; yield return null; }\n            ambient.Play(AudioSynth.Click(), 0.8f, 0.7f);\n            if (roomLight != null) roomLight.intensity = 0f;\n            yield return Route(new[] { doorOutside, corridorNorth }, new[] { 0.6f, 0f }, new[] { float.NaN, float.NaN });\n        }\n\n        IEnumerator RandomCheck()\n        {\n            // never the same event twice in a row\n            int e;\n            do { e = Random.Range(0, 6); } while (e == lastEvent);\n            lastEvent = e;\n            if (DialogueIdle && e != 3) Authority(Loc.T(enterLines[Random.Range(0, enterLines.Length)]), 3f);\n            switch (e)\n            {\n                case 0: yield return RoomCheck(); break;\n                case 1: yield return CheckSleeper(); break;\n                case 2: yield return StandOverYou(); break;\n                case 3: yield return FakeOut(); break;\n                case 4: yield return CountHeads(); break;\n                default: yield return Random.value < 0.5f ? LightsOn() : DoorwaySilence(); break;\n            }\n        }\n\n        IEnumerator WardenLoop()\n        {\n            while (!ended)\n            {\n                // long quiet gaps: time to use the phone (he is still somewhere in the hall)\n                wardenWait = Random.Range(24f, 38f);\n                while (wardenWait > 0f && !ended) { wardenWait -= GameSpeed.Dt; yield return null; }\n                if (ended) yield break;\n                float r = Random.value;\n                if (r < 0.35f) yield return PassBy();\n                else if (r < 0.6f) yield return Peek();\n                else\n                {\n                    yield return RandomCheck();\n                    // after he has been in the room, he stays away a bit longer\n                    float rest = Random.Range(10f, 16f);\n                    while (rest > 0f && !ended) { rest -= GameSpeed.Dt; yield return null; }\n                }\n            }\n        }\n\n        // ------------------------------------------------------------------ main loop\n        float wardenBaseSpeed = -1f;\n\n        /// <summary>Story speed 2x: the warden walks (and waits) twice as fast too.</summary>\n        void ApplyWardenSpeed()\n        {\n            if (warden == null) return;\n            UnityEngine.AI.NavMeshAgent ag = warden.GetComponent<UnityEngine.AI.NavMeshAgent>();\n            if (ag == null) return;\n            if (wardenBaseSpeed < 0f) wardenBaseSpeed = ag.speed;\n            ag.speed = wardenBaseSpeed * GameSpeed.Factor;\n            ag.acceleration = Mathf.Max(ag.acceleration, 8f * GameSpeed.Factor);\n            warden.timeScale = GameSpeed.Factor;\n        }\n\n        protected override void LevelUpdate()\n        {\n            ApplyWardenSpeed();\n            // lie down / sit up\n            bool canLie = !phone.IsExposed;\n            if (rig.CurrentMode == PlayerRig.Mode.Seated && GameInput.SpaceHeld() && canLie) rig.LieDown();\n            else if (rig.CurrentMode == PlayerRig.Mode.Lying && !GameInput.SpaceHeld()) rig.SitUp();\n            SetLids(rig.CurrentMode == PlayerRig.Mode.Lying ? 0.72f : 0f);\n            phone.allowRaise = rig.CurrentMode == PlayerRig.Mode.Seated;\n\n            // the door creaks when he comes in\n            bool inside = warden != null && In(warden.transform.position, roomZone);\n            if (inside && !wardenWasInside && wardenSteps != null) wardenSteps.PlayAt(AudioSynth.Creak(), 0.7f);\n            wardenWasInside = inside;\n\n            UpdateObjective();\n            UpdateSignal();\n            UpdateDanger(inside);\n            UpdatePrompt();\n        }\n\n        void UpdateObjective()\n        {\n            if (!firstCheckDone) { SetObjective(L(\"Listen for his footsteps.\\nWhen he comes in: HOLD SPACE to lie down.\", \"注意听他的脚步声。\\n他进来时：按住空格躺下。\")); return; }\n            if (!replied) { SetObjective(L(\"Reply to Never Blinks (Messages).\\nOnly when he's gone. HOLD SPACE when he comes.\", \"回复\\\"从不眨眼\\\"（信息）。\\n只能等他走了再用。他来时按住空格。\")); return; }\n            if (!phone.IsUnlocked(PhoneController.AppContacts)) { SetObjective(L(\"Unlock CONTACTS.\\nCode = this room's number (he says it every night).\", \"解锁\\\"通讯录\\\"。\\n密码 = 这间寝室的门牌号（他每晚都会念）。\")); return; }\n            if (!phone.FirstContactSeen) { SetObjective(L(\"Open Contacts and look at\\nthe OLDEST contact.\", \"打开通讯录，\\n看看最老的那个联系人。\")); return; }\n            if (!signalAsked) { SetObjective(L(\"Wait for messages.\\nLie down (HOLD SPACE) whenever he comes.\", \"等待新信息。\\n他一来就躺下（按住空格）。\")); return; }\n            if (flashes < 3) { SetObjective(L(\"Face the WINDOW, phone up, LEFT MOUSE to flash (\" + flashes + \"/3).\\nOnly when he is far away.\", \"面向窗户，拿起手机，按鼠标左键闪光（\" + flashes + \"/3）。\\n只在他走远的时候。\")); return; }\n            SetObjective(\"\");\n        }\n\n        bool FacingWindow()\n        {\n            if (windowTarget == null || rig.eye == null) return false;\n            Vector3 to = windowTarget.position - rig.eye.position; to.y = 0f;\n            Vector3 f = rig.eye.forward; f.y = 0f;\n            return Vector3.Angle(f, to) < 28f;\n        }\n\n        void UpdateSignal()\n        {\n            if (!signalAsked || answered || flashes >= 3) return;\n            if (phone.IsUp && phone.ScreenOn && FacingWindow() && GameInput.LeftDown())\n            {\n                flashes++;\n                phone.glowBoost = 1f;\n                ambient.Play(AudioSynth.Click(), 0.5f);\n                if (warden != null && wardenVision != null && wardenVision.CanSee(phoneExposurePoint.position, rig.transform, 16f))\n                {\n                    danger = Mathf.Min(0.99f, danger + 0.45f);\n                    lastSeenReason = \"light\";\n                }\n                if (flashes >= 3) StartCoroutine(Answer());\n            }\n        }\n\n        void UpdatePrompt()\n        {\n            string p = null;\n            if (signalAsked && !answered && flashes < 3 && phone.IsUp && phone.ScreenOn)\n                p = FacingWindow() ? L(\"[Left Mouse]  Flash the screen at the window  (\" + flashes + \"/3)\", \"[鼠标左键]  用屏幕朝窗户闪光（\" + flashes + \"/3）\") : L(\"Face the window\", \"面向窗户\");\n            else if (!phone.IsExposed && rig.CurrentMode == PlayerRig.Mode.Seated && !firstCheckDone) p = L(\"HOLD [Space]  Lie down\", \"按住 [空格]  躺下\");\n            SetPrompt(p);\n        }\n\n        void UpdateDanger(bool wardenInside)\n        {\n            float rate = 0f;\n            if (warden != null && warden.Running && wardenVision != null)\n            {\n                if (phone.IsExposed && wardenVision.CanSee(phoneExposurePoint.position, rig.transform, 14f))\n                {\n                    rate = 1f / Mathf.Max(0.05f, lightNoticeSeconds);\n                    lastSeenReason = \"light\";\n                }\n                else if (wardenInside && rig.CurrentMode != PlayerRig.Mode.Lying && wardenVision.CanSee(rig.eye.position, rig.transform, 8f))\n                {\n                    rate = 1f / Mathf.Max(0.05f, awakeNoticeSeconds);\n                    lastSeenReason = \"awake\";\n                }\n            }\n            if (AccumulateDanger(rate))\n            {\n                if (lastSeenReason == \"light\") Strike(L(\"...A light. Lights out means lights out.\", \"……有光。熄灯就是熄灯。\"));\n                else Strike(L(\"Why are you sitting up? Lie down.\", \"你坐着干什么？躺下。\"));\n            }\n        }\n\n        static bool In(Vector3 p, Vector4 r) { return p.x >= r.x && p.x <= r.z && p.z >= r.y && p.z <= r.w; }\n\n        protected override IEnumerator OnCaught()\n        {\n            if (wardenLoop != null) StopCoroutine(wardenLoop);\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            SetLids(0f);\n            Authority(L(\"Hand it over.\", \"交出来。\"), 4f, true);\n            if (warden != null)\n            {\n                warden.Approach(bedsideStand, rig.transform);\n                float t = 0f;\n                yield return Wait(0.4f);\n                while (!warden.HasArrived && t < 9f) { t += Time.deltaTime; yield return null; }\n            }\n            yield return WaitIdle();\n            Authority(L(\"Sweet dreams.\", \"做个好梦。\"), 3f);\n            yield return WaitIdle();\n            yield return Caught(\"confiscated\");\n        }\n    }\n}\n"},"Level04Director":{"path":"Assets/Game/Scripts/Level04Director.cs","role":"Chapter 6 Inspection Day (Friday, the fifth day): get the phone back, the 1979 photo (Voss was Seat 31), desk inspection, final choice: hide it (THE SEAT) or send it to everyone (LIGHTS)","source":"// @role Chapter 6 Inspection Day (Friday, the fifth day): get the phone back, the 1979 photo (Voss was Seat 31), desk inspection, final choice: hide it (THE SEAT) or send it to everyone (LIGHTS)\n// @calls LevelDirectorBase, TeacherAI, TeacherVision, PhoneController, PlayerRig, Interactable, GameFlow\n// @tune answerSeconds:float:4-20:time to answer his questions\n// @tune inspectionFallbackSeconds:float:60-300:the inspection starts anyway this long after you take the phone\n// @tune choiceSeconds:float:5-30:time to decide when he is one desk away\nusing System.Collections;\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 4 \"Inspection Day\" - the finale. Back in the same classroom, same seat.\n    ///  1. The phone is still behind the loose panel in your desk. Get it back while he lectures.\n    ///  2. He asks questions, like on the first day (only about what he has said).\n    ///  3. Triangle: \"look at the last photo.\" 1979, same seat - VOSS. The teacher sat here.\n    ///  4. The inspection begins: desk by desk, front to back. Yours is last.\n    ///  5. One desk away, you decide:\n    ///       1 = hide it again   -> ENDING \"THE SEAT\"   (the secret survives, and so does the school)\n    ///       2 = send it to all  -> ENDING \"LIGHTS\"     (every hidden phone in the room lights up)\n    ///  Third warning: \"...Just like I was.\" (LOSE, retry from this chapter)\n    /// </summary>\n    public class Level04Director : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public TeacherAI teacher;\n        public TeacherVision vision;\n        public Transform seatPoint;\n        public Interactable cubbyZone, loosePanel, hiddenPhone;\n        public Transform takePhoneStandPoint;\n        public AudioClip bellClip;\n        [Header(\"Ending LIGHTS: the room behind the stairs\")]\n        public Transform basementSeat;\n        public Transform basementDoorHinge;\n        public GameObject vossInDoorway;\n        [Tooltip(\"The students in the basement (they turn their heads to the door when Voss appears).\")]\n        public Transform[] basementStudents;\n        [Tooltip(\"What he finds on the desks he checks, in verdict order (pencils, horse drawing, nothing, the 'help' note). Built by GameSceneBuilder.\")]\n        public GameObject[] verdictProps;\n\n        [Header(\"Questions\")]\n        public float answerSeconds = 10f;\n        public Vector2 callInterval = new Vector2(24f, 36f);\n        [Tooltip(\"If the old photo is never found, the inspection starts anyway this long after taking the phone.\")]\n        public float inspectionFallbackSeconds = 100f;\n        public float choiceSeconds = 14f;\n\n        bool calling, cubbySearched, gotPhone, inspecting, toldDanger, choosing;\n        float nextCall = -1f, callTimer, phoneTime;\n        int linesSaid = -1;\n        LessonQuestion question;\n        readonly List<int> asked = new List<int>();\n        readonly List<Transform> classmates = new List<Transform>();\n        Coroutine lecture;\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"INSTRUCTOR VOSS\";\n            authorityPitch = 0.76f;\n            if (teacher != null)\n            {\n                teacher.lines = LessonDefaults.InspectionLines();\n                teacher.questions = LessonDefaults.InspectionQuestions();\n            }\n            phone.hasPhone = false;\n            phone.allowRaise = false;\n            phone.phoneClock = \"09:00\";\n            phone.showOldPhoto = true;\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.appUnlocked[PhoneController.AppMessages] = true;\n            phone.appUnlocked[PhoneController.AppContacts] = true;\n            phone.appUnlocked[PhoneController.AppCamera] = true;\n            phone.appUnlocked[PhoneController.AppSearch] = true;\n            phone.lockNotification = L(\"2 new messages\\nTriangle: inspection today.\", \"2 条新信息\\n三角：今天查课桌。\");\n            phone.AddHistory(\"Triangle\", L(\"volume 31. now you know what this place kept.\", \"第 31 卷。现在你知道这地方留下了什么。\"), false);\n            phone.AddHistory(\"Never Blinks\", L(\"day five tomorrow. can't sleep. goodnight :)\", \"明天就是第五天。睡不着。晚安 :)\"), false);\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            foreach (Transform t in FindObjectsByType<Transform>(FindObjectsInactive.Exclude, FindObjectsSortMode.None))\n                if (t.name.StartsWith(\"Fig_Classmate_Seated\")) classmates.Add(t);\n            SetupDesk();\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (seatPoint != null) rig.SitAt(seatPoint.position, seatPoint.eulerAngles.y);\n            if (teacher != null) teacher.Begin();\n            StartCoroutine(Opening());\n        }\n\n        protected override string StrikeSuffix(int n, bool pa)\n        {\n            if (pa) return base.StrikeSuffix(n, true);\n            return n == 1 ? L(\"  One. You know how many you get.\", \"  一次。你知道自己有几次机会。\") : L(\"  Two. I was sitting where you are when I got my second.\", \"  两次。我当年拿到第二次警告时，就坐在你那个位置。\");\n        }\n\n        protected override bool ReminderBlocked() { return calling || choosing; }\n\n        void SetupDesk()\n        {\n            if (cubbyZone != null)\n            {\n                cubbyZone.prompt = \"Search your desk\";\n                cubbyZone.active = false;\n                cubbyZone.onUse = () => { rig.EnterInspect(); SetZone(false); cubbySearched = true; };\n            }\n            if (loosePanel != null) { loosePanel.prompt = \"Pull the loose panel\"; loosePanel.onUse = () => StartCoroutine(PullPanel()); }\n            if (hiddenPhone != null) { hiddenPhone.prompt = \"Take the phone back\"; hiddenPhone.active = false; hiddenPhone.onUse = TakePhone; }\n        }\n\n        void SetZone(bool on)\n        {\n            if (cubbyZone == null) return;\n            foreach (Collider c in cubbyZone.GetComponents<Collider>()) c.enabled = on;\n        }\n\n        // ------------------------------------------------------------------ story\n        IEnumerator Opening()\n        {\n            rig.Lock();\n            yield return ChapterCard(\"CHAPTER 6\", \"INSPECTION DAY\", \"FRIDAY  -  09:00\");\n            rig.BackToSeat();\n            if (cubbyZone != null) cubbyZone.active = true;\n            if (bellClip != null) { ambient.Play(bellClip, 0.8f); yield return Wait(2.5f); }\n            PA(L(\"Good morning! Today is Inspection Day. Instructor Voss will inspect every desk.\", \"早上好！今天是检查日。沃斯督导将检查每一张课桌。\"), 6f, false, 0.6f);\n            Authority(L(\"Sit straight. A short lesson first. I will be asking questions.\", \"坐直。先上一小段课。我会提问。\"), 5f, false, 0.6f);\n            Thought(L(\"I left it behind the panel last night.\\n\", \"昨晚我把它藏在挡板后面了。\\n\") + Rule(L(\"Get it back\", \"把它拿回来\")) + L(\" before he gets to my desk.\", \"，赶在他检查到我的课桌之前。\"), 6f, false, 0.6f);\n            lecture = StartCoroutine(Lecture());\n            StartCoroutine(Reminder(L(\"(Look down at the cubby. The phone is still behind the panel.)\", \"（低头看课桌抽屉。手机还在挡板后面。）\"), () => cubbySearched, 28f));\n        }\n\n        IEnumerator PullPanel()\n        {\n            loosePanel.active = false;\n            Transform t = loosePanel.transform;\n            foreach (Collider c in t.GetComponentsInChildren<Collider>()) c.enabled = false;\n            Vector3 a = t.localPosition, b = a + new Vector3(0f, 0f, -0.14f), c2 = b + new Vector3(0.16f, 0f, 0f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(a, b, k * k * (3f - 2f * k)); yield return null; }\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.45f) { t.localPosition = Vector3.Lerp(b, c2, k * k * (3f - 2f * k)); yield return null; }\n            t.localPosition = c2;\n            if (hiddenPhone != null) hiddenPhone.active = true;\n        }\n\n        void TakePhone()\n        {\n            hiddenPhone.active = false;\n            hiddenPhone.gameObject.SetActive(false);\n            phone.hasPhone = true;\n            gotPhone = true;\n            nextCall = Random.Range(callInterval.x, callInterval.y) * 0.5f;\n            Thought(L(\"Still here. Sit up \", \"还在。按 \") + Rule(L(\"[Space]\", \"[空格]\")) + L(\", \", \" 坐直，\") + Rule(L(\"HOLD RIGHT MOUSE\", \"按住右键\")) + L(\" when he isn't looking.\", \"看手机——趁他没在看。\"), 7f, true);\n            StartCoroutine(Messages());\n        }\n\n        IEnumerator Messages()\n        {\n            yield return Wait(2f);\n            phone.Receive(\"Triangle\", L(\"inspection today. he checks every desk. every single one.\", \"今天查课桌。他每张都查。每一张。\"));\n            yield return Wait(1.5f);\n            phone.Receive(\"Triangle\", L(\"before he gets to you: look at the last photo. the one we never told you about.\", \"他查到你之前：看最后一张照片。我们一直没告诉你的那张。\"));\n            StartCoroutine(Reminder(L(\"Triangle said: \", \"三角说：\") + Rule(L(\"Photos - the last photo\", \"相册 - 最后一张照片\")) + L(\".\", \"。\"), () => phone.OldPhotoFound || inspecting || ended, 34f));\n            while (!phone.OldPhotoFound && !inspecting && !ended) yield return null;\n            if (ended || inspecting) yield break;\n            Thought(L(\"1979. Back row, by the window. \", \"1979 年。最后一排，靠窗。\") + Rule(L(\"My seat.\", \"我的座位。\")) + L(\"\\nIn pencil: VOSS. He sat here.\", \"\\n铅笔写着：沃斯。他坐过这里。\"), 6f, true, 0.5f);\n            phone.Receive(\"Triangle\", L(\"he had this phone once. he gave it up. that's how he got to stay.\", \"这部手机他以前也有过。他交出去了。所以他才能留下来。\"));\n            yield return Wait(2f);\n            phone.Receive(\"Triangle\", L(\"he's starting. decide what you want it to be for.\", \"他开始了。想好你要拿它做什么。\"));\n            yield return Wait(2f);\n            StartInspection();\n        }\n\n        void StartInspection()\n        {\n            if (inspecting || ended) return;\n            inspecting = true;\n            if (calling) { calling = false; questionBox.SetActive(false); }\n            if (lecture != null) StopCoroutine(lecture);\n            StartCoroutine(Inspection());\n        }\n\n        // ------------------------------------------------------------------ the inspection\n        IEnumerator Inspection()\n        {\n            yield return WaitIdle();\n            PA(L(\"Inspection will now begin. Please remain seated and grateful.\", \"检查现在开始。请保持坐姿，并心怀感激。\"), 4.5f, false, 0.4f);\n            UnityEngine.AI.NavMeshAgent ag = teacher.GetComponent<UnityEngine.AI.NavMeshAgent>();\n            if (ag != null) ag.speed = 1.9f;\n\n            // only a few desks on the way to yours: one at the front, one in the middle, then the two next to you\n            List<Transform> all = new List<Transform>(classmates);\n            all.RemoveAll(x => x == null);\n            all.Sort((a, b) => b.position.z.CompareTo(a.position.z));\n            List<Transform> near = new List<Transform>(all);\n            near.Sort((a, b) => Vector3.Distance(b.position, rig.transform.position).CompareTo(Vector3.Distance(a.position, rig.transform.position)));\n            List<Transform> order = new List<Transform>();\n            if (all.Count > 0) order.Add(all[0]);\n            if (all.Count > 2 && !order.Contains(all[all.Count / 2])) order.Add(all[all.Count / 2]);\n            for (int k = Mathf.Max(0, near.Count - 2); k < near.Count; k++) if (!order.Contains(near[k])) order.Add(near[k]);\n            // every verdict matches something on that desk (put there now, so you can see it before he gets there)\n            string[] verdicts =\n            {\n                \"Pencils. Two. Approved.\",\n                \"A drawing of a horse. Confiscated. ...It is a good horse.\",\n                \"Nothing. Good. Nothing is good.\",\n                \"A note that says 'help'. Is this a joke? Confiscated. Ha. Ha.\",\n            };\n            bool[] confiscated = { false, true, false, true };\n            if (order.Count > verdicts.Length) order.RemoveRange(verdicts.Length, order.Count - verdicts.Length);\n            for (int i = 0; i < order.Count; i++)\n            {\n                GameObject prop = verdictProps != null && i < verdictProps.Length ? verdictProps[i] : null;\n                if (prop == null || order[i] == null) continue;\n                Vector3 c = order[i].position;\n                prop.transform.position = new Vector3(c.x + (i % 2 == 0 ? -0.06f : 0.06f), 0.752f, c.z + 0.6f);\n                prop.SetActive(true);\n            }\n            int v = 0;\n            for (int i = 0; i < order.Count && !ended; i++)\n            {\n                Transform s = order[i];\n                if (s == null) continue;\n                // he stands in the nearest aisle, never on or between the desks\n                float ax = 0.65f;\n                foreach (float a in new[] { 0.65f, 3.5f, 6.5f, 9.3f }) if (Mathf.Abs(a - s.position.x) < Mathf.Abs(ax - s.position.x)) ax = a;\n                Vector3 stand = new Vector3(ax, 0f, s.position.z);\n                teacher.Approach(stand, s);\n                float t = 0f;\n                yield return Wait(0.3f);\n                while (!teacher.HasArrived && t < 8f && !ended) { t += Time.deltaTime; yield return null; }\n                if (ended) yield break;\n                Authority(Loc.T(verdicts[v % verdicts.Length]), 4.2f, true, 0.2f);\n                ambient.Play(AudioSynth.Creak(), 0.25f, 1.4f);\n                // a long silence after each verdict: time to think about what he just took (or didn't)\n                t = 0f;\n                while (t < 3.6f && !ended) { t += GameSpeed.Dt; yield return null; }\n                // confiscated: he takes it with him\n                if (confiscated[v % confiscated.Length] && verdictProps != null && v < verdictProps.Length && verdictProps[v] != null) verdictProps[v].SetActive(false);\n                v++;\n            }\n            if (ended) yield break;\n            yield return Choice();\n        }\n\n        IEnumerator Choice()\n        {\n            yield return WaitIdle();\n            choosing = true;\n            phone.CancelTask();\n            Authority(Name + L(\". Seat thirty-one. Your turn.\", \"。三十一号座位。轮到你了。\"), 5f, true);\n            Thought(L(\"He's coming. \", \"他过来了。\") + Rule(L(\"Decide.\", \"做决定。\")), 4f);\n            ShowQuestion(L(\"He's one desk away.\\n\\n1    Hide it again. Keep the seat's secret.\\n2    Send it. To everyone.\", \"他只差一张课桌了。\\n\\n1    再藏起来。守住这个座位的秘密。\\n2    发出去。发给所有人。\"));\n            int pick = 0;\n            float tt = 0f;\n            while (tt < choiceSeconds && pick == 0 && !ended)\n            {\n                tt += Time.deltaTime;\n                questionTimer.rectTransform.anchorMax = new Vector2(1f - tt / choiceSeconds, 1f);\n                questionStatus.text = L(\"Press 1 or 2\", \"按 1 或 2\");\n                int d = GameInput.DigitDown();\n                if (d == 1 || d == 2) pick = d;\n                yield return null;\n            }\n            questionBox.SetActive(false);\n            choosing = false;\n            SetObjective(\"\");\n            if (ended) yield break;\n            ended = true;   // no more warnings from here on: this is your decision\n            if (pick == 2) yield return EndingLights();\n            else yield return EndingSeat();\n        }\n\n        IEnumerator WalkToYou()\n        {\n            if (teacher == null || takePhoneStandPoint == null) yield break;\n            teacher.Approach(takePhoneStandPoint.position, rig.transform);\n            float t = 0f;\n            yield return Wait(0.3f);\n            while (!teacher.HasArrived && t < 8f) { t += Time.deltaTime; yield return null; }\n        }\n\n        IEnumerator EndingSeat()\n        {\n            phone.allowRaise = false;\n            phone.hasPhone = false;\n            rig.Lock();\n            Thought(L(\"(You slide it back behind the panel. Like whoever sat here before you.)\", \"（你把它塞回挡板后面。就像之前坐在这里的每一个人。）\"), 5f, true);\n            yield return WalkToYou();\n            yield return WaitIdle();\n            ambient.Duck(6f);\n            Authority(L(\"Lid up.\", \"掀开桌盖。\"), 3f);\n            yield return WaitIdle();\n            Authority(L(\"Books. Approved.\", \"书本。合格。\"), 3.5f);\n            Authority(\"...\", 3f);\n            Authority(L(\"This panel is loose.\", \"这块挡板松了。\"), 4f);\n            yield return WaitIdle();\n            Thought(L(\"Don't breathe.\", \"别呼吸。\"), 3f);\n            yield return WaitIdle();\n            Authority(L(\"...It has always been loose.\", \"……它一直都是松的。\"), 4.5f);\n            Authority(L(\"An inspected desk is a happy desk, \", \"被检查过的课桌，是快乐的课桌，\") + Name + L(\".\", \"。\"), 5f);\n            yield return WaitIdle();\n            if (teacher != null) teacher.WalkToAndFace(teacher.lectureSpot, teacher.lectureFacingYaw);\n            PA(L(\"Inspection complete. Zero items found. Congratulations, Clearview!\", \"检查完毕。未发现任何物品。恭喜明鉴！\"), 6f);\n            yield return WaitIdle();\n            Thought(L(\"It's still there. For whoever sits here next.\", \"它还在那里。留给下一个坐在这里的人。\"), 5f);\n            yield return WaitIdle();\n            GameFlow.endingChoice = 1;\n            yield return FinishLevel(\"ending_seat\", 2.5f);\n        }\n\n        IEnumerator EndingLights()\n        {\n            rig.Lock();\n            phone.forceRaise = true;\n            phone.ForceOpen(PhoneController.AppMessages);\n            bool sent = false;\n            phone.StartTask(new PhoneTask\n            {\n                forward = true,\n                header = \"Forward\",\n                options = new[] { \"EVERYONE (all contacts)\" },\n                sendText = L(\"the stairs are open. everyone. now.\", \"楼梯开着。所有人。现在。\"),\n                typeSeconds = 4f,\n                onDone = i => sent = true,\n            });\n            Thought(Rule(L(\"[LEFT MOUSE]\", \"[左键]\")) + L(\" select, then \", \" 选择，然后 \") + Rule(L(\"HOLD LEFT MOUSE\", \"按住左键\")) + L(\" to send.\", \" 发送。\"), 99f, true);\n            StartCoroutine(WalkToYou());\n            yield return Wait(1.5f);\n            Authority(L(\"...What are you doing.\", \"……你在干什么。\"), 4f, true);\n            float t = 0f;\n            bool said = false;\n            while (!sent)\n            {\n                t += Time.deltaTime;\n                if (t > 6f && !said) { said = true; Authority(L(\"Put it down, \", \"放下，\") + Name + L(\". Put it DOWN.\", \"。放下！\"), 5f, true); }\n                yield return null;\n            }\n            ClearLine();\n            yield return Wait(0.6f);\n            yield return LightsUp();\n            yield return Wait(2.6f);   // let the chord ring out\n            StudentSay(\"CLASSMATE\", L(\"...Seat thirty-one.\", \"……三十一号。\"), 2.2f, false, 0.1f);\n            StudentSay(\"CLASSMATE\", L(\"It's open. The stairs.\", \"开着。楼梯。\"), 2.2f, false, 0.1f);\n            yield return WaitIdle();\n            Authority(\"...\", 1.8f, false, 0.1f);\n            yield return WaitIdle();\n            phone.forceRaise = false;\n            if (teacher != null) teacher.WalkToAndFace(teacher.boardSpot, teacher.boardFacingYaw);\n            Authority(L(\"Page forty. Read quietly.\", \"第四十页。安静阅读。\"), 3f, false, 0.1f);\n            yield return WaitIdle();\n            Thought(L(\"He turned to the board.\\nHe isn't looking. \", \"他转向了黑板。\\n他没在看。\") + Rule(L(\"He's letting us go.\", \"他在放我们走。\")), 4f, false, 0.1f);\n            yield return WaitIdle();\n            ambient.Play(AudioSynth.Glitch(), 0.5f);\n            PA(L(\"<color=#7a1d16>...N0thing happened t0day. Thank y0u.</color>\", \"<color=#7a1d16>……今天什么都没发生。谢谢。</color>\"), 3.5f);\n            yield return WaitIdle();\n            GameFlow.endingChoice = 2;\n            if (basementSeat != null) yield return Basement();\n            yield return FinishLevel(\"ending_lights\", 2.5f);\n        }\n\n        /// <summary>Epilogue of LIGHTS: that afternoon, at the bottom of the stairs. Then Voss in the doorway.</summary>\n        IEnumerator Basement()\n        {\n            yield return Fade(0f, 1f, 1.6f);\n            caption.text = L(\"THAT AFTERNOON.\\n\\nTHE ROOM AT THE BOTTOM OF THE STAIRS.\", \"那天下午。\\n\\n楼梯底下的房间。\");\n            phone.forceRaise = false;\n            phone.hasPhone = true;      // down here you can use it - everyone does\n            phone.allowRaise = true;\n            rig.SitAt(basementSeat.position, basementSeat.eulerAngles.y);\n            PrepareHeads();\n            rig.BackToSeat();\n            ambient.droneVolume = 0.03f;\n            ambient.ventVolume = 0.02f;\n            AudioSource voices = gameObject.AddComponent<AudioSource>();\n            voices.clip = AudioSynth.Murmur();\n            voices.loop = true;\n            voices.spatialBlend = 0f;\n            voices.volume = 0.35f;\n            voices.Play();\n            yield return Wait(2f);\n            caption.text = \"\";\n            yield return Fade(1f, 0f, 1.4f);\n\n            StudentSay(\"TRIANGLE\", L(\"Seat thirty-one! Sit. ...Told you. After the bell.\", \"三十一号！坐。……我说过的。下课铃之后。\"), 3.2f, false, 0.15f);\n            StudentSay(\"HUMS WHEN SCARED\", L(\"You came. I'm not humming - did you notice?\", \"你来了。我没在哼歌——你发现了吗？\"), 3.2f, false, 0.15f);\n            Coroutine chat = StartCoroutine(BasementChat());\n            StudentSay(\"NEVER BLINKS\", L(\"Still can't sleep. But it's better down here.\", \"还是睡不着。但在这下面好多了。\"), 3.2f, false, 0.15f);\n            StudentSay(\"LENT ME AN ERASER\", L(\"Say anything. Out loud. Nobody's writing it down.\", \"随便说什么。大声说。没人在记。\"), 3.2f, false, 0.15f);\n            yield return WaitIdle();\n            Thought(L(\"Nobody is whispering. \", \"没有人在小声说话。\") + Rule(L(\"Nobody looks at the ceiling.\", \"没有人抬头看天花板。\")) +\n                    L(\"\\nEveryone's phone is out. \", \"\\n每个人都拿着手机。\") + Rule(L(\"Mine too: HOLD RIGHT MOUSE.\", \"我的也可以：按住鼠标右键。\")), 5f, false, 0.15f);\n            yield return WaitIdle();\n            yield return Wait(6f);   // time to read the group chat\n\n            // someone at the door\n            if (vossInDoorway != null) vossInDoorway.SetActive(true);\n            ambient.Play(AudioSynth.Creak(), 0.5f, 0.8f);\n            if (chat != null) StopCoroutine(chat);\n            TurnHeads(true);   // slowly, one after another, everyone turns to the door\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 1.2f) { voices.volume = Mathf.Lerp(0.35f, 0.03f, k); yield return null; }\n            Thought(L(\"The doorway. \", \"门口。\") + Rule(L(\"Instructor Voss.\", \"沃斯督导。\")) + L(\"\\nEveryone stops talking.\", \"\\n所有人都不说话了。\"), 4.5f, true);\n            yield return Wait(4.5f);\n            Authority(\"...\", 3f);\n            yield return Wait(3.2f);\n            // he steps back onto the landing and closes the door - from the outside\n            Vector3 v0 = vossInDoorway != null ? vossInDoorway.transform.position : Vector3.zero;\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.8f)\n            {\n                if (vossInDoorway != null) vossInDoorway.transform.position = v0 + vossInDoorway.transform.forward * -0.8f * k;\n                yield return null;\n            }\n            if (basementDoorHinge != null)\n            {\n                Quaternion a = basementDoorHinge.rotation, b = Quaternion.Euler(0f, 0f, 0f);\n                for (float k = 0f; k < 1f; k += Time.deltaTime / 1.4f)\n                {\n                    basementDoorHinge.rotation = Quaternion.Slerp(a, b, k * k * (3f - 2f * k));\n                    if (k > 0.5f && vossInDoorway != null) vossInDoorway.SetActive(false);\n                    yield return null;\n                }\n                basementDoorHinge.rotation = b;\n            }\n            if (vossInDoorway != null) vossInDoorway.SetActive(false);\n            ambient.Play(AudioSynth.Click(), 0.6f, 0.6f);\n            Thought(L(\"He closed the door.\\n\", \"他关上了门。\\n\") + Rule(L(\"From the outside.\", \"从外面。\")), 5f, true);\n            yield return Wait(1.2f);\n            TurnHeads(false);   // ...and slowly, back to each other\n            yield return Wait(1.6f);\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 2f) { voices.volume = Mathf.Lerp(0.03f, 0.4f, k); yield return null; }\n            StudentSay(\"TRIANGLE\", L(\"...So. Where were we?\", \"……所以。我们刚说到哪了？\"), 3.5f);\n            phone.Receive(\"Never Blinks\", L(\"did he just close it for us?\", \"他刚刚……是帮我们把门关上了吗？\"));\n            yield return Wait(2f);\n            phone.Receive(\"Triangle\", L(\"he sat in seat 31 once. maybe he remembers.\", \"他以前也坐过 31 号。也许他还记得。\"));\n            yield return WaitIdle();\n            yield return Wait(3f);\n        }\n\n        // ------------------------------------------------------------------ the basement: a group chat, heads that turn\n        IEnumerator BasementChat()\n        {\n            string[,] chat =\n            {\n                { \"Bus 14\", \"first time typing without checking who's behind me\" },\n                { \"Don't Reply\", \"replying. for once.\" },\n                { \"Hums When Scared\", \"la la la (that's me humming. on purpose)\" },\n                { \"Lent Me An Eraser\", \"welcome, 31. you still owe me an eraser btw\" },\n                { \"Never Blinks\", \"i blinked. nobody wrote it down\" },\n                { \"Triangle\", \"house rule down here: say it out loud or type it. both count.\" },\n            };\n            string[] zh =\n            {\n                \"第一次打字不用先看身后有没有人\",\n                \"回复。就这一次。\",\n                \"啦啦啦（是我在哼歌。故意的）\",\n                \"欢迎你，31。对了你还欠我一块橡皮\",\n                \"我眨眼了。没人记下来\",\n                \"这下面的规矩：说出来，或者打出来。都算。\",\n            };\n            for (int i = 0; i < zh.Length; i++)\n            {\n                yield return Wait(i == 0 ? 0.5f : Random.Range(1.6f, 2.6f));\n                phone.Receive(chat[i, 0], L(chat[i, 1], zh[i]));\n            }\n        }\n\n        Transform[] heads;\n        Quaternion[] headRest;\n        Coroutine[] headTurns;\n\n        /// <summary>Gathers each basement student's head parts under a neck pivot, so the head can turn on its own.</summary>\n        void PrepareHeads()\n        {\n            if (basementStudents == null) return;\n            heads = new Transform[basementStudents.Length];\n            headRest = new Quaternion[basementStudents.Length];\n            headTurns = new Coroutine[basementStudents.Length];\n            for (int i = 0; i < basementStudents.Length; i++)\n            {\n                Transform f = basementStudents[i];\n                if (f == null) continue;\n                Transform look = f.Find(\"Chibi\");\n                if (look == null) continue;\n                Transform pivot = new GameObject(\"HeadPivot\").transform;\n                pivot.SetParent(look, false);\n                pivot.localPosition = new Vector3(0f, 1.13f, 0f);\n                List<Transform> parts = new List<Transform>();\n                foreach (Transform c in look) if (c != pivot && c.localPosition.y >= 1.13f) parts.Add(c);\n                foreach (Transform c in parts) c.SetParent(pivot, true);\n                heads[i] = pivot;\n                headRest[i] = pivot.localRotation;\n            }\n        }\n\n        void TurnHeads(bool toDoor)\n        {\n            if (heads == null) return;\n            for (int i = 0; i < heads.Length; i++)\n            {\n                if (heads[i] == null) continue;\n                Quaternion target = headRest[i];\n                if (toDoor && vossInDoorway != null)\n                {\n                    Vector3 to = vossInDoorway.transform.position - heads[i].position; to.y = 0f;\n                    Vector3 local = heads[i].parent.InverseTransformDirection(to);\n                    float yaw = Mathf.Clamp(Mathf.Atan2(local.x, local.z) * Mathf.Rad2Deg, -80f, 80f);\n                    target = headRest[i] * Quaternion.Euler(-4f, yaw, 0f);\n                }\n                if (headTurns[i] != null) StopCoroutine(headTurns[i]);\n                headTurns[i] = StartCoroutine(TurnHead(heads[i], target, (toDoor ? 0.25f : 0.15f) * i + Random.Range(0f, 0.2f), toDoor ? 1.6f : 1.9f));\n            }\n        }\n\n        static IEnumerator TurnHead(Transform h, Quaternion to, float delay, float seconds)\n        {\n            yield return new WaitForSeconds(delay);\n            Quaternion from = h.localRotation;\n            for (float k = 0f; k < 1f; k += Time.deltaTime / seconds)\n            {\n                h.localRotation = Quaternion.Slerp(from, to, k * k * (3f - 2f * k));\n                yield return null;\n            }\n            h.localRotation = to;\n        }\n\n        /// <summary>\n        /// The climax: every hidden phone in the room lights up, nearest first, faster and faster. A wide chord\n        /// rises underneath; each phone rings its own note going up a major scale; when the last one is lit,\n        /// a big open chord blooms. (Everything else goes quiet so this is the loudest moment in the game.)\n        /// </summary>\n        IEnumerator LightsUp()\n        {\n            List<Transform> order = new List<Transform>(classmates);\n            order.RemoveAll(x => x == null);\n            order.Sort((a, b) => Vector3.Distance(a.position, rig.transform.position).CompareTo(Vector3.Distance(b.position, rig.transform.position)));\n\n            ambient.droneVolume = 0f;\n            ambient.ventVolume = 0f;\n            AudioSource swell = OneShot2D(AudioSynth.Swell(), 0.6f, 1f);\n            yield return Wait(1.2f);\n\n            float[] scale = { 1f, 1.2f, 1.3333f, 1.5f, 1.8f, 2f, 2.4f, 2.6667f, 3f, 3.6f, 4f };   // minor pentatonic, going up (free, but lonely)\n            Shader sh = Shader.Find(\"Universal Render Pipeline/Unlit\");\n            for (int i = 0; i < order.Count; i++)\n            {\n                Transform s = order[i];\n                GameObject g = new GameObject(\"PhoneGlow\");\n                g.transform.position = s.position + new Vector3(0f, 0.85f, 0.25f);\n                Light l = g.AddComponent<Light>();\n                l.type = LightType.Point;\n                l.color = new Color(0.62f, 0.85f, 1f);\n                l.range = 1.8f;\n                l.intensity = 0f;\n                StartCoroutine(GlowIn(l, 2.4f));\n                GameObject quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\n                Destroy(quad.GetComponent<Collider>());\n                quad.transform.SetParent(g.transform, false);\n                quad.transform.localScale = new Vector3(0.07f, 0.13f, 1f);\n                quad.transform.localRotation = Quaternion.Euler(60f, 180f, 0f);\n                Renderer r = quad.GetComponent<Renderer>();\n                if (sh != null) r.material = new Material(sh) { color = new Color(0.75f, 0.92f, 1f) };\n\n                float pitch = scale[Mathf.Min(i, scale.Length - 1)] * 0.5f * (i >= scale.Length ? 1f + (i - scale.Length + 1) * 0.06f : 1f);\n                OneShot2D(AudioSynth.Ping(), Mathf.Lerp(0.22f, 0.4f, i / (float)Mathf.Max(1, order.Count)), pitch);\n                ambient.Play(AudioSynth.Vibrate(), 0.15f, Random.Range(0.9f, 1.15f));\n                // starts slow, then the whole room catches\n                float wait = Mathf.Lerp(0.6f, 0.13f, Mathf.Clamp01(i / 7f));\n                yield return Wait(wait);\n            }\n            yield return Wait(0.25f);\n            OneShot2D(AudioSynth.Bloom(), 0.9f, 1f);\n            if (swell != null) StartCoroutine(FadeOut(swell, 2.5f));\n            dangerFx.level = 0f;\n        }\n\n        IEnumerator GlowIn(Light l, float to)\n        {\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.35f) { if (l != null) l.intensity = Mathf.Lerp(0f, to * 1.6f, k); yield return null; }\n            for (float k = 0f; k < 1f; k += Time.deltaTime / 0.6f) { if (l != null) l.intensity = Mathf.Lerp(to * 1.6f, to, k); yield return null; }\n        }\n\n        AudioSource OneShot2D(AudioClip clip, float volume, float pitch)\n        {\n            if (clip == null) return null;\n            GameObject g = new GameObject(\"Climax audio\");\n            g.transform.SetParent(transform, false);\n            AudioSource a = g.AddComponent<AudioSource>();\n            a.clip = clip;\n            a.volume = volume;\n            a.pitch = pitch;\n            a.spatialBlend = 0f;\n            a.priority = 0;\n            a.Play();\n            Destroy(g, clip.length / Mathf.Max(0.1f, pitch) + 0.5f);\n            return a;\n        }\n\n        IEnumerator FadeOut(AudioSource a, float seconds)\n        {\n            float v0 = a != null ? a.volume : 0f;\n            for (float k = 0f; k < 1f && a != null; k += Time.deltaTime / seconds) { a.volume = v0 * (1f - k); yield return null; }\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            phone.allowRaise = rig.CurrentMode == PlayerRig.Mode.Seated && phone.hasPhone && !choosing;\n            if (gotPhone)\n            {\n                phoneTime += Time.deltaTime;\n                if (!inspecting && phoneTime > inspectionFallbackSeconds) StartInspection();\n            }\n            if (phone.hasPhone && phone.RaisedOnce && !toldDanger)\n            {\n                toldDanger = true;\n                Thought(L(\"Same rules. If he can see it, \", \"规则一样。如果他能看到手机，\") + Rule(L(\"it shakes and turns red\", \"它会抖动并变红\")) + L(\".\", \"。\"));\n            }\n            UpdateObjective();\n            UpdateInteraction();\n            UpdateDanger();\n            UpdateCalls();\n        }\n\n        void UpdateObjective()\n        {\n            if (choosing) { SetObjective(L(\"DECIDE.\\n1 = hide it again    2 = send it to everyone\", \"做决定。\\n1 = 再藏起来    2 = 发给所有人\")); return; }\n            if (inspecting) { SetObjective(L(\"The inspection has begun.\\nKeep the phone hidden. Yours is the last desk.\", \"检查已经开始。\\n藏好手机。你的课桌是最后一张。\")); return; }\n            if (!gotPhone) { SetObjective(L(\"Get the phone back.\\nLook down at the cubby (E), pull the loose panel.\", \"把手机拿回来。\\n低头看课桌抽屉（E），拉开松动的挡板。\")); return; }\n            if (!phone.OldPhotoFound) { SetObjective(L(\"Answer his questions (1 / 2 / 3, phone down).\\nCheck PHOTOS - the LAST photo.\", \"回答他的问题（1 / 2 / 3，先放下手机）。\\n查看相册——最后一张照片。\")); return; }\n            SetObjective(L(\"Wait. He's starting the inspection.\", \"等着。他要开始检查了。\"));\n        }\n\n        void UpdateInteraction()\n        {\n            string p = null;\n            PlayerRig.Mode m = rig.CurrentMode;\n            if (m == PlayerRig.Mode.Seated || m == PlayerRig.Mode.Inspect)\n            {\n                if (m == PlayerRig.Mode.Inspect && GameInput.SpaceDown()) { rig.BackToSeat(); SetZone(true); SetPrompt(null); return; }\n                p = RaycastInteract();\n                if (p == null && m == PlayerRig.Mode.Inspect) p = L(\"[Space]  Sit back up\", \"[空格]  坐直\");\n            }\n            SetPrompt(p);\n        }\n\n        void UpdateDanger()\n        {\n            bool seen = phone.IsExposed && teacher != null && teacher.Running && vision != null && vision.CanSee(phoneExposurePoint.position, rig.transform);\n            // during the inspection he is close and paying attention: he notices faster\n            float secs = inspecting ? noticeSeconds * 0.7f : noticeSeconds;\n            bool searching = rig.CurrentMode == PlayerRig.Mode.Inspect && inspecting && teacher != null && vision != null && vision.CanSee(rig.eye.position, rig.transform, 4f);\n            float rate = seen ? 1f / Mathf.Max(0.05f, secs) : (searching ? 1f / 4f : 0f);\n            if (AccumulateDanger(rate))\n            {\n                if (seen) Strike(L(\"...Is that a device, \", \"……那是电子设备吗，\") + Name + L(\"?\", \"？\"));\n                else Strike(L(\"Hands out of the desk. I inspect it, not you.\", \"手拿出来。检查课桌的是我，不是你。\"));\n            }\n        }\n\n        protected override IEnumerator OnCaught()\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            if (lecture != null) StopCoroutine(lecture);\n            Authority(L(\"That's three, \", \"第三次了，\") + Name + L(\".\", \"。\"), 4f, true);\n            yield return WalkToYou();\n            yield return WaitIdle();\n            Authority(L(\"Give it to me. ...You'll thank me. Just like I was.\", \"交给我。……你会感谢我的。就像我当年一样。\"), 6f);\n            yield return WaitIdle();\n            PA(L(\"Inspection complete. One item found. Congratulations, Clearview!\", \"检查完毕。发现一件物品。恭喜明鉴！\"), 5.5f);\n            yield return WaitIdle();\n            yield return Caught(\"inspected\");\n        }\n\n        // ------------------------------------------------------------------ lecture & questions\n        IEnumerator Lecture()\n        {\n            int i = 0;\n            bool pa = false;\n            while (!ended && !inspecting)\n            {\n                if (!calling && DialogueIdle && teacher != null && teacher.lines.Count > 0)\n                {\n                    int idx = i % teacher.lines.Count;\n                    if (idx > linesSaid) linesSaid = idx;\n                    Authority(Loc.T(teacher.lines[idx].text));\n                    i++;\n                    yield return WaitIdle();\n                    if (i == 4 && !pa) { pa = true; PA(L(\"Reminder: smiling during inspection is encouraged, but not required. It is encouraged.\", \"提醒：检查期间鼓励微笑，但不强制。是鼓励。\")); yield return WaitIdle(); }\n                    float t = 0f;\n                    while (t < 3f && !ended) { if (DialogueIdle) t += GameSpeed.Dt; yield return null; }\n                }\n                yield return null;\n            }\n        }\n\n        void UpdateCalls()\n        {\n            if (!gotPhone || inspecting || teacher == null) return;\n            if (!calling)\n            {\n                if (nextCall > 0f) { nextCall -= GameSpeed.Dt; if (nextCall <= 0f) StartCall(); }\n                return;\n            }\n            callTimer -= Time.deltaTime;\n            questionTimer.rectTransform.anchorMax = new Vector2(Mathf.Clamp01(callTimer / answerSeconds), 1f);\n            bool canAnswer = rig.CurrentMode == PlayerRig.Mode.Seated && !phone.IsExposed;\n            if (phone.IsExposed) questionStatus.text = L(\"PUT THE PHONE DOWN to answer!  (release Right Mouse)\", \"先放下手机才能回答！（松开右键）\");\n            else if (rig.CurrentMode != PlayerRig.Mode.Seated) questionStatus.text = L(\"SIT UP to answer!  [Space]\", \"坐直才能回答！[空格]\");\n            else questionStatus.text = L(\"Press 1, 2 or 3\", \"按 1、2 或 3\");\n            if (canAnswer)\n            {\n                int d = GameInput.DigitDown();\n                if (d >= 1 && d <= 3) { EndCall(d - 1 == question.correct, false); return; }\n            }\n            if (callTimer <= 0f) EndCall(false, true);\n        }\n\n        void StartCall()\n        {\n            question = PickQuestion();\n            if (question == null) { nextCall = 10f; return; }\n            calling = true;\n            callTimer = answerSeconds;\n            teacher.CallOn(rig.transform);\n            Authority(Name + L(\".  \", \"。\") + Loc.T(question.question), answerSeconds + 1f, true);\n            string q = Loc.T(question.question) + \"\\n\";\n            for (int i = 0; i < question.options.Length; i++) q += \"\\n\" + (i + 1) + \"    \" + Loc.T(question.options[i]);\n            ShowQuestion(q);\n        }\n\n        LessonQuestion PickQuestion()\n        {\n            List<int> pool = new List<int>();\n            for (int i = 0; i < teacher.questions.Count; i++)\n                if (teacher.questions[i].aboutLine <= linesSaid && !asked.Contains(i)) pool.Add(i);\n            if (pool.Count == 0)\n            {\n                asked.Clear();\n                for (int i = 0; i < teacher.questions.Count; i++) if (teacher.questions[i].aboutLine <= linesSaid) pool.Add(i);\n            }\n            if (pool.Count == 0) return null;\n            int pick = pool[Random.Range(0, pool.Count)];\n            foreach (int i in pool) if (teacher.questions[i].aboutLine >= 0 && Random.value < 0.7f) { pick = i; break; }\n            asked.Add(pick);\n            return teacher.questions[pick];\n        }\n\n        void EndCall(bool correct, bool timedOut)\n        {\n            calling = false;\n            questionBox.SetActive(false);\n            teacher.EndCall();\n            nextCall = Random.Range(callInterval.x, callInterval.y);\n            if (correct) Authority(L(\"...Correct. You listen. Like I did.\", \"……正确。你在听。像我当年一样。\"), 4f, true);\n            else if (timedOut) Strike(L(\"I asked you a question, \", \"我在问你问题，\") + Name + L(\".\", \"。\"));\n            else Strike(L(\"Wrong. Nobody in that seat has ever been wrong.\", \"错了。坐那个位置的人从来没答错过。\"));\n        }\n    }\n}\n"},"LevelDirectorBase":{"path":"Assets/Game/Scripts/LevelDirectorBase.cs","role":"Shared chapter rules: one subtitle at a time, danger meter, 3 hidden warnings, objective panel, prompts, chapter cards","source":"// @role Shared chapter rules: one subtitle at a time, danger meter, 3 hidden warnings, objective panel, prompts, chapter cards\n// @calls PlayerRig, PhoneController, DangerFX, AmbientAudio, AudioSynth, Interactable, GameFlow, GameSpeed, Readable, PosterEgg\n// @tune chances:int:1-5:warnings before the phone is taken (never shown as a number)\n// @tune noticeSeconds:float:0.5-6:seconds a watcher must see the phone before a warning\n// @tune dangerDecayPerSecond:float:0.1-1:how fast danger drains once nobody is looking\n// @tune graceAfterWarning:float:0-6:seconds of safety right after a warning\n// @tune typeCharsPerSecond:float:20-120:subtitle typewriter speed\nusing System.Collections;\nusing System.Collections.Generic;\nusing Unity.AI.Navigation;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Everything the four chapters share:\n    ///  - ONE subtitle at a time: authority / students / PA at the top, the player's thoughts bottom-left.\n    ///    Text is typed in (typewriter), with a small \"voice\" blip per speaker.\n    ///  - Interaction ray (look at something + E), prompts.\n    ///  - Danger: while a watcher can see what you're doing, the phone shakes and turns red, the screen edges\n    ///    go red and the music turns sour. Full = a warning. Three warnings, never shown as numbers.\n    ///  - Warning feedback: red \"WARNING\" flash, a low hit, and sudden silence.\n    ///  - Chapter cards, fades, finishing the level.\n    /// </summary>\n    public abstract class LevelDirectorBase : MonoBehaviour\n    {\n        [Header(\"Core references (filled by the scene builder)\")]\n        public PlayerRig rig;\n        public PhoneController phone;\n        public NavMeshSurface navSurface;\n        public Transform phoneExposurePoint;\n\n        [Header(\"Rules\")]\n        public int chances = 3;\n        [Tooltip(\"Seconds of being seen with the phone until he notices (phone fully red).\")]\n        public float noticeSeconds = 2.5f;\n        public float dangerDecayPerSecond = 0.35f;\n        public float graceAfterWarning = 3f;\n        public float interactDistance = 1.8f;\n\n        [Header(\"Subtitle timing (seconds)\")]\n        public float teacherLineSeconds = 7.5f;\n        public float thoughtSeconds = 7.5f;\n        public float gapBetweenLines = 1.4f;\n        public float typeCharsPerSecond = 55f;\n        public bool voiceBlips = true;\n\n        [Header(\"Reading posters (walk up and look at them)\")]\n        [Tooltip(\"Seconds the crosshair must rest on a poster before you read it.\")]\n        public float readSeconds = 0.6f;\n\n        protected enum Who { Authority, Student, Thought, PA }\n        protected class Line { public Who who; public string speaker; public string text; public float seconds; public float gap; }\n\n        protected int strikes;\n        protected float danger, grace;\n        protected bool ended;\n        protected AmbientAudio ambient;\n        protected DangerFX dangerFx;\n        /// <summary>Label shown above the authority's lines (\"TEACHER\", \"LUNCH MONITOR\"...).</summary>\n        protected string authorityLabel = \"TEACHER\";\n        protected float authorityPitch = 0.8f;\n        protected string Name { get { return Loc.Chinese && GameFlow.playerName == \"Student\" ? \"同学\" : GameFlow.playerName; } }\n\n        Readable[] readables;\n        Readable reading;\n        float readT;\n        /// <summary>How many posters / signs the player has read in this chapter.</summary>\n        protected int postersRead;\n\n        readonly Queue<Line> queue = new Queue<Line>();\n        Line current;\n        float currentLeft, gapLeft, reveal;\n        int revealedShown;\n        string currentFull = \"\";\n\n        // HUD\n        protected Image fade, questionTimer;\n        protected Text speechText, speechWho, thoughtText, prompt, caption, questionText, questionStatus;\n        protected GameObject questionBox, speechBox, thoughtBox, promptBox;\n        Image speechBg, speechAccent, paStripe;\n        Text warningText, speedText;\n        float warningT;\n        GameObject chapterRoot;\n        Text chapterLabelText, chapterTitleText, chapterTimeText, chapterSloganText;\n        Image lidTop, lidBottom, lidDark;\n        Text objectiveText, objectiveLabel;\n        Image objectiveBg, objectiveDivider;\n        RectTransform objectivePanel;\n        float objectiveFlash;\n        string actionShown = \"\";\n        static readonly Color PanelBg = new Color(0.05f, 0.055f, 0.06f, 0.9f);\n        static readonly Color Amber = new Color(1f, 0.8f, 0.45f);\n        const float PanelW = 380f, PanelPad = 20f;\n        float lids;\n\n        static readonly Color SpeechBg = new Color(0.07f, 0.08f, 0.09f, 0.88f);\n        static readonly Color SpeechInk = new Color(0.96f, 0.94f, 0.9f);\n        static readonly Color Red = new Color(0.78f, 0.12f, 0.1f);\n\n        // ------------------------------------------------------------------ lifecycle\n        protected virtual void Awake()\n        {\n            RemoveOtherCameras();\n            BuildHUD();\n            ambient = AmbientAudio.Create(transform);\n            dangerFx = DangerFX.Create(transform);\n        }\n\n        protected virtual void Start()\n        {\n            Cursor.lockState = CursorLockMode.Locked;\n            Cursor.visible = false;\n            if (navSurface != null) navSurface.BuildNavMesh();\n            readables = FindObjectsByType<Readable>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);\n            PosterEgg.InstallAll();   // posters that change when you come close (works on scenes built before an entry was added)\n        }\n\n        protected virtual void Update()\n        {\n            if (GameInput.EscDown()) { Cursor.lockState = CursorLockMode.None; Cursor.visible = true; }\n            if (GameInput.LeftDown() && Cursor.lockState != CursorLockMode.Locked) { Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false; }\n            if (GameInput.SkipDown() && !ended) { StopAllCoroutines(); StartCoroutine(FinishLevel(\"skip\", 0.4f)); }\n            if (GameInput.SpeedDown()) { GameSpeed.Fast = !GameSpeed.Fast; ambient.Play(AudioSynth.Tick(), 0.3f, GameSpeed.Fast ? 1.5f : 0.9f); }\n            if (speedText != null) speedText.text = GameSpeed.Fast ? L(\"2x  (Tab)\", \"2 倍速（Tab）\") : L(\"1x  (Tab: 2x)\", \"1 倍速（Tab：2 倍）\");\n            TickDialogue();\n            TickHUD();\n            PlacePrompt();\n            LevelAlways();\n            if (ended)\n            {\n                if (phone != null) phone.danger = 0f;\n                danger = Mathf.MoveTowards(danger, 0f, Time.deltaTime);\n                ambient.dangerLevel = 0f;\n                dangerFx.level = 0f;\n                return;\n            }\n            UpdateReading();\n            LevelUpdate();\n            ambient.dangerLevel = danger;\n            dangerFx.level = danger;\n        }\n\n        /// <summary>Runs every frame, even after the level has ended.</summary>\n        protected virtual void LevelAlways() { }\n\n        /// <summary>Runs every frame while the level is being played.</summary>\n        protected abstract void LevelUpdate();\n\n        /// <summary>Third warning: what happens when they take the phone. Must end with GameFlow.EndLevel.</summary>\n        protected abstract IEnumerator OnCaught();\n\n        /// <summary>Gameplay is always seen through the player's eyes; any other camera (e.g. a FlyCamera) is removed.</summary>\n        void RemoveOtherCameras()\n        {\n            Transform mine = rig != null ? rig.transform : transform;\n            foreach (Camera c in FindObjectsByType<Camera>(FindObjectsInactive.Include, FindObjectsSortMode.None))\n            {\n                if (c.transform.IsChildOf(mine)) continue;\n                GameObject root = c.gameObject;\n                foreach (MonoBehaviour mb in c.GetComponentsInParent<MonoBehaviour>(true))\n                    if (mb != null && mb.GetType().Name == \"FlyCameraController\") { root = mb.gameObject; break; }\n                root.SetActive(false);\n                Destroy(root);\n            }\n            foreach (AudioListener l in FindObjectsByType<AudioListener>(FindObjectsInactive.Include, FindObjectsSortMode.None))\n                if (!l.transform.IsChildOf(mine)) Destroy(l);\n            if (rig != null && rig.eye != null)\n            {\n                Camera own = rig.eye.GetComponent<Camera>();\n                if (own != null) { own.enabled = true; own.gameObject.tag = \"MainCamera\"; }\n            }\n        }\n\n        // ------------------------------------------------------------------ dialogue: one line at a time\n        protected void Say(Who who, string speaker, string text, float seconds, bool interrupt = false, float gap = -1f)\n        {\n            Line l = new Line { who = who, speaker = speaker, text = text, seconds = seconds, gap = gap >= 0f ? gap : gapBetweenLines };\n            if (interrupt) { queue.Clear(); Show(l); }\n            else queue.Enqueue(l);\n        }\n\n        protected void Authority(string text, float seconds = -1f, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.Authority, authorityLabel, text, seconds > 0f ? seconds : teacherLineSeconds, interrupt, gap);\n        }\n\n        protected void Thought(string text, float seconds = -1f, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.Thought, \"\", text, seconds > 0f ? seconds : thoughtSeconds, interrupt, gap);\n        }\n\n        protected void PA(string text, float seconds = -1f, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.PA, \"PA SYSTEM\", text, seconds > 0f ? seconds : teacherLineSeconds, interrupt, gap);\n        }\n\n        protected void StudentSay(string speaker, string text, float seconds, bool interrupt = false, float gap = -1f)\n        {\n            Say(Who.Student, speaker, text, seconds, interrupt, gap);\n        }\n\n        void Show(Line l)\n        {\n            current = l;\n            currentLeft = l.seconds;\n            currentFull = l.text ?? \"\";\n            reveal = 0f;\n            revealedShown = 0;\n            bool speech = l.who != Who.Thought;\n            speechBox.SetActive(speech);\n            thoughtBox.SetActive(!speech);\n            if (speech)\n            {\n                // PA announcements use the same dark subtitle as everyone else (a white box read like a phone notification)\n                bool pa = l.who == Who.PA;\n                speechBg.color = SpeechBg;\n                speechAccent.color = pa ? new Color(0.6f, 0.62f, 0.66f) : Red;\n                paStripe.enabled = false;\n                speechWho.text = pa ? Loc.L(\"LOUDSPEAKER  (school announcement)\", \"广播（学校通知）\") : Loc.T(l.speaker ?? \"\").ToUpper();\n                speechWho.color = pa ? new Color(0.72f, 0.74f, 0.78f) : new Color(1f, 0.45f, 0.38f);\n                speechText.color = SpeechInk;\n                speechText.text = \"\";\n                if (pa) ambient.Play(AudioSynth.Chime(), 0.35f);\n                // the box grows with the line (Chinese and long lines wrap instead of running out of the box)\n                RectTransform sb = (RectTransform)speechBox.transform;\n                sb.sizeDelta = new Vector2(sb.sizeDelta.x, Mathf.Max(118f, UIFactory.PreferredHeight(speechText, currentFull) + 56f));\n            }\n            else\n            {\n                thoughtText.text = \"\";\n                RectTransform tb = (RectTransform)thoughtBox.transform;\n                tb.sizeDelta = new Vector2(tb.sizeDelta.x, Mathf.Max(160f, UIFactory.PreferredHeight(thoughtText, currentFull) + 36f));\n            }\n        }\n\n        protected void ClearLine()\n        {\n            gapLeft = current != null ? current.gap : gapBetweenLines;\n            current = null;\n            speechBox.SetActive(false);\n            thoughtBox.SetActive(false);\n        }\n\n        void TickDialogue()\n        {\n            if (current != null)\n            {\n                int total = RichText.VisibleLength(currentFull);\n                if (revealedShown < total)\n                {\n                    // PA lines wait for the chime before they start typing\n                    float delay = current.who == Who.PA ? 0.6f : 0f;\n                    reveal += GameSpeed.Dt * typeCharsPerSecond;\n                    int shown = Mathf.Clamp(Mathf.FloorToInt(reveal - delay * typeCharsPerSecond), 0, total);\n                    if (shown != revealedShown)\n                    {\n                        for (int i = revealedShown; i < shown; i++) Voice(current, i);\n                        revealedShown = shown;\n                        string s = shown >= total ? currentFull : RichText.Reveal(currentFull, shown);\n                        if (current.who == Who.Thought) thoughtText.text = s; else speechText.text = s;\n                    }\n                }\n                currentLeft -= GameSpeed.Dt;\n                if (currentLeft <= 0f) ClearLine();\n                return;\n            }\n            if (gapLeft > 0f) { gapLeft -= GameSpeed.Dt; return; }\n            if (queue.Count > 0) Show(queue.Dequeue());\n        }\n\n        void Voice(Line l, int index)\n        {\n            if (!voiceBlips) return;\n            char ch = RichText.VisibleChar(currentFull, index);\n            if (!char.IsLetter(ch)) return;\n            if (l.who == Who.Thought)\n            {\n                if (index % 3 == 0) ambient.Play(AudioSynth.Tick(), 0.08f, Random.Range(0.9f, 1.1f));\n                return;\n            }\n            if (index % 3 != 0) return;\n            float p = l.who == Who.Authority ? authorityPitch : (l.who == Who.PA ? 1.25f : 1.35f);\n            ambient.Play(AudioSynth.Blip(), l.who == Who.PA ? 0.12f : 0.17f, p * Random.Range(0.93f, 1.07f));\n        }\n\n        protected bool DialogueIdle { get { return current == null && queue.Count == 0 && gapLeft <= 0f; } }\n\n        protected IEnumerator WaitIdle() { while (!DialogueIdle) yield return null; }\n\n        /// <summary>When something else should keep a reminder quiet (questions, roll call...).</summary>\n        protected virtual bool ReminderBlocked() { return false; }\n\n        /// <summary>Repeats a thought every 'every' seconds (only when nothing else is being said) until 'done'.</summary>\n        protected IEnumerator Reminder(string text, System.Func<bool> done, float every)\n        {\n            while (!ended && !done())\n            {\n                while (!ended && !done() && (!DialogueIdle || ReminderBlocked())) yield return null;\n                if (ended || done()) yield break;\n                Thought(text);\n                float t = 0f;\n                while (t < every && !done()) { t += GameSpeed.Dt; yield return null; }\n            }\n        }\n\n        /// <summary>Rules in the player's thoughts are highlighted so they stand out.</summary>\n        protected static string Rule(string s) { return \"<b><color=#ff9a6e>\" + s + \"</color></b>\"; }\n\n        /// <summary>A scripted pause, at story speed (2x halves it).</summary>\n        protected static WaitForSeconds Wait(float seconds) { return new WaitForSeconds(seconds / GameSpeed.Factor); }\n\n        /// <summary>English / Chinese pair, picked by the language setting (Loc).</summary>\n        protected static string L(string en, string zh) { return Loc.L(en, zh); }\n\n        // ------------------------------------------------------------------ reading posters\n        /// <summary>\n        /// Every poster, sign and label in the school is there to be read. Walk up to one (or, sitting, look at it\n        /// for a moment) and the player reads it: a thought, a Search word, or the poster answering back.\n        /// </summary>\n        void UpdateReading()\n        {\n            if (readables == null || readables.Length == 0 || rig == null || rig.eye == null) return;\n            PlayerRig.Mode m = rig.CurrentMode;\n            bool seated = m == PlayerRig.Mode.Seated;\n            bool canRead = (m == PlayerRig.Mode.Walk || seated) && (phone == null || !phone.IsExposed);\n            Readable best = null;\n            if (canRead)\n            {\n                float bestA = 999f;\n                Vector3 eye = rig.eye.position, fwd = rig.eye.forward;\n                foreach (Readable r in readables)\n                {\n                    if (r == null || r.read || !r.isActiveAndEnabled) continue;\n                    Vector3 to = r.Centre - eye;\n                    float d = to.magnitude;\n                    float range = seated ? Mathf.Min(11f, r.Range * 3.6f) : r.Range;\n                    if (d > range || d < 0.05f) continue;\n                    if (Vector3.Dot(r.transform.forward, to) < 0f) continue;   // looking at the back of it\n                    float a = Vector3.Angle(fwd, to);\n                    float allow = Mathf.Max(6f, Mathf.Atan2(r.Radius * 0.8f, d) * Mathf.Rad2Deg);\n                    if (a > allow || a >= bestA) continue;\n                    if (ReadBlocked(eye, r)) continue;\n                    best = r;\n                    bestA = a;\n                }\n            }\n            if (best != reading) { reading = best; readT = 0f; }\n            if (reading == null) return;\n            readT += Time.deltaTime;\n            if (readT < readSeconds) return;\n            Readable done = reading;\n            reading = null;\n            done.read = true;\n            OnRead(done);\n        }\n\n        bool ReadBlocked(Vector3 eye, Readable r)\n        {\n            Vector3 to = r.Centre - eye;\n            float d = to.magnitude;\n            foreach (RaycastHit h in Physics.RaycastAll(eye, to / d, Mathf.Max(0f, d - 0.1f), ~0, QueryTriggerInteraction.Ignore))\n            {\n                if (h.transform.IsChildOf(rig.transform) || h.transform.IsChildOf(r.transform)) continue;\n                return true;\n            }\n            return false;\n        }\n\n        /// <summary>A poster was read. Chapters can add their own reactions (call base).</summary>\n        protected virtual void OnRead(Readable r)\n        {\n            postersRead++;\n            if (r.Reacts)\n            {\n                r.React();\n                ambient.Play(AudioSynth.Glitch(), 0.22f);\n            }\n            string say = string.IsNullOrEmpty(r.reaction) ? \"\" : Loc.T(r.reaction);\n            if (!string.IsNullOrEmpty(r.keyword) && phone != null && phone.AddSearchWord(r.keyword))\n                say += (say.Length > 0 ? \"\\n\" : \"\") + Rule(L(\"Search word noted: \", \"记下搜索词：\") + Loc.T(r.keyword));\n            if (say.Length > 0) Thought(say, Mathf.Clamp(3f + RichText.VisibleLength(say) / 20f, 4f, 9f));\n        }\n\n        // ------------------------------------------------------------------ interaction\n        /// <summary>Raycast from the eye; returns the prompt to show (or null) and uses the thing on [E].</summary>\n        protected string RaycastInteract()\n        {\n            if (rig == null || rig.eye == null) return null;\n            if (phone != null && phone.IsExposed) return null;\n            RaycastHit[] hits = Physics.RaycastAll(rig.eye.position, rig.eye.forward, interactDistance, ~0, QueryTriggerInteraction.Collide);\n            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));\n            foreach (RaycastHit hit in hits)\n            {\n                if (hit.transform.IsChildOf(rig.transform)) continue;\n                Interactable it = hit.collider.GetComponentInParent<Interactable>();\n                if (it != null && it.active && it.onUse != null)\n                {\n                    if (GameInput.InteractDown()) it.onUse();\n                    return \"[E]  \" + Loc.T(it.prompt);\n                }\n                if (!hit.collider.isTrigger) return null;   // something solid is in front\n            }\n            return null;\n        }\n\n        /// <summary>\n        /// What you can do right now ([E] ..., phone hints): under the crosshair. While the phone is up the box\n        /// slides to the right of the phone, so it never covers the screen.\n        /// </summary>\n        protected void SetPrompt(string p)\n        {\n            string t = p ?? \"\";\n            if (t == actionShown) return;\n            actionShown = t;\n            prompt.text = t;\n            promptBox.SetActive(t.Length > 0);\n            if (t.Length > 0)\n            {\n                float w = Mathf.Clamp(prompt.preferredWidth + 48f, 260f, 640f);\n                RectTransform rt = (RectTransform)promptBox.transform;\n                rt.sizeDelta = new Vector2(w, 10f);\n                rt.sizeDelta = new Vector2(w, Mathf.Ceil(prompt.preferredHeight) + 22f);\n            }\n        }\n\n        void PlacePrompt()\n        {\n            if (promptBox == null || !promptBox.activeSelf) return;\n            RectTransform rt = (RectTransform)promptBox.transform;\n            bool phoneUp = phone != null && phone.IsExposed;\n            Vector2 want = phoneUp ? new Vector2(270f + rt.sizeDelta.x * 0.5f, -150f) : new Vector2(0f, -90f);\n            rt.anchoredPosition = Vector2.Lerp(rt.anchoredPosition, want, 1f - Mathf.Exp(-Time.unscaledDeltaTime * 14f));\n        }\n\n        /// <summary>Sizes the panel to its text, so nothing ever runs outside the background.</summary>\n        void LayoutPanel()\n        {\n            if (objectivePanel == null) return;\n            bool hasObj = !string.IsNullOrEmpty(objectiveText.text);\n            objectiveLabel.gameObject.SetActive(hasObj);\n            objectiveDivider.gameObject.SetActive(hasObj);\n            objectiveText.gameObject.SetActive(hasObj);\n            float y = 12f;\n            if (hasObj)\n            {\n                y = 46f;\n                float oh = Mathf.Ceil(objectiveText.preferredHeight) + 2f;\n                objectiveText.rectTransform.anchoredPosition = new Vector2(PanelPad, -y);\n                objectiveText.rectTransform.sizeDelta = new Vector2(PanelW - PanelPad * 2f, oh);\n                y += oh + 12f;\n            }\n            objectivePanel.sizeDelta = new Vector2(PanelW, y);\n            objectivePanel.gameObject.SetActive(hasObj);\n        }\n\n        // ------------------------------------------------------------------ danger & warnings\n        /// <summary>\n        /// rate = how fast he notices (1/seconds); 0 = nobody is looking (it drains back).\n        /// Returns true when the danger is full: a warning must be given.\n        /// </summary>\n        protected bool AccumulateDanger(float rate)\n        {\n            if (grace > 0f) grace -= Time.deltaTime;\n            if (rate > 0f && grace <= 0f) danger += Time.deltaTime * rate;\n            else danger -= Time.deltaTime * dangerDecayPerSecond;\n            danger = Mathf.Clamp01(danger);\n            if (phone != null) phone.danger = phone.IsExposed ? danger : 0f;\n            if (danger >= 1f)\n            {\n                danger = 0f;\n                grace = graceAfterWarning;\n                if (phone != null) phone.Flash();\n                return true;\n            }\n            return false;\n        }\n\n        /// <summary>The warning count spoken after the line (never shown as a number on screen).</summary>\n        protected virtual string StrikeSuffix(int n, bool pa)\n        {\n            if (pa) return n == 1 ? Loc.L(\"  This is your first reminder. You will receive three.\", \"  这是第一次提醒。您一共会收到三次。\") : Loc.L(\"  This is your second reminder. There is no fourth reminder.\", \"  这是第二次提醒。不会有第四次提醒。\");\n            return n == 1 ? Loc.L(\"  That's one warning. You get three.\", \"  这是第一次警告。你一共只有三次。\") : Loc.L(\"  That's two. One more, and whatever you're hiding is mine.\", \"  第二次了。再有一次，你藏的东西就归我了。\");\n        }\n\n        /// <summary>One of the three chances is used. Only the voices tell the player.</summary>\n        protected void Strike(string line, bool pa = false)\n        {\n            if (ended) return;\n            strikes++;\n            warningT = 1.6f;\n            dangerFx.Flash();\n            ambient.Play(AudioSynth.Stinger(), 0.7f);\n            ambient.Duck(1.6f);\n            if (strikes >= chances) { ended = true; StartCoroutine(OnCaught()); return; }\n            if (pa) PA(line + StrikeSuffix(strikes, true), 7.5f, true);\n            else Authority(line + StrikeSuffix(strikes, false), 7f, true);\n        }\n\n        // ------------------------------------------------------------------ cards, fades, endings\n        protected IEnumerator Fade(float from, float to, float seconds)\n        {\n            for (float t = 0f; t < seconds; t += Time.unscaledDeltaTime)\n            {\n                Color c = fade.color; c.a = Mathf.Lerp(from, to, t / seconds); fade.color = c;\n                yield return null;\n            }\n            Color e = fade.color; e.a = to; fade.color = e;\n        }\n\n        /// <summary>Black card with typed chapter info, then fades into the level. Any key skips the wait.</summary>\n        protected IEnumerator ChapterCard(string label, string title, string time, float hold = 2.2f)\n        {\n            Color fc = fade.color; fc.a = 1f; fade.color = fc;\n            chapterRoot.SetActive(true);\n            chapterLabelText.text = \"\"; chapterTitleText.text = \"\"; chapterTimeText.text = \"\"; chapterSloganText.text = \"\";\n            yield return TypeInto(chapterLabelText, Loc.T(label), 30f);\n            yield return TypeInto(chapterTitleText, Loc.T(title), 18f);\n            yield return TypeInto(chapterTimeText, Loc.T(time), 30f);\n            chapterSloganText.text = Loc.L(\"CLEARVIEW ACADEMY  -  WHAT IS SEEN, IS SAFE.\", \"明鉴学院  -  被看见的，就是安全的。\");\n            float t = 0f;\n            while (t < hold && !GameInput.AnyKeyDown()) { t += GameSpeed.Dt; yield return null; }\n            chapterRoot.SetActive(false);\n            yield return Fade(1f, 0f, 1.2f);\n        }\n\n        IEnumerator TypeInto(Text t, string s, float cps)\n        {\n            for (int i = 1; i <= s.Length; i++)\n            {\n                t.text = s.Substring(0, i);\n                if (char.IsLetterOrDigit(s[i - 1])) ambient.Play(AudioSynth.Tick(), 0.12f, Random.Range(0.9f, 1.1f));\n                float w = 1f / cps;\n                while (w > 0f) { w -= GameSpeed.Dt; yield return null; }\n            }\n        }\n\n        /// <summary>Fade out and report a win to the game flow.</summary>\n        protected IEnumerator FinishLevel(string reason, float fadeSeconds = 1.4f)\n        {\n            ended = true;\n            SetObjective(\"\");\n            yield return Fade(0f, 1f, fadeSeconds);\n            GameFlow.EndLevel(LessonResult.Win, reason);\n        }\n\n        protected IEnumerator Caught(string reason, float fadeSeconds = 1.2f)\n        {\n            ended = true;\n            SetObjective(\"\");\n            yield return Fade(0f, 1f, fadeSeconds);\n            GameFlow.EndLevel(LessonResult.Caught, reason);\n        }\n\n        /// <summary>\n        /// The current goal, always visible top-left (what to do + where). Changing it flashes the box and chimes,\n        /// so the player never has to guess the next step. null/empty hides it.\n        /// </summary>\n        protected void SetObjective(string text)\n        {\n            if (objectiveText == null) return;\n            string t = text ?? \"\";\n            if (objectiveText.text == t) return;\n            objectiveText.text = t;\n            LayoutPanel();\n            if (t.Length > 0) { objectiveFlash = 1.2f; ambient.Play(AudioSynth.Confirm(), 0.18f, 1.3f); }\n        }\n\n        /// <summary>Buzz in your pocket (phone notification).</summary>\n        protected void PhoneBuzz()\n        {\n            ambient.Play(AudioSynth.Vibrate(), 0.5f);\n        }\n\n        /// <summary>Eyelids: 0 = open, 1 = shut (lying down in bed).</summary>\n        protected void SetLids(float v) { lids = Mathf.Clamp01(v); }\n\n        protected void ShowQuestion(string text)\n        {\n            questionText.text = text;\n            UIFactory.FitFont(questionText, text, 16);\n            questionStatus.text = \"\";\n            questionTimer.rectTransform.anchorMax = Vector2.one;\n            questionBox.SetActive(true);\n        }\n\n        // ------------------------------------------------------------------ HUD\n        void TickHUD()\n        {\n            if (warningT > 0f)\n            {\n                warningT -= Time.unscaledDeltaTime;\n                bool on = Mathf.Repeat(warningT, 0.4f) > 0.15f;\n                warningText.enabled = warningT > 0f && on;\n            }\n            else warningText.enabled = false;\n\n            if (objectiveFlash > 0f)\n            {\n                objectiveFlash -= Time.unscaledDeltaTime;\n                bool on = Mathf.Repeat(objectiveFlash, 0.3f) > 0.12f;\n                objectiveBg.color = on ? new Color(0.42f, 0.09f, 0.07f, 0.94f) : PanelBg;\n            }\n            else if (objectiveBg != null) objectiveBg.color = PanelBg;\n\n            float h = Mathf.Lerp(0f, 560f, lids);\n            lidTop.rectTransform.sizeDelta = new Vector2(0f, h);\n            lidBottom.rectTransform.sizeDelta = new Vector2(0f, h);\n            lidDark.color = new Color(0f, 0f, 0f, lids * 0.55f);\n        }\n\n        void BuildHUD()\n        {\n            Canvas canvas = UIFactory.MakeCanvas(\"HUD\", 40);   // above the phone, so subtitles are never covered\n            canvas.transform.SetParent(transform, false);\n            Transform root = canvas.transform;\n\n            // eyelids (lying in bed)\n            lidDark = UIFactory.AddImage(UIFactory.Stretch(\"LidDark\", root), new Color(0f, 0f, 0f, 0f));\n            lidTop = UIFactory.AddImage(UIFactory.Rect(\"LidTop\", root, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, Vector2.zero), Color.black);\n            lidBottom = UIFactory.AddImage(UIFactory.Rect(\"LidBottom\", root, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0.5f, 0f), Vector2.zero, Vector2.zero), Color.black);\n\n            UIFactory.AddImage(UIFactory.Centered(\"Crosshair\", root, 0f, 0f, 6f, 6f), new Color(1f, 1f, 1f, 0.75f));\n\n            // OBJECTIVE + what you can do now - top-left panel that grows with its text\n            objectivePanel = UIFactory.Rect(\"Objective\", root, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(28f, -170f), new Vector2(PanelW, 100f));\n            objectiveBg = UIFactory.AddImage(objectivePanel, PanelBg);\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", objectivePanel, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(5f, 0f)), Amber);\n            objectiveLabel = UIFactory.AddText(UIFactory.TopLeft(\"Label\", objectivePanel, PanelPad, 12f, PanelW - 2f * PanelPad, 22f), Loc.L(\"OBJECTIVE\", \"当前目标\"), 16, Amber, TextAnchor.UpperLeft);\n            objectiveLabel.fontStyle = FontStyle.Bold;\n            objectiveDivider = UIFactory.AddImage(UIFactory.TopLeft(\"Divider\", objectivePanel, PanelPad, 37f, PanelW - 2f * PanelPad, 1f), new Color(1f, 0.8f, 0.45f, 0.35f));\n            objectiveText = UIFactory.AddText(UIFactory.TopLeft(\"Text\", objectivePanel, PanelPad, 46f, PanelW - 2f * PanelPad, 40f), \"\", 19, new Color(0.95f, 0.94f, 0.9f), TextAnchor.UpperLeft);\n            objectiveText.lineSpacing = 1.1f;\n            // interaction / keyboard prompt - under the crosshair (moves beside the phone while it is up)\n            RectTransform pb = UIFactory.Centered(\"Prompt\", root, 0f, -90f, 420f, 52f);\n            UIFactory.AddImage(pb, new Color(0.05f, 0.055f, 0.06f, 0.82f));\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", pb, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(4f, 0f)), Amber);\n            prompt = UIFactory.AddText(UIFactory.Rect(\"Text\", pb, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), new Vector2(2f, 0f), new Vector2(-28f, -12f)), \"\", 22, Color.white, TextAnchor.MiddleCenter);\n            prompt.fontStyle = FontStyle.Bold;\n            prompt.horizontalOverflow = HorizontalWrapMode.Wrap;\n            promptBox = pb.gameObject;\n            promptBox.SetActive(false);\n            objectivePanel.gameObject.SetActive(false);\n\n            // SPEECH / PA - top\n            RectTransform sb = UIFactory.Rect(\"Speech\", root, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -36f), new Vector2(1500f, 118f));\n            speechBg = UIFactory.AddImage(sb, SpeechBg);\n            speechAccent = UIFactory.AddImage(UIFactory.Rect(\"Accent\", sb, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(10f, 0f)), Red);\n            paStripe = UIFactory.AddImage(UIFactory.Rect(\"PaStripe\", sb, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 6f)), new Color(0.62f, 0.85f, 0.76f));\n            speechWho = UIFactory.AddText(UIFactory.TopLeft(\"Who\", sb, 30f, 10f, 1200f, 30f), \"\", 21, new Color(1f, 0.45f, 0.38f), TextAnchor.UpperLeft);\n            speechWho.fontStyle = FontStyle.Bold;\n            speechText = UIFactory.AddText(UIFactory.Rect(\"Text\", sb, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), new Vector2(6f, -12f), new Vector2(-60f, -44f)), \"\", 28, SpeechInk, TextAnchor.MiddleCenter);\n            speechBox = sb.gameObject;\n            speechBox.SetActive(false);\n\n            // WARNING flash\n            warningText = UIFactory.AddText(UIFactory.Rect(\"Warning\", root, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -190f), new Vector2(900f, 90f)), Loc.L(\"WARNING\", \"警告\"), 72, new Color(1f, 0.12f, 0.08f), TextAnchor.MiddleCenter);\n            warningText.fontStyle = FontStyle.Bold;\n            UIFactory.AddShadow(warningText, new Color(0f, 0f, 0f, 0.9f), 3f);\n            warningText.enabled = false;\n\n            // PLAYER thoughts / instructions - bottom left (the phone sits bottom centre)\n            RectTransform tb = UIFactory.Rect(\"Thoughts\", root, new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(40f, 40f), new Vector2(660f, 160f));\n            UIFactory.AddImage(tb, new Color(0.08f, 0.06f, 0.02f, 0.82f));\n            UIFactory.AddImage(UIFactory.Rect(\"Accent\", tb, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 4f)), new Color(1f, 0.8f, 0.45f, 0.8f));\n            thoughtText = UIFactory.AddText(UIFactory.Rect(\"Text\", tb, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-40f, -26f)), \"\", 26, new Color(1f, 0.86f, 0.5f), TextAnchor.MiddleLeft);\n            thoughtText.fontStyle = FontStyle.Italic;\n            thoughtBox = tb.gameObject;\n            thoughtBox.SetActive(false);\n\n            // question / roll-call answer / choices - left middle\n            RectTransform qb = UIFactory.Rect(\"Question\", root, new Vector2(0f, 0.5f), new Vector2(0f, 0.5f), new Vector2(0f, 0.5f), new Vector2(40f, -70f), new Vector2(640f, 310f));\n            UIFactory.AddImage(qb, new Color(0.05f, 0.05f, 0.06f, 0.92f));\n            UIFactory.AddImage(UIFactory.Rect(\"Bar\", qb, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 6f)), Red);\n            questionText = UIFactory.AddText(UIFactory.TopLeft(\"Q\", qb, 24f, 22f, 592f, 200f), \"\", 26, Color.white, TextAnchor.UpperLeft);\n            questionStatus = UIFactory.AddText(UIFactory.TopLeft(\"Status\", qb, 24f, 236f, 592f, 40f), \"\", 22, new Color(1f, 0.7f, 0.4f), TextAnchor.UpperLeft);\n            questionStatus.fontStyle = FontStyle.Bold;\n            RectTransform tbar = UIFactory.TopLeft(\"TimerBG\", qb, 24f, 284f, 592f, 10f);\n            UIFactory.AddImage(tbar, new Color(1f, 1f, 1f, 0.15f));\n            questionTimer = UIFactory.AddImage(UIFactory.Rect(\"Timer\", tbar, Vector2.zero, Vector2.one, new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero), new Color(1f, 0.4f, 0.3f));\n            questionBox = qb.gameObject;\n            questionBox.SetActive(false);\n\n            // story speed, top right corner\n            speedText = UIFactory.AddText(UIFactory.Rect(\"Speed\", root, new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(-24f, -14f), new Vector2(320f, 26f)), \"\", 17, new Color(1f, 1f, 1f, 0.55f), TextAnchor.UpperRight);\n\n            fade = UIFactory.AddImage(UIFactory.Stretch(\"Fade\", root), Color.black);\n            caption = UIFactory.AddText(UIFactory.Centered(\"Caption\", root, 0f, 0f, 1400f, 100f), \"\", 40, new Color(0.9f, 0.9f, 0.9f), TextAnchor.MiddleCenter);\n\n            // chapter card (on top of the fade)\n            RectTransform cr = UIFactory.Stretch(\"ChapterCard\", root);\n            chapterRoot = cr.gameObject;\n            chapterLabelText = UIFactory.AddText(UIFactory.Centered(\"Label\", cr, 0f, 120f, 1400f, 50f), \"\", 28, new Color(0.6f, 0.6f, 0.6f), TextAnchor.MiddleCenter);\n            chapterTitleText = UIFactory.AddText(UIFactory.Centered(\"Title\", cr, 0f, 30f, 1600f, 120f), \"\", 92, new Color(0.94f, 0.92f, 0.86f), TextAnchor.MiddleCenter);\n            chapterTitleText.fontStyle = FontStyle.Bold;\n            chapterTimeText = UIFactory.AddText(UIFactory.Centered(\"Time\", cr, 0f, -70f, 1400f, 50f), \"\", 30, new Color(0.7f, 0.7f, 0.7f), TextAnchor.MiddleCenter);\n            chapterSloganText = UIFactory.AddText(UIFactory.Rect(\"Slogan\", cr, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 60f), new Vector2(1400f, 40f)), \"\", 20, new Color(0.75f, 0.2f, 0.18f), TextAnchor.MiddleCenter);\n            chapterRoot.SetActive(false);\n        }\n    }\n}\n"},"Loc":{"path":"Assets/Game/Scripts/Loc.cs","role":"Language setting (English / 中文): inline pairs L(en, zh) for story text, and a table T(en) for data text (lecture lines, posters, photo captions)","source":"// @role Language setting (English / 中文): inline pairs L(en, zh) for story text, and a table T(en) for data text (lecture lines, posters, photo captions)\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The game's language. Chosen on the title page, saved in PlayerPrefs.\n    ///   Loc.L(\"English\", \"中文\")  - story text written next to its translation (subtitles, thoughts, phone messages)\n    ///   Loc.T(\"English\")          - looks the English up in LocTable (text stored in scenes or data lists)\n    /// While building scenes in the editor everything is stored in English; it is translated when the game runs.\n    /// </summary>\n    public static class Loc\n    {\n        const string Key = \"cover_lang\";\n        static int lang = -1;\n\n        public static bool Chinese\n        {\n            get { if (lang < 0) lang = PlayerPrefs.GetInt(Key, 0); return lang == 1 && Application.isPlaying; }\n            set { lang = value ? 1 : 0; PlayerPrefs.SetInt(Key, lang); PlayerPrefs.Save(); }\n        }\n\n        public static string L(string en, string zh) { return Chinese && !string.IsNullOrEmpty(zh) ? zh : en; }\n\n        public static string T(string en)\n        {\n            if (!Chinese || string.IsNullOrEmpty(en)) return en;\n            string zh;\n            return LocTable.Table.TryGetValue(en, out zh) ? zh : en;\n        }\n\n        public static string[] T(string[] en)\n        {\n            if (en == null) return null;\n            string[] o = new string[en.Length];\n            for (int i = 0; i < en.Length; i++) o[i] = T(en[i]);\n            return o;\n        }\n    }\n}\n"},"LocTable":{"path":"Assets/Game/Scripts/LocTable.cs","role":"Chinese text for everything that is stored as English data: scene posters, contacts, photos, lessons, labels","source":"// @role Chinese text for everything that is stored as English data: scene posters, contacts, photos, lessons, labels\nusing System.Collections.Generic;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// English -> 中文, used by Loc.T(). Story lines in the directors use Loc.L(\"en\", \"zh\") inline instead;\n    /// this table is for text that lives in scenes, serialized lists or arrays (posters, contacts, questions...).\n    /// A missing key simply stays English, so adding new English text never breaks anything.\n    /// </summary>\n    public static class LocTable\n    {\n        public static readonly Dictionary<string, string> Table = new Dictionary<string, string>\n        {\n            // ---------- speaker labels ----------\n            { \"TEACHER\", \"老师\" },\n            { \"LUNCH MONITOR\", \"午餐监督员\" },\n            { \"WARDEN\", \"宿管\" },\n            { \"INSTRUCTOR VOSS\", \"沃斯督导\" },\n            { \"STUDENT (whispering)\", \"同学（小声）\" },\n            { \"(whispering)\", \"（小声）\" },\n            { \"CLASSMATE\", \"同学\" },\n            { \"SLEEPING STUDENT\", \"睡着的同学\" },\n            { \"TRIANGLE\", \"三角\" },\n            { \"HUMS WHEN SCARED\", \"害怕时会哼歌\" },\n            { \"NEVER BLINKS\", \"从不眨眼\" },\n            { \"LENT ME AN ERASER\", \"借过我橡皮\" },\n            { \"PA SYSTEM\", \"广播\" },\n\n            // ---------- roll call names ----------\n            { \"Irving Adler\", \"欧文·阿德勒\" },\n            { \"Harry Keyishian\", \"哈里·基希安\" },\n            { \"Ellwood Cubberley\", \"埃尔伍德·库伯利\" },\n            { \"Bert Turtle\", \"伯特·塔托\" },\n            { \"Emily Carter\", \"艾米莉·卡特\" },\n            { \"Daniel Brooks\", \"丹尼尔·布鲁克斯\" },\n            { \"Sophie Turner\", \"索菲·特纳\" },\n            { \"Lucas Reed\", \"卢卡斯·里德\" },\n            { \"Student\", \"同学\" },\n\n            // ---------- chapters ----------\n            { \"CHAPTER 1\", \"第一章\" },\n            { \"CHAPTER 2\", \"第二章\" },\n            { \"CHAPTER 3\", \"第三章\" },\n            { \"CHAPTER 4\", \"第四章\" },\n            { \"CHAPTER 5\", \"第五章\" },\n            { \"CHAPTER 6\", \"第六章\" },\n            { \"THE LESSON\", \"第一课\" },\n            { \"LUNCH\", \"午餐\" },\n            { \"LIGHTS OUT\", \"熄灯\" },\n            { \"INSPECTION DAY\", \"检查日\" },\n            { \"MONDAY  -  08:00\", \"星期一  -  08:00\" },\n            { \"MONDAY  -  12:40\", \"星期一  -  12:40\" },\n            { \"MONDAY  -  23:40\", \"星期一  -  23:40\" },\n            { \"FRIDAY  -  09:00\", \"星期五  -  09:00\" },\n            { \"1   THE LESSON\", \"1   第一课\" },\n            { \"2   LUNCH\", \"2   午餐\" },\n            { \"3   LIGHTS OUT\", \"3   熄灯\" },\n            { \"4   INSPECTION DAY\", \"4   检查日\" },\n\n            // ---------- end pages ----------\n            { \"SOMEONE ANSWERED\", \"有人回应了\" },\n            { \"THE STAIRS GO DOWN\", \"楼梯通往下面\" },\n            { \"SOMEONE FLASHED BACK\", \"有人闪灯回应\" },\n            { \"The one in front of you is one of them.\\nAfter the bell: the stairwell.\", \"坐在你前面的那个人，是他们中的一员。\\n下课铃之后：楼梯间。\" },\n            { \"A message, passed hand to hand.\\nThe door marked STAFF was never locked.\\nIt was only watched.\", \"一条信息，一个接一个地传下去。\\n写着“教职工专用”的门从来没锁过。\\n只是一直有人盯着。\" },\n            { \"Three lights across the yard.\\nOther dorms. Other rooms. Other phones.\\nYou are not the first. You are not the only.\", \"院子对面亮起三盏灯。\\n别的宿舍。别的房间。别的手机。\\n你不是第一个。也不是唯一一个。\" },\n            { \"CAUGHT\", \"被抓了\" },\n            { \"CONFISCATED\", \"没收\" },\n            { \"INSPECTED\", \"被查出\" },\n            { \"Three warnings.\\nThe phone is his now.\", \"三次警告。\\n手机现在归他了。\" },\n            { \"The Lunch Monitor files a report.\\nThe stairs stay closed. Lunch continues.\", \"午餐监督员写了一份报告。\\n楼梯依旧关着。午餐继续。\" },\n            { \"He took it with the flashlight still on your face.\\nSweet dreams.\", \"他拿走手机时，手电筒还照在你脸上。\\n做个好梦。\" },\n            { \"One item found.\\n\\\"You'll thank me. Just like I was.\\\"\", \"发现一件物品。\\n“你会感谢我的。就像我当年一样。”\" },\n\n            // ---------- phone: hints, notifications, tasks ----------\n            { \"Hint: the year it all began\", \"提示：一切开始的那一年\" },\n            { \"Hint: lights out (24-hour clock)\", \"提示：熄灯时间（24 小时制）\" },\n            { \"Hint: when your class is photographed\", \"提示：你们班拍照的时间\" },\n            { \"Hint: where you sleep (room number)\", \"提示：你睡觉的地方（寝室号）\" },\n            { \"Hint: when we eat (24-hour clock)\", \"提示：我们吃饭的时间（24 小时制）\" },\n            { \"Hint: the stamp in the oldest book (month + year)\", \"提示：最旧那本书里的印章（月份 + 年份）\" },\n            { \"1 new message\\nUnknown: congrats on the worst seat in the whole school :)\", \"1 条新信息\\n未知号码：恭喜你坐到全校最糟糕的座位 :)\" },\n            { \"Reply\", \"回复\" },\n            { \"Forward\", \"转发\" },\n            { \"Forward to...\", \"转发给……\" },\n            { \"Not them. They're not part of this.\", \"不是他们。他们跟这事没关系。\" },\n            { \"To: Never Blinks\", \"发给：从不眨眼\" },\n            { \"EVERYONE (all contacts)\", \"所有人（全部联系人）\" },\n            { \"Unknown\", \"未知号码\" },\n\n            // ---------- contacts ----------\n            { \"Seat 31 · '79\", \"31 号座 · '79\" },\n            { \"\\\"If you are reading this, keep going.\\\"\\n(last seen: gave it back, 1980)\", \"“如果你在读这个，继续走下去。”\\n（最后的记录：1980 年，把它交了回去）\" },\n            { \"Mom (not mine)\", \"妈妈（不是我的）\" },\n            { \"Do not call. It rings in the front office.\", \"别打。会在前台办公室响。\" },\n            { \"Don't Reply\", \"别回复\" },\n            { \"Seriously. Don't.\", \"认真的。别回。\" },\n            { \"Lent Me An Eraser\", \"借过我橡皮\" },\n            { \"Still owes me an eraser.\", \"还欠我一块橡皮。\" },\n            { \"Bus 14\", \"14 路公交\" },\n            { \"Left in spring. Didn't say goodbye.\", \"春天走了。没说再见。\" },\n            { \"Triangle\", \"三角\" },\n            { \"The one with the chalk triangle. One of us.\", \"画粉笔三角形的那个。我们的人。\" },\n            { \"Hums When Scared\", \"害怕时会哼歌\" },\n            { \"Window tables. Lunch.\", \"靠窗的餐桌。午饭时。\" },\n            { \"Never Blinks\", \"从不眨眼\" },\n            { \"Room 304. Across from you.\", \"304 寝室。在你对面。\" },\n\n            // ---------- photos ----------\n            { \"2009. Back row, by the window.\\nSame seat. (Nice haircut, me.)\", \"2009。最后一排，靠窗。\\n同一个座位。（那时我的发型真不错。）\" },\n            { \"2016. \\\"Keep the screen low.\\nThey watch the light.\\\"\", \"2016。“屏幕放低。\\n他们会盯着亮光。”\" },\n            { \"2018. Proof that he sneezes like a cat.\\nDelete before he sees.\", \"2018。证据：他打喷嚏像猫。\\n别让他看见，赶紧删。\" },\n            { \"2021. The one in front with the triangle\\nis one of us. Tap their shoulder twice.\", \"2021。前排椅背上画着三角形的那个人\\n是我们的人。拍他肩膀两下。\" },\n            { \"Lights out. 21:00. Exactly.\", \"熄灯。21:00。准时。\" },\n            { \"1979. Back row, by the window. Same seat.\\nIn pencil, under the photo: VOSS.\", \"1979。最后一排，靠窗。同一个座位。\\n照片下方用铅笔写着：沃斯。\" },\n\n            // ---------- interact prompts ----------\n            { \"Use\", \"使用\" },\n            { \"Slip through the STAFF door\", \"溜进“教职工专用”门\" },\n            { \"Push the door open\", \"推开门\" },\n            { \"Listen to her\", \"听她说\" },\n            { \"Sit down\", \"坐下\" },\n            { \"Search your desk\", \"翻找课桌\" },\n            { \"Pull the loose panel\", \"拉开松动的挡板\" },\n            { \"Take the phone back\", \"把手机拿回来\" },\n\n            // ---------- lesson: Chapter 1 ----------\n            { \"Today we continue with the Founding Charter of our school.\", \"今天我们继续学习本校的《建校章程》。\" },\n            { \"Our school was founded in 1952. Nineteen fifty-two. Far away from the noise of the city.\", \"我们学校创立于 1952 年。一九五二年。远离城市的喧嚣。\" },\n            { \"The Charter has four rules. Rule one: what is seen, is safe.\", \"章程共有四条。第一条：被看见的，就是安全的。\" },\n            { \"Every device in this building is monitored. That is how we keep you safe.\", \"这栋楼里的每一台设备都受到监控。我们就是这样保护你们的安全。\" },\n            { \"Rule two: no voice leaves these walls.\", \"第二条：任何声音都不得传出这些墙。\" },\n            { \"Rule three: lights out is at nine. Twenty-one hundred. Exactly.\", \"第三条：九点熄灯。二十一点整。准时。\" },\n            { \"The pigeons in the courtyard are not monitored. ...Yet.\", \"院子里的鸽子不受监控。……暂时。\" },\n            { \"The founder planted the oak tree in the courtyard on the very first day.\", \"创办人在建校第一天，就在院子里种下了那棵橡树。\" },\n            { \"Seven classes. Seven bells. Every single day.\", \"七节课。七次铃声。每一天都是。\" },\n            { \"Whoever drew a moustache on the founder's portrait: I know you are left-handed.\", \"在创办人画像上画胡子的那位：我知道你是左撇子。\" },\n            { \"Rule four: we do not keep things from each other.\", \"第四条：我们彼此之间没有秘密。\" },\n            { \"A quiet room is a good room. Remember that.\", \"安静的教室，就是好教室。记住这一点。\" },\n            { \"And the back row, by the window... I sat in that seat once. Before you. Before all of you.\", \"还有最后一排，靠窗的那个位置……我也坐过。在你之前。在你们所有人之前。\" },\n            { \"What is six plus seven?\", \"六加七等于几？\" },\n            { \"In what year was our school founded?\", \"我们学校创立于哪一年？\" },\n            { \"What is Rule one of the Charter?\", \"章程第一条是什么？\" },\n            { \"What is seen, is safe\", \"被看见的，就是安全的\" },\n            { \"Silence is golden\", \"沉默是金\" },\n            { \"Hands on the desk\", \"双手放在桌上\" },\n            { \"When is lights out?\", \"几点熄灯？\" },\n            { \"What did the founder plant in the courtyard?\", \"创办人在院子里种了什么？\" },\n            { \"An oak tree\", \"一棵橡树\" },\n            { \"A pine tree\", \"一棵松树\" },\n            { \"A rose garden\", \"一座玫瑰园\" },\n            { \"How many bells ring every day?\", \"每天响几次铃？\" },\n            { \"Five\", \"五次\" },\n            { \"Nine\", \"九次\" },\n            { \"Seven\", \"七次\" },\n            { \"What is Rule two?\", \"第二条是什么？\" },\n            { \"No voice leaves these walls\", \"任何声音都不得传出这些墙\" },\n            { \"No running in the halls\", \"走廊里禁止奔跑\" },\n            { \"No phones after nine\", \"九点后禁止用手机\" },\n            { \"Which of these is NOT monitored?\", \"以下哪一项不受监控？\" },\n            { \"The library\", \"图书馆\" },\n            { \"The courtyard pigeons\", \"院子里的鸽子\" },\n            { \"The hallway\", \"走廊\" },\n\n            // ---------- lesson: Inspection Day ----------\n            { \"Inspection Day was established in 1953. One year after our founding.\", \"检查日设立于 1953 年。建校后的第二年。\" },\n            { \"The Charter's first rule: what is seen, is safe.\", \"章程第一条：被看见的，就是安全的。\" },\n            { \"An inspected desk is a happy desk.\", \"被检查过的课桌，是快乐的课桌。\" },\n            { \"Last year we found four hundred and twelve forbidden items. All of them are safe now.\", \"去年我们查出了四百一十二件违禁物品。它们现在都很安全。\" },\n            { \"I have taught in this room for thirty-one years. I sat in it before that.\", \"我在这间教室教了三十一年。在那之前，我坐在这里上课。\" },\n            { \"There is nothing in this school I have not seen.\", \"这所学校里，没有什么是我没见过的。\" },\n            { \"Rule four: we do not keep things from each other. It is my favourite rule.\", \"第四条：我们彼此之间没有秘密。这是我最喜欢的一条。\" },\n            { \"Some of you think you are the first. You are never the first.\", \"你们有些人以为自己是第一个。你们从来都不是第一个。\" },\n            { \"What is six times seven?\", \"六乘七等于几？\" },\n            { \"When was Inspection Day established?\", \"检查日是哪一年设立的？\" },\n            { \"An inspected desk is a...?\", \"被检查过的课桌，是……？\" },\n            { \"Happy desk\", \"快乐的课桌\" },\n            { \"Safe desk\", \"安全的课桌\" },\n            { \"Clean desk\", \"干净的课桌\" },\n            { \"How many forbidden items were found last year?\", \"去年查出了多少件违禁物品？\" },\n            { \"How long has he taught in this room?\", \"他在这间教室教了多久？\" },\n            { \"13 years\", \"13 年\" },\n            { \"31 years\", \"31 年\" },\n            { \"30 years\", \"30 年\" },\n            { \"Which rule is his favourite?\", \"他最喜欢哪一条？\" },\n            { \"Rule one\", \"第一条\" },\n            { \"Rule two\", \"第二条\" },\n            { \"Rule four\", \"第四条\" },\n\n            // ---------- Chapter 2: lunch ----------\n            { \"Reminder: smiling is part of your uniform.\", \"提醒：微笑是校服的一部分。\" },\n            { \"Today's dessert has been cancelled for your safety. Enjoy your safety.\", \"为了你们的安全，今天的甜点已取消。请享受你们的安全。\" },\n            { \"A student has been happy for fourteen consecutive days. Congratulations to everyone.\", \"有一位同学已经连续快乐了十四天。恭喜所有人。\" },\n            { \"Please do not look out of the windows. The windows are for light.\", \"请不要看窗外。窗户是用来透光的。\" },\n            { \"Lunch ends in five minutes. Please finish being nourished.\", \"午餐将在五分钟后结束。请完成营养摄入。\" },\n            { \"Chew. Thirty-two times.\", \"嚼。三十二下。\" },\n            { \"Why aren't you eating?\", \"你为什么不吃？\" },\n            { \"Eyes forward. Thank you.\", \"眼睛看前面。谢谢。\" },\n\n            // ---------- Chapter 3: lights out ----------\n            { \"Bed check.\", \"查床。\" },\n            { \"Three-oh-four. Count.\", \"三零四。点数。\" },\n            { \"...\", \"……\" },\n            { \"Nobody move.\", \"谁都别动。\" },\n            { \"Eyes closed. All of them.\", \"闭眼。所有人。\" },\n            { \"I can hear you breathing. Good. Keep doing that.\", \"我听得见你们呼吸。很好。继续保持。\" },\n            { \"Still breathing. Good.\", \"还在呼吸。很好。\" },\n            { \"Bed number two. Asleep. Correct.\", \"二号床。睡着了。正确。\" },\n            { \"Who taught you to snore like that.\", \"谁教你这么打呼噜的。\" },\n            { \"...Sleep is mandatory.\", \"……睡觉是强制的。\" },\n            { \"...don't take it...\", \"……别拿走……\" },\n            { \"...mum?...\", \"……妈妈？……\" },\n            { \"...thirty-two times...\", \"……三十二下……\" },\n            { \"...I'm smiling, I'm smiling...\", \"……我在笑，我在笑……\" },\n            { \"One.\", \"一。\" },\n            { \"Two.\", \"二。\" },\n            { \"Three.\", \"三。\" },\n            { \"Four.\", \"四。\" },\n            { \"Five.\", \"五。\" },\n            { \"...Six.\", \"……六。\" },\n\n            // ---------- Chapter 4: inspection verdicts ----------\n            { \"Pencils. Two. Approved.\", \"铅笔。两支。合格。\" },\n            { \"A drawing of a horse. Confiscated. ...It is a good horse.\", \"一幅马的画。没收。……画得不错。\" },\n            { \"Nothing. Good. Nothing is good.\", \"什么都没有。很好。什么都没有就是好。\" },\n            { \"A note that says 'help'. Is this a joke? Confiscated. Ha. Ha.\", \"一张写着“救命”的纸条。开玩笑吗？没收。哈。哈。\" },\n            { \"Approved.\", \"合格。\" },\n            { \"Gum. Under the desk. Since 1986. Approved, historically.\", \"口香糖。粘在桌底。从 1986 年起。作为历史文物，合格。\" },\n            { \"An eraser. Whose eraser is this? ...Approved.\", \"一块橡皮。这是谁的橡皮？……合格。\" },\n            { \"Approved. Thank you for your cooperation.\", \"合格。感谢配合。\" },\n\n            // ---------- posters, signs, plaques (scene text) ----------\n            { \"WHAT IS SEEN, IS SAFE.\", \"被看见的，就是安全的。\" },\n            { \"WE DON'T KEEP THINGS\\nFROM EACH OTHER.\", \"我们彼此之间\\n没有秘密。\" },\n            { \"WE KEEP THINGS\\nFROM EACH OTHER.\", \"我们彼此之间\\n有秘密。\" },\n            { \"SEAT 31\", \"31 号座\" },\n            { \"'79   '86   '94\\n'03   '11   '19\\n\\n...and you?\", \"'79   '86   '94\\n'03   '11   '19\\n\\n……还有你？\" },\n            { \"HAPPY INSPECTION DAY!  :)\", \"检查日快乐！ :)\" },\n            { \"AN INSPECTED DESK\\nIS A HAPPY DESK\", \"被检查过的课桌\\n是快乐的课桌\" },\n            { \"Instructor Voss\\nthanks you in advance.\", \"沃斯督导\\n提前感谢你。\" },\n            { \"INSTRUCTOR  VOSS\", \"沃斯  督导\" },\n            { \"FOUNDED 1952\", \"创立于 1952\" },\n            { \"Far from the noise\\nof the city.\\nClose to you.\", \"远离城市的\\n喧嚣。\\n离你很近。\" },\n            { \"A QUIET ROOM\\nIS A GOOD ROOM\", \"安静的教室\\n就是好教室\" },\n            { \"(Thank you for being quiet.)\", \"（感谢你保持安静。）\" },\n            { \"HANDS WHERE\\nWE CAN SEE\\nTHEM  :)\", \"双手放在\\n我们看得见\\n的地方  :)\" },\n            { \"REPORT A\\nFRIEND TODAY!\", \"今天就\\n举报一位朋友！\" },\n            { \"It's what friends are for.\", \"朋友就是用来干这个的。\" },\n            { \"DEVICES ARE NOT PERMITTED\", \"禁止携带电子设备\" },\n            { \"All devices are monitored.\\nThis is for your safety.\", \"所有设备均受监控。\\n这是为了你的安全。\" },\n            { \"NO RUNNING.\\nNO WALKING SLOWLY.\", \"禁止奔跑。\\n禁止慢走。\" },\n            { \"SMILE!\", \"微笑！\" },\n            { \"You are on camera.\\nYou are always on camera.\", \"你在镜头里。\\n你一直在镜头里。\" },\n            { \"CLASSROOM 1\", \"1 号教室\" },\n            { \"YOUR UNIFORM\\nIS YOUR FRIEND\", \"校服\\n是你的朋友\" },\n            { \"Wear it. Be it.\", \"穿上它。成为它。\" },\n            { \"IN SESSION\\nDO NOT KNOCK\", \"上课中\\n请勿敲门\" },\n            { \"CAFETERIA\", \"食堂\" },\n            { \"CAFETERIA\\nOPENS 12:40\", \"食堂\\n12:40 开放\" },\n            { \"STAFF ONLY\", \"教职工专用\" },\n            { \"DAYS SINCE LAST INCIDENT:  0\", \"距上次事故天数：0\" },\n            { \"CHEW 32 TIMES\", \"每口嚼 32 下\" },\n            { \"Smile between bites.\", \"两口之间请微笑。\" },\n            { \"TODAY'S MENU\", \"今日菜单\" },\n            { \"NUTRITION\\n(beige)\\n\\nDessert: cancelled\\nfor your safety\", \"营养餐\\n（米色）\\n\\n甜点：为了你的安全\\n已取消\" },\n            { \"LUNCH IS A\\nPRIVILEGE\", \"午餐是\\n一种特权\" },\n            { \"Enjoy it correctly.\", \"请正确地享用。\" },\n            { \"THE WINDOWS\\nARE FOR LIGHT\", \"窗户是\\n用来透光的\" },\n            { \"Not for looking.\", \"不是用来看的。\" },\n            { \"THESE STAIRS DO NOT EXIST\", \"这段楼梯不存在\" },\n            { \"LIGHTS OUT  21:00\", \"熄灯  21:00\" },\n            { \"ROOM 304\", \"304 寝室\" },\n            { \"SLEEP IS\\nMANDATORY\", \"睡眠是\\n强制的\" },\n            { \"Dreams are optional.\\nPlease dream quietly.\", \"做梦是自愿的。\\n请安静地做梦。\" },\n            { \"COUNT SHEEP,\\nNOT DAYS\", \"数羊，\\n别数日子\" },\n\n            // ---------- new chapters: labels, cards, titles ----------\n            { \"PHOTOGRAPHER\", \"摄影师\" },\n            { \"PREFECT\", \"学生督察\" },\n            { \"EVERYONE\", \"所有人\" },\n            { \"LIBRARIAN\", \"图书管理员\" },\n            { \"PICTURE DAY\", \"拍照日\" },\n            { \"THE ARCHIVE\", \"档案室\" },\n            { \"WEDNESDAY  -  10:15\", \"星期三  -  10:15\" },\n            { \"THURSDAY  -  15:30\", \"星期四  -  15:30\" },\n            { \"4   PICTURE DAY\", \"4   拍照日\" },\n            { \"5   THE ARCHIVE\", \"5   档案室\" },\n            { \"6   INSPECTION DAY\", \"6   检查日\" },\n            { \"SAY \\\"CLEARVIEW!\\\"\", \"说“明鉴！”\" },\n            { \"THE LESSON NEVER ENDED\", \"那堂课从未结束\" },\n            { \"Twenty reports. Three reporters.\\nA live screen with nobody on it.\\nAnd a photo from April 1967.\", \"二十份举报。三个举报员。\\n一块没有人的直播屏幕。\\n还有一张 1967 年 4 月的照片。\" },\n            { \"Five days in 1967, meant to end with the truth.\\nClearview kept the first four days.\\nTomorrow is the fifth.\", \"1967 年的五天，本该以真相结束。\\n明鉴学院留下了前四天。\\n明天就是第五天。\" },\n            { \"DEVELOPED\", \"已冲印\" },\n            { \"SHHH\", \"嘘\" },\n            { \"Report number twenty-one.\\nYour citizen card comes back with a red X.\\nNow you report, too.\", \"第二十一份举报。\\n你的公民卡发回来时多了一个红色的 X。\\n现在，你也要举报了。\" },\n            { \"The librarian stamps your hand: RETURNED.\\nThe book goes back on the repair shelf.\", \"图书管理员在你手背上盖了个章：已归还。\\n那本书回到了待修书架上。\" },\n            { \"Read the stamp in the oldest book\", \"读最旧那本书里的印章\" },\n            { \"Open drawer 31\", \"打开 31 号抽屉\" },\n\n            // ---------- Picture Day: PA, prefects, photo targets ----------\n            { \"Reminder: a citizen card must be carried at all times. Including in dreams.\", \"提醒：公民卡必须随身携带。做梦时也不例外。\" },\n            { \"Prefects are thanked for their service. Students are thanked for being observed.\", \"感谢学生督察的服务。感谢各位同学接受观察。\" },\n            { \"If you see something, say something. If you see nothing, say that too.\", \"看到什么，就说出来。什么都没看到，也请说出来。\" },\n            { \"Please do not blink during your photograph. Blinking will be photographed again.\", \"拍照时请不要眨眼。眨眼会被重新拍照。\" },\n            { \"Card. ...Oh, you don't have it yet. I'll remember you.\", \"卡。……哦，你还没有。我会记住你的。\" },\n            { \"Smile. It's for your card.\", \"笑一笑。这是印在你卡上的。\" },\n            { \"Strength through discipline.\", \"纪律带来力量。\" },\n            { \"The report board: 20 reports, 3 reporters\", \"举报布告板：20 份举报，3 个举报员\" },\n            { \"The LIVE screen. Nobody on it.\", \"“直播”屏幕。上面没有人。\" },\n            { \"The 1967 photo: the Cubberley Wing opens\", \"1967 年的照片：库伯利楼启用\" },\n\n            // ---------- Search words ----------\n            { \"CLEARVIEW\", \"明鉴\" },\n            { \"1952\", \"1952\" },\n            { \"1967\", \"1967\" },\n            { \"DAY FIVE\", \"第五天\" },\n            { \"STRENGTH\", \"力量\" },\n            { \"THE WAVE\", \"浪潮\" },\n            { \"VOSS\", \"沃斯\" },\n            { \"RED X\", \"红色 X\" },\n\n            // ---------- poster reactions (what the player notices when reading) ----------\n            { \"12:40. Lunch is at 12:40. Every day. Exactly.\\nThey say times here like passwords.\", \"12:40。午饭在 12:40。每天。准时。\\n这里的人说时间就像在说密码。\" },\n            { \"The balloons say HAPPY. The bunting says HAPPY.\\nNobody in the room says anything.\", \"气球上写着“快乐”。彩旗上写着“快乐”。\\n教室里没有一个人说话。\" },\n            { \"Friday. Day five. In 1967 the fifth day was the one with the empty screen.\", \"星期五。第五天。1967 年的第五天，就是那块空屏幕的那一天。\" },\n            { \"\\\"Thanks you in advance.\\\" In advance. For something we haven't done yet.\", \"“提前感谢你。”提前。为了我们还没做的事。\" },\n            { \"VOSS. Reporter of the Year, 1980. Seat 31 before that.\\nHe knows exactly where to look.\", \"沃斯。1980 年度最佳举报员。在那之前，31 号座。\\n他很清楚该往哪里看。\" },\n            { \"Rule one. Somebody scratched two words into the paint underneath:\\nBY WHOM?\", \"第一条。有人在下面的油漆上刻了几个字：\\n被谁？\" },\n            { \"1952. The year it all began.\\nIf I ever find a phone in this school, that's the first number I'd try.\", \"1952。一切开始的那一年。\\n要是我在这所学校里找到一部手机，我第一个就试这个数字。\" },\n            { \"Small print at the bottom: \\\"Silence is not the same as hiding.\\nPlease do not confuse them.\\\"\", \"底下有一行小字：“安静不等于隐藏。\\n请不要混淆两者。”\" },\n            { \"Hands where they can see them. So the phone goes where they can't:\\nunder the desk.\", \"手要放在他们看得见的地方。所以手机就放在他们看不见的地方：\\n课桌底下。\" },\n            { \"Under it, a tally for this week. Twenty marks.\\nThree of them in red.\", \"下面是这周的计数。二十道。\\n其中三道是红色的。\" },\n            { \"...The small print changed while I was reading it.\", \"……我读着读着，那行小字变了。\" },\n            { \"It's what friends are for.\\n\\n(Thank you for reading.\\nYour interest has been noted.)\", \"朋友就是用来干这个的。\\n\\n（感谢阅读。\\n你的关注已被记录。）\" },\n            { \"\\\"All devices are monitored.\\\" Even the ones nobody knows about?\\nEspecially those, probably.\", \"“所有设备均受监控。”连没人知道的那些也是？\\n大概尤其是那些。\" },\n            { \"Between running and walking slowly there is exactly one allowed speed.\\nTheirs.\", \"在奔跑和慢走之间，只有一种被允许的速度。\\n他们的速度。\" },\n            { \"Always on camera. ...But a camera can only look one way at a time.\", \"一直在镜头里。……可摄像头一次只能看一个方向。\" },\n            { \"Someone crossed out \\\"Be it\\\" in pencil and wrote: \\\"Hide in it.\\\"\", \"有人用铅笔划掉了“成为它”，改成：“躲进它。”\" },\n            { \"In session. During lunch. ...Who is in there?\", \"上课中。在午饭时间。……里面是谁？\" },\n            { \"STAFF ONLY. The handle is worn shiny.\\nMore hands than there are staff.\", \"教职工专用。门把手被摸得发亮。\\n摸过它的手，比教职工多得多。\" },\n            { \"The 0 isn't printed. It's painted. Over something else. Many times.\", \"那个 0 不是印上去的。是刷上去的。盖住了别的数字。刷了很多遍。\" },\n            { \"Thirty-two. Somewhere by the windows a girl is counting under her breath.\\nNo - humming.\", \"三十二。窗边有个女孩在小声数数。\\n不对——是在哼歌。\" },\n            { \"At the very bottom, three times: SERVED AT 12:40. 12:40. 12:40.\", \"最底下写了三遍：12:40 供餐。12:40。12:40。\" },\n            { \"\\\"Enjoy it correctly.\\\" There are diagrams on the back.\\nI don't turn it over.\", \"“请正确地享用。”背面还有示意图。\\n我没翻过来看。\" },\n            { \"Not for looking. ...The camera in the corner keeps looking at them, though.\\nEvery few seconds it turns its back on the counters.\", \"不是用来看的。……可角落的摄像头一直在看窗户。\\n每隔几秒，它就会背对柜台。\" },\n            { \"In pencil, underneath: \\\"then who keeps walking down them?\\\"\", \"下面有人用铅笔写着：“那一直往下走的又是谁？”\" },\n            { \"A chalk triangle. The same as on the chair in front of mine.\", \"一个粉笔三角形。和我前面那把椅子上的一样。\" },\n            { \"21:00. Twenty-one hundred. The Photos code - they made us learn it by heart.\", \"21:00。二十一点整。相册的密码——他们逼我们背得滚瓜烂熟。\" },\n            { \"Room 304. Three-oh-four. The room number, the way he counts it.\", \"304 寝室。三零四。他查房点数时就是这么念的。\" },\n            { \"\\\"Please dream quietly.\\\" Someone in this room talks in their sleep.\\nMostly numbers.\", \"“请安静地做梦。”这个房间里有人说梦话。\\n说的大多是数字。\" },\n            { \"Someone counted days anyway: tiny marks all along the edge.\\nHundreds of them. Different pens.\", \"还是有人在数日子：边上画满了小小的记号。\\n好几百道。用的是不同的笔。\" },\n            { \"31\", \"31\" },\n            { \"A sticker on the wall, right behind the gap in the back row: 31.\\nEven here, they kept my seat.\", \"最后一排的空位后面，墙上贴着一张贴纸：31。\\n连在这里，他们也给我留着座位。\" },\n            { \"THIS WEEK\", \"本周\" },\n            { \"REPORTS FILED: 20\\nREPORTERS ASSIGNED: 3\\n\\nThank you for volunteering.\", \"已提交举报：20\\n指派举报员：3\\n\\n感谢你的自愿。\" },\n            { \"THIS WEEK. Reports filed: 20. Reporters assigned: 3.\\n\\\"Thank you for volunteering.\\\"\", \"本周。已提交举报：20。指派举报员：3。\\n“感谢你的自愿。”\" },\n            { \"FOUNDER'S ADDRESS\\nLIVE  10:45\", \"创办人讲话\\n直播  10:45\" },\n            { \"LIVE at 10:45: the Founder will speak to us.\\nThe screen under it is only snow.\", \"10:45 直播：创办人将对我们讲话。\\n下面那块屏幕上只有雪花。\" },\n            { \"CUBBERLEY WING\\nAPRIL 1967\", \"库伯利楼\\n1967 年 4 月\" },\n            { \"\\\"Strength through discipline.\\\"\", \"“纪律带来力量。”\" },\n            { \"CUBBERLEY WING, APRIL 1967. Everyone in the photo raises the same hand,\\ncupped, at the shoulder. A salute nobody has taught us. Yet.\", \"库伯利楼，1967 年 4 月。照片里每个人都举着同一只手，\\n弯成杯状，举在肩旁。一种还没人教过我们的敬礼。暂时还没有。\" },\n            { \"PICTURE DAY  -  10:45 SHARP\", \"拍照日  -  10:45 准时\" },\n            { \"10:45. When they photograph us.\\nTen-forty-five, written like a time and read like a code.\", \"10:45。他们给我们拍照的时间。\\n十点四十五，写出来是时间，读起来像密码。\" },\n            { \"STRENGTH THROUGH DISCIPLINE\", \"纪律带来力量\" },\n            { \"Monday's banner said WHAT IS SEEN, IS SAFE.\\nSomeone printed a new one overnight.\", \"星期一的横幅还写着“被看见的，就是安全的”。\\n一夜之间，有人印了条新的。\" },\n            { \"STRENGTH THROUGH\\nCOMMUNITY\", \"集体带来\\n力量\" },\n            { \"STRENGTH THROUGH\\nACTION\", \"行动带来\\n力量\" },\n            { \"...ACTION. It said COMMUNITY a second ago.\\nDidn't it?\", \"……行动。一秒钟前它写的还是“集体”。\\n不是吗？\" },\n            { \"SMILE WITH\\nYOUR WHOLE\\nFACE\", \"请用\\n整张脸\\n微笑\" },\n            { \"Students who do not smile\\nwill be photographed again.\", \"不笑的同学\\n将被重新拍照。\" },\n            { \"Small print: \\\"...and again. And again.\\\"\", \"小字：“……一遍又一遍。”\" },\n            { \"YOUR PHOTO GOES ON\\nYOUR CITIZEN CARD\", \"你的照片将印在\\n你的公民卡上\" },\n            { \"Carry it. Show it. Be it.\", \"带着它。出示它。成为它。\" },\n            { \"Citizen cards. On Monday we were students.\\nSome cards will have a red X. Nobody says what it means.\", \"公民卡。星期一我们还是学生。\\n有些卡上会有红色的 X。没人说那是什么意思。\" },\n            { \"GYMNASIUM  -  CUBBERLEY WING\", \"体育馆  -  库伯利楼\" },\n            { \"Cubberley Wing. The same name is on the trophy case.\\nNobody here knows who Cubberley was. Nobody asks.\", \"库伯利楼。奖杯柜上也是这个名字。\\n这里没人知道库伯利是谁。也没人问。\" },\n            { \"HISTORY (SELECTED)\", \"历史（精选）\" },\n            { \"The history section is one shelf long.\\nHalf of it is the Charter.\", \"历史区只有一个书架那么长。\\n其中一半是《章程》。\" },\n            { \"SELF-HELP\", \"自助成长\" },\n            { \"\\\"How To Be Seen.\\\" \\\"Being Seen: A Workbook.\\\" \\\"Seen And Safe.\\\"\\nThe whole shelf is the same book.\", \"《如何被看见》《被看见：练习册》《被看见，就安全》。\\n整个书架都是同一本书。\" },\n            { \"FICTION (APPROVED)\", \"小说（已审核）\" },\n            { \"Every approved novel ends with someone being grateful.\", \"每一本审核通过的小说，结尾都有人在感恩。\" },\n            { \"The dictionary jumps from HIDE to HIDING PLACE.\\nThe page in between has been cut out.\", \"字典从“隐藏”直接跳到“藏身处”。\\n中间那一页被人剪掉了。\" },\n            { \"RETURNS\", \"还书处\" },\n            { \"All books are returned\\neventually.\", \"所有的书\\n终将归还。\" },\n            { \"\\\"All books are returned eventually.\\\" One of them never has been.\", \"“所有的书终将归还。”有一本从来没还回来过。\" },\n            { \"ARCHIVE  -  STAFF ONLY\", \"档案室  -  教职工专用\" },\n            { \"Staff only. The rope only comes up to my knees.\\nMost rules here are like that: they work because we stop.\", \"教职工专用。那根绳子才到我膝盖。\\n这里大多数规矩都是这样：之所以管用，是因为我们自己停下了。\" },\n            { \"QUIET, PLEASE\", \"请保持安静\" },\n            { \"Underneath, smaller: \\\"The meter is always listening.\\\"\", \"下面有一行更小的字：“仪表一直在听。”\" },\n            { \"OUR CATALOGUE BEGINS\\nIN APRIL 1967\", \"本馆目录始于\\n1967 年 4 月\" },\n            { \"Earlier records were reorganised\\nfor your safety.\", \"更早的记录已为了你的安全\\n而重新整理。\" },\n            { \"April 1967. The same month as the photo in the gym.\\nEverything before it was \\\"reorganised\\\".\", \"1967 年 4 月。和体育馆那张照片同一个月。\\n在那之前的一切都被“重新整理”了。\" },\n            { \"STRENGTH THROUGH DISCIPLINE\\nSTRENGTH THROUGH COMMUNITY\\nSTRENGTH THROUGH ACTION\", \"纪律带来力量\\n集体带来力量\\n行动带来力量\" },\n            { \"All three lines now, as if the motto had always been there.\", \"现在三句都齐了，好像这条校训一直都在那里。\" },\n            { \"BANNED BOOKS WEEK\\n- CANCELLED -\", \"禁书周\\n- 已取消 -\" },\n            { \"This year's list:\\nTHE WAVE (1981)\\n...and this poster.\", \"今年的书单：\\n《浪潮》（1981）\\n……还有这张海报。\" },\n            { \"THE WAVE. A novel about a classroom that turns into a movement.\\nThe only title they forgot to black out.\", \"《浪潮》。一本关于一个班级变成一场运动的小说。\\n唯一一个他们忘了涂黑的书名。\" },\n            { \"CLEARVIEW\\nYEARBOOK 1980\", \"明鉴学院\\n1980 年鉴\" },\n            { \"Reporter of the Year:\\nH. VOSS  (Seat 31)\", \"年度最佳举报员：\\nH. 沃斯（31 号座）\" },\n            { \"H. VOSS. Seat 31. Reporter of the Year, 1980 -\\nthe year the first owner of this phone \\\"gave it back\\\".\", \"H. 沃斯。31 号座。1980 年度最佳举报员——\\n正是这部手机的第一任主人“把它交回去”的那一年。\" },\n            { \"CITIZEN CARDS\\nARE READY\", \"公民卡\\n已可领取\" },\n            { \"If your card has a RED X,\\nplease report to the office.\\n(You will know what to do.)\", \"如果你的卡上有红色的 X，\\n请到办公室报到。\\n（你会知道该做什么。）\" },\n            { \"A red X means you report.\\nHums When Scared checked hers twice.\", \"红色的 X 意思是：你负责举报。\\n“害怕时会哼歌”把她的卡检查了两遍。\" },\n\n            // ---------- Picture Day retakes, the repair corner ----------\n            { \"...Someone blinked. Again in a minute. Free time - don't wander far.\", \"……有人眨眼了。一分钟后重拍。自由活动——别走远。\" },\n            { \"...Someone wasn't smiling with their whole face. Again in a minute.\", \"……有人没有用整张脸笑。一分钟后重拍。\" },\n            { \"...A shadow. On a chin. Unacceptable. Once more, in a minute.\", \"……一道阴影。在下巴上。不可接受。一分钟后再拍一次。\" },\n            { \"...Lovely. Lovely. Except one of you. Again in a minute.\", \"……很好。很好。除了你们中的一个。一分钟后重拍。\" },\n            { \"Open the old book (Records, vol. 31)\", \"打开那本旧书（记录，第 31 卷）\" },\n            { \"OLD BOOKS  -  AWAITING REPAIR\", \"旧书  -  等待修复\" },\n            { \"DO NOT HANDLE.  (This means you.)\", \"请勿触碰。（说的就是你。）\" },\n            { \"Awaiting repair since... there's no date.\\nThe rope only comes up to my knees. Rules here work because we stop.\", \"等待修复——从什么时候开始？没有写日期。\\n绳子才到我膝盖。这里的规矩之所以管用，是因为我们自己停下了。\" },\n            { \"A sticker on the wall: 31. The yellow X on the risers moves before every photo.\\nThe 31 doesn't.\", \"墙上贴着一张贴纸：31。台阶上那个黄色的 X 每次拍照前都会换地方。\\n这个 31 不会。\" },\n            { \"CLEARVIEW ALERTS\", \"明鉴提醒\" },\n            { \"ASSISTANT LIBRARIAN\", \"图书馆助理\" },\n\n            // ---------- the classroom: everything the lesson mentions is on the wall or outside the window ----------\n            { \"HAPPY INSPECTION DAY!  SINCE 1953  :)\", \"检查日快乐！  始于 1953  :)\" },\n            { \"LAST YEAR:\\n412 ITEMS FOUND\", \"去年：\\n查获 412 件物品\" },\n            { \"All of them are safe now.\\nThank you for keeping\\nnothing from us.\", \"它们现在都很安全。\\n感谢你\\n对我们毫无隐瞒。\" },\n            { \"Four hundred and twelve things people kept. All \\\"safe\\\" now.\\nI wonder what number mine would be.\", \"四百一十二件别人藏起来的东西。现在都“安全”了。\\n不知道我的会是第几件。\" },\n            { \"THE FOUNDING\\nCHARTER\", \"建校\\n章程\" },\n            { \"1. What is seen, is safe.\\n2. No voice leaves these walls.\\n3. Lights out at 21:00. Exactly.\\n4. We do not keep things from each other.\", \"1. 被看见的，就是安全的。\\n2. 任何声音都不得传出这些墙。\\n3. 21:00 熄灯。准时。\\n4. 我们彼此之间没有秘密。\" },\n            { \"Four rules. Somebody underlined rule four.\\nTwice. In red.\", \"四条规矩。有人在第四条下面画了线。\\n画了两道。用红笔。\" },\n            { \"OUR FOUNDER  -  1952\", \"我们的创办人  -  1952\" },\n            { \"The founder, 1952. Somebody gave him a moustache in pencil.\\nBoth curls hook to the left. Drawn by a left hand.\", \"创办人，1952 年。有人用铅笔给他画了两撇胡子。\\n两边都往左勾。是左手画的。\" },\n            { \"The founder. Somebody tried to rub out the pencil moustache for Inspection Day.\\nYou can still see it. Pencil never really comes off.\", \"创办人。为了检查日，有人想把那两撇铅笔胡子擦掉。\\n还是看得出来。铅笔印从来擦不干净。\" },\n            { \"The bell. Seven a day. Seven classes, every single day.\\nThe loudest thing in the school, and nobody else is allowed to be.\", \"这个铃。一天七次。七节课，每一天都是。\\n它是学校里最响的东西，而别人都不许出声。\" },\n            { \"The oak in the courtyard. The founder planted it on the very first day.\\nThe only thing here older than the rules.\", \"院子里的橡树。创办人在建校第一天种下的。\\n这里唯一比规矩还老的东西。\" },\n            { \"Inspection Day. The oak doesn't care.\\nThe founder planted it on the very first day. It has never been inspected.\", \"检查日。橡树才不在乎。\\n创办人在第一天种下它。它从来没被检查过。\" },\n            { \"Pigeons on the window ledge. The courtyard ones.\\nNot monitored. ...Yet. One of them is looking right at me.\", \"窗台上的鸽子。院子里那群。\\n不受监控。……暂时。其中一只正盯着我看。\" },\n            { \"Pigeons on the ledge. Nobody inspects them.\\nNot yet.\", \"窗台上的鸽子。没人检查它们。\\n暂时还没有。\" },\n            { \"help\", \"救命\" },\n            { \"Do not feed the pigeons. Pigeons are loud. Loud things are noticed.\", \"请勿喂鸽子。鸽子很吵。吵闹的东西会被注意到。\" },\n        };\n    }\n}\n"},"PatrolAI":{"path":"Assets/Game/Scripts/PatrolAI.cs","role":"A walking watcher on a NavMesh (Lunch Monitor, night warden): roams, follows scripted routes, scans while waiting","source":"// @role A walking watcher on a NavMesh (Lunch Monitor, night warden): roams, follows scripted routes, scans while waiting\n// @calls TeacherVision\n// @tune scanAngle:float:0-90:how far he looks left/right while standing\n// @tune scanSpeed:float:0.1-2:how fast he looks around\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.AI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// A walking watcher on a NavMesh (lunch monitor, night warden): goes around furniture, never through it.\n    ///   ROAM  - picks random points inside roamRect, waits there and looks around.\n    ///   ROUTE - follows a list of points given by the level (waits + facing per point), then reports back.\n    ///   APPROACH / HOLD - the level takes over (coming to take the phone, staring at you...).\n    /// </summary>\n    [RequireComponent(typeof(NavMeshAgent))]\n    public class PatrolAI : MonoBehaviour\n    {\n        [Tooltip(\"Random points are picked inside this rectangle (x min, z min, x max, z max).\")]\n        public Vector4 roamRect = new Vector4(15f, 0.8f, 29f, 9.5f);\n        public Vector2 waitTime = new Vector2(2f, 4.5f);\n        [Tooltip(\"While waiting, the head sweeps left/right by this many degrees.\")]\n        public float scanAngle = 55f;\n        public float scanSpeed = 0.6f;\n        public bool roamOnBegin = true;\n\n        public bool Running { get; private set; }\n        public bool HasArrived { get { return arrived; } }\n        public bool RouteDone { get { return route == null; } }\n\n        NavMeshAgent agent;\n        Transform visual;\n        bool arrived, holding, waiting;\n        float waitLeft, baseYaw, scanT, sinceGo;\n        Transform lookAt;\n        Vector3[] route;\n        float[] routeWaits, routeYaws;\n        int routeIndex;\n        System.Action onRouteDone;\n\n        void Awake()\n        {\n            agent = GetComponent<NavMeshAgent>();\n            agent.enabled = false;   // enabled after the NavMesh is built\n            visual = new GameObject(\"Visual\").transform;\n            List<Transform> kids = new List<Transform>();\n            foreach (Transform c in transform) kids.Add(c);\n            visual.SetParent(transform, false);\n            foreach (Transform c in kids) c.SetParent(visual, false);\n        }\n\n        public void Begin()\n        {\n            agent.enabled = true;\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(transform.position, out hit, 2f, NavMesh.AllAreas)) agent.Warp(hit.position);\n            Running = true;\n            if (roamOnBegin) NextRoam();\n            else { arrived = true; waiting = true; waitLeft = 9999f; baseYaw = transform.eulerAngles.y; }\n        }\n\n        /// <summary>Walk a list of points. waits[i] = seconds at point i; yaws[i] = facing there (NaN = keep).</summary>\n        [Tooltip(\"Speeds up the pauses at each point (story speed 2x sets this to 2).\")]\n        public float timeScale = 1f;\n\n        public void RunRoute(Vector3[] points, float[] waits, float[] yaws, System.Action done)\n        {\n            holding = false;\n            lookAt = null;\n            route = points;\n            routeWaits = waits;\n            routeYaws = yaws;\n            routeIndex = 0;\n            onRouteDone = done;\n            Go(route[0]);\n        }\n\n        public void Approach(Vector3 point, Transform look)\n        {\n            route = null;\n            holding = true;\n            lookAt = look;\n            Go(point);\n        }\n\n        public void Hold(Transform look)\n        {\n            route = null;\n            holding = true;\n            lookAt = look;\n            Stop();\n        }\n\n        public void ResumeRoam()\n        {\n            holding = false;\n            lookAt = null;\n            route = null;\n            NextRoam();\n        }\n\n        void Update()\n        {\n            if (!Running || !agent.enabled) return;\n            sinceGo += Time.deltaTime;\n\n            if (!arrived && sinceGo > 0.3f && !agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.05f)\n            {\n                arrived = true;\n                agent.isStopped = true;\n                OnArrive();\n            }\n\n            if (holding)\n            {\n                if (arrived && lookAt != null) Face(lookAt.position - transform.position, 220f);\n                return;\n            }\n\n            if (arrived && waiting)\n            {\n                scanT += Time.deltaTime * scanSpeed;\n                float yawNow = baseYaw + Mathf.Sin(scanT * Mathf.PI) * scanAngle;\n                transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.Euler(0f, yawNow, 0f), 140f * Time.deltaTime);\n                waitLeft -= Time.deltaTime * timeScale;\n                if (waitLeft <= 0f) Next();\n            }\n        }\n\n        void OnArrive()\n        {\n            if (holding) return;\n            waiting = true;\n            scanT = 0f;\n            baseYaw = transform.eulerAngles.y;\n            if (route != null)\n            {\n                float y = (routeYaws != null && routeIndex < routeYaws.Length) ? routeYaws[routeIndex] : float.NaN;\n                if (!float.IsNaN(y)) baseYaw = y;\n                waitLeft = (routeWaits != null && routeIndex < routeWaits.Length) ? routeWaits[routeIndex] : 0f;\n            }\n            else waitLeft = Random.Range(waitTime.x, waitTime.y);\n        }\n\n        void Next()\n        {\n            waiting = false;\n            if (route != null)\n            {\n                routeIndex++;\n                if (routeIndex < route.Length) { Go(route[routeIndex]); return; }\n                route = null;\n                System.Action cb = onRouteDone;\n                onRouteDone = null;\n                arrived = true; waiting = true; waitLeft = 9999f;\n                if (cb != null) cb();\n                return;\n            }\n            NextRoam();\n        }\n\n        void NextRoam() { Go(RandomPoint()); }\n\n        void Face(Vector3 dir, float speed)\n        {\n            dir.y = 0f;\n            if (dir.sqrMagnitude < 0.001f) return;\n            transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.LookRotation(dir), speed * Time.deltaTime);\n        }\n\n        void Go(Vector3 p)\n        {\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(p, out hit, 1.2f, NavMesh.AllAreas)) p = hit.position;\n            agent.isStopped = false;\n            agent.SetDestination(p);\n            arrived = false;\n            waiting = false;\n            sinceGo = 0f;\n        }\n\n        void Stop()\n        {\n            if (agent.enabled) { agent.isStopped = true; agent.ResetPath(); }\n            arrived = true;\n        }\n\n        Vector3 RandomPoint()\n        {\n            for (int i = 0; i < 25; i++)\n            {\n                Vector3 p = new Vector3(Random.Range(roamRect.x, roamRect.z), transform.position.y, Random.Range(roamRect.y, roamRect.w));\n                NavMeshHit hit;\n                if (!NavMesh.SamplePosition(p, out hit, 0.6f, NavMesh.AllAreas)) continue;\n                NavMeshPath path = new NavMeshPath();\n                if (agent.CalculatePath(hit.position, path) && path.status == NavMeshPathStatus.PathComplete) return hit.position;\n            }\n            return transform.position;\n        }\n\n        void LateUpdate()\n        {\n            // keep the visible body on the real floor (the NavMesh floats a few cm above it)\n            if (visual == null) return;\n            RaycastHit hit;\n            Vector3 from = transform.position + Vector3.up * 0.8f;\n            if (Physics.Raycast(from, Vector3.down, out hit, 2f, ~(1 << gameObject.layer), QueryTriggerInteraction.Ignore))\n            {\n                // only small corrections: never climb onto a chair, bench or desk the ray happens to hit\n                float want = Mathf.Clamp(hit.point.y - transform.position.y, -0.12f, 0.17f);\n                Vector3 lp = visual.localPosition;\n                lp.y = Mathf.MoveTowards(lp.y, want, 1f * Time.deltaTime);\n                visual.localPosition = lp;\n            }\n        }\n    }\n}\n"},"PhoneController":{"path":"Assets/Game/Scripts/PhoneController.cs","role":"The hidden phone: hold to raise, passcodes, app loading, Photos, Messages, Contacts, forward/reply tasks, notifications, danger shake","source":"// @role The hidden phone: hold to raise, passcodes, app loading, Photos, Messages, Contacts, forward/reply tasks, notifications, danger shake\n// @calls AudioSynth\n// @tune bootSeconds:float:1-10:start-up time (lowering the phone resets it)\n// @tune raiseSeconds:float:0.1-1:time to raise the phone\n// @tune readCharsPerSecond:float:5-60:message reading speed (only while the phone is up)\n// @tune glowIntensity:float:0-4:how much the screen lights your face (and gives you away at night)\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    [System.Serializable]\n    public class PhoneContact\n    {\n        public string name;\n        public string year;\n        [TextArea] public string note;\n        public PhoneContact(string n, string y, string no) { name = n; year = y; note = no; }\n    }\n\n    public class PhoneMsg\n    {\n        public string from;\n        public string text;\n        public bool mine;\n        public float shown;   // characters read so far\n    }\n\n    /// <summary>Something the level wants the player to do in Messages: reply, or forward to a contact.</summary>\n    public class PhoneTask\n    {\n        public bool forward;\n        public string header = \"Reply\";\n        public string[] options;\n        public int correct = -1;\n        public string wrongText = \"Not them. They're not part of this.\";\n        public string sendText;\n        public string toLabel;\n        /// <summary>Returns null if the choice can be sent now, or a reason it can't (\"No signal...\").</summary>\n        public System.Func<int, string> check;\n        public System.Action<int> onDone;\n        public float typeSeconds = 3f;\n    }\n\n    /// <summary>\n    /// The inherited phone (screen-space UI).\n    ///   Hold RIGHT MOUSE = phone up.  Release = put it down (hide).\n    ///   LOCK SCREEN  : 4-digit code with the number keys. Backspace deletes. (1952 - the year it all began)\n    ///   STARTING UP  : old phone, bootSeconds (5 s). Keep it up the WHOLE time - put it down and it locks again.\n    ///   HOME         : Photos, Camera, Contacts, Messages, Search. A / D choose, Left Mouse / Enter open.\n    ///                  Every app has its own code (heard somewhere in the school) and its own loading time,\n    ///                  with the same rule: put the phone down while it loads and it locks again.\n    ///   PHOTOS       : A / D browse, Q back.\n    ///   MESSAGES     : new messages are read only while you look at them. Replies / forwards: A / D choose,\n    ///                  Left Mouse select, then HOLD Left Mouse to type and send.\n    ///   CONTACTS     : A / D browse names left by everyone who had this phone before you.\n    ///   CAMERA       : the screen becomes a viewfinder (you see the room through it). Aim the middle of the screen,\n    ///                  Left Mouse = shutter (a click anyone close can hear), A / D = flash on / off. Photos go to PHOTOS.\n    ///   SEARCH       : the school's catalogue. A / D choose a word you have READ somewhere, HOLD Left Mouse to search.\n    ///   SILENT       : the little bell top right. M switches it (only from The Archive on; before, nobody explains it).\n    /// </summary>\n    public class PhoneController : MonoBehaviour\n    {\n        public enum PhoneScreen { Lock, Booting, Home, AppLock, AppLoading, Photos, Messages, Contacts, Camera, Search }\n        public const int AppPhotos = 0, AppCamera = 1, AppContacts = 2, AppMessages = 3, AppSearch = 4;\n\n        [Header(\"Codes & timing\")]\n        public string phoneCode = \"1952\";\n        public string phoneHint = \"Hint: the year it all began\";\n        [TextArea] public string lockNotification = \"1 new message\\nUnknown: congrats on the worst seat in the whole school :)\";\n        public float bootSeconds = 5f;\n        public float raiseSeconds = 0.25f;\n        public float lowerSeconds = 0.3f;\n        public string[] appNames = { \"Photos\", \"Camera\", \"Contacts\", \"Messages\", \"Search\" };\n        public string[] appCodes = { \"2100\", \"1045\", \"0304\", \"1240\", \"0467\" };\n        public string[] appHints =\n        {\n            \"Hint: lights out (24-hour clock)\",\n            \"Hint: when your class is photographed\",\n            \"Hint: where you sleep (room number)\",\n            \"Hint: when we eat (24-hour clock)\",\n            \"Hint: the stamp in the oldest book (month + year)\",\n        };\n\n        /// <summary>\n        /// One app per chapter. The home screen lists them in the order they are unlocked, and an app's code hint\n        /// stays \"???\" until you reach the chapter where it can be opened.\n        /// </summary>\n        public static readonly int[] HomeOrder = { AppPhotos, AppMessages, AppContacts, AppCamera, AppSearch };\n        static readonly string[] UnlockScene = { \"Level01_Lesson\", \"Level04_PictureDay\", \"Level03_LightsOut\", \"Level02_Lunch\", \"Level05_Archive\" };\n        public float[] appLoadSeconds = { 7f, 5f, 5f, 5f, 5f };\n        public bool[] appUnlocked = new bool[5];\n\n        [Header(\"Phone look\")]\n        public string phoneClock = \"10:05\";\n\n        [Header(\"Messages\")]\n        public float readCharsPerSecond = 22f;\n        public List<PhoneContact> contacts = DefaultContacts();\n\n        [Header(\"Photos\")]\n        [Tooltip(\"Shows the 1979 photo (The Inspector).\")]\n        public bool showOldPhoto;\n\n        [Header(\"Camera (Picture Day)\")]\n        [Tooltip(\"The flash starts ON - everyone sees a flash.\")]\n        public bool cameraFlash = true;\n        [Tooltip(\"Picture Day: the flash switches itself back ON every time the phone comes out.\")]\n        public bool flashOnEveryRaise;\n        [Tooltip(\"Called on every shutter press: the target in frame (or null) and whether the flash fired.\")]\n        public System.Action<PhotoTarget, bool> onShutter;\n\n        [Header(\"Silent mode (the little bell on the screen; only explained in The Archive)\")]\n        [Tooltip(\"The M key works (Chapter 5). Before that the bell is just a small icon nobody explains.\")]\n        public bool silentAvailable;\n        public bool silent;\n        [Tooltip(\"The old switch is unreliable: each time the phone comes out, silent mode may quietly switch itself off.\")]\n        [Range(0f, 1f)] public float silentFailChance;\n        /// <summary>True when the last raise quietly switched silent mode off (the level reads and clears it).</summary>\n        [HideInInspector] public bool silentJustFailed;\n        public System.Action<bool> onSilentChanged;\n\n        [Header(\"Search (The Archive)\")]\n        [Tooltip(\"Words the player has read somewhere (posters, spines, stamps). Search only knows these.\")]\n        public List<string> searchWords = new List<string>();\n        public float searchSeconds = 1.4f;\n        /// <summary>Given a word (English), returns the result text to show. Set by the level.</summary>\n        public System.Func<string, string> searchFunc;\n        public System.Action<string> onSearched;\n\n        [Header(\"Screen glow (Lights Out)\")]\n        public Light glowLight;\n        public float glowIntensity = 1.6f;\n        [HideInInspector] public float glowBoost;\n\n        [Header(\"State (set by the level)\")]\n        public bool hasPhone;\n        public bool allowRaise;\n        [Tooltip(\"The level holds the phone up for you (the ending).\")]\n        public bool forceRaise;\n        [Tooltip(\"0..1 - how close the watcher is to noticing. The phone shakes and turns red.\")]\n        public float danger;\n\n        public static List<PhoneContact> DefaultContacts()\n        {\n            return new List<PhoneContact>\n            {\n                new PhoneContact(\"Seat 31 · '79\", \"1979\", \"\\\"If you are reading this, keep going.\\\"\\n(last seen: gave it back, 1980)\"),\n                new PhoneContact(\"Mom (not mine)\", \"2009\", \"Do not call. It rings in the front office.\"),\n                new PhoneContact(\"Don't Reply\", \"2016\", \"Seriously. Don't.\"),\n                new PhoneContact(\"Lent Me An Eraser\", \"2018\", \"Still owes me an eraser.\"),\n                new PhoneContact(\"Bus 14\", \"2019\", \"Left in spring. Didn't say goodbye.\"),\n                new PhoneContact(\"Triangle\", \"2021\", \"The one with the chalk triangle. One of us.\"),\n                new PhoneContact(\"Hums When Scared\", \"2021\", \"Window tables. Lunch.\"),\n                new PhoneContact(\"Never Blinks\", \"2022\", \"Room 304. Across from you.\"),\n            };\n        }\n\n        public PhoneScreen Screen { get; private set; }\n        public bool IsExposed { get { return raise > 0.001f; } }\n        public bool IsUp { get { return raise >= 0.999f; } }\n        public bool IsHeld { get { return held; } }\n        /// <summary>Unlocked and past the start-up screen.</summary>\n        public bool ScreenOn { get { return Screen != PhoneScreen.Lock && Screen != PhoneScreen.Booting; } }\n        public bool ClueFound { get; private set; }\n        public bool OldPhotoFound { get; private set; }\n        public bool FirstContactSeen { get; private set; }\n        public bool RaisedOnce { get; private set; }\n        public int PhotosTaken { get { return taken.Count; } }\n        public PhotoTarget Aimed { get { return aimed; } }\n        public bool LastSearchDone { get; private set; }\n\n        /// <summary>Adds a word the Search app can look up. Returns false if it was already known.</summary>\n        public bool AddSearchWord(string w)\n        {\n            if (string.IsNullOrEmpty(w) || searchWords.Contains(w)) return false;\n            searchWords.Add(w);\n            return true;\n        }\n\n        public float BootSecondsElapsed { get { return Screen == PhoneScreen.Booting ? loadT : 0f; } }\n        public float AppLoadingElapsed { get { return Screen == PhoneScreen.AppLoading ? loadT : 0f; } }\n        public PhoneTask Task { get { return task; } }\n        public int OpenApp { get { return openApp; } }\n        public bool IsUnlocked(int app) { return app >= 0 && app < appUnlocked.Length && appUnlocked[app]; }\n\n        /// <summary>Has the player reached the chapter where this app's code can be worked out?</summary>\n        public bool HintAvailable(int app)\n        {\n            if (app < 0 || app >= UnlockScene.Length) return false;\n            int need = GameFlow.LevelIndex(UnlockScene[app]);\n            int now = GameFlow.LevelIndex(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);\n            return need >= 0 && now >= need;\n        }\n\n        string HintFor(int app)\n        {\n            if (!HintAvailable(app) || app >= appHints.Length) return Loc.L(\"Hint: ???\", \"提示：???\");\n            return Loc.T(appHints[app]);\n        }\n\n        public static string AppName(int app)\n        {\n            switch (app)\n            {\n                case AppPhotos: return Loc.L(\"Photos\", \"相册\");\n                case AppCamera: return Loc.L(\"Camera\", \"相机\");\n                case AppContacts: return Loc.L(\"Contacts\", \"通讯录\");\n                case AppMessages: return Loc.L(\"Messages\", \"信息\");\n                default: return Loc.L(\"Search\", \"搜索\");\n            }\n        }\n        public System.Action onMessageArrived;\n\n        public int UnreadCount\n        {\n            get\n            {\n                int n = 0;\n                foreach (PhoneMsg m in msgs) if (!m.mine && m.shown < m.text.Length) n++;\n                return n;\n            }\n        }\n\n        float raise, loadT, noticeTimer, viewTimer, typeProgress;\n        bool held, typing;\n        string entry = \"\";\n        string notice = \"\";\n        int selectedApp, openApp, photoIndex, contactIndex, choice;\n        readonly List<PhoneMsg> msgs = new List<PhoneMsg>();\n        PhoneTask task;\n        // camera + search\n        readonly List<string> taken = new List<string>();\n        PhotoTarget[] targets;\n        PhotoTarget aimed;\n        float shutterFlash, searchProgress;\n        bool searching;\n        int searchIndex;\n        string searchResult = \"\";\n        AudioSource sfx;\n        GameObject cameraRoot, searchRoot, snapshot;\n        Text camLabel, camFlashText, camCount, snapLabel, searchQuery, searchResultText, searchHeader;\n        RectTransform searchFill, screenRT;\n        GameObject searchBarRoot;\n        Image screenBg, crackImg, panelBg, whiteFlash;\n        Image[] reticle;\n        Image bellBody, bellClapper, bellSlash;\n        Text bellText;\n\n        // UI\n        RectTransform panel;\n        GameObject lockRoot, loadRoot, homeRoot, photosRoot, msgRoot, contactsRoot;\n        Text lockTitle, lockDots, loadTitle, loadPercent, homeClock, photoCaption, photoCounter, footer;\n        Text msgHeader, taskHeader, taskBody, taskHelp, contactName, contactYear, contactNote, contactCounter;\n        RectTransform loadFill, typeFill;\n        GameObject taskRoot, typeBarRoot;\n        Image[] appTiles;\n        Text[] appLabels;\n        GameObject[] photos;\n        Image[] bubbleBg;\n        Text[] bubbleFrom, bubbleText;\n        const int Bubbles = 4;\n        // new-message notification that peeks up from the bottom of the screen while the phone is down\n        RectTransform notif;\n        Text notifFrom, notifText, notifCount;\n        float notifT;\n        const float NotifHidden = -140f, NotifShown = 24f;\n        const float HiddenY = -950f, ShownY = -40f;   // low on the screen, partly \"under the desk\"\n        const float PanelScale = 1.1f;   // applied through the canvas scale (not a stretched transform) so text stays sharp\n        Image dangerTint;\n        float flashT;\n        Text lockHint, lockNote;\n        GameObject lockNoteRoot;\n        static readonly Color Ink = new Color(0.12f, 0.12f, 0.14f);\n        static readonly Color ScreenColor = new Color(0.95f, 0.91f, 0.82f);\n\n        // Photos and their captions are defined together here (in code), so a picture and its caption\n        // can never get out of step. Index 3 (the chalk triangle) is the clue for the student in front.\n        const int cluePhoto = 3;\n        const int oldPhoto = 5;\n        static readonly string[] photoCaptions =\n        {\n            \"2009. Back row, by the window.\\nSame seat. (Nice haircut, me.)\",\n            \"2016. \\\"Keep the screen low.\\nThey watch the light.\\\"\",\n            \"2018. Proof that he sneezes like a cat.\\nDelete before he sees.\",\n            \"2021. The one in front with the triangle\\nis one of us. Tap their shoulder twice.\",\n            \"Lights out. 21:00. Exactly.\",\n            \"1979. Back row, by the window. Same seat.\\nIn pencil, under the photo: VOSS.\",\n        };\n        int BasePhotos { get { return showOldPhoto ? 6 : 5; } }\n        int PhotoCount { get { return BasePhotos + taken.Count; } }\n\n        Canvas phoneCanvas;\n\n        void Awake()\n        {\n            sfx = gameObject.AddComponent<AudioSource>();\n            sfx.playOnAwake = false;\n            sfx.spatialBlend = 0f;\n            BuildUI();\n            Screen = PhoneScreen.Lock;\n            SharpenText();\n        }\n\n        /// <summary>\n        /// Phone screens use a clean sans-serif (the typewriter font stays for the school's own signs and subtitles):\n        /// thin monospaced letters at small sizes looked blurry on the phone.\n        /// </summary>\n        void SharpenText()\n        {\n            if (phoneCanvas == null) return;\n            Font sans = Loc.Chinese ? UIFactory.CjkFont : UIFactory.DefaultFont;\n            foreach (Text t in phoneCanvas.GetComponentsInChildren<Text>(true))\n            {\n                if (sans != null) t.font = sans;\n                t.fontSize += 1;\n            }\n        }\n\n        // ------------------------------------------------------------------ public API for levels\n        public void Receive(string from, string text)\n        {\n            msgs.Add(new PhoneMsg { from = from, text = text, mine = false, shown = 0f });\n            if (notifFrom != null && hasPhone)\n            {\n                notifFrom.text = Loc.T(from).ToUpper();\n                int maxChars = Loc.Chinese ? 20 : 44;\n                notifText.text = text.Length > maxChars ? text.Substring(0, maxChars - 2) + \"...\" : text;\n                notifT = 4.5f;\n            }\n            if (onMessageArrived != null) onMessageArrived();\n        }\n\n        /// <summary>A message that is already read (history from earlier days).</summary>\n        public void AddHistory(string from, string text, bool mine)\n        {\n            msgs.Add(new PhoneMsg { from = from, text = text, mine = mine, shown = text.Length });\n        }\n\n        public void StartTask(PhoneTask t)\n        {\n            task = t;\n            choice = 0;\n            typing = false;\n            typeProgress = 0f;\n        }\n\n        public void CancelTask() { task = null; typing = false; }\n\n        /// <summary>Skip the lock screen (cutscenes): the phone is on and showing an app.</summary>\n        public void ForceOpen(int app)\n        {\n            hasPhone = true;\n            if (app >= 0 && app < appUnlocked.Length) appUnlocked[app] = true;\n            openApp = app;\n            Screen = app == AppMessages ? PhoneScreen.Messages : (app == AppContacts ? PhoneScreen.Contacts : (app == AppPhotos ? PhoneScreen.Photos : PhoneScreen.Home));\n            if (app == AppCamera) EnterCamera();\n            if (app == AppSearch) Screen = PhoneScreen.Search;\n        }\n\n        /// <summary>A strike: the phone jolts and flashes red.</summary>\n        public void Flash() { flashT = 1f; }\n\n        // ------------------------------------------------------------------ update\n        void Update()\n        {\n            bool wasDown = raise <= 0.001f;\n            held = forceRaise || (hasPhone && allowRaise && GameInput.RightHeld());\n            if (held && wasDown && flashOnEveryRaise) cameraFlash = true;   // the old phone forgets: flash back on\n            if (held && wasDown && silent && silentFailChance > 0f && Random.value < silentFailChance) { silent = false; silentJustFailed = true; }   // no notice: only the bell shows it\n            float speed = held ? 1f / Mathf.Max(0.01f, raiseSeconds) : 1f / Mathf.Max(0.01f, lowerSeconds);\n            raise = Mathf.MoveTowards(raise, held ? 1f : 0f, speed * Time.deltaTime);\n            if (raise > 0.5f) RaisedOnce = true;\n            float e = raise * raise * (3f - 2f * raise);\n            // danger: shake + red, stronger the closer he is to noticing\n            if (flashT > 0f) flashT -= Time.deltaTime * 1.5f;\n            float d = Mathf.Clamp01(danger);\n            Vector2 shake = Random.insideUnitCircle * (d * d * 18f + Mathf.Max(0f, flashT) * 26f);\n            panel.anchoredPosition = new Vector2(0f, Mathf.Lerp(HiddenY, ShownY, e)) + shake;\n            dangerTint.color = new Color(0.85f, 0.05f, 0.05f, Mathf.Max(d * 0.65f, Mathf.Max(0f, flashT) * 0.75f));\n\n            if (glowLight != null)\n            {\n                if (glowBoost > 0f) glowBoost = Mathf.Max(0f, glowBoost - Time.deltaTime * 3f);\n                glowLight.intensity = raise * glowIntensity * (1f + glowBoost * 3f);\n                glowLight.enabled = raise > 0.01f;\n            }\n\n            // Leaving the phone during a loading screen resets it.\n            if (!held && Screen == PhoneScreen.Booting) { Screen = PhoneScreen.Lock; entry = \"\"; Notice(Loc.L(\"The phone locked itself again.\", \"手机又锁上了。\")); }\n            if (!held && Screen == PhoneScreen.AppLoading) { Screen = PhoneScreen.AppLock; entry = \"\"; Notice(Loc.L(AppName(openApp) + \" locked again.\", AppName(openApp) + \" 又锁上了。\")); }\n\n            if (notif != null)\n            {\n                if (notifT > 0f) notifT -= Time.deltaTime;\n                int unread = UnreadCount;\n                bool show = hasPhone && raise < 0.05f && (notifT > 0f || unread > 0);\n                float target = show ? NotifShown : NotifHidden;\n                Vector2 np = notif.anchoredPosition;\n                np.y = Mathf.Lerp(np.y, target, 1f - Mathf.Exp(-Time.deltaTime * 10f));\n                notif.anchoredPosition = np;\n                notifCount.text = unread > 1 ? Loc.L(unread + \" new messages\", unread + \" 条新信息\") : (unread == 1 ? Loc.L(\"1 new message\", \"1 条新信息\") : \"\");\n                // a quick nudge when it arrives\n                notif.localRotation = Quaternion.Euler(0f, 0f, notifT > 4.1f ? Mathf.Sin(Time.time * 60f) * 1.5f : 0f);\n            }\n\n            if (noticeTimer > 0f) noticeTimer -= Time.deltaTime;\n            if (IsUp) Tick();\n            Refresh();\n        }\n\n        void Tick()\n        {\n            float dt = GameSpeed.Dt;   // loading, reading, typing and searching all run at story speed\n            if (silentAvailable && GameInput.MuteDown())\n            {\n                silent = !silent;\n                Notice(silent ? Loc.L(\"Silent mode ON.\", \"静音模式：开。\") : Loc.L(\"Silent mode OFF.\", \"静音模式：关。\"));\n                if (onSilentChanged != null) onSilentChanged(silent);\n            }\n            switch (Screen)\n            {\n                case PhoneScreen.Lock:\n                case PhoneScreen.AppLock:\n                    if (Screen == PhoneScreen.AppLock && GameInput.BackDown()) { Screen = PhoneScreen.Home; entry = \"\"; break; }\n                    int dg = GameInput.DigitDown();\n                    if (dg >= 0 && entry.Length < 4) entry += dg.ToString();\n                    if (GameInput.BackspaceDown() && entry.Length > 0) entry = entry.Substring(0, entry.Length - 1);\n                    if (entry.Length == 4) CheckCode();\n                    break;\n\n                case PhoneScreen.Booting:\n                    loadT += dt;\n                    if (loadT >= bootSeconds) { Screen = PhoneScreen.Home; selectedApp = 0; }\n                    break;\n\n                case PhoneScreen.Home:\n                    if (GameInput.LeftKeyDown()) selectedApp = (selectedApp + HomeOrder.Length - 1) % HomeOrder.Length;\n                    if (GameInput.RightKeyDown()) selectedApp = (selectedApp + 1) % HomeOrder.Length;\n                    if (GameInput.LeftDown() || GameInput.EnterDown())\n                    {\n                        openApp = HomeOrder[selectedApp];   // selectedApp = position on the home screen\n                        entry = \"\";\n                        if (IsUnlocked(openApp)) OpenUnlockedApp();\n                        else Screen = PhoneScreen.AppLock;\n                    }\n                    break;\n\n                case PhoneScreen.AppLoading:\n                    loadT += dt;\n                    if (loadT >= appLoadSeconds[openApp])\n                    {\n                        appUnlocked[openApp] = true;\n                        OpenUnlockedApp();\n                    }\n                    break;\n\n                case PhoneScreen.Photos:\n                    if (GameInput.LeftKeyDown()) { photoIndex = (photoIndex + PhotoCount - 1) % PhotoCount; viewTimer = 0f; }\n                    if (GameInput.RightKeyDown()) { photoIndex = (photoIndex + 1) % PhotoCount; viewTimer = 0f; }\n                    if (GameInput.BackDown()) Screen = PhoneScreen.Home;\n                    viewTimer += dt;\n                    if (viewTimer > 1.5f)\n                    {\n                        if (photoIndex == cluePhoto) ClueFound = true;\n                        if (photoIndex == oldPhoto) OldPhotoFound = true;\n                    }\n                    break;\n\n                case PhoneScreen.Contacts:\n                    if (contacts.Count > 0)\n                    {\n                        if (GameInput.LeftKeyDown()) { contactIndex = (contactIndex + contacts.Count - 1) % contacts.Count; viewTimer = 0f; }\n                        if (GameInput.RightKeyDown()) { contactIndex = (contactIndex + 1) % contacts.Count; viewTimer = 0f; }\n                    }\n                    if (GameInput.BackDown()) Screen = PhoneScreen.Home;\n                    viewTimer += dt;\n                    if (contactIndex == 0 && viewTimer > 1.5f) FirstContactSeen = true;\n                    break;\n\n                case PhoneScreen.Messages:\n                    TickMessages(dt);\n                    break;\n\n                case PhoneScreen.Camera:\n                    if (GameInput.BackDown()) { Screen = PhoneScreen.Home; break; }\n                    if (GameInput.LeftKeyDown() || GameInput.RightKeyDown()) { cameraFlash = !cameraFlash; Notice(cameraFlash ? Loc.L(\"Flash ON.\", \"闪光灯：开。\") : Loc.L(\"Flash OFF.\", \"闪光灯：关。\")); }\n                    if (GameInput.LeftDown()) Shutter();\n                    break;\n\n                case PhoneScreen.Search:\n                    TickSearch(dt);\n                    break;\n            }\n        }\n\n        // ------------------------------------------------------------------ camera\n        void EnterCamera()\n        {\n            Screen = PhoneScreen.Camera;\n            targets = FindObjectsByType<PhotoTarget>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);\n        }\n\n        /// <summary>The ray through the middle of the phone's screen (the viewfinder).</summary>\n        Ray AimRay()\n        {\n            Camera cam = Camera.main;\n            if (cam == null || screenRT == null) return new Ray(transform.position, transform.forward);\n            Vector3 world = screenRT.TransformPoint(screenRT.rect.center);\n            Vector2 sp = RectTransformUtility.WorldToScreenPoint(null, world);\n            return cam.ScreenPointToRay(sp);\n        }\n\n        PhotoTarget FindAimed()\n        {\n            if (targets == null) return null;\n            Ray ray = AimRay();\n            PhotoTarget best = null;\n            float bestA = 999f;\n            foreach (PhotoTarget t in targets)\n            {\n                if (t == null || !t.isActiveAndEnabled) continue;\n                Vector3 to = t.transform.position - ray.origin;\n                float d = to.magnitude;\n                if (d > t.range || d < 0.1f) continue;\n                float a = Vector3.Angle(ray.direction, to);\n                if (a > 9f || a >= bestA) continue;\n                bool blocked = false;\n                foreach (RaycastHit h in Physics.RaycastAll(ray.origin, to / d, d - 0.15f, ~0, QueryTriggerInteraction.Ignore))\n                {\n                    if (h.transform.IsChildOf(transform) || h.transform.IsChildOf(t.transform)) continue;\n                    blocked = true;\n                    break;\n                }\n                if (blocked) continue;\n                best = t;\n                bestA = a;\n            }\n            return best;\n        }\n\n        void Shutter()\n        {\n            sfx.PlayOneShot(AudioSynth.Click(), 0.9f);\n            if (cameraFlash) { shutterFlash = 1f; glowBoost = 1f; }\n            PhotoTarget t = aimed;\n            if (t != null && !t.taken)\n            {\n                t.taken = true;\n                taken.Add(t.label);\n                Notice(Loc.L(\"Saved to Photos.\", \"已存入相册。\"));\n            }\n            else if (t != null) Notice(Loc.L(\"Already have that one.\", \"这张已经拍过了。\"));\n            else Notice(Loc.L(\"Nothing worth keeping in frame.\", \"取景框里没有值得留下的东西。\"));\n            if (onShutter != null) onShutter(t, cameraFlash);\n        }\n\n        // ------------------------------------------------------------------ search\n        void TickSearch(float dt)\n        {\n            if (GameInput.BackDown() && !searching) { Screen = PhoneScreen.Home; return; }\n            int n = searchWords.Count;\n            if (!searching)\n            {\n                if (n > 0)\n                {\n                    if (GameInput.LeftKeyDown()) { searchIndex = (searchIndex + n - 1) % n; }\n                    if (GameInput.RightKeyDown()) { searchIndex = (searchIndex + 1) % n; }\n                    if (GameInput.LeftDown()) { searching = true; searchProgress = 0f; searchResult = \"\"; LastSearchDone = false; }\n                }\n                return;\n            }\n            if (GameInput.LeftHeld()) searchProgress = Mathf.Min(1f, searchProgress + dt / Mathf.Max(0.1f, searchSeconds));\n            if (searchProgress >= 1f)\n            {\n                searching = false;\n                string w = searchWords[Mathf.Clamp(searchIndex, 0, n - 1)];\n                searchResult = searchFunc != null ? searchFunc(w) : null;\n                if (string.IsNullOrEmpty(searchResult)) searchResult = Loc.L(\"0 results.\", \"0 条结果。\");\n                LastSearchDone = true;\n                sfx.PlayOneShot(AudioSynth.Ping(), 0.4f);\n                if (onSearched != null) onSearched(w);\n            }\n        }\n\n        void OpenUnlockedApp()\n        {\n            viewTimer = 0f;\n            if (openApp == AppPhotos) { Screen = PhoneScreen.Photos; photoIndex = 0; }\n            else if (openApp == AppContacts) { Screen = PhoneScreen.Contacts; contactIndex = 0; }\n            else if (openApp == AppMessages) Screen = PhoneScreen.Messages;\n            else if (openApp == AppCamera) EnterCamera();\n            else if (openApp == AppSearch) { Screen = PhoneScreen.Search; searchIndex = Mathf.Max(0, searchWords.Count - 1); }\n            else { Screen = PhoneScreen.Home; Notice(Loc.L(\"This app doesn't open. Yet.\", \"这个 App 打不开。还打不开。\")); }\n        }\n\n        void TickMessages(float dt)\n        {\n            if (GameInput.BackDown() && !forceRaise) { Screen = PhoneScreen.Home; return; }\n            // read the first unread message\n            foreach (PhoneMsg m in msgs)\n            {\n                if (m.mine || m.shown >= m.text.Length) continue;\n                m.shown = Mathf.Min(m.text.Length, m.shown + readCharsPerSecond * dt);\n                return;\n            }\n            if (task == null) return;\n            if (!typing)\n            {\n                int n = task.options != null ? task.options.Length : 0;\n                if (n > 0)\n                {\n                    if (GameInput.LeftKeyDown()) choice = (choice + n - 1) % n;\n                    if (GameInput.RightKeyDown()) choice = (choice + 1) % n;\n                }\n                if (GameInput.LeftDown() && n > 0)\n                {\n                    if (task.correct >= 0 && choice != task.correct) { Notice(Loc.T(task.wrongText)); return; }\n                    if (task.check != null)\n                    {\n                        string err = task.check(choice);\n                        if (!string.IsNullOrEmpty(err)) { Notice(err); return; }\n                    }\n                    typing = true;\n                    typeProgress = 0f;\n                }\n                return;\n            }\n            if (GameInput.LeftHeld()) typeProgress = Mathf.Min(1f, typeProgress + dt / Mathf.Max(0.1f, task.typeSeconds));\n            if (typeProgress >= 1f)\n            {\n                PhoneTask done = task;\n                int c = choice;\n                string sent = done.forward ? done.sendText : done.options[c];\n                msgs.Add(new PhoneMsg { from = \"me\", text = sent, mine = true, shown = sent.Length });\n                task = null;\n                typing = false;\n                Notice(Loc.L(\"Delivered.\", \"已送达。\"));\n                if (done.onDone != null) done.onDone(c);\n            }\n        }\n\n        void CheckCode()\n        {\n            if (Screen == PhoneScreen.Lock)\n            {\n                if (entry == phoneCode) { Screen = PhoneScreen.Booting; loadT = 0f; Notice(Loc.L(\"Don't put it down.\", \"别放下手机。\")); }\n                else Notice(Loc.L(\"Wrong passcode.\", \"密码错误。\"));\n            }\n            else\n            {\n                string code = (openApp >= 0 && openApp < appCodes.Length) ? appCodes[openApp] : \"\";\n                if (!string.IsNullOrEmpty(code) && entry == code) { Screen = PhoneScreen.AppLoading; loadT = 0f; Notice(Loc.L(\"Don't put it down.\", \"别放下手机。\")); }\n                else Notice(Loc.L(\"Wrong passcode.\", \"密码错误。\"));\n            }\n            entry = \"\";\n        }\n\n        void Notice(string s) { notice = s; noticeTimer = 2.5f; }\n\n        // ------------------------------------------------------------------ drawing\n        void Refresh()\n        {\n            bool isLock = Screen == PhoneScreen.Lock || Screen == PhoneScreen.AppLock;\n            bool isLoad = Screen == PhoneScreen.Booting || Screen == PhoneScreen.AppLoading;\n            lockRoot.SetActive(isLock);\n            loadRoot.SetActive(isLoad);\n            homeRoot.SetActive(Screen == PhoneScreen.Home);\n            photosRoot.SetActive(Screen == PhoneScreen.Photos);\n            msgRoot.SetActive(Screen == PhoneScreen.Messages);\n            contactsRoot.SetActive(Screen == PhoneScreen.Contacts);\n            bool cam = Screen == PhoneScreen.Camera;\n            cameraRoot.SetActive(cam);\n            searchRoot.SetActive(Screen == PhoneScreen.Search);\n            // the camera turns the screen into glass: you see the room through it\n            screenBg.color = cam ? new Color(1f, 1f, 1f, 0.03f) : ScreenColor;\n            panelBg.color = cam ? new Color(0f, 0f, 0f, 0f) : new Color(0.05f, 0.05f, 0.06f);\n            crackImg.enabled = !cam;\n            if (shutterFlash > 0f) shutterFlash = Mathf.Max(0f, shutterFlash - Time.deltaTime * 2.5f);\n            whiteFlash.color = new Color(1f, 1f, 1f, shutterFlash * 0.9f);\n\n            string hint = \"\";\n            if (isLock)\n            {\n                lockTitle.text = Screen == PhoneScreen.Lock ? Loc.L(\"Enter passcode\", \"输入密码\") : Loc.L(AppName(openApp) + \" is locked\\nEnter passcode\", AppName(openApp) + \" 已上锁\\n输入密码\");\n                string dots = \"\";\n                for (int i = 0; i < 4; i++) dots += (i < entry.Length ? \"*\" : \"_\") + (i < 3 ? \"  \" : \"\");\n                lockDots.text = dots;\n                lockHint.text = Screen == PhoneScreen.Lock ? Loc.T(phoneHint) : HintFor(openApp);\n                lockNoteRoot.SetActive(Screen == PhoneScreen.Lock);\n                lockNote.text = LockNotificationText();\n                UIFactory.FitFont(lockNote, lockNote.text);\n                hint = Screen == PhoneScreen.Lock ? Loc.L(\"Number keys: type    Backspace: delete\", \"数字键：输入    Backspace：删除\") : Loc.L(\"Number keys: type    Q: back\", \"数字键：输入    Q：返回\");\n            }\n            else if (isLoad)\n            {\n                float total = Screen == PhoneScreen.Booting ? bootSeconds : appLoadSeconds[openApp];\n                float p = Mathf.Clamp01(loadT / Mathf.Max(0.1f, total));\n                loadTitle.text = Screen == PhoneScreen.Booting ? Loc.L(\"STARTING UP\", \"正在开机\") : Loc.L(\"OPENING \" + AppName(openApp).ToUpper(), \"正在打开 \" + AppName(openApp));\n                loadPercent.text = Mathf.FloorToInt(p * 100f) + \"%\";\n                loadFill.anchorMax = new Vector2(p, 1f);\n                hint = Loc.L(\"Keep holding Right Mouse.\", \"按住鼠标右键别松开。\");\n            }\n            else if (Screen == PhoneScreen.Home)\n            {\n                homeClock.text = phoneClock;\n                int unread = UnreadCount;\n                for (int i = 0; i < appTiles.Length; i++)\n                {\n                    int app = HomeOrder[i];\n                    bool on = i == selectedApp;\n                    appTiles[i].color = on ? new Color(0.20f, 0.20f, 0.22f) : new Color(0f, 0f, 0f, 0.12f);\n                    appLabels[i].color = on ? new Color(0.98f, 0.9f, 0.7f) : Ink;\n                    string extra = !IsUnlocked(app) ? Loc.L(\"\\n(locked)\", \"\\n（已上锁）\") : (app == AppMessages && unread > 0 ? Loc.L(\"\\n(\" + unread + \" new)\", \"\\n（\" + unread + \" 条新）\") : \"\");\n                    appLabels[i].text = AppName(app) + extra;\n                }\n                hint = Loc.L(\"A / D: choose app    Left Mouse: open\", \"A / D：选择    鼠标左键：打开\");\n            }\n            else if (Screen == PhoneScreen.Photos)\n            {\n                bool snap = photoIndex >= BasePhotos;\n                for (int i = 0; i < photos.Length; i++) photos[i].SetActive(!snap && i == photoIndex);\n                snapshot.SetActive(snap);\n                if (snap)\n                {\n                    string label = Loc.T(taken[Mathf.Clamp(photoIndex - BasePhotos, 0, taken.Count - 1)]);\n                    snapLabel.text = label;\n                    photoCaption.text = Loc.L(\"Today. \", \"今天。\") + label;\n                }\n                else photoCaption.text = photoIndex < photoCaptions.Length ? Loc.T(photoCaptions[photoIndex]) : \"\";\n                UIFactory.FitFont(photoCaption, photoCaption.text);\n                photoCounter.text = (photoIndex + 1) + \" / \" + PhotoCount;\n                hint = Loc.L(\"A / D: browse    Q: back\", \"A / D：翻看    Q：返回\");\n            }\n            else if (Screen == PhoneScreen.Contacts)\n            {\n                if (contacts.Count > 0)\n                {\n                    PhoneContact c = contacts[Mathf.Clamp(contactIndex, 0, contacts.Count - 1)];\n                    contactName.text = Loc.T(c.name);\n                    contactYear.text = Loc.L(\"saved in \" + c.year, \"存于 \" + c.year + \" 年\");\n                    contactNote.text = Loc.T(c.note);\n                    UIFactory.FitFont(contactNote, contactNote.text);\n                    UIFactory.FitFont(contactName, contactName.text, 14);\n                    contactCounter.text = (contactIndex + 1) + \" / \" + contacts.Count;\n                }\n                hint = Loc.L(\"A / D: browse    Q: back\", \"A / D：翻看    Q：返回\");\n            }\n            else if (Screen == PhoneScreen.Messages)\n            {\n                hint = RefreshMessages();\n            }\n            else if (cam)\n            {\n                if (IsUp) aimed = FindAimed();\n                bool has = aimed != null;\n                camLabel.text = has ? (aimed.taken ? Loc.L(\"(already taken)  \", \"（已拍过）  \") : \"\") + Loc.T(aimed.label) : Loc.L(\"...\", \"……\");\n                Color rc = has && !aimed.taken ? new Color(1f, 0.85f, 0.35f) : new Color(1f, 1f, 1f, 0.7f);\n                foreach (Image r in reticle) r.color = rc;\n                camFlashText.text = cameraFlash ? Loc.L(\"FLASH  ON\", \"闪光灯  开\") : Loc.L(\"FLASH  OFF\", \"闪光灯  关\");\n                camFlashText.color = cameraFlash ? new Color(1f, 0.55f, 0.35f) : new Color(0.8f, 0.85f, 0.8f);\n                camCount.text = Loc.L(taken.Count + \" taken\", \"已拍 \" + taken.Count + \" 张\");\n                hint = Loc.L(\"Aim the middle    Left Mouse: shutter    A / D: flash    Q: back\", \"对准中间    左键：拍照    A / D：闪光灯    Q：返回\");\n            }\n            else if (Screen == PhoneScreen.Search)\n            {\n                int n = searchWords.Count;\n                string w = n > 0 ? Loc.T(searchWords[Mathf.Clamp(searchIndex, 0, n - 1)]) : Loc.L(\"(no words yet - read something)\", \"（还没有搜索词——先去读点什么）\");\n                searchQuery.text = n > 1 ? \"<  \" + w + \"  >\" : w;\n                searchBarRoot.SetActive(searching);\n                searchFill.anchorMax = new Vector2(searchProgress, 1f);\n                searchResultText.text = searching ? Loc.L(\"searching...\", \"搜索中……\") : searchResult;\n                UIFactory.FitFont(searchResultText, searchResultText.text);\n                searchHeader.text = AppName(AppSearch) + Loc.L(\"   (\" + n + \" words)\", \"   （\" + n + \" 个词）\");\n                hint = n == 0 ? Loc.L(\"Q: back\", \"Q：返回\") : (searching ? Loc.L(\"Keep HOLDING Left Mouse\", \"按住鼠标左键别松\") : Loc.L(\"A / D: word    HOLD Left Mouse: search    Q: back\", \"A / D：选词    按住左键：搜索    Q：返回\"));\n            }\n            if (silentAvailable && noticeTimer <= 0f && !cam) hint = Loc.L(\"M: silent mode\", \"M：静音模式\") + (string.IsNullOrEmpty(hint) ? \"\" : \"    \" + hint);\n            footer.text = noticeTimer > 0f ? notice : hint;\n            UIFactory.FitFont(footer, footer.text);\n            // the little bell, top right, on every screen\n            Color bell = silent ? new Color(0.75f, 0.2f, 0.15f) : (cam ? new Color(1f, 1f, 1f, 0.8f) : new Color(0.3f, 0.3f, 0.32f));\n            bellBody.color = bellClapper.color = bell;\n            bellSlash.enabled = silent;\n            bellText.text = silent ? Loc.L(\"SILENT\", \"静音\") : \"\";\n            footer.color = noticeTimer > 0f ? (cam ? new Color(1f, 0.6f, 0.45f) : new Color(0.75f, 0.2f, 0.15f)) : (cam ? new Color(0.92f, 0.92f, 0.9f) : new Color(0.35f, 0.35f, 0.37f));\n        }\n\n        string LockNotificationText()\n        {\n            foreach (PhoneMsg m in msgs)\n            {\n                if (m.mine || m.shown >= m.text.Length) continue;\n                int n = UnreadCount;\n                int maxChars = Loc.Chinese ? 30 : 46;\n                string preview = m.text.Length > maxChars ? m.text.Substring(0, maxChars) + \"...\" : m.text;\n                return Loc.L(n + (n == 1 ? \" new message\\n\" : \" new messages\\n\"), n + \" 条新信息\\n\") + Loc.T(m.from) + \": \" + preview;\n            }\n            return Loc.T(lockNotification);\n        }\n\n        string RefreshMessages()\n        {\n            int unread = UnreadCount;\n            msgHeader.text = AppName(AppMessages) + (unread > 0 ? Loc.L(\"   (\" + unread + \" new)\", \"   （\" + unread + \" 条新）\") : \"\");\n\n            // show messages up to the one being read\n            int last = msgs.Count - 1;\n            for (int i = 0; i < msgs.Count; i++)\n            {\n                if (!msgs[i].mine && msgs[i].shown < msgs[i].text.Length) { last = i; break; }\n            }\n            int first = Mathf.Max(0, last - Bubbles + 1);\n            for (int s = 0; s < Bubbles; s++)\n            {\n                int i = first + s;\n                bool on = i <= last && i < msgs.Count;\n                bubbleBg[s].gameObject.SetActive(on);\n                if (!on) continue;\n                PhoneMsg m = msgs[i];\n                int shown = Mathf.FloorToInt(m.shown);\n                bool reading = !m.mine && shown < m.text.Length;\n                bubbleFrom[s].text = m.mine ? Loc.L(\"me\", \"我\") : Loc.T(m.from);\n                UIFactory.FitFont(bubbleText[s], m.text + \"_\");   // sized by the whole message, so it never jumps while reading\n                bubbleText[s].text = (reading ? m.text.Substring(0, shown) + \"_\" : m.text);\n                bubbleBg[s].color = m.mine ? new Color(0.22f, 0.24f, 0.26f, 0.95f) : new Color(0f, 0f, 0f, 0.09f);\n                bubbleText[s].color = m.mine ? new Color(0.95f, 0.92f, 0.82f) : Ink;\n                bubbleFrom[s].color = m.mine ? new Color(0.9f, 0.75f, 0.5f) : new Color(0.45f, 0.3f, 0.2f);\n                bubbleFrom[s].alignment = m.mine ? TextAnchor.UpperRight : TextAnchor.UpperLeft;\n                bubbleText[s].alignment = m.mine ? TextAnchor.UpperRight : TextAnchor.UpperLeft;\n            }\n\n            bool showTask = task != null && unread == 0;\n            taskRoot.SetActive(showTask);\n            if (unread > 0) return Loc.L(\"reading...  (keep the phone up)\", \"正在读……（别放下手机）\");\n            if (!showTask) return Loc.L(\"Q: back\", \"Q：返回\");\n            typeBarRoot.SetActive(typing);\n            if (!typing)\n            {\n                taskHeader.text = Loc.T(task.header);\n                string opt = task.options != null && task.options.Length > 0 ? Loc.T(task.options[Mathf.Clamp(choice, 0, task.options.Length - 1)]) : \"\";\n                taskBody.text = \"<  \" + opt + \"  >\";\n                UIFactory.FitFont(taskBody, taskBody.text);\n                taskHelp.text = Loc.L(\"A / D: choose    Left Mouse: select\", \"A / D：选择    鼠标左键：确定\");\n                return \"\";\n            }\n            string text = task.forward ? task.sendText : task.options[choice];\n            taskHeader.text = task.forward ? Loc.L(\"To: \", \"发给：\") + Loc.T(task.options[choice]) : (string.IsNullOrEmpty(task.toLabel) ? Loc.L(\"Reply\", \"回复\") : Loc.T(task.toLabel));\n            int n = Mathf.FloorToInt(typeProgress * text.Length);\n            UIFactory.FitFont(taskBody, text + \"_\");\n            taskBody.text = text.Substring(0, Mathf.Clamp(n, 0, text.Length)) + \"_\";\n            typeFill.anchorMax = new Vector2(typeProgress, 1f);\n            taskHelp.text = Loc.L(\"HOLD Left Mouse: type & send\", \"按住鼠标左键：输入并发送\");\n            return \"\";\n        }\n\n        // ------------------------------------------------------------------ UI\n        /// <summary>The phone's own notification: a dark banner with the sender and the first words, plus \"hold right mouse\".</summary>\n        void BuildNotification(Transform canvasRoot)\n        {\n            notif = UIFactory.Rect(\"Notification\", canvasRoot, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, NotifHidden), new Vector2(480f, 104f));\n            UIFactory.AddImage(notif, new Color(0.06f, 0.06f, 0.07f, 0.96f));\n            UIFactory.AddImage(UIFactory.Rect(\"Edge\", notif, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 3f)), new Color(0.95f, 0.86f, 0.62f));\n            RectTransform icon = UIFactory.TopLeft(\"Icon\", notif, 16f, 18f, 46f, 46f);\n            UIFactory.AddImage(icon, new Color(0.95f, 0.86f, 0.62f));\n            UIFactory.AddText(UIFactory.Stretch(\"Glyph\", icon), \"...\", 26, new Color(0.1f, 0.1f, 0.12f), TextAnchor.MiddleCenter).fontStyle = FontStyle.Bold;\n            Text app = UIFactory.AddText(UIFactory.TopLeft(\"App\", notif, 76f, 10f, 300f, 22f), Loc.L(\"MESSAGES  -  now\", \"信息  -  刚刚\"), 15, new Color(0.65f, 0.65f, 0.68f), TextAnchor.UpperLeft);\n            app.fontStyle = FontStyle.Bold;\n            notifCount = UIFactory.AddText(UIFactory.TopLeft(\"Count\", notif, 230f, 10f, 234f, 22f), \"\", 15, new Color(0.95f, 0.86f, 0.62f), TextAnchor.UpperRight);\n            notifFrom = UIFactory.AddText(UIFactory.TopLeft(\"From\", notif, 76f, 32f, 392f, 24f), \"\", 18, Color.white, TextAnchor.UpperLeft);\n            notifFrom.fontStyle = FontStyle.Bold;\n            notifText = UIFactory.AddText(UIFactory.TopLeft(\"Text\", notif, 76f, 56f, 392f, 24f), \"\", 17, new Color(0.85f, 0.85f, 0.85f), TextAnchor.UpperLeft);\n            notifText.horizontalOverflow = HorizontalWrapMode.Overflow;\n            UIFactory.AddText(UIFactory.TopLeft(\"Hint\", notif, 76f, 80f, 392f, 20f), Loc.L(\"HOLD RIGHT MOUSE to read\", \"按住鼠标右键查看\"), 14, new Color(0.95f, 0.86f, 0.62f, 0.8f), TextAnchor.UpperLeft);\n        }\n\n        void BuildUI()\n        {\n            Canvas canvas = UIFactory.MakeCanvas(\"PhoneCanvas\", 30);\n            canvas.transform.SetParent(transform, false);\n            canvas.pixelPerfect = true;\n            // bigger phone = a larger canvas scale factor, so glyphs are rendered at their real on-screen size\n            canvas.GetComponent<CanvasScaler>().referenceResolution = new Vector2(1920f, 1080f) / PanelScale;\n            phoneCanvas = canvas;\n\n            panel = UIFactory.Rect(\"Phone\", canvas.transform, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f),\n                                   new Vector2(0f, HiddenY), new Vector2(440f, 780f));\n            BuildNotification(canvas.transform);\n            panelBg = UIFactory.AddImage(panel, new Color(0.05f, 0.05f, 0.06f));\n            // the bezel as four bars, so the camera can make the glass see-through and the frame stays\n            Color bz = new Color(0.05f, 0.05f, 0.06f);\n            UIFactory.AddImage(UIFactory.Rect(\"Bezel_T\", panel, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 18f)), bz);\n            UIFactory.AddImage(UIFactory.Rect(\"Bezel_B\", panel, new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(0.5f, 0f), Vector2.zero, new Vector2(0f, 18f)), bz);\n            UIFactory.AddImage(UIFactory.Rect(\"Bezel_L\", panel, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, new Vector2(18f, 0f)), bz);\n            UIFactory.AddImage(UIFactory.Rect(\"Bezel_R\", panel, new Vector2(1f, 0f), new Vector2(1f, 1f), new Vector2(1f, 0.5f), Vector2.zero, new Vector2(18f, 0f)), bz);\n            RectTransform screen = UIFactory.Rect(\"Screen\", panel, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-36f, -36f));\n            screen.gameObject.AddComponent<RectMask2D>();   // nothing (the crack, long texts) draws outside the glass\n            screenBg = UIFactory.AddImage(screen, ScreenColor);\n            screenRT = screen;\n\n            // a crack across the screen protector - someone else's damage\n            RectTransform crack = UIFactory.Centered(\"Crack\", screen, 40f, 150f, 380f, 2f);\n            crack.localRotation = Quaternion.Euler(0f, 0f, 38f);\n            crackImg = UIFactory.AddImage(crack, new Color(0f, 0f, 0f, 0.18f));\n\n            // --- passcode (phone lock + app lock)\n            lockRoot = UIFactory.Stretch(\"Passcode\", screen).gameObject;\n            RectTransform note = UIFactory.TopLeft(\"Notification\", lockRoot.transform, 14f, 14f, 376f, 78f);\n            UIFactory.AddImage(note, new Color(0f, 0f, 0f, 0.12f));\n            lockNote = UIFactory.AddText(UIFactory.Rect(\"T\", note, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-20f, -10f)), \"\", 17, Ink, TextAnchor.MiddleLeft);\n            lockNoteRoot = note.gameObject;\n            lockTitle = UIFactory.AddText(UIFactory.TopLeft(\"Title\", lockRoot.transform, 18f, 100f, 368f, 70f), \"\", 26, Ink, TextAnchor.MiddleCenter);\n            lockDots = UIFactory.AddText(UIFactory.TopLeft(\"Dots\", lockRoot.transform, 18f, 168f, 368f, 50f), \"\", 44, Ink, TextAnchor.MiddleCenter);\n            lockHint = UIFactory.AddText(UIFactory.TopLeft(\"Hint\", lockRoot.transform, 18f, 222f, 368f, 34f), \"\", 18, new Color(0.55f, 0.3f, 0.15f), TextAnchor.MiddleCenter);\n            string[] keys = { \"1\", \"2\", \"3\", \"4\", \"5\", \"6\", \"7\", \"8\", \"9\", \"\", \"0\", \"\" };\n            for (int i = 0; i < keys.Length; i++)\n            {\n                if (keys[i] == \"\") continue;\n                int col = i % 3, row = i / 3;\n                RectTransform k = UIFactory.TopLeft(\"Key\" + keys[i], lockRoot.transform, 52f + col * 104f, 272f + row * 84f, 88f, 70f);\n                UIFactory.AddImage(k, new Color(0f, 0f, 0f, 0.08f));\n                UIFactory.AddText(UIFactory.Stretch(\"T\", k), keys[i], 32, Ink, TextAnchor.MiddleCenter);\n            }\n\n            // --- loading (boot + app)\n            loadRoot = UIFactory.Stretch(\"Loading\", screen).gameObject;\n            UIFactory.AddImage((RectTransform)loadRoot.transform, new Color(0.04f, 0.04f, 0.05f));\n            Color dim = new Color(0.8f, 0.78f, 0.72f);\n            loadTitle = UIFactory.AddText(UIFactory.TopLeft(\"Title\", loadRoot.transform, 18f, 260f, 368f, 50f), \"\", 26, dim, TextAnchor.MiddleCenter);\n            RectTransform bar = UIFactory.TopLeft(\"Bar\", loadRoot.transform, 60f, 330f, 284f, 10f);\n            UIFactory.AddImage(bar, new Color(1f, 1f, 1f, 0.15f));\n            loadFill = UIFactory.Rect(\"Fill\", bar, Vector2.zero, new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero);\n            UIFactory.AddImage(loadFill, new Color(0.95f, 0.75f, 0.45f));\n            loadPercent = UIFactory.AddText(UIFactory.TopLeft(\"Percent\", loadRoot.transform, 18f, 350f, 368f, 40f), \"\", 22, dim, TextAnchor.MiddleCenter);\n\n            // --- home\n            homeRoot = UIFactory.Stretch(\"Home\", screen).gameObject;\n            homeClock = UIFactory.AddText(UIFactory.TopLeft(\"Clock\", homeRoot.transform, 18f, 40f, 368f, 100f), \"\", 72, Ink, TextAnchor.MiddleCenter);\n            appTiles = new Image[appNames.Length];\n            appLabels = new Text[appNames.Length];\n            for (int i = 0; i < HomeOrder.Length; i++)\n            {\n                int app = HomeOrder[i];\n                int col = i % 3, row = i / 3;\n                RectTransform t = UIFactory.TopLeft(\"App_\" + appNames[app], homeRoot.transform, 22f + col * 122f, 200f + row * 150f, 110f, 130f);\n                appTiles[i] = UIFactory.AddImage(t, Color.clear);\n                RectTransform icon = UIFactory.TopLeft(\"Icon\", t, 25f, 12f, 60f, 60f);\n                UIFactory.AddImage(icon, Color.HSVToRGB(app * 0.17f, 0.35f, 0.65f));\n                UIFactory.AddText(UIFactory.Stretch(\"Order\", icon), (i + 1).ToString(), 22, new Color(1f, 1f, 1f, 0.75f), TextAnchor.MiddleCenter);\n                appLabels[i] = UIFactory.AddText(UIFactory.TopLeft(\"Label\", t, 0f, 76f, 110f, 54f), AppName(app), 16, Ink, TextAnchor.UpperCenter);\n            }\n\n            // --- photos\n            photosRoot = UIFactory.Stretch(\"Photos\", screen).gameObject;\n            RectTransform frame = UIFactory.TopLeft(\"Frame\", photosRoot.transform, 18f, 40f, 368f, 320f);\n            UIFactory.AddImage(frame, new Color(0.1f, 0.1f, 0.1f));\n            photos = new GameObject[6];\n            photos[0] = PhotoClass(frame, \"Photo_Class2009\", new Color(0.55f, 0.58f, 0.6f), new Color(0.18f, 0.18f, 0.2f), new Color(0.25f, 0.27f, 0.32f), null);\n            photos[1] = PhotoHand(frame);\n            photos[2] = PhotoSneeze(frame);\n            photos[3] = PhotoTriangle(frame);\n            photos[4] = PhotoNight(frame);\n            photos[5] = PhotoClass(frame, \"Photo_Class1979\", new Color(0.62f, 0.52f, 0.38f), new Color(0.3f, 0.22f, 0.15f), new Color(0.4f, 0.31f, 0.21f), Loc.L(\"VOSS\", \"沃斯\"));\n            snapshot = UIFactory.Stretch(\"Photo_Snapshot\", frame).gameObject;\n            Box(snapshot.transform, 0f, 0f, 368f, 320f, new Color(0.32f, 0.33f, 0.3f));\n            Box(snapshot.transform, 0f, 250f, 368f, 70f, new Color(0.22f, 0.22f, 0.2f));\n            Box(snapshot.transform, 84f, 60f, 200f, 150f, new Color(0.8f, 0.78f, 0.7f));\n            snapLabel = UIFactory.AddText(UIFactory.TopLeft(\"Label\", snapshot.transform, 90f, 66f, 188f, 138f), \"\", 20, Ink, TextAnchor.MiddleCenter);\n            snapLabel.fontStyle = FontStyle.Bold;\n            snapshot.SetActive(false);\n            photoCaption = UIFactory.AddText(UIFactory.TopLeft(\"Caption\", photosRoot.transform, 18f, 375f, 368f, 140f), \"\", 18, Ink, TextAnchor.UpperLeft);\n            photoCounter = UIFactory.AddText(UIFactory.TopLeft(\"Counter\", photosRoot.transform, 18f, 8f, 368f, 30f), \"\", 16, Ink, TextAnchor.MiddleRight);\n\n            // --- messages\n            msgRoot = UIFactory.Stretch(\"Messages\", screen).gameObject;\n            msgHeader = UIFactory.AddText(UIFactory.TopLeft(\"Header\", msgRoot.transform, 18f, 10f, 368f, 34f), AppName(AppMessages), 22, Ink, TextAnchor.MiddleLeft);\n            msgHeader.fontStyle = FontStyle.Bold;\n            UIFactory.AddImage(UIFactory.TopLeft(\"Divider\", msgRoot.transform, 18f, 46f, 368f, 2f), new Color(0f, 0f, 0f, 0.25f));\n            bubbleBg = new Image[Bubbles];\n            bubbleFrom = new Text[Bubbles];\n            bubbleText = new Text[Bubbles];\n            for (int i = 0; i < Bubbles; i++)\n            {\n                RectTransform b = UIFactory.TopLeft(\"Bubble\" + i, msgRoot.transform, 14f, 56f + i * 112f, 376f, 106f);\n                bubbleBg[i] = UIFactory.AddImage(b, new Color(0f, 0f, 0f, 0.09f));\n                bubbleFrom[i] = UIFactory.AddText(UIFactory.TopLeft(\"From\", b, 10f, 4f, 356f, 22f), \"\", 15, Ink, TextAnchor.UpperLeft);\n                bubbleFrom[i].fontStyle = FontStyle.Bold;\n                bubbleText[i] = UIFactory.AddText(UIFactory.TopLeft(\"Text\", b, 10f, 26f, 356f, 78f), \"\", 17, Ink, TextAnchor.UpperLeft);\n            }\n            taskRoot = UIFactory.TopLeft(\"Task\", msgRoot.transform, 14f, 504f, 376f, 160f).gameObject;\n            UIFactory.AddImage((RectTransform)taskRoot.transform, new Color(0.2f, 0.12f, 0.08f, 0.12f));\n            taskHeader = UIFactory.AddText(UIFactory.TopLeft(\"Header\", taskRoot.transform, 10f, 6f, 356f, 26f), \"\", 17, new Color(0.45f, 0.25f, 0.12f), TextAnchor.UpperLeft);\n            taskHeader.fontStyle = FontStyle.Bold;\n            taskBody = UIFactory.AddText(UIFactory.TopLeft(\"Body\", taskRoot.transform, 10f, 34f, 356f, 80f), \"\", 19, Ink, TextAnchor.UpperCenter);\n            typeBarRoot = UIFactory.TopLeft(\"TypeBar\", taskRoot.transform, 10f, 118f, 356f, 8f).gameObject;\n            UIFactory.AddImage((RectTransform)typeBarRoot.transform, new Color(0f, 0f, 0f, 0.15f));\n            typeFill = UIFactory.Rect(\"Fill\", typeBarRoot.transform, Vector2.zero, new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero);\n            UIFactory.AddImage(typeFill, new Color(0.85f, 0.45f, 0.15f));\n            taskHelp = UIFactory.AddText(UIFactory.TopLeft(\"Help\", taskRoot.transform, 10f, 132f, 356f, 24f), \"\", 14, new Color(0.35f, 0.35f, 0.37f), TextAnchor.UpperCenter);\n            taskRoot.SetActive(false);\n\n            // --- contacts\n            contactsRoot = UIFactory.Stretch(\"Contacts\", screen).gameObject;\n            UIFactory.AddText(UIFactory.TopLeft(\"Header\", contactsRoot.transform, 18f, 10f, 368f, 34f), AppName(AppContacts), 22, Ink, TextAnchor.MiddleLeft).fontStyle = FontStyle.Bold;\n            contactCounter = UIFactory.AddText(UIFactory.TopLeft(\"Counter\", contactsRoot.transform, 18f, 10f, 368f, 34f), \"\", 16, Ink, TextAnchor.MiddleRight);\n            RectTransform card = UIFactory.TopLeft(\"Card\", contactsRoot.transform, 18f, 70f, 368f, 420f);\n            UIFactory.AddImage(card, new Color(0f, 0f, 0f, 0.08f));\n            RectTransform avatar = UIFactory.TopLeft(\"Avatar\", card, 134f, 24f, 100f, 100f);\n            UIFactory.AddImage(avatar, new Color(0.6f, 0.58f, 0.52f));\n            UIFactory.AddText(UIFactory.Stretch(\"Q\", avatar), \"?\", 54, new Color(0.95f, 0.92f, 0.85f), TextAnchor.MiddleCenter);\n            contactName = UIFactory.AddText(UIFactory.TopLeft(\"Name\", card, 10f, 140f, 348f, 44f), \"\", 25, Ink, TextAnchor.MiddleCenter);\n            contactName.fontStyle = FontStyle.Bold;\n            contactYear = UIFactory.AddText(UIFactory.TopLeft(\"Year\", card, 10f, 186f, 348f, 28f), \"\", 16, new Color(0.45f, 0.3f, 0.2f), TextAnchor.MiddleCenter);\n            contactNote = UIFactory.AddText(UIFactory.TopLeft(\"Note\", card, 20f, 236f, 328f, 160f), \"\", 19, Ink, TextAnchor.UpperCenter);\n\n            // --- camera: a see-through viewfinder\n            cameraRoot = UIFactory.Stretch(\"Camera\", screen).gameObject;\n            Color w = new Color(1f, 1f, 1f, 0.8f);\n            for (int i = 0; i < 4; i++)\n            {\n                Vector2 a = new Vector2(i % 2, i / 2);\n                RectTransform c = UIFactory.Rect(\"Corner\" + i, cameraRoot.transform, a, a, a, new Vector2(a.x > 0 ? -24f : 24f, a.y > 0 ? -60f : 120f), new Vector2(46f, 46f));\n                UIFactory.AddImage(UIFactory.Rect(\"H\", c, a, a, a, Vector2.zero, new Vector2(46f, 4f)), w);\n                UIFactory.AddImage(UIFactory.Rect(\"V\", c, a, a, a, Vector2.zero, new Vector2(4f, 46f)), w);\n            }\n            reticle = new Image[4];\n            reticle[0] = UIFactory.AddImage(UIFactory.Centered(\"Ret_L\", cameraRoot.transform, -26f, 0f, 22f, 3f), w);\n            reticle[1] = UIFactory.AddImage(UIFactory.Centered(\"Ret_R\", cameraRoot.transform, 26f, 0f, 22f, 3f), w);\n            reticle[2] = UIFactory.AddImage(UIFactory.Centered(\"Ret_T\", cameraRoot.transform, 0f, 26f, 3f, 22f), w);\n            reticle[3] = UIFactory.AddImage(UIFactory.Centered(\"Ret_B\", cameraRoot.transform, 0f, -26f, 3f, 22f), w);\n            RectTransform lb = UIFactory.TopLeft(\"LabelBG\", cameraRoot.transform, 18f, 470f, 368f, 46f);\n            UIFactory.AddImage(lb, new Color(0f, 0f, 0f, 0.55f));\n            camLabel = UIFactory.AddText(UIFactory.Stretch(\"Label\", lb), \"\", 19, Color.white, TextAnchor.MiddleCenter);\n            RectTransform tb = UIFactory.TopLeft(\"TopBG\", cameraRoot.transform, 0f, 0f, 404f, 40f);\n            UIFactory.AddImage(tb, new Color(0f, 0f, 0f, 0.55f));\n            camFlashText = UIFactory.AddText(UIFactory.TopLeft(\"Flash\", tb, 14f, 6f, 200f, 28f), \"\", 17, Color.white, TextAnchor.MiddleLeft);\n            camFlashText.fontStyle = FontStyle.Bold;\n            camCount = UIFactory.AddText(UIFactory.TopLeft(\"Count\", tb, 190f, 6f, 200f, 28f), \"\", 16, Color.white, TextAnchor.MiddleRight);\n            RectTransform fb = UIFactory.TopLeft(\"FooterBG\", cameraRoot.transform, 0f, 672f, 404f, 72f);\n            UIFactory.AddImage(fb, new Color(0f, 0f, 0f, 0.55f));\n            cameraRoot.SetActive(false);\n\n            // --- search: the school's catalogue\n            searchRoot = UIFactory.Stretch(\"Search\", screen).gameObject;\n            searchHeader = UIFactory.AddText(UIFactory.TopLeft(\"Header\", searchRoot.transform, 18f, 10f, 368f, 34f), AppName(AppSearch), 22, Ink, TextAnchor.MiddleLeft);\n            searchHeader.fontStyle = FontStyle.Bold;\n            UIFactory.AddImage(UIFactory.TopLeft(\"Divider\", searchRoot.transform, 18f, 46f, 368f, 2f), new Color(0f, 0f, 0f, 0.25f));\n            UIFactory.AddText(UIFactory.TopLeft(\"Catalogue\", searchRoot.transform, 18f, 54f, 368f, 24f), Loc.L(\"CLEARVIEW LIBRARY CATALOGUE  -  since 04/1967\", \"明鉴图书馆目录  -  始于 1967 年 4 月\"), 14, new Color(0.45f, 0.3f, 0.2f), TextAnchor.MiddleLeft);\n            RectTransform qbox = UIFactory.TopLeft(\"Query\", searchRoot.transform, 18f, 86f, 368f, 56f);\n            UIFactory.AddImage(qbox, new Color(0f, 0f, 0f, 0.1f));\n            searchQuery = UIFactory.AddText(UIFactory.Stretch(\"Text\", qbox), \"\", 21, Ink, TextAnchor.MiddleCenter);\n            searchQuery.fontStyle = FontStyle.Bold;\n            searchBarRoot = UIFactory.TopLeft(\"Bar\", searchRoot.transform, 18f, 150f, 368f, 8f).gameObject;\n            UIFactory.AddImage((RectTransform)searchBarRoot.transform, new Color(0f, 0f, 0f, 0.15f));\n            searchFill = UIFactory.Rect(\"Fill\", searchBarRoot.transform, Vector2.zero, new Vector2(0f, 1f), new Vector2(0f, 0.5f), Vector2.zero, Vector2.zero);\n            UIFactory.AddImage(searchFill, new Color(0.85f, 0.45f, 0.15f));\n            searchResultText = UIFactory.AddText(UIFactory.TopLeft(\"Result\", searchRoot.transform, 22f, 172f, 360f, 480f), \"\", 18, Ink, TextAnchor.UpperLeft);\n            searchRoot.SetActive(false);\n\n            footer = UIFactory.AddText(UIFactory.TopLeft(\"Footer\", screen, 18f, 680f, 368f, 50f), \"\", 16, Ink, TextAnchor.UpperCenter);\n\n            dangerTint = UIFactory.AddImage(UIFactory.Stretch(\"DangerRed\", screen), new Color(0.85f, 0.05f, 0.05f, 0f));\n            // a tiny bell in the corner of every screen: the silent switch nobody ever explains\n            RectTransform bellR = UIFactory.TopLeft(\"Bell\", screen, 382f, 3f, 20f, 18f);\n            bellBody = UIFactory.AddImage(UIFactory.TopLeft(\"Body\", bellR, 5f, 1f, 10f, 11f), new Color(0.3f, 0.3f, 0.32f));\n            bellClapper = UIFactory.AddImage(UIFactory.TopLeft(\"Clapper\", bellR, 2f, 12f, 16f, 3f), new Color(0.3f, 0.3f, 0.32f));\n            RectTransform slash = UIFactory.Centered(\"Slash\", bellR, 0f, 0f, 24f, 3f);\n            slash.localRotation = Quaternion.Euler(0f, 0f, 40f);\n            bellSlash = UIFactory.AddImage(slash, new Color(0.75f, 0.2f, 0.15f));\n            bellSlash.enabled = false;\n            bellText = UIFactory.AddText(UIFactory.TopLeft(\"BellText\", screen, 270f, 2f, 108f, 20f), \"\", 13, new Color(0.75f, 0.2f, 0.15f), TextAnchor.MiddleRight);\n            bellText.fontStyle = FontStyle.Bold;\n            whiteFlash = UIFactory.AddImage(UIFactory.Stretch(\"ShutterFlash\", screen), new Color(1f, 1f, 1f, 0f));\n            whiteFlash.raycastTarget = false;\n        }\n\n        // Photos are drawn with simple shapes - replace with real images later.\n        static RectTransform Box(Transform parent, float x, float y, float w, float h, Color c)\n        {\n            RectTransform r = UIFactory.TopLeft(\"Shape\", parent, x, y, w, h);\n            UIFactory.AddImage(r, c);\n            return r;\n        }\n\n        GameObject PhotoClass(RectTransform frame, string name, Color wall, Color head, Color body, string pencil)\n        {\n            GameObject p = UIFactory.Stretch(name, frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, wall);\n            Box(p.transform, 0f, 250f, 368f, 70f, new Color(wall.r * 0.6f, wall.g * 0.6f, wall.b * 0.6f));\n            for (int row = 0; row < 3; row++)\n                for (int i = 0; i < 5; i++)\n                {\n                    float x = 40f + i * 62f + row * 6f, y = 60f + row * 62f;\n                    Box(p.transform, x, y, 22f, 22f, head);\n                    Box(p.transform, x - 6f, y + 24f, 34f, 30f, body);\n                }\n            // circled: back row, window side\n            float cx = 34f, cy = 54f;\n            Color y1 = pencil == null ? new Color(1f, 0.8f, 0.2f) : new Color(0.15f, 0.12f, 0.1f);\n            Box(p.transform, cx, cy, 34f, 3f, y1); Box(p.transform, cx, cy + 62f, 34f, 3f, y1);\n            Box(p.transform, cx, cy, 3f, 64f, y1); Box(p.transform, cx + 32f, cy, 3f, 64f, y1);\n            if (pencil != null)\n            {\n                Text t = UIFactory.AddText(UIFactory.TopLeft(\"Pencil\", p.transform, 14f, 268f, 200f, 40f), pencil, 26, new Color(0.18f, 0.14f, 0.1f), TextAnchor.MiddleLeft);\n                t.fontStyle = FontStyle.Italic;\n                Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.4f, 0.3f, 0.1f, 0.12f));   // age\n            }\n            return p;\n        }\n\n        GameObject PhotoHand(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Hand2016\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.22f, 0.16f, 0.11f));\n            Box(p.transform, 0f, 40f, 368f, 18f, new Color(0.4f, 0.3f, 0.2f));\n            Box(p.transform, 130f, 150f, 120f, 70f, new Color(0.75f, 0.6f, 0.48f));\n            Box(p.transform, 160f, 110f, 46f, 84f, new Color(0.05f, 0.05f, 0.06f));\n            Box(p.transform, 164f, 114f, 38f, 70f, new Color(0.95f, 0.85f, 0.6f));\n            return p;\n        }\n\n        GameObject PhotoSneeze(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Sneeze2018\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.3f, 0.36f, 0.32f));        // blackboard\n            Box(p.transform, 140f, 90f, 90f, 230f, new Color(0.55f, 0.18f, 0.16f));     // teacher, blurred mid-sneeze\n            Box(p.transform, 158f, 40f, 54f, 54f, new Color(0.8f, 0.65f, 0.55f));\n            Box(p.transform, 150f, 30f, 70f, 10f, new Color(1f, 1f, 1f, 0.35f));       // motion blur\n            Box(p.transform, 230f, 50f, 40f, 4f, new Color(1f, 1f, 1f, 0.6f));\n            Box(p.transform, 236f, 62f, 30f, 4f, new Color(1f, 1f, 1f, 0.5f));\n            return p;\n        }\n\n        GameObject PhotoTriangle(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Triangle2021\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.5f, 0.5f, 0.5f));\n            Box(p.transform, 74f, 40f, 220f, 200f, new Color(0.45f, 0.33f, 0.22f));   // chair back\n            Box(p.transform, 90f, 240f, 20f, 80f, new Color(0.35f, 0.25f, 0.17f));\n            Box(p.transform, 258f, 240f, 20f, 80f, new Color(0.35f, 0.25f, 0.17f));\n            // chalk triangle: three bars around the centre of the chair back\n            Triangle(p.transform, new Vector2(184f, -140f), 110f, 6f, new Color(0.95f, 0.95f, 0.9f));\n            return p;\n        }\n\n        GameObject PhotoNight(RectTransform frame)\n        {\n            GameObject p = UIFactory.Stretch(\"Photo_Night\", frame).gameObject;\n            Box(p.transform, 0f, 0f, 368f, 320f, new Color(0.03f, 0.03f, 0.05f));\n            Box(p.transform, 250f, 60f, 60f, 80f, new Color(0.95f, 0.8f, 0.45f));\n            return p;\n        }\n\n        /// <summary>Outline triangle centred at 'center' (top-left space: x right, y negative down).</summary>\n        public static void Triangle(Transform parent, Vector2 center, float side, float thick, Color c)\n        {\n            float h = side * 0.866f;\n            Vector2 a = center + new Vector2(-side * 0.5f, -h / 3f);\n            Vector2 b = center + new Vector2(side * 0.5f, -h / 3f);\n            Vector2 top = center + new Vector2(0f, h * 2f / 3f);\n            Bar(parent, a, b, thick, c);\n            Bar(parent, b, top, thick, c);\n            Bar(parent, top, a, thick, c);\n        }\n\n        static void Bar(Transform parent, Vector2 from, Vector2 to, float thick, Color c)\n        {\n            Vector2 mid = (from + to) * 0.5f;\n            Vector2 d = to - from;\n            RectTransform r = UIFactory.Rect(\"Bar\", parent, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0.5f, 0.5f), mid, new Vector2(d.magnitude, thick));\n            r.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(d.y, d.x) * Mathf.Rad2Deg);\n            UIFactory.AddImage(r, c);\n        }\n    }\n}\n"},"PhotoTarget":{"path":"Assets/Game/Scripts/PhotoTarget.cs","role":"Something worth photographing with the phone's Camera app (Chapter 4 Picture Day)","source":"// @role Something worth photographing with the phone's Camera app (Chapter 4 Picture Day)\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>Something worth photographing with the phone's Camera app (Chapter 4).</summary>\n    public class PhotoTarget : MonoBehaviour\n    {\n        public string id;\n        [Tooltip(\"Shown in the viewfinder and as the photo's caption (English; Chinese from LocTable).\")]\n        public string label;\n        public float range = 9f;\n        [HideInInspector] public bool taken;\n    }\n}\n"},"PictureDayDirector":{"path":"Assets/Game/Scripts/PictureDayDirector.cs","role":"Chapter 4 Picture Day (Wednesday): a gym full of students milling about; every so often a CLASS PHOTO countdown - get to your spot, phone down, hold still, smile. Between photos: CAMERA (1045), photograph 3 things without being reported","source":"// @role Chapter 4 Picture Day (Wednesday): a gym full of students milling about; every so often a CLASS PHOTO countdown - get to your spot, phone down, hold still, smile. Between photos: CAMERA (1045), photograph 3 things without being reported\n// @calls LevelDirectorBase, PatrolAI, TeacherVision, PhoneController, PhotoTarget, Readable\n// @tune freeSeconds:float:20-90:free time between two class photos\n// @tune callSeconds:float:5-40:countdown to get to your spot\n// @tune shutterHearing:float:1-8:how close a prefect must be to hear the shutter (m) - 2.2 = right next to you\n// @tune flashRange:float:4-20:how far a flash is seen (any direction, line of sight)\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Chapter 4 \"Picture Day\" (the gymnasium in the Cubberley Wing, Wednesday - \"day three\").\n    ///  - The class mills about the gym. Every minute or so: CLASS PHOTO. A countdown; everyone walks to their place on\n    ///    the risers. You must be on YOUR spot (the yellow X - it MOVES before every photo) when it ends: phone down, standing\n    ///    still, HOLD SPACE to smile. Missing, moving, not smiling or a phone in the picture = a warning (a report).\n    ///    The photographer always finds a reason to take it again (\"someone blinked\").\n    ///  - Only in the free time between photos can you use the phone. Two PREFECTS walk the floor and REPORT.\n    ///  - CAMERA (code 10:45 -> 1045): photograph the report board, the LIVE screen with nobody on it and the April 1967\n    ///    photo, then send them to Triangle. The shutter clicks (prefects close by hear it). The FLASH switches itself\n    ///    back ON every time the phone comes out (A / D turns it off).\n    ///  - After sending: the final photo. Get it right = WIN.\n    /// </summary>\n    public class PictureDayDirector : LevelDirectorBase\n    {\n        [Header(\"Scene references (filled by the scene builder)\")]\n        public PatrolAI photographer;\n        public TeacherVision photographerVision;\n        public PatrolAI[] prefects;\n        public TeacherVision[] prefectVisions;\n        public Transform[] prefectPhotoSpots;\n        public PatrolAI[] walkers;\n        [Tooltip(\"All places on the risers (one more than there are walkers). Each photo, the X picks one for you.\")]\n        public Transform[] walkerSpots;\n        public Transform spotMarker;\n        public float walkerCallSpeed = 1.9f;\n        public float walkerFreeSpeed = 1.25f;\n        public Transform cameraSpot;\n        public Transform playerSpot;\n        public Light photoFlash;\n\n        [Header(\"Rules\")]\n        public float freeSeconds = 42f;\n        public float firstFreeSeconds = 55f;\n        public float callSeconds = 10f;\n        public float spotRadius = 0.6f;\n        public float shutterHearing = 2.2f;\n        public float flashRange = 15f;\n\n        enum Phase { Intro, Free, Call, Shot, Done }\n        Phase phase = Phase.Intro;\n        float phaseLeft, prefectTalk, paTimer = 50f;\n        int paIndex, photosShot;\n        bool unlockedCam, allPhotos, taskGiven, sent, finalCall, toldFlash, toldRaise, toldCallRules;\n        bool board, screen, trophy;\n        Vector3 lastPos;\n        float speed;\n        Text countdown;\n        int playerPlace = -1, calls;\n        string placeText = \"\";\n\n        static readonly string[] ambientPA =\n        {\n            \"Reminder: a citizen card must be carried at all times. Including in dreams.\",\n            \"Prefects are thanked for their service. Students are thanked for being observed.\",\n            \"If you see something, say something. If you see nothing, say that too.\",\n            \"Please do not blink during your photograph. Blinking will be photographed again.\",\n        };\n        static readonly string[] retakes =\n        {\n            \"...Someone blinked. Again in a minute. Free time - don't wander far.\",\n            \"...Someone wasn't smiling with their whole face. Again in a minute.\",\n            \"...A shadow. On a chin. Unacceptable. Once more, in a minute.\",\n            \"...Lovely. Lovely. Except one of you. Again in a minute.\",\n        };\n\n        protected override void Awake()\n        {\n            base.Awake();\n            authorityLabel = \"PHOTOGRAPHER\";\n            authorityPitch = 1.05f;\n            phone.hasPhone = true;\n            phone.allowRaise = false;\n            phone.phoneClock = \"10:16\";\n            phone.flashOnEveryRaise = true;\n            phone.appUnlocked[PhoneController.AppPhotos] = true;\n            phone.appUnlocked[PhoneController.AppMessages] = true;\n            phone.appUnlocked[PhoneController.AppContacts] = true;\n            phone.lockNotification = L(\"No new messages.\", \"没有新信息。\");\n            phone.AddHistory(\"Never Blinks\", L(\"three lights answered last night. three.\", \"昨晚有三盏灯回应了。三盏。\"), false);\n            phone.AddHistory(\"Triangle\", L(\"wednesday is picture day. bring the phone. keep it low.\", \"周三是拍照日。带上手机。放低一点。\"), false);\n            phone.onMessageArrived = () => { if (!phone.IsExposed) PhoneBuzz(); };\n            phone.onShutter = OnShutter;\n            if (photoFlash != null) photoFlash.enabled = false;\n            BuildCountdown();\n        }\n\n        protected override void Start()\n        {\n            base.Start();\n            if (photographer != null) photographer.Begin();\n            if (prefects != null) foreach (PatrolAI p in prefects) if (p != null) p.Begin();\n            if (walkers != null) foreach (PatrolAI w in walkers) if (w != null) w.Begin();\n            lastPos = rig.transform.position;\n            rig.Lock();\n            StartCoroutine(Opening());\n        }\n\n        IEnumerator Opening()\n        {\n            yield return ChapterCard(\"CHAPTER 4\", \"PICTURE DAY\", \"WEDNESDAY  -  10:15\");\n            PA(L(\"Good morning, Clearview. Today is Picture Day. Classes will be photographed from ten forty-five. Ten. Forty-five.\", \"早上好，明鉴学院。今天是拍照日。各班从十点四十五分开始拍照。十。四十五。\"), 7f);\n            PA(L(\"Your photograph will be printed on your new Citizen Card. When you hear the countdown, go to your place. Smile.\", \"你的照片将印在新的公民卡上。听到倒计时，请回到你的位置。微笑。\"), 7f);\n            yield return Wait(1f);\n            rig.AllowWalk();\n            Thought(L(\"Wednesday. Monday it was rules. Yesterday we all stood up and said the motto together. Twice.\\nToday: photos for our new \", \"星期三。星期一讲规矩。昨天我们全体起立，一起念校训。念了两遍。\\n今天：给新的\") + Rule(L(\"citizen cards\", \"公民卡\")) + L(\".\", \"拍照。\"), 8f);\n            Thought(Rule(L(\"Red armbands\", \"红袖章\")) + L(\" = prefects. They don't take phones. They \", \" = 学生督察。他们不收手机。他们\") + Rule(L(\"report\", \"举报\")) + L(\".\\nWhen the countdown starts, I have to be \", \"。\\n倒计时一开始，我就得回到\") + Rule(L(\"on my spot\", \"我的位置\")) + L(\".\", \"上。\"), 8f);\n            phone.Receive(\"Triangle\", L(\"this phone has a camera. the code is when they photograph us.\", \"这部手机有相机。密码是他们给我们拍照的时间。\"));\n            phone.Receive(\"Triangle\", L(\"three things: the board on the east wall. the 'live' screen. the old photo in the trophy case.\", \"三样东西：东墙的布告板。那块“直播”屏幕。奖杯柜里的老照片。\"));\n            phone.Receive(\"Triangle\", L(\"only between photos. and the flash turns itself back on every time. turn it OFF.\", \"只能在两次拍照之间拍。还有，闪光灯每次都会自己重新打开。记得关掉。\"));\n            yield return WaitIdle();\n            phase = Phase.Free;\n            phaseLeft = firstFreeSeconds;\n            StartCoroutine(Reminder(L(\"My phone buzzed. \", \"手机震了。\") + Rule(L(\"HOLD RIGHT MOUSE\", \"按住鼠标右键\")) + L(\" - where no armband is looking.\", \"——在没有红袖章看着的地方。\"), () => phone.RaisedOnce || ended, 24f));\n        }\n\n        // ------------------------------------------------------------------ main loop\n        protected override void LevelUpdate()\n        {\n            Vector3 p = rig.transform.position;\n            Vector3 dp = p - lastPos; dp.y = 0f;\n            speed = Mathf.Lerp(speed, dp.magnitude / Mathf.Max(0.0001f, Time.deltaTime), 0.3f);\n            lastPos = p;\n\n            PlayerRig.Mode m = rig.CurrentMode;\n            phone.allowRaise = phone.hasPhone && m == PlayerRig.Mode.Walk && phase != Phase.Shot && phase != Phase.Done;\n            rig.freezeMovement = phone.IsExposed;\n            if (phone.IsExposed && !toldRaise)\n            {\n                toldRaise = true;\n                Thought(L(\"While I look at the phone, \", \"看手机的时候，\") + Rule(L(\"I stand still\", \"我站着不动\")) + L(\". Anyone looking can see it.\", \"。谁看过来都能看见。\"), 6f);\n            }\n            if (!toldFlash && phone.Screen == PhoneController.PhoneScreen.Camera && phone.IsUp)\n            {\n                toldFlash = true;\n                Thought(L(\"The camera. Aim with the middle of the screen, \", \"相机。用屏幕中间对准，\") + Rule(L(\"LEFT MOUSE = shutter\", \"鼠标左键 = 快门\")) + L(\".\\n\", \"。\\n\") + Rule(L(\"The flash is ON\", \"闪光灯是开着的\")) + L(\" - A / D turns it off. Every time.\", \"——按 A / D 关掉。每次都要。\"), 8f, true);\n            }\n            UpdatePhase();\n            UpdateStory();\n            UpdateObjective();\n            UpdateDanger();\n            UpdateAmbient();\n            SetPrompt(PromptNow());\n        }\n\n        bool OnSpot()\n        {\n            if (playerSpot == null) return true;\n            Vector3 a = rig.transform.position, b = playerSpot.position;\n            if (a.y < b.y - 0.15f) return false;\n            a.y = b.y = 0f;\n            return Vector3.Distance(a, b) < spotRadius;\n        }\n\n        string PromptNow()\n        {\n            if (rig.CurrentMode != PlayerRig.Mode.Walk) return null;\n            if (phase == Phase.Call && OnSpot() && !phone.IsExposed)\n                return GameInput.SpaceHeld() ? L(\"SMILING  :)   (keep holding SPACE, don't move)\", \"微笑中  :)  （按住空格别松，别动）\") : L(\"On your spot. HOLD SPACE to smile.\", \"到位了。按住空格微笑。\");\n            if (phone.IsExposed && phone.Screen == PhoneController.PhoneScreen.Camera)\n            {\n                PhotoTarget t = phone.Aimed;\n                if (t != null && !t.taken) return L(\"IN FRAME  -  LEFT MOUSE: take the photo\", \"已入框  -  鼠标左键：拍照\");\n                return null;\n            }\n            return RaycastInteract();\n        }\n\n        // ------------------------------------------------------------------ the class-photo cycle\n        void UpdatePhase()\n        {\n            if (phase == Phase.Intro || phase == Phase.Done) { countdown.text = \"\"; return; }\n            if (phase == Phase.Shot) return;\n            phaseLeft -= phase == Phase.Free && allPhotos ? GameSpeed.Dt : Time.deltaTime;   // only pure waiting speeds up (2x)\n            if (phase == Phase.Free)\n            {\n                countdown.text = L(\"next class photo in \", \"下次合照：\") + Mathf.CeilToInt(Mathf.Max(0f, phaseLeft)) + L(\" s\", \" 秒\");\n                countdown.color = phaseLeft < 10f ? new Color(1f, 0.6f, 0.4f) : new Color(1f, 0.85f, 0.55f, 0.6f);\n                countdown.fontSize = phaseLeft < 10f ? 40 : 28;\n                if (phaseLeft <= 0f) StartCall();\n                return;\n            }\n            // call: count down\n            countdown.text = L(\"CLASS PHOTO  \", \"班级合照  \") + Mathf.CeilToInt(Mathf.Max(0f, phaseLeft));\n            countdown.fontSize = 52;\n            countdown.color = Mathf.Repeat(phaseLeft, 0.5f) > 0.25f ? new Color(1f, 0.3f, 0.22f) : new Color(1f, 0.75f, 0.6f);\n            if (phaseLeft <= 0f) StartCoroutine(TakeClassPhoto());\n        }\n\n        void StartCall()\n        {\n            phase = Phase.Call;\n            phaseLeft = callSeconds;\n            finalCall = sent;\n            ambient.Play(AudioSynth.Chime(), 0.4f);\n            PA(finalCall ? L(\"Final class photograph. Take your places. Make it perfect.\", \"最后一次合照。各就各位。务必完美。\")\n                         : L(\"Class photograph! Take your places. Quickly.\", \"拍合照了！各就各位。快。\"), 4f, true);\n            if (finalCall) Thought(L(\"The last one. The X is back where it started: \", \"最后一张。X 回到了最开始的地方：\") + Rule(L(\"back row, by the window.\", \"最后一排，靠窗。\")), 4f);\n            // the photographer moves the X: a new place for you every photo (the first one: back row, window end)\n            if (walkerSpots != null && walkerSpots.Length > 0)\n            {\n                int n = walkerSpots.Length;\n                // the first photo and the FINAL one: back row, window end (where Triangle says \"it's always that spot\")\n                bool fixedSpot = calls == 0 || finalCall;\n                int pick = fixedSpot ? n - 1 : Random.Range(0, n);\n                if (!fixedSpot && pick == playerPlace) pick = (pick + 1 + Random.Range(0, n - 1)) % n;\n                playerPlace = pick;\n                Vector3 p = walkerSpots[pick].position;\n                if (playerSpot != null) playerSpot.position = p;\n                if (spotMarker != null) spotMarker.position = p;\n                placeText = PlaceText(p);\n                ambient.Play(AudioSynth.Ping(), 0.3f, 1.3f);\n                // everyone else takes the other places\n                int w = 0;\n                for (int i = 0; i < n && walkers != null && w < walkers.Length; i++)\n                {\n                    if (i == pick) continue;\n                    PatrolAI wk = walkers[w++];\n                    if (wk == null) continue;\n                    UnityEngine.AI.NavMeshAgent ag = wk.GetComponent<UnityEngine.AI.NavMeshAgent>();\n                    if (ag != null) ag.speed = walkerCallSpeed;\n                    wk.RunRoute(new[] { walkerSpots[i].position }, new[] { 999f }, new[] { 180f }, null);\n                }\n            }\n            calls++;\n            if (!toldCallRules)\n            {\n                toldCallRules = true;\n                Thought(L(\"Everyone is walking to the risers. \", \"所有人都在往台阶上走。\") + Rule(L(\"My spot = the YELLOW X.\", \"我的位置 = 那个黄色的 X。\")) +\n                        L(\"\\nPhone DOWN. Stand still. \", \"\\n放下手机。站着别动。\") + Rule(L(\"HOLD SPACE to smile.\", \"按住空格微笑。\")), 7f);\n            }\n            else if (!finalCall) Thought(L(\"The X has moved: \", \"X 换地方了：\") + Rule(placeText), 4f);\n            if (prefects != null)\n                for (int i = 0; i < prefects.Length; i++)\n                    if (prefects[i] != null && prefectPhotoSpots != null && i < prefectPhotoSpots.Length)\n                        prefects[i].RunRoute(new[] { prefectPhotoSpots[i].position }, new[] { 999f }, new[] { prefectPhotoSpots[i].eulerAngles.y }, null);\n            if (photographer != null && cameraSpot != null)\n                photographer.RunRoute(new[] { cameraSpot.position }, new[] { 999f }, new[] { 0f }, null);\n        }\n\n        IEnumerator TakeClassPhoto()\n        {\n            phase = Phase.Shot;\n            countdown.text = \"\";\n            Authority(L(\"Three... two... one... say 'Clearview!'\", \"三……二……一……说“明鉴！”\"), 2.6f, true);\n            yield return Wait(2.2f);\n            StudentSay(\"EVERYONE\", L(\"CLEARVIEW!\", \"明鉴！\"), 1.4f, true);\n            yield return Wait(0.35f);\n            // the moment the shutter goes: judge\n            bool onSpot = OnSpot(), phoneDown = !phone.IsExposed, smiling = GameInput.SpaceHeld(), still = speed < 0.35f;\n            ambient.Play(AudioSynth.Click(), 0.9f, 0.8f);\n            if (photoFlash != null) photoFlash.enabled = true;\n            fade.color = Color.white;\n            yield return Wait(0.12f);\n            if (photoFlash != null) photoFlash.enabled = false;\n            for (float t = 0f; t < 1f; t += Time.deltaTime / 0.9f) { fade.color = new Color(1f, 1f, 1f, 1f - t); yield return null; }\n            fade.color = new Color(0f, 0f, 0f, 0f);\n            photosShot++;\n            bool ok = onSpot && phoneDown && smiling && still;\n            if (!onSpot) Strike(L(\"Seat 31 is missing from the photograph. A prefect has been informed.\", \"31 号座的同学不在照片里。已通知学生督察。\"), true);\n            else if (!phoneDown) Strike(L(\"Is that a PHONE in my photograph?\", \"我的照片里是不是有一部手机？\"));\n            else if (!still) Strike(L(\"You moved. Seat 31 is a blur. Report filed.\", \"你动了。照片里的 31 号座糊成了一片。举报已登记。\"), true);\n            else if (!smiling) Strike(L(\"Seat 31. That was not a smile. Report filed.\", \"31 号座。那不叫微笑。举报已登记。\"), true);\n            if (ended) yield break;\n            yield return Wait(1.2f);\n            if (ok && finalCall)\n            {\n                phase = Phase.Done;\n                yield return FinalPhoto();\n                yield break;\n            }\n            if (ok) Authority(Loc.T(retakes[(photosShot - 1) % retakes.Length]), 5f);\n            else Authority(L(\"Again in a minute. All of you. Thank Seat 31.\", \"一分钟后重拍。所有人。谢谢 31 号座。\"), 4.5f);\n            // free time: everyone wanders off again\n            if (walkers != null)\n                foreach (PatrolAI w in walkers)\n                {\n                    if (w == null) continue;\n                    UnityEngine.AI.NavMeshAgent ag = w.GetComponent<UnityEngine.AI.NavMeshAgent>();\n                    if (ag != null) ag.speed = walkerFreeSpeed;\n                    w.ResumeRoam();\n                }\n            if (prefects != null) foreach (PatrolAI p in prefects) if (p != null) p.ResumeRoam();\n            phase = Phase.Free;\n            phaseLeft = freeSeconds;\n            StartCoroutine(PhotographerFreeTime());\n        }\n\n        /// <summary>\"middle row, door end\" - where the X is, in words.</summary>\n        string PlaceText(Vector3 p)\n        {\n            string row = p.y > 0.5f ? L(\"BACK row\", \"最后一排\") : (p.y > 0.3f ? L(\"MIDDLE row\", \"中间一排\") : L(\"FRONT row\", \"第一排\"));\n            string side = p.x < 5.2f ? L(\"by the WINDOWS\", \"靠窗那头\") : (p.x > 10.8f ? L(\"the far (EAST) end\", \"靠东墙那头\") : L(\"in the MIDDLE\", \"正中间\"));\n            return row + L(\", \", \"，\") + side;\n        }\n\n        /// <summary>Between photos the photographer fiddles with his lights (and turns his back on the hall now and then).</summary>\n        IEnumerator PhotographerFreeTime()\n        {\n            if (photographer == null || cameraSpot == null) yield break;\n            Vector3 home = cameraSpot.position;\n            yield return Wait(Random.Range(4f, 9f));\n            while (phase == Phase.Free && !ended)\n            {\n                Vector3 lamp = home + new Vector3(Random.value < 0.5f ? -2.6f : 2.6f, 0f, 1.1f);\n                photographer.RunRoute(new[] { lamp, home }, new[] { 5f, Random.Range(6f, 10f) }, new[] { 0f, 180f }, null);\n                while (!photographer.RouteDone && phase == Phase.Free && !ended) yield return null;\n            }\n        }\n\n        IEnumerator FinalPhoto()\n        {\n            rig.Lock();\n            phone.allowRaise = false;\n            SetPrompt(null);\n            SetObjective(\"\");\n            Authority(L(\"...Perfect. Nobody move. That one is for the cards.\", \"……完美。谁都别动。这张就印在卡上。\"), 4f, true);\n            Thought(L(\"In the photo, I'm in the back row, by the window.\\nSame as every year. Same as every face before mine.\", \"照片里，我在最后一排，靠窗。\\n和每一年一样。和我之前的每一张脸一样。\"), 6f);\n            PA(L(\"Thank you, Clearview. Your cards will be ready tomorrow. Some cards will have a red X. Please do not ask what it means.\", \"谢谢你，明鉴。你们的卡明天就能领取。有些卡上会有一个红色的 X。请不要问那是什么意思。\"), 7f);\n            yield return WaitIdle();\n            yield return FinishLevel(\"photo\", 2f);\n        }\n\n        // ------------------------------------------------------------------ story\n        void UpdateStory()\n        {\n            if (!unlockedCam && phone.IsUnlocked(PhoneController.AppCamera))\n            {\n                unlockedCam = true;\n                Thought(L(\"10:45. It opened. \", \"10:45。打开了。\") + Rule(L(\"Three photos\", \"三张照片\")) + L(\" - between the class photos, never during.\", \"——要在两次合照之间拍，别在倒计时里拍。\"), 6f);\n            }\n            if (!allPhotos && board && screen && trophy)\n            {\n                allPhotos = true;\n                phone.Receive(\"Triangle\", L(\"that's all three. send them to me. Messages.\", \"三张都齐了。发给我。用“信息”。\"));\n            }\n            if (allPhotos && !taskGiven && phone.UnreadCount == 0)\n            {\n                taskGiven = true;\n                phone.StartTask(new PhoneTask\n                {\n                    forward = true,\n                    header = \"Forward to...\",\n                    options = new[] { \"Lent Me An Eraser\", \"Triangle\", \"Hums When Scared\", \"Never Blinks\" },\n                    correct = 1,\n                    sendText = L(\"[3 photos]\", \"[3 张照片]\"),\n                    onDone = i => StartCoroutine(Sent()),\n                    typeSeconds = 3f,\n                });\n            }\n        }\n\n        IEnumerator Sent()\n        {\n            sent = true;\n            ambient.Play(AudioSynth.Confirm(), 0.4f);\n            yield return Wait(1.5f);\n            phone.Receive(\"Triangle\", L(\"got them. look at the board again: 20 reports. 3 reporters. who wrote the other 17?\", \"收到了。再看看那块板：20 份举报。3 个举报员。剩下那 17 份是谁写的？\"));\n            phone.Receive(\"Triangle\", L(\"tomorrow after school: the library. it's in the cubberley wing too. same month as that photo.\", \"明天放学后：图书馆。它也在库伯利楼。和那张照片同一个月。\"));\n            phone.Receive(\"Triangle\", L(\"now one perfect photo, and they let us go. back row, by the window. it's always that spot.\", \"现在拍一张完美的合照，他们就放我们走。最后一排，靠窗。一直都是那个位置。\"));\n            if (phase == Phase.Free) phaseLeft = Mathf.Min(phaseLeft, 15f);\n        }\n\n        void UpdateObjective()\n        {\n            if (phase == Phase.Done || phase == Phase.Intro) return;\n            if (phase == Phase.Call || phase == Phase.Shot)\n            {\n                SetObjective(L(\"CLASS PHOTO! Before the countdown ends:\\nstand on the YELLOW X - \", \"班级合照！倒计时结束前：\\n站到黄色的 X 上——\") + placeText + L(\".\\nPhone DOWN. Don't move. HOLD SPACE to smile.\", \"。\\n放下手机。别动。按住空格微笑。\"));\n                return;\n            }\n            string next = \"\\n\" + L(\"(Free time until the next class photo - see the timer.)\", \"（自由活动，直到下次合照——看上方的计时。）\");\n            if (sent) { SetObjective(L(\"Wait for the final class photo.\\nStay near the risers: the X will move again.\", \"等最后一次合照。\\n待在台阶附近：X 还会换位置。\") + next); return; }\n            if (allPhotos) { SetObjective(L(\"Send the 3 photos to Triangle.\\nMessages -> A / D pick Triangle -> Left Mouse, then HOLD Left Mouse.\", \"把 3 张照片发给三角。\\n信息 -> A / D 选三角 -> 鼠标左键，再按住左键。\") + next); return; }\n            if (unlockedCam)\n            {\n                string Box(bool b) { return b ? \"[x] \" : \"[  ] \"; }\n                SetObjective(L(\"Photograph 3 things (Camera, LEFT MOUSE = shutter):\\n\", \"拍下 3 样东西（相机，鼠标左键 = 快门）：\\n\")\n                    + Box(board) + L(\"the report board (EAST wall)\\n\", \"举报布告板（东墙）\\n\")\n                    + Box(screen) + L(\"the LIVE screen (WEST wall, by the door)\\n\", \"“直播”屏幕（西墙，门边）\\n\")\n                    + Box(trophy) + L(\"the 1967 photo (trophy case, SOUTH wall)\\n\", \"1967 年的照片（奖杯柜，南墙）\\n\")\n                    + L(\"Flash OFF every time (A / D). No prefect close when you click.\", \"每次都要关闪光灯（A / D）。按快门时别让督察在附近。\") + next);\n                return;\n            }\n            if (phone.RaisedOnce) SetObjective(L(\"Unlock CAMERA.\\nCode = when your class is photographed (10:45 -> 4 digits).\", \"解锁“相机”。\\n密码 = 你们班拍照的时间（10:45 → 四位数）。\") + next);\n            else SetObjective(L(\"Read Triangle's messages: HOLD RIGHT MOUSE.\\nNobody may see the phone - prefects (red armbands), the photographer.\", \"读三角的信息：按住鼠标右键。\\n不能让人看到手机——学生督察（红袖章）、摄影师。\") + next);\n        }\n\n        // ------------------------------------------------------------------ camera\n        void OnShutter(PhotoTarget t, bool flash)\n        {\n            if (ended || phase == Phase.Done) return;\n            float d;\n            PatrolAI near = NearestPrefect(out d);\n            bool heard = near != null && d < shutterHearing;\n            bool seen = flash && FlashSeen();\n            if (t != null)\n            {\n                if (t.id == \"board\" && !board) { board = true; Thought(L(\"Twenty reports in three days. Only three of us were asked to report.\\nThe other seventeen... \", \"三天，二十份举报。只有三个人是被指派去举报的。\\n剩下那十七份……\") + Rule(L(\"volunteered\", \"是自愿的\")) + L(\".\", \"。\"), 6.5f); }\n                if (t.id == \"screen\" && !screen) { screen = true; Thought(L(\"LIVE. The Founder will speak to us at 10:45.\\nThe screen shows \", \"直播。创办人将在 10:45 对我们讲话。\\n屏幕上\") + Rule(L(\"nothing\", \"什么都没有\")) + L(\". Just snow.\", \"。只有雪花。\"), 6.5f); }\n                if (t.id == \"trophy\" && !trophy) { trophy = true; Thought(L(\"April 1967. The Cubberley Wing opens.\\nEveryone in the photo holds the same hand up, \", \"1967 年 4 月。库伯利楼启用。\\n照片里每个人都举着同一只手，\") + Rule(L(\"cupped, at the shoulder\", \"弯成杯状，举在肩旁\")) + L(\".\", \"。\"), 7f); }\n            }\n            if (seen)\n            {\n                Strike(L(\"A flash has been observed in the gymnasium. Only the official photographer may flash. Report filed.\", \"体育馆内发现闪光。只有官方摄影师可以使用闪光灯。举报已登记。\"), true);\n                return;\n            }\n            if (heard)\n            {\n                StudentSay(\"PREFECT\", L(\"...Was that a shutter?\", \"……刚才是快门声吗？\"), 2.5f, true);\n                Strike(L(\"A shutter has been reported by a prefect. Thank you, prefect.\", \"一名学生督察举报了一次快门声。谢谢你，督察。\"), true);\n                return;\n            }\n            if (flash) Thought(L(\"The flash went off. Nobody turned. ...Lucky.\\n\", \"闪光灯亮了。没人回头。……走运。\\n\") + Rule(L(\"A / D: flash OFF - every time I take the phone out.\", \"A / D：关闪光灯——每次拿出手机都要关。\")), 5f);\n        }\n\n        PatrolAI NearestPrefect(out float dist)\n        {\n            dist = 999f;\n            PatrolAI best = null;\n            if (prefects == null) return null;\n            foreach (PatrolAI p in prefects)\n            {\n                if (p == null) continue;\n                float d = Vector3.Distance(p.transform.position, rig.transform.position);\n                if (d < dist) { dist = d; best = p; }\n            }\n            return best;\n        }\n\n        bool FlashSeen()\n        {\n            Vector3 p = rig.eye.position;\n            if (photographerVision != null && LineOfSight(photographerVision, p)) return true;\n            if (prefectVisions != null) foreach (TeacherVision v in prefectVisions) if (v != null && LineOfSight(v, p)) return true;\n            return false;\n        }\n\n        bool LineOfSight(TeacherVision v, Vector3 p)\n        {\n            Vector3 e = v.EyePosition;\n            Vector3 to = p - e;\n            float d = to.magnitude;\n            if (d > flashRange) return false;\n            foreach (RaycastHit h in Physics.RaycastAll(e, to / d, d - 0.05f, ~0, QueryTriggerInteraction.Ignore))\n            {\n                if (h.transform.IsChildOf(v.transform) || h.transform.IsChildOf(rig.transform)) continue;\n                return false;\n            }\n            return true;\n        }\n\n        // ------------------------------------------------------------------ watchers\n        void UpdateDanger()\n        {\n            bool byPrefect = false, byPhotographer = false;\n            if (phone.IsExposed)\n            {\n                Vector3 p = phoneExposurePoint.position;\n                byPhotographer = photographerVision != null && photographerVision.CanSee(p, rig.transform);\n                if (!byPhotographer && prefectVisions != null)\n                    foreach (TeacherVision v in prefectVisions) if (v != null && v.CanSee(p, rig.transform)) byPrefect = true;\n            }\n            if (AccumulateDanger(byPrefect || byPhotographer ? 1f / Mathf.Max(0.05f, noticeSeconds) : 0f))\n            {\n                if (byPhotographer) Strike(L(\"No phones in my pictures. ...I'm telling the office.\", \"我的照片里不许有手机。……我要告诉办公室。\"));\n                else\n                {\n                    StudentSay(\"PREFECT\", L(\"Device. I saw it. I'm writing it down.\", \"设备。我看见了。我记下来了。\"), 2.5f, true);\n                    Strike(L(\"A device has been reported in the gymnasium. Thank you, prefect.\", \"体育馆内有人举报了一台设备。谢谢你，督察。\"), true);\n                }\n            }\n        }\n\n        void UpdateAmbient()\n        {\n            paTimer -= GameSpeed.Dt;\n            if (paTimer <= 0f && DialogueIdle && phase == Phase.Free)\n            {\n                paTimer = Random.Range(50f, 70f);\n                PA(Loc.T(ambientPA[paIndex % ambientPA.Length]), 6f);\n                paIndex++;\n            }\n            if (prefectTalk > 0f) prefectTalk -= Time.deltaTime;\n            if (prefectTalk <= 0f && DialogueIdle && !phone.IsExposed && phase == Phase.Free)\n            {\n                float d;\n                PatrolAI p = NearestPrefect(out d);\n                if (p != null && d < 2.2f)\n                {\n                    prefectTalk = 28f;\n                    string[] lines = { \"Card. ...Oh, you don't have it yet. I'll remember you.\", \"Smile. It's for your card.\", \"Strength through discipline.\" };\n                    StudentSay(\"PREFECT\", Loc.T(lines[Random.Range(0, lines.Length)]), 3.5f);\n                }\n            }\n        }\n\n        void BuildCountdown()\n        {\n            Canvas c = UIFactory.MakeCanvas(\"PhotoCountdown\", 41);\n            c.transform.SetParent(transform, false);\n            countdown = UIFactory.AddText(UIFactory.Rect(\"Countdown\", c.transform, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -275f), new Vector2(900f, 70f)), \"\", 46, Color.white, TextAnchor.MiddleCenter);\n            countdown.fontStyle = FontStyle.Bold;\n            UIFactory.AddShadow(countdown, new Color(0f, 0f, 0f, 0.85f), 3f);\n        }\n\n        protected override IEnumerator OnCaught()\n        {\n            phase = Phase.Done;\n            countdown.text = \"\";\n            phone.allowRaise = false;\n            phone.CancelTask();\n            rig.Lock();\n            PA(L(\"Report number twenty-one: Seat 31. A prefect will collect the student.\", \"第二十一份举报：31 号座。一名督察将前来带走该生。\"), 5f, true);\n            float d;\n            PatrolAI p = NearestPrefect(out d);\n            if (p != null)\n            {\n                Vector3 to = rig.transform.position - p.transform.position; to.y = 0f;\n                p.Approach(rig.transform.position - to.normalized * 0.9f, rig.transform);\n                float t = 0f;\n                yield return Wait(0.4f);\n                while (!p.HasArrived && t < 7f) { t += Time.deltaTime; yield return null; }\n            }\n            StudentSay(\"PREFECT\", L(\"Come with me. You'll get your photo taken in the office.\", \"跟我走。你的照片去办公室拍。\"), 4f);\n            yield return WaitIdle();\n            yield return Caught(\"reported\");\n        }\n    }\n}\n"},"Pigeon":{"path":"Assets/Game/Scripts/Pigeon.cs","role":"A courtyard pigeon outside the classroom windows: pecks, looks around, hops a little. Not monitored. ...Yet.","source":"// @role A courtyard pigeon outside the classroom windows: pecks, looks around, hops a little. Not monitored. ...Yet.\n// @calls AudioSynth\n// @tune hopRadius:float:0-1.5:how far it hops from where it started (m)\n// @tune cooVolume:float:0-1:coo loudness (about as present as a footstep)\n// ArchiveDirector makes the library flock agitated (the librarian comes to shoo them).\nusing System.Collections.Generic;\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The lesson says the courtyard pigeons are not monitored, the PA says they are not your friends.\n    /// So they are there: on the window ledges, on the grass, on the founder's oak. Built by GameSceneBuilder.\n    /// </summary>\n    public class Pigeon : MonoBehaviour\n    {\n        [Tooltip(\"The head group (it dips to peck and turns to look around).\")]\n        public Transform head;\n        [Tooltip(\"How far it hops from where it started (m). 0 = it stays put and only pecks.\")]\n        public float hopRadius = 0.6f;\n        [Tooltip(\"Which directions it may hop in (a ledge pigeon only hops along the ledge).\")]\n        public Vector3 hopAxes = new Vector3(1f, 0f, 1f);\n        [Tooltip(\"How loud its coo is (soft: about as present as a footstep).\")]\n        public float cooVolume = 0.2f;\n        [Tooltip(\"This one stares at you whenever you're near (\\\"One of them is looking right at me.\\\").\")]\n        public bool starer;\n\n        /// <summary>Every pigeon in the scene (the library uses this to stir up the flock).</summary>\n        public static readonly List<Pigeon> All = new List<Pigeon>();\n\n        AudioSource voice;\n        float nextCoo, agitated;\n\n        Vector3 home, from, to;\n        Quaternion headRest;\n        float t, next;\n        int state;   // 0 idle (looking around), 1 peck, 2 hop\n\n        void OnEnable() { All.Add(this); }\n        void OnDisable() { All.Remove(this); }\n\n        /// <summary>The flock gets noisy for a while: flapping, cooing, hopping about.</summary>\n        public void Agitate(float seconds) { agitated = Mathf.Max(agitated, seconds); nextCoo = Random.Range(0f, 0.6f); }\n        public bool Agitated { get { return agitated > 0f; } }\n\n        /// <summary>Shooed: one last flap, then quiet.</summary>\n        public void Calm()\n        {\n            agitated = 0f;\n            if (voice != null) voice.PlayOneShot(AudioSynth.Flap(), cooVolume * 1.4f);\n            nextCoo = Random.Range(10f, 20f);\n        }\n\n        void Start()\n        {\n            voice = gameObject.AddComponent<AudioSource>();\n            voice.playOnAwake = false;\n            voice.spatialBlend = 1f;\n            voice.rolloffMode = AudioRolloffMode.Linear;\n            voice.minDistance = 0.8f;\n            voice.maxDistance = 9f;\n            voice.dopplerLevel = 0f;\n            nextCoo = Random.Range(3f, 14f);\n            home = transform.position;\n            from = to = home;\n            next = Random.Range(0.4f, 2.5f);\n            if (head != null) headRest = head.localRotation;\n        }\n\n        void Update()\n        {\n            float dt = Time.deltaTime;\n            t += dt;\n            if (agitated > 0f) agitated -= dt;\n            nextCoo -= dt;\n            if (nextCoo <= 0f && voice != null)\n            {\n                bool loud = agitated > 0f;\n                if (loud && Random.value < 0.5f) voice.PlayOneShot(AudioSynth.Flap(), cooVolume * 1.6f);\n                else { voice.pitch = Random.Range(0.92f, 1.08f); voice.PlayOneShot(AudioSynth.Coo(), cooVolume * (loud ? 1.8f : 1f)); }\n                nextCoo = loud ? Random.Range(0.5f, 1.3f) : Random.Range(8f, 20f);\n                if (loud && state == 0) next = 0f;   // fidget\n            }\n            if (starer && state == 0)\n            {\n                Camera c = Camera.main;\n                if (c != null && Vector3.Distance(c.transform.position, transform.position) < 12f)\n                {\n                    // turn the body towards you, then the head looks straight at you. It does not blink.\n                    Vector3 d = c.transform.position - transform.position; d.y = 0f;\n                    if (d.sqrMagnitude > 0.001f) transform.rotation = Quaternion.Slerp(transform.rotation, Quaternion.LookRotation(d), dt * 2.5f);\n                    if (head != null) head.rotation = Quaternion.Slerp(head.rotation, Quaternion.LookRotation(c.transform.position - head.position), dt * 6f);\n                    t = 0f;\n                    return;\n                }\n            }\n            if (state == 0)\n            {\n                if (head != null) head.localRotation = headRest * Quaternion.Euler(0f, Mathf.Sin(Time.time * 1.3f + home.x * 3f + home.z) * 28f, 0f);\n                if (t < next) return;\n                t = 0f;\n                if (hopRadius > 0.01f && Random.value < 0.4f)\n                {\n                    Vector2 r = Random.insideUnitCircle * hopRadius;\n                    from = transform.position;\n                    to = home + Vector3.Scale(new Vector3(r.x, 0f, r.y), hopAxes);\n                    state = 2;\n                }\n                else state = 1;\n            }\n            else if (state == 1)\n            {\n                float a = Mathf.Abs(Mathf.Sin(t * Mathf.PI / 0.28f));\n                if (head != null) head.localRotation = headRest * Quaternion.Euler(55f * a, 0f, 0f);\n                if (t > 0.56f) Idle();\n            }\n            else\n            {\n                Vector3 d = to - from;\n                d.y = 0f;\n                if (d.sqrMagnitude > 0.0004f) transform.rotation = Quaternion.Slerp(transform.rotation, Quaternion.LookRotation(d), dt * 10f);\n                float k = Mathf.Clamp01(t / 0.35f);\n                Vector3 p = Vector3.Lerp(from, to, k);\n                p.y = home.y + Mathf.Sin(k * Mathf.PI) * 0.07f;\n                transform.position = p;\n                if (k >= 1f) Idle();\n            }\n        }\n\n        void Idle()\n        {\n            state = 0;\n            t = 0f;\n            next = Random.Range(0.7f, 3.5f);\n            if (head != null) head.localRotation = headRest;\n        }\n    }\n}\n"},"PlayerRig":{"path":"Assets/Game/Scripts/PlayerRig.cs","role":"The player body: walk, pulled to the seat, seated look, inspect the desk cubby, lie down in bed","source":"// @role The player body: walk, pulled to the seat, seated look, inspect the desk cubby, lie down in bed\n// @tune walkSpeed:float:1-5:walking speed (m/s)\n// @tune sneakSpeed:float:0.5-2:quiet walking speed (hold Ctrl / C)\n// @tune sensitivity:float:1-10:mouse look speed\n// @tune pullSpeed:float:0.5-3:speed when the class watches you walk to your seat\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The main character.\n    ///   WALK    - free first-person walking (hallway, cafeteria).\n    ///   PULLED  - the game takes control and walks you somewhere (to your seat).\n    ///   SEATED  - can't get up by yourself. Mouse looks around (head turn is limited).\n    ///   INSPECT - leaning down to look inside the desk cubby.\n    ///   PLACING - looking down at the desk top.\n    ///   LYING   - lying in bed, pretending to sleep (Lights Out).\n    ///   LOCKED  - no control (cutscenes, game over).\n    /// </summary>\n    [RequireComponent(typeof(CharacterController))]\n    public class PlayerRig : MonoBehaviour\n    {\n        public enum Mode { Walk, Pulled, Seated, Inspect, Placing, Lying, Locked }\n\n        public Transform eye;\n        [Header(\"Walking\")]\n        public float walkSpeed = 2.8f;\n        public float runSpeed = 4.2f;\n        [Tooltip(\"Hold Left Ctrl / C: walk quietly at this speed.\")]\n        public float sneakSpeed = 1.2f;\n        public float gravity = -20f;\n        public float standingEye = 1.5f;\n        public float pullSpeed = 1.3f;\n        [Tooltip(\"Set by the level, e.g. while you are looking at the phone you stand still.\")]\n        public bool freezeMovement;\n        [Header(\"Look\")]\n        public float sensitivity = 5f;\n        [Header(\"Seated eye positions (local to the seat)\")]\n        public Vector3 seatedEye = new Vector3(0f, 1.25f, 0.05f);   // same eye height as the seated NPCs\n        public Vector3 inspectEye = new Vector3(0f, 0.64f, 0.12f);\n        public float inspectPitch = 8f;\n        public Vector3 placingEye = new Vector3(0f, 1.15f, 0.22f);\n        public float placingPitch = 55f;\n        [Header(\"Lying in bed\")]\n        public Vector3 lyingEye = new Vector3(0f, 0.72f, -0.45f);\n        public float lyingPitch = -28f;\n\n        public Mode CurrentMode { get; private set; }\n\n        CharacterController cc;\n        float yaw, pitch, vy;\n        float headYaw, headPitch, basePitch, basePitchTarget;\n        float yawLimit = 100f, pitchMin = -55f, pitchMax = 60f;\n        Vector3 eyeTarget;\n        Vector3[] path;\n        int pathIndex;\n        Vector3 seatPosition;\n        float seatYaw;\n        System.Action onSeated;\n        float eyeSpeed = 1.5f;\n\n        void Awake()\n        {\n            cc = GetComponent<CharacterController>();\n            CurrentMode = Mode.Walk;\n            yaw = transform.eulerAngles.y;\n            eyeTarget = new Vector3(0f, standingEye, 0f);\n            if (eye != null) eye.localPosition = eyeTarget;\n        }\n\n        void Update()\n        {\n            switch (CurrentMode)\n            {\n                case Mode.Walk: UpdateWalk(); break;\n                case Mode.Pulled: UpdatePull(); break;\n                case Mode.Seated:\n                case Mode.Inspect:\n                case Mode.Lying: UpdateHead(); break;\n                case Mode.Placing: ApplyHead(); break;\n            }\n            if (eye != null) eye.localPosition = Vector3.MoveTowards(eye.localPosition, eyeTarget, eyeSpeed * Time.deltaTime);\n        }\n\n        // ------------------------------------------------------------------ walking\n        void UpdateWalk()\n        {\n            Vector2 d = GameInput.MouseDelta() * sensitivity;\n            yaw += d.x;\n            pitch = Mathf.Clamp(pitch - d.y, -80f, 80f);\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            if (eye != null) eye.localRotation = Quaternion.Euler(pitch, 0f, 0f);\n\n            Vector2 mv = freezeMovement ? Vector2.zero : GameInput.Move();\n            Vector3 dir = transform.right * mv.x + transform.forward * mv.y;\n            if (dir.sqrMagnitude > 1f) dir.Normalize();\n            float speed = GameInput.SneakHeld() ? sneakSpeed : (GameInput.RunHeld() ? runSpeed : walkSpeed);\n            if (!cc.enabled) return;\n            if (cc.isGrounded) vy = -1f;\n            vy += gravity * Time.deltaTime;\n            cc.Move((dir * speed + Vector3.up * vy) * Time.deltaTime);\n        }\n\n        /// <summary>Take control away and walk the character along 'points' to the seat.</summary>\n        public void PullToSeat(Vector3[] points, Vector3 seatPos, float seatFacingYaw, System.Action seated)\n        {\n            CurrentMode = Mode.Pulled;\n            cc.enabled = false;\n            pullSpeedNow = 0.4f;\n            path = points;\n            pathIndex = 0;\n            seatPosition = seatPos;\n            seatYaw = seatFacingYaw;\n            onSeated = seated;\n        }\n\n        [Header(\"Being pulled to the seat\")]\n        [Tooltip(\"Direction the eyes drift towards while walking in (0 = the front of the class).\")]\n        public float pullLookYaw = 0f;\n        [Range(0f, 1f)] public float pullLookBias = 0.55f;\n        float pullSpeedNow;\n\n        void UpdatePull()\n        {\n            if (path == null || pathIndex >= path.Length) { SitDown(); return; }\n            bool last = pathIndex == path.Length - 1;\n            Vector3 target = path[pathIndex];\n            target.y = transform.position.y;\n            Vector3 to = target - transform.position;\n            float dist = to.magnitude;\n\n            // ease in, ease out on the last stretch\n            float top = last ? Mathf.Lerp(0.35f, pullSpeed, Mathf.Clamp01(dist / 0.8f)) : pullSpeed;\n            pullSpeedNow = Mathf.MoveTowards(pullSpeedNow, top, 1.2f * Time.deltaTime);\n            transform.position = Vector3.MoveTowards(transform.position, target, pullSpeedNow * Time.deltaTime);\n\n            // look: partly where you walk, partly at the class staring back at you - never straight into a wall\n            if (dist > 0.05f)\n            {\n                float walkYaw = Mathf.Atan2(to.x, to.z) * Mathf.Rad2Deg;\n                float want = Mathf.LerpAngle(walkYaw, pullLookYaw, last ? 0.85f : pullLookBias);\n                yaw = Mathf.MoveTowardsAngle(yaw, want, 70f * Time.deltaTime);\n            }\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            pitch = Mathf.MoveTowards(pitch, 6f, 30f * Time.deltaTime);\n            if (eye != null) eye.localRotation = Quaternion.Euler(pitch, 0f, 0f);\n\n            // cut corners: move on to the next point a little before reaching this one\n            if (dist < (last ? 0.02f : 0.45f)) pathIndex++;\n        }\n\n        void SitDown()\n        {\n            transform.position = seatPosition;\n            yaw = seatYaw;\n            transform.rotation = Quaternion.Euler(0f, seatYaw, 0f);\n            headYaw = 0f; headPitch = pitch; basePitch = 0f; basePitchTarget = 0f;\n            BackToSeat();\n            if (onSeated != null) onSeated();\n        }\n\n        // ------------------------------------------------------------------ seated\n        /// <summary>Put the character straight into a seat (level start, bench, bed).</summary>\n        public void SitAt(Vector3 pos, float facingYaw)\n        {\n            cc.enabled = false;\n            transform.position = pos;\n            yaw = facingYaw;\n            transform.rotation = Quaternion.Euler(0f, facingYaw, 0f);\n            headYaw = 0f; headPitch = 0f; pitch = 0f; basePitch = 0f; basePitchTarget = 0f;\n            BackToSeat();\n            if (eye != null) { eye.localPosition = seatedEye; eye.localRotation = Quaternion.identity; }\n        }\n\n        /// <summary>Stand up and walk again from 'pos'.</summary>\n        public void StandUpAt(Vector3 pos)\n        {\n            transform.position = pos;\n            yaw = transform.eulerAngles.y + headYaw;\n            pitch = 0f;\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            cc.enabled = true;\n            eyeTarget = new Vector3(0f, standingEye, 0f);\n            CurrentMode = Mode.Walk;\n        }\n\n        /// <summary>Move a walking character somewhere else instantly (e.g. sent back by the PA).</summary>\n        public void Teleport(Vector3 pos, float facingYaw)\n        {\n            bool was = cc.enabled;\n            cc.enabled = false;\n            transform.position = pos;\n            yaw = facingYaw;\n            transform.rotation = Quaternion.Euler(0f, yaw, 0f);\n            cc.enabled = was;\n        }\n\n        public void BackToSeat()\n        {\n            CurrentMode = Mode.Seated;\n            eyeTarget = seatedEye;\n            eyeSpeed = 1.5f;\n            basePitchTarget = 0f;\n            yawLimit = 100f; pitchMin = -60f; pitchMax = 60f;\n        }\n\n        public void EnterInspect()\n        {\n            CurrentMode = Mode.Inspect;\n            eyeTarget = inspectEye;\n            basePitchTarget = inspectPitch;\n            headYaw = 0f; headPitch = 0f;\n            yawLimit = 40f; pitchMin = -25f; pitchMax = 30f;\n        }\n\n        public void EnterPlacing()\n        {\n            CurrentMode = Mode.Placing;\n            eyeTarget = placingEye;\n            basePitchTarget = placingPitch;\n            headYaw = 0f; headPitch = 0f;\n        }\n\n        /// <summary>Lie down in bed (pretend to sleep). SitUp() = BackToSeat().</summary>\n        public void LieDown()\n        {\n            CurrentMode = Mode.Lying;\n            eyeTarget = lyingEye;\n            eyeSpeed = 2.4f;\n            basePitchTarget = lyingPitch;\n            headYaw = Mathf.Clamp(headYaw, -35f, 35f);\n            headPitch = 0f;\n            yawLimit = 35f; pitchMin = -15f; pitchMax = 15f;\n        }\n\n        public void SitUp() { BackToSeat(); eyeSpeed = 2.4f; }\n\n        public void Lock() { CurrentMode = Mode.Locked; }\n\n        /// <summary>Hand walking control (back) to the player - used at the very start, once the teacher has called you in.</summary>\n        public void AllowWalk() { CurrentMode = Mode.Walk; }\n\n        public bool IsSeatedMode { get { return CurrentMode == Mode.Seated || CurrentMode == Mode.Inspect || CurrentMode == Mode.Placing; } }\n\n        /// <summary>Where the head is turned relative to the seat (degrees).</summary>\n        public float HeadYaw { get { return headYaw; } }\n\n        void UpdateHead()\n        {\n            Vector2 d = GameInput.MouseDelta() * sensitivity;\n            headYaw = Mathf.Clamp(headYaw + d.x, -yawLimit, yawLimit);\n            headPitch = Mathf.Clamp(headPitch - d.y, pitchMin, pitchMax);\n            ApplyHead();\n        }\n\n        void ApplyHead()\n        {\n            basePitch = Mathf.MoveTowards(basePitch, basePitchTarget, 150f * Time.deltaTime);\n            if (eye != null) eye.localRotation = Quaternion.Euler(basePitch + headPitch, headYaw, 0f);\n        }\n    }\n}\n"},"PosterEgg":{"path":"Assets/Game/Scripts/PosterEgg.cs","role":"A poster that changes when you come close and look at it: a too-perfect smile, a glitch, an inedible lunch, a mirror (you, in uniform), a red X, or Voss","source":"// @role A poster that changes when you come close and look at it: a too-perfect smile, a glitch, an inedible lunch, a mirror (you, in uniform), a red X, or Voss\n// @calls AudioSynth, UIFactory, GameSpeed, Loc\n// @tune readFirst:float:0-5:seconds of looking before it starts to change (0 = from the text length)\n// @tune changeSeconds:float:0-5:seconds the change takes (0 = by kind)\n// Drawn from plain rectangles at runtime; pure atmosphere, no gameplay effect.\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Put on a world-space poster canvas (GameSceneBuilder.AddEggs picks the posters by name). When the player stands\n    /// near and looks at it, an overlay fades in over the poster; walk away and it fades back. Everything is drawn\n    /// with rectangles at runtime, so the scenes stay plain.\n    /// </summary>\n    public class PosterEgg : MonoBehaviour\n    {\n        public enum Kind { Smile, Glitch, Lunch, Mirror, RedX, Voss }\n\n        /// <summary>Which posters (by name) do what. Used by the scene builder, and again at runtime so new entries work without a rebuild.</summary>\n        public static readonly System.Collections.Generic.Dictionary<string, Kind> Table = new System.Collections.Generic.Dictionary<string, Kind>\n        {\n            { \"Poster_Smile\", Kind.Smile }, { \"Poster_WholeFace\", Kind.Smile },\n            // glitches: the screens, the incidents, the stairs that don't exist - and every poster that insists on a date\n            { \"Sign_Devices\", Kind.Glitch }, { \"Sign_LiveAddress\", Kind.Glitch }, { \"Banner_DaysSinceIncident\", Kind.Glitch }, { \"Sign_NotHere\", Kind.Glitch },\n            { \"Poster_Catalogue\", Kind.Glitch }, { \"Poster_BannedBooks\", Kind.Glitch }, { \"Poster_Founding\", Kind.Glitch },\n            { \"Sign_LightsOut\", Kind.Glitch }, { \"Banner_PictureDay\", Kind.Glitch }, { \"Poster_Counting\", Kind.Glitch }, { \"Sign_Repair\", Kind.Glitch },\n            { \"Poster_Menu\", Kind.Lunch }, { \"Poster_Privilege\", Kind.Lunch },\n            { \"Poster_Uniform\", Kind.Mirror }, { \"Poster_CitizenCard\", Kind.Mirror }, { \"Photo_1967\", Kind.Mirror },\n            { \"Poster_CardsReady\", Kind.RedX },\n            { \"Display_Yearbook1980\", Kind.Voss }, { \"Poster_InspectedDesk\", Kind.Voss },\n        };\n\n        /// <summary>Adds the egg to every matching poster in the loaded scene that doesn't have one yet.</summary>\n        public static void InstallAll()\n        {\n            foreach (Canvas c in Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include, FindObjectsSortMode.None))\n            {\n                Kind k;\n                if (c.renderMode != RenderMode.WorldSpace || !Table.TryGetValue(c.name, out k) || c.GetComponent<PosterEgg>() != null) continue;\n                c.gameObject.AddComponent<PosterEgg>().kind = k;\n            }\n        }\n\n        /// <summary>The player's body lives on this layer: the player's camera skips it, mirrors show it.</summary>\n        public const int MirrorLayer = 30;\n\n        public Kind kind;\n        [Tooltip(\"How close you must be (m). 0 = worked out from the poster's size.\")]\n        public float range;\n        [Tooltip(\"Seconds to change completely while you look.\")]\n        public float changeSeconds;\n        [Tooltip(\"Seconds of looking before it starts to change (time to read the text). 0 = from the text length.\")]\n        public float readFirst;\n        float looked;\n\n        RectTransform root, layer;\n        CanvasGroup group;\n        Text[] texts;\n        Color[] textColors;\n        string[] textStrings;\n        Vector2[] textPos;\n        float p, W, H;\n        bool everNear;\n        Transform cam;\n\n        // per kind\n        RectTransform[] eyes;\n        Vector2[] eyeRest;\n        RectTransform fly;\n        RectTransform[] bars;\n        Text[] ghosts;\n        RectTransform slice;\n        Camera mirrorCam;\n        RenderTexture rt;\n        float glitchT;\n\n        void Start()\n        {\n            root = transform as RectTransform;\n            if (root == null) { enabled = false; return; }\n            W = root.sizeDelta.x;\n            H = root.sizeDelta.y;\n            texts = GetComponentsInChildren<Text>(true);\n            textColors = new Color[texts.Length];\n            textStrings = new string[texts.Length];\n            textPos = new Vector2[texts.Length];\n            for (int i = 0; i < texts.Length; i++) { textColors[i] = texts[i].color; textStrings[i] = texts[i].text; textPos[i] = texts[i].rectTransform.anchoredPosition; }\n            if (range <= 0f) range = Mathf.Clamp(1.8f + Mathf.Max(W, H) * 0.0012f, 2f, 3.6f);\n            if (changeSeconds <= 0f) changeSeconds = kind == Kind.Mirror || kind == Kind.Voss ? 1.4f : (kind == Kind.Glitch ? 0.3f : 1f);\n            // first you get to read it: about a second per short line, more for longer posters\n            int chars = 0;\n            foreach (Text t in texts) chars += t.text.Length;\n            if (readFirst <= 0f) readFirst = Mathf.Clamp(0.3f + chars * (Loc.Chinese ? 0.02f : 0.008f), 0.4f, 1.2f);\n\n            if (kind != Kind.Glitch)\n            {\n                layer = UIFactory.Stretch(\"Egg_\" + kind, root);\n                layer.SetAsLastSibling();\n                group = layer.gameObject.AddComponent<CanvasGroup>();\n                group.alpha = 0f;\n                group.interactable = group.blocksRaycasts = false;\n                Image bg = null;\n                foreach (Image im in GetComponentsInChildren<Image>(true)) if (im.name == \"BG\") { bg = im; break; }\n                UIFactory.AddImage(UIFactory.Stretch(\"Cover\", layer), bg != null ? bg.color : new Color(0.9f, 0.9f, 0.86f));\n            }\n            switch (kind)\n            {\n                case Kind.Smile: BuildSmile(); break;\n                case Kind.Lunch: BuildLunch(); break;\n                case Kind.Mirror: BuildMirror(); break;\n                case Kind.RedX: BuildRedX(); break;\n                case Kind.Voss: BuildVoss(); break;\n                case Kind.Glitch: BuildGlitch(); break;\n            }\n        }\n\n        void OnDestroy() { if (rt != null) rt.Release(); }\n\n        // ------------------------------------------------------------------ drawing helpers (pixels, from the centre)\n        RectTransform R(string name, float x, float y, float w, float h, Color c, float rot = 0f, Transform parent = null)\n        {\n            RectTransform r = UIFactory.Centered(name, parent != null ? parent : layer, x, y, w, h);\n            r.localRotation = Quaternion.Euler(0f, 0f, rot);\n            UIFactory.AddImage(r, c);\n            return r;\n        }\n\n        float S { get { return Mathf.Min(W, H); } }   // a square drawing area that fits the poster\n\n        // ------------------------------------------------------------------ the smile: symmetric, wide, the eyes don't smile\n        void BuildSmile()\n        {\n            // a plain, perfectly symmetric smiley: two big blank eyes, one huge curved mouth, two dimples. Too wide. Too still.\n            float s = S * 0.92f;\n            Color ink = new Color(0.1f, 0.1f, 0.12f), mouth = new Color(0.45f, 0.08f, 0.1f), blush = new Color(0.98f, 0.62f, 0.62f, 0.6f);\n            R(\"Face\", 0f, 0f, s, s, new Color(1f, 0.9f, 0.55f));\n            eyes = new[] { R(\"Eye_L\", -s * 0.17f, s * 0.16f, s * 0.085f, s * 0.19f, ink), R(\"Eye_R\", s * 0.17f, s * 0.16f, s * 0.085f, s * 0.19f, ink) };\n            eyeRest = new[] { eyes[0].anchoredPosition, eyes[1].anchoredPosition };\n            int n = 21;\n            float rad = s * 0.34f, cy = s * 0.04f;\n            for (int i = 0; i < n; i++)\n            {\n                float a = Mathf.Lerp(195f, 345f, i / (float)(n - 1)) * Mathf.Deg2Rad;\n                Vector2 q = new Vector2(Mathf.Cos(a) * rad, cy + Mathf.Sin(a) * rad * 0.85f);\n                // thick in the middle, thinner towards the corners\n                float thick = s * Mathf.Lerp(0.045f, 0.075f, Mathf.Sin(Mathf.PI * i / (n - 1)));\n                R(\"Mouth\", q.x, q.y, s * 0.075f, thick, mouth, Mathf.Atan2(Mathf.Cos(a) * 0.85f, -Mathf.Sin(a)) * Mathf.Rad2Deg);\n            }\n            float ex = Mathf.Cos(195f * Mathf.Deg2Rad) * rad, ey = cy + Mathf.Sin(195f * Mathf.Deg2Rad) * rad * 0.85f;\n            R(\"Dimple_L\", ex - s * 0.035f, ey + s * 0.035f, s * 0.018f, s * 0.07f, mouth, 25f);\n            R(\"Dimple_R\", -ex + s * 0.035f, ey + s * 0.035f, s * 0.018f, s * 0.07f, mouth, -25f);\n            R(\"Blush_L\", -s * 0.3f, -s * 0.02f, s * 0.11f, s * 0.05f, blush);\n            R(\"Blush_R\", s * 0.3f, -s * 0.02f, s * 0.11f, s * 0.05f, blush);\n        }\n\n        // ------------------------------------------------------------------ lunch: grey tray, grey food, one fly\n        void BuildLunch()\n        {\n            float w = W * 0.86f, h = H * 0.62f;\n            R(\"Tray\", 0f, -H * 0.05f, w, h, new Color(0.55f, 0.56f, 0.55f));\n            R(\"Slot_A\", -w * 0.22f, -H * 0.05f + h * 0.18f, w * 0.48f, h * 0.5f, new Color(0.45f, 0.46f, 0.45f));\n            R(\"Slot_B\", w * 0.25f, -H * 0.05f + h * 0.18f, w * 0.4f, h * 0.5f, new Color(0.45f, 0.46f, 0.45f));\n            R(\"Slot_C\", 0f, -H * 0.05f - h * 0.27f, w * 0.9f, h * 0.36f, new Color(0.45f, 0.46f, 0.45f));\n            // grey-green mush\n            for (int i = 0; i < 5; i++)\n                R(\"Mush\", -w * 0.22f + (i - 2) * w * 0.06f, -H * 0.05f + h * (0.12f + (i % 2) * 0.08f), w * 0.16f, h * 0.2f, new Color(0.52f, 0.56f, 0.38f), i * 17f);\n            // a grey slab with spots\n            R(\"Slab\", w * 0.25f, -H * 0.05f + h * 0.18f, w * 0.3f, h * 0.3f, new Color(0.62f, 0.55f, 0.5f), -6f);\n            for (int i = 0; i < 4; i++) R(\"Spot\", w * (0.18f + 0.05f * i), -H * 0.05f + h * (0.12f + 0.06f * (i % 2)), w * 0.03f, w * 0.03f, new Color(0.35f, 0.3f, 0.26f));\n            // pale soup, with a hair in it\n            R(\"Soup\", 0f, -H * 0.05f - h * 0.27f, w * 0.8f, h * 0.26f, new Color(0.78f, 0.76f, 0.62f));\n            R(\"Hair\", w * 0.05f, -H * 0.05f - h * 0.26f, w * 0.3f, 2.5f, new Color(0.12f, 0.1f, 0.08f), 12f);\n            fly = R(\"Fly\", 0f, 0f, w * 0.035f, w * 0.03f, new Color(0.08f, 0.08f, 0.09f));\n            R(\"Wing_L\", -w * 0.022f, w * 0.015f, w * 0.03f, w * 0.014f, new Color(0.85f, 0.88f, 0.9f, 0.8f), 25f, fly);\n            R(\"Wing_R\", w * 0.022f, w * 0.015f, w * 0.03f, w * 0.014f, new Color(0.85f, 0.88f, 0.9f, 0.8f), -25f, fly);\n        }\n\n        // ------------------------------------------------------------------ the mirror: it shows you (in uniform)\n        void BuildMirror()\n        {\n            int tw = 256, th = Mathf.Max(64, Mathf.RoundToInt(256f * H / Mathf.Max(1f, W)));\n            rt = new RenderTexture(tw, th, 16);\n            rt.name = \"Mirror_\" + name;\n            RectTransform pic = UIFactory.Stretch(\"Mirror\", layer);\n            pic.offsetMin = new Vector2(S * 0.04f, S * 0.04f);\n            pic.offsetMax = new Vector2(-S * 0.04f, -S * 0.04f);\n            RawImage ri = pic.gameObject.AddComponent<RawImage>();\n            ri.texture = rt;\n            ri.uvRect = new Rect(1f, 0f, -1f, 1f);   // mirrored\n            ri.raycastTarget = false;\n            R(\"Sheen\", W * 0.2f, H * 0.2f, W * 0.05f, H * 0.9f, new Color(1f, 1f, 1f, 0.08f), -25f);\n            GameObject g = new GameObject(\"MirrorCamera\");\n            g.transform.SetParent(transform, false);\n            mirrorCam = g.AddComponent<Camera>();\n            mirrorCam.targetTexture = rt;\n            mirrorCam.fieldOfView = 42f;\n            mirrorCam.nearClipPlane = 0.05f;\n            mirrorCam.farClipPlane = 30f;\n            mirrorCam.enabled = false;\n        }\n\n        // ------------------------------------------------------------------ red X\n        void BuildRedX()\n        {\n            Color red = new Color(0.78f, 0.08f, 0.06f);\n            float diag = Mathf.Sqrt(W * W + H * H) * 0.82f, ang = Mathf.Atan2(H, W) * Mathf.Rad2Deg;\n            bars = new[] { R(\"Bar_A\", 0f, 0f, diag, S * 0.16f, red, ang), R(\"Bar_B\", 0f, 0f, diag, S * 0.16f, red, -ang) };\n            layer.GetComponentInChildren<Image>().color = new Color(0.97f, 0.93f, 0.86f);\n        }\n\n        // ------------------------------------------------------------------ Voss: stern eyes, a full beard, a red tie\n        void BuildVoss()\n        {\n            float s = S * 0.92f;\n            Color skin = new Color(0.86f, 0.74f, 0.64f), beard = new Color(0.2f, 0.15f, 0.12f), suit = new Color(0.15f, 0.15f, 0.18f), ink = new Color(0.08f, 0.08f, 0.09f);\n            R(\"Backdrop\", 0f, 0f, W, H, new Color(0.3f, 0.35f, 0.32f));\n            R(\"Shoulders\", 0f, -s * 0.42f, s * 0.95f, s * 0.3f, suit);\n            R(\"Shirt\", 0f, -s * 0.33f, s * 0.2f, s * 0.14f, new Color(0.94f, 0.93f, 0.88f));\n            R(\"Tie\", 0f, -s * 0.4f, s * 0.06f, s * 0.22f, new Color(0.55f, 0.07f, 0.06f));\n            R(\"Head\", 0f, s * 0.06f, s * 0.46f, s * 0.56f, skin);\n            R(\"Hair\", 0f, s * 0.31f, s * 0.48f, s * 0.1f, beard);\n            R(\"Beard\", 0f, -s * 0.12f, s * 0.48f, s * 0.22f, beard);\n            R(\"Jaw_L\", -s * 0.22f, -s * 0.02f, s * 0.05f, s * 0.2f, beard);\n            R(\"Jaw_R\", s * 0.22f, -s * 0.02f, s * 0.05f, s * 0.2f, beard);\n            R(\"Mouth\", 0f, -s * 0.07f, s * 0.12f, s * 0.018f, new Color(0.45f, 0.2f, 0.18f));\n            R(\"Moustache\", 0f, -s * 0.035f, s * 0.2f, s * 0.035f, beard);\n            R(\"Nose\", 0f, s * 0.03f, s * 0.05f, s * 0.08f, new Color(0.8f, 0.64f, 0.55f));\n            eyes = new[] { R(\"Eye_L\", -s * 0.1f, s * 0.12f, s * 0.07f, s * 0.025f, ink), R(\"Eye_R\", s * 0.1f, s * 0.12f, s * 0.07f, s * 0.025f, ink) };\n            eyeRest = new[] { eyes[0].anchoredPosition, eyes[1].anchoredPosition };\n            R(\"Brow_L\", -s * 0.1f, s * 0.17f, s * 0.1f, s * 0.025f, beard, -10f);\n            R(\"Brow_R\", s * 0.1f, s * 0.17f, s * 0.1f, s * 0.025f, beard, 10f);\n        }\n\n        // ------------------------------------------------------------------ glitch: colour ghosts, jitter, a torn slice\n        void BuildGlitch()\n        {\n            ghosts = new Text[texts.Length * 2];\n            for (int i = 0; i < texts.Length; i++)\n                for (int k = 0; k < 2; k++)\n                {\n                    Text src = texts[i];\n                    RectTransform r = Instantiate(src.rectTransform, src.rectTransform.parent);\n                    r.name = src.name + (k == 0 ? \"_GhostR\" : \"_GhostC\");\n                    r.SetSiblingIndex(src.rectTransform.GetSiblingIndex());\n                    Text g = r.GetComponent<Text>();\n                    g.color = k == 0 ? new Color(1f, 0.1f, 0.2f, 0f) : new Color(0.1f, 0.9f, 1f, 0f);\n                    ghosts[i * 2 + k] = g;\n                }\n            slice = UIFactory.Rect(\"Slice\", root, new Vector2(0f, 0.5f), new Vector2(1f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(0f, H * 0.08f));\n            UIFactory.AddImage(slice, new Color(0.9f, 0.95f, 1f, 0f));\n        }\n\n        // ------------------------------------------------------------------ every frame\n        void Update()\n        {\n            if (cam == null) { Camera c = Camera.main; if (c == null) return; cam = c.transform; c.cullingMask &= ~(1 << MirrorLayer); }\n            Vector3 to = transform.position - cam.position;\n            float d = to.magnitude;\n            // near + roughly looking at it (within 38 degrees of the view centre) = the reading clock runs\n            bool near = d < range && Vector3.Dot(transform.forward, to) > 0f && Vector3.Angle(cam.forward, to) < 38f;\n            float before = p;\n            looked = near ? looked + GameSpeed.Dt : Mathf.Max(0f, looked - Time.deltaTime * 0.5f);\n            bool changing = near && looked >= readFirst;\n            p = Mathf.MoveTowards(p, changing ? 1f : 0f, (changing ? GameSpeed.Dt : Time.deltaTime) / (changing ? changeSeconds : 2.2f));\n            if (changing && !everNear && kind == Kind.Glitch) { everNear = true; AudioSource.PlayClipAtPoint(AudioSynth.Glitch(), transform.position, 0.18f); }\n            if (p <= 0f && before <= 0f && kind != Kind.Glitch) { if (mirrorCam != null) mirrorCam.enabled = false; return; }\n            float v = p * p * (3f - 2f * p);\n            if (group != null) group.alpha = v;\n\n            switch (kind)\n            {\n                case Kind.Smile:\n                case Kind.Voss:\n                    // the eyes follow you (just a little)\n                    Vector3 local = transform.InverseTransformPoint(cam.position);\n                    float follow = Mathf.Clamp(local.x / Mathf.Max(1f, W), -1f, 1f) * S * 0.035f;   // canvas units\n                    for (int i = 0; i < eyes.Length; i++) eyes[i].anchoredPosition = eyeRest[i] + new Vector2(follow, 0f);\n                    break;\n                case Kind.Lunch:\n                    float t = Time.time * 1.7f;\n                    fly.anchoredPosition = new Vector2(Mathf.Sin(t * 1.3f) * W * 0.25f + Mathf.Sin(t * 4.1f) * W * 0.03f, Mathf.Sin(t * 0.9f + 1f) * H * 0.18f);\n                    fly.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(t * 3f) * 40f);\n                    break;\n                case Kind.Mirror:\n                    mirrorCam.enabled = v > 0.01f;\n                    Transform mc = mirrorCam.transform;\n                    mc.position = transform.position - transform.forward * 0.03f;\n                    Vector3 face = cam.position + Vector3.down * 0.12f;\n                    mc.rotation = Quaternion.LookRotation(face - mc.position, Vector3.up);\n                    break;\n                case Kind.RedX:\n                    for (int i = 0; i < texts.Length; i++) texts[i].color = Color.Lerp(textColors[i], new Color(0.78f, 0.08f, 0.06f), Mathf.Clamp01(p * 2f));\n                    if (group != null) group.alpha = Mathf.Clamp01((p - 0.35f) / 0.65f);\n                    float g2 = Mathf.Clamp01((p - 0.35f) / 0.65f);\n                    bars[0].localScale = new Vector3(Mathf.Clamp01(g2 * 2f), 1f, 1f);\n                    bars[1].localScale = new Vector3(Mathf.Clamp01(g2 * 2f - 1f), 1f, 1f);\n                    break;\n                case Kind.Glitch:\n                    UpdateGlitch(v);\n                    break;\n            }\n        }\n\n        /// <summary>Does the centre of the screen (the crosshair) point at this poster's rectangle?</summary>\n        bool CrosshairOnPoster()\n        {\n            Plane plane = new Plane(transform.forward, transform.position);\n            Ray ray = new Ray(cam.position, cam.forward);\n            float enter;\n            if (!plane.Raycast(ray, out enter)) return false;\n            Vector3 local = transform.InverseTransformPoint(ray.GetPoint(enter));   // canvas units (px)\n            float mx = W * 0.5f + 40f, my = H * 0.5f + 40f;                       // a little forgiving at the edges\n            return Mathf.Abs(local.x) <= mx && Mathf.Abs(local.y) <= my;\n        }\n\n        void UpdateGlitch(float v)\n        {\n            glitchT -= Time.deltaTime;\n            bool burst = v > 0.05f && glitchT < 0f;\n            if (burst) glitchT = Random.Range(0.05f, 0.25f);\n            if (v <= 0.001f)\n            {\n                for (int i = 0; i < texts.Length; i++) { texts[i].rectTransform.anchoredPosition = textPos[i]; texts[i].text = textStrings[i]; }\n                for (int i = 0; i < ghosts.Length; i++) ghosts[i].color = new Color(ghosts[i].color.r, ghosts[i].color.g, ghosts[i].color.b, 0f);\n                slice.GetComponent<Image>().color = new Color(1f, 1f, 1f, 0f);\n                return;\n            }\n            if (!burst) return;\n            for (int i = 0; i < texts.Length; i++)\n            {\n                // a translated poster: keep whatever text it shows now (Readable may have swapped it)\n                if (texts[i].text != Scrambled(textStrings[i])) textStrings[i] = texts[i].text;\n                float jx = Random.Range(-1f, 1f) * W * 0.02f * v;\n                texts[i].rectTransform.anchoredPosition = textPos[i] + new Vector2(jx, Random.Range(-1f, 1f) * H * 0.01f * v);\n                texts[i].text = Random.value < 0.18f * v ? Scrambled(textStrings[i]) : textStrings[i];\n                for (int k = 0; k < 2; k++)\n                {\n                    Text g = ghosts[i * 2 + k];\n                    g.text = texts[i].text;\n                    g.rectTransform.anchoredPosition = texts[i].rectTransform.anchoredPosition + new Vector2((k == 0 ? -1f : 1f) * W * Random.Range(0.005f, 0.02f) * v, 0f);\n                    Color c = g.color; c.a = 0.55f * v; g.color = c;\n                }\n            }\n            Image si = slice.GetComponent<Image>();\n            if (Random.value < 0.4f * v)\n            {\n                slice.anchoredPosition = new Vector2(Random.Range(-1f, 1f) * W * 0.04f, Random.Range(-0.45f, 0.45f) * H);\n                si.color = new Color(Random.value, Random.value, Random.value, 0.5f * v);\n            }\n            else si.color = new Color(1f, 1f, 1f, 0f);\n        }\n\n        static string Scrambled(string s)\n        {\n            if (string.IsNullOrEmpty(s)) return s;\n            char[] c = s.ToCharArray();\n            int seed = s.Length * 31;\n            for (int i = 0; i < c.Length; i++)\n                if (c[i] != '\\n' && c[i] != ' ' && ((i * 7 + seed) % 5 == 0)) c[i] = \"#%&@!?/\\\\01\"[(i + seed) % 10];\n            return new string(c);\n        }\n    }\n}\n"},"Readable":{"path":"Assets/Game/Scripts/Readable.cs","role":"A poster / sign / label the player can read by walking up and looking at it: a thought, a Search keyword, or the poster answering back","source":"// @role A poster / sign / label the player can read by walking up and looking at it: a thought, a Search keyword, or the poster answering back\n// @calls Loc\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Put on a world-space poster canvas. When the player is close enough and keeps the crosshair on it for a moment,\n    /// the level director \"reads\" it once:\n    ///   reaction  - what the player notices (small print, a clue, a joke that belongs to this school)\n    ///   keyword   - a word for the phone's Search app (Chapter 5)\n    ///   altTitle / altBody - the poster changes after you read it (it reacts to being read)\n    /// Text is stored in English; Chinese comes from LocTable.\n    /// </summary>\n    public class Readable : MonoBehaviour\n    {\n        [TextArea] public string reaction;\n        public string keyword;\n        [TextArea] public string altTitle;\n        [TextArea] public string altBody;\n        [Tooltip(\"How close you must be (m). 0 = worked out from the poster's size.\")]\n        public float range;\n        [Tooltip(\"Size of the thing being read (m). 0 = worked out from the poster's size. Set it for things that aren't posters (a tree, a bell).\")]\n        public float radius;\n        [HideInInspector] public bool read;\n\n        /// <summary>Centre of the poster and half its diagonal (world units).</summary>\n        public Vector3 Centre { get { return transform.position; } }\n\n        public float Radius\n        {\n            get\n            {\n                if (radius > 0f) return radius;\n                RectTransform rt = transform as RectTransform;\n                if (rt == null) return 0.3f;\n                Vector2 s = Vector2.Scale(rt.sizeDelta, new Vector2(rt.lossyScale.x, rt.lossyScale.y));\n                return Mathf.Max(0.12f, s.magnitude * 0.5f);\n            }\n        }\n\n        public float Range { get { return range > 0f ? range : Mathf.Clamp(1.6f + Radius * 2.2f, 1.8f, 6f); } }\n\n        /// <summary>The poster answers back: swap its printed text (with a glitch).</summary>\n        public void React()\n        {\n            foreach (Text t in GetComponentsInChildren<Text>(true))\n            {\n                if (t.name == \"Title\" && !string.IsNullOrEmpty(altTitle)) t.text = Loc.T(altTitle);\n                if (t.name == \"Body\" && !string.IsNullOrEmpty(altBody)) t.text = Loc.T(altBody);\n            }\n        }\n\n        public bool Reacts { get { return !string.IsNullOrEmpty(altTitle) || !string.IsNullOrEmpty(altBody); } }\n    }\n}\n"},"TVStatic":{"path":"Assets/Game/Scripts/TVStatic.cs","role":"A screen showing nothing but snow (\"LIVE\" with nobody on it) - flickering grey emission","source":"// @role A screen showing nothing but snow (\"LIVE\" with nobody on it) - flickering grey emission\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>An empty \"live\" broadcast: the screen flickers between greys, now and then a roll bar.</summary>\n    public class TVStatic : MonoBehaviour\n    {\n        public Renderer screen;\n        public Light glow;\n        public float strength = 1.6f;\n        MaterialPropertyBlock mpb;\n        float next;\n\n        void Awake()\n        {\n            if (screen == null) screen = GetComponent<Renderer>();\n            mpb = new MaterialPropertyBlock();\n        }\n\n        void Update()\n        {\n            if (screen == null || Time.time < next) return;\n            next = Time.time + Random.Range(0.03f, 0.07f);\n            float v = Random.Range(0.35f, 1f) * strength;\n            if (Random.value < 0.04f) v *= 0.3f;   // the picture rolls\n            Color c = new Color(v * 0.9f, v * 0.95f, v);\n            screen.GetPropertyBlock(mpb);\n            mpb.SetColor(\"_EmissionColor\", c);\n            mpb.SetColor(\"_BaseColor\", new Color(0.5f, 0.5f, 0.52f));\n            screen.SetPropertyBlock(mpb);\n            if (glow != null) glow.intensity = 0.4f + v * 0.35f;\n        }\n    }\n}\n"},"TeacherAI":{"path":"Assets/Game/Scripts/TeacherAI.cs","role":"The teacher on a NavMesh: lectures, writes on the board (back turned = safe), wanders, calls on you, comes to take the phone","source":"// @role The teacher on a NavMesh: lectures, writes on the board (back turned = safe), wanders, calls on you, comes to take the phone\n// @calls TeacherVision\n// @tune lectureWeight:float:0-1:chance he lectures facing the class\n// @tune boardWeight:float:0-1:chance he turns to the board (safe window)\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.AI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// The teacher. Walks on a NavMesh (so he goes AROUND desks and students, never through them) and\n    /// picks his next activity at random:\n    ///   LECTURE    - stands at the front facing the class (dangerous)\n    ///   BOARD      - writes on the blackboard with his back to the class (safe window)\n    ///   WANDER     - walks to a random spot in the room, then looks around\n    /// The level director can interrupt him to CALL ON the player, or to come and TAKE the phone.\n    /// What he SAYS is in LessonScript (lines + questions) and is shown as subtitles by the director.\n    /// </summary>\n    [RequireComponent(typeof(NavMeshAgent))]\n    public class TeacherAI : MonoBehaviour\n    {\n        public enum Activity { Idle, Lecture, Board, Wander, LookAround, Calling, Approach }\n\n        [Header(\"Spots (world positions on the classroom floor)\")]\n        public Vector3 lectureSpot = new Vector3(3.2f, 0.15f, 10.0f);\n        public float lectureFacingYaw = 180f;\n        public Vector3 boardSpot = new Vector3(3.6f, 0.15f, 11.3f);\n        public float boardFacingYaw = 0f;\n        [Tooltip(\"Random wander points are picked inside this rectangle (x min, z min, x max, z max).\")]\n        public Vector4 roomRect = new Vector4(0.4f, 0.5f, 9.6f, 11.4f);\n\n        [Header(\"Timing (seconds)\")]\n        public Vector2 lectureTime = new Vector2(7f, 11f);\n        public Vector2 boardTime = new Vector2(5f, 8f);\n        public Vector2 lookAroundTime = new Vector2(2f, 4f);\n        [Range(0f, 1f)] public float lectureWeight = 0.35f;\n        [Range(0f, 1f)] public float boardWeight = 0.3f;\n\n        [Header(\"Speech\")]\n        public List<LessonLine> lines = LessonDefaults.Lines();\n        public List<LessonQuestion> questions = LessonDefaults.Questions();\n\n        public Activity Current { get; private set; }\n        public bool Running { get; private set; }\n        /// <summary>True when he is facing the board (his back to the class).</summary>\n        public bool IsWritingOnBoard { get { return Current == Activity.Board && arrived; } }\n\n        NavMeshAgent agent;\n        float timer;\n        bool arrived;\n        float targetYaw;\n        bool hasTargetYaw;\n        Transform faceTarget;\n        float sinceGo;\n        Transform visual;   // all his visible parts; kept on the real floor (the NavMesh floats a little above it)\n\n        void Awake()\n        {\n            agent = GetComponent<NavMeshAgent>();\n            agent.enabled = false;   // enabled after the NavMesh is built\n\n            visual = new GameObject(\"Visual\").transform;\n            List<Transform> kids = new List<Transform>();\n            foreach (Transform c in transform) kids.Add(c);\n            visual.SetParent(transform, false);\n            foreach (Transform c in kids) c.SetParent(visual, false);\n        }\n\n        /// <summary>Call after the NavMesh exists.</summary>\n        public void Begin()\n        {\n            agent.enabled = true;\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(transform.position, out hit, 2f, NavMesh.AllAreas)) agent.Warp(hit.position);\n            Running = true;\n            StartActivity(Activity.Board);\n        }\n\n        public void CallOn(Transform player)\n        {\n            Current = Activity.Calling;\n            faceTarget = player;\n            hasTargetYaw = false;\n            Stop();\n        }\n\n        public void EndCall()\n        {\n            faceTarget = null;\n            PickNext();\n        }\n\n        /// <summary>Walk over to the player (used when taking the phone away).</summary>\n        public void Approach(Vector3 standPoint, Transform lookAt)\n        {\n            Current = Activity.Approach;\n            faceTarget = lookAt;\n            Go(standPoint);\n        }\n\n        public bool HasArrived { get { return arrived; } }\n\n        /// <summary>Go back to his normal random lesson routine.</summary>\n        public void Resume() { EndCall(); }\n\n        /// <summary>Stop where he is and face a direction (e.g. the board) until Resume().</summary>\n        public void HoldFacing(float yaw)\n        {\n            Current = Activity.Calling;\n            faceTarget = null;\n            hasTargetYaw = true;\n            targetYaw = yaw;\n            Stop();\n        }\n\n        /// <summary>Walk to a point, then face a direction and stay there until Resume().</summary>\n        public void WalkToAndFace(Vector3 point, float yaw)\n        {\n            Current = Activity.Approach;\n            faceTarget = null;\n            hasTargetYaw = true;\n            targetYaw = yaw;\n            Go(point);\n        }\n\n        void Update()\n        {\n            if (!Running || !agent.enabled) return;\n\n            sinceGo += Time.deltaTime;\n            if (!arrived && sinceGo > 0.3f && !agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.05f)\n            {\n                arrived = true;\n                agent.isStopped = true;\n                timer = DurationFor(Current);\n            }\n\n            if (arrived || Current == Activity.Calling)\n            {\n                Vector3 dir = Vector3.zero;\n                if (faceTarget != null) { dir = faceTarget.position - transform.position; dir.y = 0f; }\n                else if (hasTargetYaw) dir = Quaternion.Euler(0f, targetYaw, 0f) * Vector3.forward;\n                if (dir.sqrMagnitude > 0.001f)\n                    transform.rotation = Quaternion.RotateTowards(transform.rotation, Quaternion.LookRotation(dir), 220f * Time.deltaTime);\n            }\n\n            if (Current == Activity.Calling || Current == Activity.Approach) return;\n\n            if (arrived)\n            {\n                timer -= Time.deltaTime;\n                if (timer <= 0f)\n                {\n                    if (Current == Activity.Wander) StartActivity(Activity.LookAround);\n                    else PickNext();\n                }\n            }\n        }\n\n        void LateUpdate()\n        {\n            if (visual == null) return;\n            RaycastHit hit;\n            Vector3 from = transform.position + Vector3.up * 0.8f;\n            if (Physics.Raycast(from, Vector3.down, out hit, 2f, ~(1 << gameObject.layer), QueryTriggerInteraction.Ignore))\n            {\n                // only small corrections: never climb onto a chair, bench or desk the ray happens to hit\n                float want = Mathf.Clamp(hit.point.y - transform.position.y, -0.12f, 0.17f);\n                Vector3 lp = visual.localPosition;\n                lp.y = Mathf.MoveTowards(lp.y, want, 1f * Time.deltaTime);\n                visual.localPosition = lp;\n            }\n        }\n\n        void PickNext()\n        {\n            float r = Random.value;\n            if (r < lectureWeight) StartActivity(Activity.Lecture);\n            else if (r < lectureWeight + boardWeight) StartActivity(Activity.Board);\n            else StartActivity(Activity.Wander);\n        }\n\n        void StartActivity(Activity a)\n        {\n            Current = a;\n            faceTarget = null;\n            switch (a)\n            {\n                case Activity.Lecture:\n                    hasTargetYaw = true; targetYaw = lectureFacingYaw;\n                    Go(lectureSpot);\n                    break;\n                case Activity.Board:\n                    hasTargetYaw = true; targetYaw = boardFacingYaw;\n                    Go(boardSpot);\n                    break;\n                case Activity.Wander:\n                    hasTargetYaw = false;\n                    Go(RandomPoint());\n                    break;\n                case Activity.LookAround:\n                    hasTargetYaw = true; targetYaw = Random.Range(0f, 360f);\n                    arrived = true;\n                    timer = DurationFor(a);\n                    break;\n            }\n        }\n\n        void Go(Vector3 p)\n        {\n            NavMeshHit hit;\n            if (NavMesh.SamplePosition(p, out hit, 1.0f, NavMesh.AllAreas)) p = hit.position;\n            agent.isStopped = false;\n            agent.SetDestination(p);\n            arrived = false;\n            sinceGo = 0f;\n        }\n\n        void Stop()\n        {\n            if (agent.enabled) { agent.isStopped = true; agent.ResetPath(); }\n            arrived = true;\n        }\n\n        Vector3 RandomPoint()\n        {\n            for (int i = 0; i < 20; i++)\n            {\n                Vector3 p = new Vector3(Random.Range(roomRect.x, roomRect.z), transform.position.y, Random.Range(roomRect.y, roomRect.w));\n                NavMeshHit hit;\n                if (!NavMesh.SamplePosition(p, out hit, 0.6f, NavMesh.AllAreas)) continue;\n                NavMeshPath path = new NavMeshPath();\n                if (agent.CalculatePath(hit.position, path) && path.status == NavMeshPathStatus.PathComplete) return hit.position;\n            }\n            return lectureSpot;\n        }\n\n        float DurationFor(Activity a)\n        {\n            switch (a)\n            {\n                case Activity.Lecture: return Random.Range(lectureTime.x, lectureTime.y);\n                case Activity.Board: return Random.Range(boardTime.x, boardTime.y);\n                case Activity.LookAround: return Random.Range(lookAroundTime.x, lookAroundTime.y);\n                case Activity.Wander: return 0.2f;\n                default: return 1f;\n            }\n        }\n    }\n}\n"},"TeacherVision":{"path":"Assets/Game/Scripts/TeacherVision.cs","role":"Can a watcher see a point: range + view cone + line of sight (classmates, pillars and desks are cover)","source":"// @role Can a watcher see a point: range + view cone + line of sight (classmates, pillars and desks are cover)\n// @tune viewAngle:float:30-180:width of the view cone (degrees)\n// @tune viewRange:float:3-20:how far he can see (m)\nusing UnityEngine;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Can this watcher (teacher, monitor, warden, security camera) see a point? Three checks:\n    ///   1. within range   2. inside the view cone (in front of him)   3. nothing solid in between\n    /// (classmates, book stacks, desks, pillars all block - that is what \"cover\" means mechanically).\n    /// 'ignoreRoot' = the player: their own body never blocks the view of their own phone.\n    /// </summary>\n    public class TeacherVision : MonoBehaviour\n    {\n        [Tooltip(\"Full width of the view cone in degrees.\")]\n        public float viewAngle = 90f;\n        public float viewRange = 12f;\n        [Tooltip(\"Height of his eyes above his feet (0 for a camera head: the eye is the object itself).\")]\n        public float eyeHeight = 1.6f;\n        [Tooltip(\"Off = this watcher sees nothing (switched off).\")]\n        public bool active = true;\n\n        public Vector3 EyePosition { get { return transform.position + Vector3.up * eyeHeight; } }\n\n        public bool CanSee(Vector3 point) { return CanSee(point, null, -1f); }\n\n        public bool CanSee(Vector3 point, Transform ignoreRoot, float rangeOverride = -1f)\n        {\n            if (!active || !isActiveAndEnabled) return false;\n            Vector3 eye = EyePosition;\n            Vector3 to = point - eye;\n            float dist = to.magnitude;\n            float range = rangeOverride > 0f ? rangeOverride : viewRange;\n            if (dist > range || dist < 0.001f) return false;\n\n            Vector3 flat = new Vector3(to.x, 0f, to.z);\n            Vector3 fwd = transform.forward; fwd.y = 0f;\n            if (flat.sqrMagnitude > 0.0001f && fwd.sqrMagnitude > 0.0001f && Vector3.Angle(fwd, flat) > viewAngle * 0.5f) return false;\n\n            RaycastHit[] hits = Physics.RaycastAll(eye, to / dist, dist - 0.02f, ~0, QueryTriggerInteraction.Ignore);\n            foreach (RaycastHit h in hits)\n            {\n                if (h.transform.IsChildOf(transform)) continue;\n                if (ignoreRoot != null && h.transform.IsChildOf(ignoreRoot)) continue;\n                return false;   // something is in the way\n            }\n            return true;\n        }\n\n        void OnDrawGizmosSelected()\n        {\n            Gizmos.color = new Color(1f, 0.3f, 0.3f);\n            Vector3 e = EyePosition;\n            Quaternion l = Quaternion.Euler(0f, -viewAngle * 0.5f, 0f), r = Quaternion.Euler(0f, viewAngle * 0.5f, 0f);\n            Gizmos.DrawLine(e, e + l * transform.forward * viewRange);\n            Gizmos.DrawLine(e, e + r * transform.forward * viewRange);\n        }\n    }\n}\n"},"TitleScreen":{"path":"Assets/Game/Scripts/TitleScreen.cs","role":"Title page: New Game (asks your name) / Continue / Chapters / Quit","source":"// @role Title page: New Game (asks your name) / Continue / Chapters / Quit\n// @calls GameFlow, AmbientAudio\nusing System.Collections;\nusing UnityEngine;\nusing UnityEngine.EventSystems;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Title page (builds its own UI): a CCTV-style frame (REC dot, timestamp, scanlines) over the school's motto.\n    ///  New Game -> \"What is your name?\" (the teacher reads it in the roll call) -> Chapter 1.\n    ///  Continue -> the furthest chapter reached.   Chapters -> any chapter (for playtests / demos).   Quit.\n    /// </summary>\n    public class TitleScreen : MonoBehaviour\n    {\n        static readonly Color Paper = new Color(0.93f, 0.90f, 0.82f);\n        static readonly Color Red = new Color(0.86f, 0.18f, 0.14f);\n\n        GameObject namePanel, chapterPanel;\n        InputField nameField;\n        Image recDot;\n        Text stamp, warning;\n        RectTransform scan;\n        AmbientAudio audioOut;\n\n        void Start()\n        {\n            Time.timeScale = 1f;\n            AudioListener.volume = 1f;\n            Cursor.lockState = CursorLockMode.None;\n            Cursor.visible = true;\n            GameFlow.LoadSavedName();\n            UIFactory.EnsureEventSystem();\n            audioOut = AmbientAudio.Create(transform);\n            audioOut.droneVolume = 0.1f;\n            audioOut.ventVolume = 0.06f;\n            Build();\n        }\n\n        void Update()\n        {\n            if (recDot != null) recDot.enabled = Mathf.Repeat(Time.time, 1.2f) < 0.7f;\n            if (stamp != null) stamp.text = Loc.L(\"CAM 01   SEAT 31   \", \"监控 01   座位 31   \") + System.DateTime.Now.ToString(\"HH:mm:ss\");\n            if (scan != null) scan.anchoredPosition = new Vector2(0f, -Mathf.Repeat(Time.time * 140f, 1200f));\n            if (warning != null) warning.enabled = Mathf.Repeat(Time.time, 2f) < 1.6f;\n            if (namePanel != null && namePanel.activeSelf && GameInput.EnterDown()) Begin();\n            if (GameInput.EscDown()) { if (namePanel != null) namePanel.SetActive(false); if (chapterPanel != null) chapterPanel.SetActive(false); }\n        }\n\n        void Build()\n        {\n            Canvas canvas = UIFactory.MakeCanvas(\"TitleCanvas\", 10);\n            Transform root = canvas.transform;\n            UIFactory.AddImage(UIFactory.Stretch(\"BG\", root), new Color(0.11f, 0.13f, 0.13f));\n            // pale institutional \"wall\" band + dado, like the corridors\n            UIFactory.AddImage(UIFactory.Rect(\"Dado\", root, Vector2.zero, new Vector2(1f, 0f), new Vector2(0.5f, 0f), Vector2.zero, new Vector2(0f, 300f)), new Color(0.2f, 0.3f, 0.28f));\n            UIFactory.AddImage(UIFactory.Rect(\"DadoLine\", root, Vector2.zero, new Vector2(1f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 300f), new Vector2(0f, 6f)), new Color(0.55f, 0.5f, 0.32f));\n\n            Text est = UIFactory.AddText(UIFactory.Centered(\"Est\", root, 0f, 330f, 1400f, 40f), Loc.L(\"CLEARVIEW ACADEMY  -  EST. 1952\", \"明鉴学院  -  创立于 1952\"), 26, new Color(0.68f, 0.74f, 0.7f), TextAnchor.MiddleCenter);\n            est.fontStyle = FontStyle.Bold;\n            Text title = UIFactory.AddText(UIFactory.Centered(\"Title\", root, 0f, 220f, 1400f, 190f), \"COVER\", 180, Paper, TextAnchor.MiddleCenter);\n            title.fontStyle = FontStyle.Bold;\n            UIFactory.AddShadow(title, new Color(0f, 0f, 0f, 0.6f), 5f);\n            UIFactory.AddText(UIFactory.Centered(\"Sub\", root, 0f, 105f, 1400f, 40f), Loc.L(\"a phone, passed down through the same seat\", \"一部手机，在同一个座位上代代相传\"), 28, new Color(0.8f, 0.78f, 0.72f), TextAnchor.MiddleCenter).fontStyle = FontStyle.Italic;\n            warning = UIFactory.AddText(UIFactory.Centered(\"Motto\", root, 0f, 50f, 1400f, 40f), Loc.L(\"WHAT IS SEEN, IS SAFE.\", \"被看见的，就是安全的。\"), 26, Red, TextAnchor.MiddleCenter);\n            warning.fontStyle = FontStyle.Bold;\n\n            float y = -40f;\n            Button start = UIFactory.MakeButton(\"NewGame\", root, Loc.L(\"New Game\", \"新游戏\"), 0f, y, 420f, 74f);\n            start.onClick.AddListener(ShowNamePanel);\n            y -= 88f;\n            if (GameFlow.ReachedLevel > 0)\n            {\n                Button cont = UIFactory.MakeButton(\"Continue\", root, Loc.L(\"Continue  -  Ch. \", \"继续  -  第 \") + (GameFlow.ReachedLevel + 1) + Loc.L(\"\", \"章\"), 0f, y, 420f, 74f);\n                cont.onClick.AddListener(GameFlow.ContinueGame);\n                y -= 88f;\n            }\n            Button chapters = UIFactory.MakeButton(\"Chapters\", root, Loc.L(\"Chapters\", \"章节\"), 0f, y, 420f, 74f);\n            chapters.onClick.AddListener(() => chapterPanel.SetActive(true));\n            y -= 88f;\n            Button quit = UIFactory.MakeButton(\"Quit\", root, Loc.L(\"Quit\", \"退出\"), 0f, y, 420f, 74f);\n            quit.onClick.AddListener(Quit);\n\n            UIFactory.AddText(UIFactory.Rect(\"Credits\", root, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 24f), new Vector2(1600f, 34f)),\n                Loc.L(\"A game by Ariel & Nina  -  CGDD 2026  -  WASD / Mouse / E / Hold Right Mouse: phone\", \"Ariel & Nina 作品  -  CGDD 2026  -  WASD / 鼠标 / E / 按住右键：手机\"), 20, new Color(0.72f, 0.74f, 0.7f), TextAnchor.MiddleCenter);\n\n            // CCTV overlay\n            RectTransform scanRoot = UIFactory.Stretch(\"Scan\", root);\n            scan = UIFactory.Rect(\"Line\", scanRoot, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), Vector2.zero, new Vector2(0f, 90f));\n            UIFactory.AddImage(scan, new Color(1f, 1f, 1f, 0.025f)).raycastTarget = false;\n            for (int i = 0; i < 4; i++)\n            {\n                Vector2 a = new Vector2(i % 2, i / 2);\n                RectTransform c = UIFactory.Rect(\"Corner\" + i, root, a, a, a, new Vector2(a.x > 0 ? -40f : 40f, a.y > 0 ? -40f : 40f), new Vector2(70f, 70f));\n                Image h = UIFactory.AddImage(UIFactory.Rect(\"H\", c, a, a, a, Vector2.zero, new Vector2(70f, 4f)), new Color(1f, 1f, 1f, 0.5f));\n                Image v = UIFactory.AddImage(UIFactory.Rect(\"V\", c, a, a, a, Vector2.zero, new Vector2(4f, 70f)), new Color(1f, 1f, 1f, 0.5f));\n                h.raycastTarget = v.raycastTarget = false;\n            }\n            recDot = UIFactory.AddImage(UIFactory.Rect(\"Rec\", root, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(70f, -66f), new Vector2(22f, 22f)), Red);\n            recDot.raycastTarget = false;\n            UIFactory.AddText(UIFactory.Rect(\"RecText\", root, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(102f, -60f), new Vector2(200f, 34f)), Loc.L(\"REC\", \"录制\"), 26, Red, TextAnchor.MiddleLeft).raycastTarget = false;\n            stamp = UIFactory.AddText(UIFactory.Rect(\"Stamp\", root, new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(-70f, -60f), new Vector2(600f, 34f)), \"\", 24, new Color(1f, 1f, 1f, 0.7f), TextAnchor.MiddleRight);\n            stamp.raycastTarget = false;\n\n            // language: English / 中文 (saved; the title reloads so every text and font switches)\n            Button lang = UIFactory.MakeButton(\"Language\", root, Loc.Chinese ? \"语言：中文   >   English\" : \"Language: English   >   中文\", -235f, y - 96f, 450f, 60f);\n            Text langText = lang.GetComponentInChildren<Text>();\n            if (langText != null) { langText.font = UIFactory.CjkFont; langText.fontSize = 24; }\n            lang.onClick.AddListener(() => { Loc.Chinese = !Loc.Chinese; UnityEngine.SceneManagement.SceneManager.LoadScene(GameFlow.TitleScene); });\n            // story speed: 1x / 2x (dialogue, messages, loading, scripted waits)\n            Button speed = UIFactory.MakeButton(\"Speed\", root, \"\", 235f, y - 96f, 450f, 60f);\n            Text speedLabel = speed.GetComponentInChildren<Text>();\n            System.Action showSpeed = () => { if (speedLabel != null) speedLabel.text = GameSpeed.Fast ? Loc.L(\"Story speed: 2x   >   1x\", \"剧情速度：2 倍   >   1 倍\") : Loc.L(\"Story speed: 1x   >   2x\", \"剧情速度：1 倍   >   2 倍\"); };\n            if (speedLabel != null) speedLabel.fontSize = 24;\n            showSpeed();\n            speed.onClick.AddListener(() => { GameSpeed.Fast = !GameSpeed.Fast; showSpeed(); });\n\n            BuildNamePanel(root);\n            BuildChapterPanel(root);\n        }\n\n        void ShowNamePanel()\n        {\n            namePanel.SetActive(true);\n            nameField.text = GameFlow.playerName == \"Student\" ? \"\" : GameFlow.playerName;\n            if (EventSystem.current != null) EventSystem.current.SetSelectedGameObject(nameField.gameObject);\n            nameField.ActivateInputField();\n        }\n\n        void Begin()\n        {\n            string n = nameField.text != null ? nameField.text.Trim() : \"\";\n            GameFlow.SaveName(n);\n            GameFlow.StartNewGame();\n        }\n\n        RectTransform Panel(string name, Transform root)\n        {\n            RectTransform panel = UIFactory.Stretch(name, root);\n            Image bg = UIFactory.AddImage(panel, new Color(0.04f, 0.045f, 0.05f, 0.97f));\n            bg.raycastTarget = true;   // blocks the buttons behind it\n            return panel;\n        }\n\n        void BuildNamePanel(Transform root)\n        {\n            RectTransform panel = Panel(\"NamePanel\", root);\n            UIFactory.AddText(UIFactory.Centered(\"Notice\", panel, 0f, 270f, 1400f, 90f),\n                Loc.L(\"NOTICE TO NEW STUDENTS: Devices are not permitted. Every device is monitored.\\nThis is for your safety. Thank you for being safe.\", \"新生须知：禁止携带电子设备。所有设备均受监控。\\n这是为了你的安全。感谢你保持安全。\"), 24, new Color(0.75f, 0.3f, 0.26f), TextAnchor.MiddleCenter);\n            UIFactory.AddText(UIFactory.Centered(\"Ask\", panel, 0f, 140f, 1200f, 90f), Loc.L(\"Roll call is in a minute.\\nWhat is your name?\", \"马上要点名了。\\n你叫什么名字？\"), 40, Paper, TextAnchor.MiddleCenter);\n\n            RectTransform box = UIFactory.Centered(\"NameField\", panel, 0f, 10f, 560f, 80f);\n            Image fieldBg = UIFactory.AddImage(box, Paper);\n            fieldBg.raycastTarget = true;\n            Text txt = UIFactory.AddText(UIFactory.Rect(\"Text\", box, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-40f, -10f)), \"\", 38, new Color(0.08f, 0.08f, 0.1f), TextAnchor.MiddleCenter);\n            txt.supportRichText = false;\n            Text ph = UIFactory.AddText(UIFactory.Rect(\"Placeholder\", box, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(-40f, -10f)), Loc.L(\"type your name\", \"输入你的名字\"), 34, new Color(0.45f, 0.43f, 0.4f), TextAnchor.MiddleCenter);\n            ph.fontStyle = FontStyle.Italic;\n            nameField = box.gameObject.AddComponent<InputField>();\n            nameField.textComponent = txt;\n            nameField.placeholder = ph;\n            nameField.targetGraphic = fieldBg;\n            nameField.characterLimit = 16;\n\n            Button go = UIFactory.MakeButton(\"EnterClassButton\", panel, Loc.L(\"Go to class\", \"去上课\"), 0f, -120f, 360f, 84f);\n            go.onClick.AddListener(Begin);\n            UIFactory.AddText(UIFactory.Centered(\"EnterHint\", panel, 0f, -200f, 800f, 40f), Loc.L(\"(Enter)    -    Esc: back\", \"（回车）    -    Esc：返回\"), 22, new Color(0.6f, 0.6f, 0.62f), TextAnchor.MiddleCenter);\n            namePanel = panel.gameObject;\n            namePanel.SetActive(false);\n        }\n\n        void BuildChapterPanel(Transform root)\n        {\n            RectTransform panel = Panel(\"ChapterPanel\", root);\n            UIFactory.AddText(UIFactory.Centered(\"Head\", panel, 0f, 300f, 1200f, 70f), Loc.L(\"CHAPTERS\", \"章节\"), 56, Paper, TextAnchor.MiddleCenter).fontStyle = FontStyle.Bold;\n            for (int i = 0; i < GameFlow.Levels.Length; i++)\n            {\n                int idx = i;\n                Button b = UIFactory.MakeButton(\"Chapter\" + i, panel, Loc.T(GameFlow.LevelTitles[i]), 0f, 215f - i * 80f, 640f, 66f);\n                b.onClick.AddListener(() => GameFlow.LoadLevel(idx));\n            }\n            Button back = UIFactory.MakeButton(\"Back\", panel, Loc.L(\"Back\", \"返回\"), 0f, -300f, 300f, 66f);\n            back.onClick.AddListener(() => chapterPanel.SetActive(false));\n            chapterPanel = panel.gameObject;\n            chapterPanel.SetActive(false);\n        }\n\n        void Quit()\n        {\n#if UNITY_EDITOR\n            UnityEditor.EditorApplication.isPlaying = false;\n#else\n            Application.Quit();\n#endif\n        }\n    }\n}\n"},"UIFactory":{"path":"Assets/Game/Scripts/UIFactory.cs","role":"Builds every on-screen panel, text, button and world-space poster canvas in code (no prefabs), with the right font for English or Chinese","source":"// @role Builds every on-screen panel, text, button and world-space poster canvas in code (no prefabs), with the right font for English or Chinese\nusing System.Collections.Generic;\nusing UnityEngine;\nusing UnityEngine.EventSystems;\nusing UnityEngine.UI;\n\nnamespace PhoneGame\n{\n    /// <summary>\n    /// Small helpers for building uGUI by code (used by the scene builder AND at runtime by the HUD / phone).\n    /// Fonts: in the editor only the built-in font can be saved into scenes; at runtime UI uses a typewriter\n    /// (monospace) font taken from the computer (Courier New / Menlo...), falling back to the built-in one.\n    /// </summary>\n    public static class UIFactory\n    {\n        static Font font, mono, cjk;\n        static bool monoTried, cjkTried;\n\n        /// <summary>A Chinese font from the computer (PingFang on a Mac, YaHei on Windows...). Runtime only.</summary>\n        public static Font CjkFont\n        {\n            get\n            {\n                if (cjk == null && !cjkTried)\n                {\n                    cjkTried = true;\n                    try\n                    {\n                        cjk = Font.CreateDynamicFontFromOSFont(new[] { \"PingFang SC\", \"Hiragino Sans GB\", \"Heiti SC\", \"STHeiti\", \"Microsoft YaHei\", \"Noto Sans CJK SC\", \"Source Han Sans SC\", \"Arial Unicode MS\" }, 32);\n                    }\n                    catch (System.Exception) { cjk = null; }\n                }\n                return cjk != null ? cjk : DefaultFont;\n            }\n        }\n\n        public static Font DefaultFont\n        {\n            get\n            {\n                if (font == null) font = Resources.GetBuiltinResource<Font>(\"LegacyRuntime.ttf\");\n                return font;\n            }\n        }\n\n        /// <summary>Typewriter font (runtime only). Falls back to the built-in font.</summary>\n        public static Font MonoFont\n        {\n            get\n            {\n                if (mono == null && !monoTried)\n                {\n                    monoTried = true;\n                    try\n                    {\n                        mono = Font.CreateDynamicFontFromOSFont(new[] { \"Courier New\", \"Courier\", \"Menlo\", \"Monaco\", \"Consolas\", \"Liberation Mono\", \"DejaVu Sans Mono\" }, 32);\n                    }\n                    catch (System.Exception) { mono = null; }\n                }\n                return mono != null ? mono : DefaultFont;\n            }\n        }\n\n        /// <summary>The font new Text gets: typewriter while playing, built-in while building scenes in the editor.</summary>\n        public static Font TextFont { get { return Application.isPlaying ? (Loc.Chinese ? CjkFont : MonoFont) : DefaultFont; } }\n\n        public static Canvas MakeCanvas(string name, int sortOrder)\n        {\n            GameObject go = new GameObject(name, typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));\n            Canvas c = go.GetComponent<Canvas>();\n            c.renderMode = RenderMode.ScreenSpaceOverlay;\n            c.sortingOrder = sortOrder;\n            CanvasScaler s = go.GetComponent<CanvasScaler>();\n            s.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\n            s.referenceResolution = new Vector2(1920f, 1080f);\n            s.matchWidthOrHeight = 0.5f;\n            return c;\n        }\n\n        /// <summary>A canvas that lives in the 3D world (posters, signs). 1 px = 1 mm.</summary>\n        public static Canvas MakeWorldCanvas(string name, Transform parent, Vector3 worldPos, Quaternion rot, float widthMeters, float heightMeters)\n        {\n            GameObject go = new GameObject(name, typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler));\n            go.transform.SetParent(parent, true);\n            Canvas c = go.GetComponent<Canvas>();\n            c.renderMode = RenderMode.WorldSpace;\n            RectTransform rt = (RectTransform)go.transform;\n            rt.sizeDelta = new Vector2(widthMeters * 1000f, heightMeters * 1000f);\n            rt.position = worldPos;\n            rt.rotation = rot;\n            rt.localScale = Vector3.one * 0.001f;\n            CanvasScaler s = go.GetComponent<CanvasScaler>();\n            s.dynamicPixelsPerUnit = TypewriterFont.PosterPixelsPerUnit;   // see TypewriterFont: bigger overflows the CJK font atlas\n            return c;\n        }\n\n        public static RectTransform Rect(string name, Transform parent, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 pos, Vector2 size)\n        {\n            GameObject go = new GameObject(name, typeof(RectTransform));\n            RectTransform rt = (RectTransform)go.transform;\n            rt.SetParent(parent, false);\n            rt.anchorMin = anchorMin;\n            rt.anchorMax = anchorMax;\n            rt.pivot = pivot;\n            rt.anchoredPosition = pos;\n            rt.sizeDelta = size;\n            return rt;\n        }\n\n        /// <summary>Rect anchored to the parent's top-left corner; pos is (x right, y down) in pixels.</summary>\n        public static RectTransform TopLeft(string name, Transform parent, float x, float y, float w, float h)\n        {\n            return Rect(name, parent, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(x, -y), new Vector2(w, h));\n        }\n\n        public static RectTransform Centered(string name, Transform parent, float x, float y, float w, float h)\n        {\n            Vector2 c = new Vector2(0.5f, 0.5f);\n            return Rect(name, parent, c, c, c, new Vector2(x, y), new Vector2(w, h));\n        }\n\n        public static RectTransform Stretch(string name, Transform parent)\n        {\n            return Rect(name, parent, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero);\n        }\n\n        public static Image AddImage(RectTransform rt, Color color)\n        {\n            Image img = rt.gameObject.AddComponent<Image>();\n            img.color = color;\n            img.raycastTarget = false;\n            return img;\n        }\n\n        public static Text AddText(RectTransform rt, string text, int size, Color color, TextAnchor align)\n        {\n            Text t = rt.gameObject.AddComponent<Text>();\n            t.font = TextFont;\n            t.text = text;\n            t.fontSize = size;\n            t.color = color;\n            t.alignment = align;\n            t.horizontalOverflow = HorizontalWrapMode.Wrap;\n            t.verticalOverflow = VerticalWrapMode.Overflow;\n            t.raycastTarget = false;\n            return t;\n        }\n\n        static readonly Dictionary<Text, int> baseSizes = new Dictionary<Text, int>();\n        static readonly Dictionary<Text, string> fitted = new Dictionary<Text, string>();\n\n        /// <summary>Height the text would need in this box (layout units), wrapping to the box width.</summary>\n        public static float PreferredHeight(Text t, string full, int fontSize = -1)\n        {\n            TextGenerationSettings g = t.GetGenerationSettings(new Vector2(t.rectTransform.rect.width, 0f));\n            if (fontSize > 0) g.fontSize = fontSize;\n            g.resizeTextForBestFit = false;\n            return t.cachedTextGeneratorForLayout.GetPreferredHeight(full ?? \"\", g) / Mathf.Max(0.01f, t.pixelsPerUnit);\n        }\n\n        /// <summary>\n        /// Picks the biggest font size (from the text's own size down to 'min') at which 'full' fits inside the box.\n        /// Use the FULL string even while it is being typed, so the size never jumps. (Chinese lines are longer.)\n        /// </summary>\n        public static void FitFont(Text t, string full, int min = 11)\n        {\n            if (t == null) return;\n            int max;\n            if (!baseSizes.TryGetValue(t, out max)) { max = t.fontSize; baseSizes[t] = max; }\n            string last;\n            if (fitted.TryGetValue(t, out last) && last == full) return;\n            fitted[t] = full;\n            float h = t.rectTransform.rect.height;\n            int size = max;\n            while (size > min && PreferredHeight(t, full, size) > h) size--;\n            t.fontSize = size;\n        }\n\n        public static void AddShadow(Graphic g, Color c, float distance)\n        {\n            Shadow s = g.gameObject.AddComponent<Shadow>();\n            s.effectColor = c;\n            s.effectDistance = new Vector2(distance, -distance);\n        }\n\n        public static Button MakeButton(string name, Transform parent, string label, float x, float y, float w, float h)\n        {\n            RectTransform rt = Centered(name, parent, x, y, w, h);\n            Image img = AddImage(rt, new Color(0.93f, 0.90f, 0.82f, 1f));\n            img.raycastTarget = true;\n            Button b = rt.gameObject.AddComponent<Button>();\n            b.targetGraphic = img;\n            ColorBlock cb = b.colors;\n            cb.highlightedColor = new Color(1f, 0.82f, 0.45f);\n            cb.pressedColor = new Color(0.8f, 0.65f, 0.35f);\n            cb.disabledColor = new Color(0.45f, 0.45f, 0.45f, 0.6f);\n            b.colors = cb;\n            AddText(Stretch(\"Label\", rt), label, 34, new Color(0.08f, 0.08f, 0.1f), TextAnchor.MiddleCenter);\n            return b;\n        }\n\n        public static void EnsureEventSystem()\n        {\n            if (Object.FindFirstObjectByType<EventSystem>() != null) return;\n            GameObject go = new GameObject(\"EventSystem\", typeof(EventSystem));\n#if ENABLE_LEGACY_INPUT_MANAGER\n            go.AddComponent<StandaloneInputModule>();\n#elif ENABLE_INPUT_SYSTEM\n            UnityEngine.InputSystem.UI.InputSystemUIInputModule m = go.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();\n            m.AssignDefaultActions();\n#endif\n        }\n    }\n}\n"}}};
